window.MT_DATA['fa'] = [{"id":1,"name":"Niveau 1","freeLessonsPerModule":{"1":10,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours en Iran, en route et à la maison.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à Téhéran","phrases":[{"fr":"Bonjour, bienvenue à Téhéran !","tgt":"سلام، به تهران خوش آمدید!","ro":"Salâm, be Tehrân khosh âmadid!","lit":"bonjour · [à] · Téhéran · bien · êtes venus"},{"fr":"Bonjour, je m'appelle Thomas.","tgt":"سلام، اسم من توماس است.","ro":"Salâm, esm-e man Tomâs ast.","lit":"bonjour · nom · [de] · moi · Thomas · est"},{"fr":"Bonjour, comment allez-vous ?","tgt":"سلام، حال شما چطور است؟","ro":"Salâm, hâl-e shomâ chetor ast?","lit":"bonjour · état · [de] · vous · comment · est"},{"fr":"Très bien, merci.","tgt":"خیلی خوب، ممنون.","ro":"Kheyli khub, mamnun.","lit":"très · bien · merci"},{"fr":"Bonjour monsieur, je suis le nouveau voisin.","tgt":"سلام آقا، من همسایه‌ی جدید هستم.","ro":"Salâm âghâ, man hamsâye-ye jadid hastam.","lit":"bonjour · monsieur · moi · voisin · [de] · nouveau · suis"},{"fr":"Bonjour, monsieur Karimi !","tgt":"صبح بخیر آقای کریمی!","ro":"Sobh bekheyr âghâ-ye Karimi!","lit":"matin · [à] · bien · monsieur · [de] · Karimi"},{"fr":"Bonne nuit, et à demain !","tgt":"شب بخیر، تا فردا!","ro":"Shab bekheyr, tâ fardâ!","lit":"nuit · [à] · bien · jusqu'à · demain"},{"fr":"Au revoir, madame Rezaï.","tgt":"خداحافظ خانم رضایی.","ro":"Khodâhâfez khânom-e Rezâyi.","lit":"au revoir · madame · [de] · Rezaï"},{"fr":"Au revoir, et à très bientôt !","tgt":"خداحافظ، به امید دیدار!","ro":"Khodâhâfez, be omid-e didâr!","lit":"au revoir · [à] · espoir · [de] · revoir"},{"fr":"Bonjour à tout le monde !","tgt":"سلام به همه!","ro":"Salâm be hame!","lit":"bonjour · [à] · tous"}],"tip":{"title":"« Salâm » et « khodâ hâfez » : saluer et dire au revoir","example":"Au revoir, madame Rezaï. — <b>خداحافظ</b> خانم رضایی.","body":"Bonne nouvelle : pour saluer en persan, un seul mot suffit à toute heure de la journée, « salâm », qui veut dire à la fois bonjour, bonsoir et salut. On le prononce en appuyant sur la fin, « sa-lâm », avec un â long et profond, comme dans le mot « pâte ». Pour prendre congé, on dit « khodâhâfez », au revoir. Le son « kh » se fait au fond de la gorge, comme un r français un peu raclé. Décomposez-le en deux morceaux, « khodâ » puis « hâfez », et enchaînez-les d'un seul souffle. Le matin, vous entendrez aussi « sobh bekheyr », bonjour du matin, et le soir « shab bekheyr », bonne nuit. Pour accueillir quelqu'un, on dit « khosh âmadid », bienvenue. Astuce pour retenir : « salâm » commence par les mêmes sons que notre « salut », vous ne l'oublierez plus.","exampleRo":"Khodâhâfez khânom-e Rezâyi.","lit":"au revoir · madame · [de] · Rezaï","say":{"Salâm":"سلام","khodâ hâfez":"خدا حافظ","salâm":"سلام","sa-lâm":"سلام","khodâhâfez":"خداحافظ","khodâ":"خدا","hâfez":"حافظ","sobh bekheyr":"صبح بخیر","shab bekheyr":"شب بخیر","khosh âmadid":"خوش آمدید"}}},{"title":"Les voisins de l'immeuble","phrases":[{"fr":"Je suis étudiant.","tgt":"من دانشجو هستم.","ro":"Man dâneshju hastam.","lit":"moi · étudiant · suis"},{"fr":"Tu es prêt ?","tgt":"تو آماده هستی؟","ro":"To âmâde hasti?","lit":"toi · prêt · es"},{"fr":"Il est notre voisin.","tgt":"او همسایه‌ی ماست.","ro":"U hamsâye-ye mâst.","lit":"lui · voisin · [de] · nous · est"},{"fr":"Elle est vraiment très gentille.","tgt":"او خیلی مهربان است.","ro":"U kheyli mehrabân ast.","lit":"elle · très · gentille · est"},{"fr":"Nous sommes français.","tgt":"ما فرانسوی هستیم.","ro":"Mâ farânsavi hastim.","lit":"nous · français · sommes"},{"fr":"Vous êtes de Téhéran ?","tgt":"شما اهل تهران هستید؟","ro":"Shomâ ahl-e Tehrân hastid?","lit":"vous · originaire · [de] · Téhéran · êtes"},{"fr":"Ils sont au travail.","tgt":"آن‌ها سر کار هستند.","ro":"Ânhâ sar-e kâr hastand.","lit":"eux · tête · [de] · travail · sont"},{"fr":"Moi, je suis Thomas, et vous ?","tgt":"من توماس هستم، و شما؟","ro":"Man Tomâs hastam, va shomâ?","lit":"moi · Thomas · suis · et · vous"},{"fr":"Toi et moi, nous sommes voisins.","tgt":"من و تو همسایه هستیم.","ro":"Man o to hamsâye hastim.","lit":"moi · et · toi · voisin · sommes"},{"fr":"Ils sont très accueillants.","tgt":"آن‌ها خیلی مهمان‌نواز هستند.","ro":"Ânhâ kheyli mehmânnavâz hastand.","lit":"eux · très · accueillants · sont"}],"tip":{"title":"Les pronoms : « man », « to », « u », « mâ », « shomâ », « ânhâ »","example":"Elle est vraiment très gentille. — <b>او</b> خیلی مهربان است.","body":"Les pronoms persans sont courts et faciles à dire : « man » pour je, « to » pour tu, « u » pour il ou elle, « mâ » pour nous, « shomâ » pour vous, et « ânhâ » pour ils ou elles. Remarquez une grande différence avec le français : le persan ne fait pas la distinction entre il et elle, le même petit « u » sert pour un homme comme pour une femme. Décomposons « U kheyli mehrabân ast » : « u », elle, « kheyli », très, « mehrabân », gentille, et « ast », est. Avec une personne que vous ne connaissez pas, un voisin ou un commerçant, utilisez toujours « shomâ », le vous de politesse, exactement comme en français. On garde « to » pour les amis proches et la famille. Pour dire toi et moi, on dit d'ailleurs « man o to », en se mettant poliment soi-même en premier. Astuce : « man » ressemble à notre « moi », et « to » à notre « toi », c'est un vrai cadeau pour un francophone.","exampleRo":"U kheyli mehrabân ast.","lit":"elle · très · gentille · est","say":{"man":"من","to":"تو","u":"او","mâ":"ما","shomâ":"شما","ânhâ":"آنها","U kheyli mehrabân ast":"او خیلی مهربان است","kheyli":"خیلی","mehrabân":"مهربان","ast":"است","man o to":"من و تو"}}},{"title":"Le nouvel appartement","phrases":[{"fr":"Moi, je suis très content.","tgt":"من خیلی خوشحال هستم.","ro":"Man kheyli khoshhâl hastam.","lit":"moi · très · content · suis"},{"fr":"L'appartement est grand.","tgt":"آپارتمان بزرگ است.","ro":"Âpârtemân bozorg ast.","lit":"appartement · grand · est"},{"fr":"La cuisine est toute petite.","tgt":"آشپزخانه خیلی کوچک است.","ro":"Âshpazkhâne kheyli kuchek ast.","lit":"cuisine · très · petite · est"},{"fr":"Tu es à la maison ?","tgt":"تو در خانه هستی؟","ro":"To dar khâne hasti?","lit":"toi · dans · maison · es"},{"fr":"Oui, je suis à la maison.","tgt":"بله، در خانه هستم.","ro":"Bale, dar khâne hastam.","lit":"oui · dans · maison · suis"},{"fr":"La chambre est très claire.","tgt":"اتاق خواب خیلی روشن است.","ro":"Otâgh-e khâb kheyli roshan ast.","lit":"chambre · [de] · sommeil · très · claire · est"},{"fr":"Il y a aussi un balcon.","tgt":"یک بالکن هم هست.","ro":"Yek bâlkon ham hast.","lit":"un · balcon · aussi · est"},{"fr":"Nous sommes au troisième étage.","tgt":"ما در طبقه‌ی سوم هستیم.","ro":"Mâ dar tabaghe-ye sevvom hastim.","lit":"nous · dans · étage · [de] · troisième · sommes"},{"fr":"Vous êtes fatigué, monsieur ?","tgt":"شما خسته هستید، آقا؟","ro":"Shomâ khaste hastid, âghâ?","lit":"vous · fatigué · êtes · monsieur"},{"fr":"Ils sont dans le salon.","tgt":"آن‌ها در پذیرایی هستند.","ro":"Ânhâ dar pazirâyi hastand.","lit":"eux · dans · salon · sont"}],"tip":{"title":"« Hastam », « hasti », « hast » : le verbe être","example":"Oui, je suis à la maison. — بله، در خانه <b>هستم</b>.","body":"Le verbe être se construit sur une base unique, « hast », à laquelle on accroche une petite terminaison pour chaque personne. On dit « hastam », je suis, « hasti », tu es, « hast », il est, puis « hastim », nous sommes, « hastid », vous êtes, et « hastand », ils sont. Pour la troisième personne, on utilise très souvent la forme courte « ast », comme dans « Âpârtemân bozorg ast », l'appartement est grand. La forme « hast » seule sert plutôt à dire qu'une chose existe, un peu comme notre il y a : « Yek bâlkon ham hast », il y a aussi un balcon. Comme la terminaison indique déjà qui parle, on peut supprimer le pronom : « Bale, dar khâne hastam » veut dire oui, je suis à la maison, sans « man ». Retenez bien ces terminaisons, « -am, -i, -im, -id, -and », car vous les retrouverez sur presque tous les verbes. Astuce : le « m » de « hastam » rappelle le « moi » de celui qui parle.","exampleRo":"Bale, dar khâne hastam.","lit":"oui · dans · maison · suis","say":{"Hastam":"هستم","hasti":"هستی","hast":"هست","hastam":"هستم","hastim":"هستیم","hastid":"هستید","hastand":"هستند","ast":"است","Âpârtemân bozorg ast":"آپارتمان بزرگ است","Yek bâlkon ham hast":"یک بالکن هم هست","Bale, dar khâne hastam":"بله، در خانه هستم","man":"من"}}},{"title":"La boulangerie et le pain sangak","phrases":[{"fr":"Le pain est encore chaud.","tgt":"نان هنوز گرم است.","ro":"Nân hanuz garm ast.","lit":"pain · encore · chaud · est"},{"fr":"La boulangerie est au coin de la rue.","tgt":"نانوایی سر کوچه است.","ro":"Nânvâyi sar-e kuche ast.","lit":"boulangerie · tête · [de] · ruelle · est"},{"fr":"Le boulanger travaille tôt le matin.","tgt":"نانوا صبح زود کار می‌کند.","ro":"Nânvâ sobh-e zud kâr mikonad.","lit":"boulanger · matin · [de] · tôt · travail · fait"},{"fr":"J'achète du pain chaque matin.","tgt":"من هر روز صبح نان می‌خرم.","ro":"Man har ruz sobh nân mikharam.","lit":"moi · chaque · jour · matin · pain · achète"},{"fr":"La file est longue aujourd'hui.","tgt":"امروز صف طولانی است.","ro":"Emruz saf tulâni ast.","lit":"aujourd'hui · file · longue · est"},{"fr":"Le pain sangak est délicieux.","tgt":"نان سنگک خوشمزه است.","ro":"Nân-e sangak khoshmaze ast.","lit":"pain · [de] · sangak · délicieux · est"},{"fr":"Le boulanger est quelqu'un de bien.","tgt":"نانوا آدم خوبی است.","ro":"Nânvâ âdam-e khubi ast.","lit":"boulanger · personne · [de] · bonne · est"},{"fr":"Je mange du pain et du fromage.","tgt":"من نان و پنیر می‌خورم.","ro":"Man nân o panir mikhoram.","lit":"moi · pain · et · fromage · mange"},{"fr":"Nous prenons le petit-déjeuner à la maison.","tgt":"ما در خانه صبحانه می‌خوریم.","ro":"Mâ dar khâne sobhâne mikhorim.","lit":"nous · dans · maison · petit-déjeuner · mangeons"},{"fr":"La boulangerie ouvre à six heures.","tgt":"نانوایی ساعت شش باز می‌شود.","ro":"Nânvâyi sâ'at-e shesh bâz mishavad.","lit":"boulangerie · heure · [de] · six · ouverte · devient"}],"tip":{"title":"Le verbe toujours à la fin de la phrase","example":"Je mange du pain et du fromage. — من نان و پنیر <b>می‌خورم</b>.","body":"Voici la règle d'or de la phrase persane : le verbe se place à la fin, presque toujours. Là où le français dit je mange du pain, le persan dit littéralement moi, pain, mange. Décomposons « Man nân o panir mikhoram » : « man », moi, « nân », pain, « o », et, « panir », fromage, et enfin « mikhoram », je mange. Tout le reste, le moment, le lieu, l'objet, vient avant le verbe : « Man har ruz sobh nân mikharam », moi chaque jour matin pain j'achète. Même le verbe être attend son tour à la fin : « Nân hanuz garm ast », le pain encore chaud est. Au début, cela donne l'impression de parler à l'envers, mais c'est très régulier et l'on s'y habitue vite. Astuce pour vous entraîner : pensez votre phrase en français, puis gardez le verbe en réserve et posez-le tout à la fin, comme le point final.","exampleRo":"Man nân o panir mikhoram.","lit":"moi · pain · et · fromage · mange","say":{"Man nân o panir mikhoram":"من نان و پنیر می‌خورم","man":"من","nân":"نان","panir":"پنیر","mikhoram":"می‌خورم","Man har ruz sobh nân mikharam":"من هر روز صبح نان می‌خرم","Nân hanuz garm ast":"نان هنوز گرم است"}}},{"title":"Le thé du matin","phrases":[{"fr":"Le thé n'est pas chaud.","tgt":"چای گرم نیست.","ro":"Chây garm nist.","lit":"thé · chaud · n'est pas"},{"fr":"Je ne suis pas fatigué.","tgt":"من خسته نیستم.","ro":"Man khaste nistam.","lit":"moi · fatigué · ne suis pas"},{"fr":"Je ne bois pas de café.","tgt":"من قهوه نمی‌خورم.","ro":"Man ghahve nemikhoram.","lit":"moi · café · [ne… pas] · bois"},{"fr":"Le sucre n'est pas sur la table.","tgt":"قند روی میز نیست.","ro":"Ghand ru-ye miz nist.","lit":"sucre · dessus · [de] · table · n'est pas"},{"fr":"Ce thé n'est pas trop fort ?","tgt":"این چای خیلی پررنگ نیست؟","ro":"In chây kheyli porrang nist?","lit":"ce · thé · très · foncé · n'est pas"},{"fr":"Non, il n'est pas fort du tout.","tgt":"نه، اصلا پررنگ نیست.","ro":"Na, aslan porrang nist.","lit":"non · du tout · foncé · n'est pas"},{"fr":"Nous n'avons pas de lait.","tgt":"ما شیر نداریم.","ro":"Mâ shir nadârim.","lit":"nous · lait · [ne… pas] · avons"},{"fr":"Je ne mange rien le matin.","tgt":"من صبح‌ها چیزی نمی‌خورم.","ro":"Man sobhhâ chizi nemikhoram.","lit":"moi · matins · quelque chose · [ne… pas] · mange"},{"fr":"Mon frère ne boit pas de thé.","tgt":"برادرم چای نمی‌خورد.","ro":"Barâdaram chây nemikhorad.","lit":"frère-mon · thé · [ne… pas] · boit"},{"fr":"Pas de problème, ça ne fait rien.","tgt":"اشکالی ندارد.","ro":"Eshkâli nadârad.","lit":"problème · [ne… pas] · a"}],"tip":{"title":"« Nist » et « na- » : la négation","example":"Je ne suis pas fatigué. — من خسته <b>نیستم</b>.","body":"En persan, la négation tient en un seul petit morceau collé au verbe, alors qu'en français on a besoin de deux mots, ne et pas. Pour le verbe être, on remplace « hast » par « nist » : « nistam », je ne suis pas, « nisti », tu n'es pas, « nist », il n'est pas. Décomposons « Man khaste nistam » : « man », moi, « khaste », fatigué, « nistam », ne suis pas. Pour les autres verbes, on ajoute « na- » devant : « dârim », nous avons, devient « nadârim », nous n'avons pas. Devant le petit « mi- » du présent, ce « na- » se transforme en « ne- » : « mikhoram », je bois, devient « nemikhoram », je ne bois pas. Une chose importante à l'oral : la voix appuie toujours sur la négation, on dit « NA-dârim » et « NE-mikhoram », ce qui la rend bien audible. Astuce : le mot non se dit justement « na », c'est la même petite syllabe qui dit non devant le verbe.","exampleRo":"Man khaste nistam.","lit":"moi · fatigué · ne suis pas","say":{"Nist":"نیست","hast":"هست","nist":"نیست","nistam":"نیستم","nisti":"نیستی","Man khaste nistam":"من خسته نیستم","man":"من","khaste":"خسته","dârim":"داریم","nadârim":"نداریم","mikhoram":"می‌خورم","nemikhoram":"نمی‌خورم","NA-dârim":"نداریم","NE-mikhoram":"نمی‌خورم"}}},{"title":"Découvrir le quartier","phrases":[{"fr":"Est-ce que vous êtes français ?","tgt":"آیا شما فرانسوی هستید؟","ro":"Âyâ shomâ farânsavi hastid?","lit":"[question] · vous · français · êtes"},{"fr":"Vous habitez dans ce quartier ?","tgt":"شما در این محله زندگی می‌کنید؟","ro":"Shomâ dar in mahalle zendegi mikonid?","lit":"vous · dans · ce · quartier · vie · faites"},{"fr":"Est-ce qu'il y a une pharmacie près d'ici ?","tgt":"آیا این نزدیکی داروخانه هست؟","ro":"Âyâ in nazdiki dârukhâne hast?","lit":"[question] · ce · proximité · pharmacie · est"},{"fr":"Oui, il y a une pharmacie au bout de la rue.","tgt":"بله، ته خیابان یک داروخانه هست.","ro":"Bale, tah-e khiyâbân yek dârukhâne hast.","lit":"oui · bout · [de] · rue · une · pharmacie · est"},{"fr":"Le parc est loin ?","tgt":"پارک دور است؟","ro":"Pârk dur ast?","lit":"parc · loin · est"},{"fr":"Non, il est tout près.","tgt":"نه، خیلی نزدیک است.","ro":"Na, kheyli nazdik ast.","lit":"non · très · proche · est"},{"fr":"Est-ce que le supermarché est ouvert ?","tgt":"آیا سوپرمارکت باز است؟","ro":"Âyâ supermârket bâz ast?","lit":"[question] · supermarché · ouvert · est"},{"fr":"Vous parlez un peu français ?","tgt":"شما کمی فرانسه صحبت می‌کنید؟","ro":"Shomâ kami farânse sohbat mikonid?","lit":"vous · un peu · français · conversation · faites"},{"fr":"Est-ce que ce quartier est calme ?","tgt":"آیا این محله آرام است؟","ro":"Âyâ in mahalle ârâm ast?","lit":"[question] · ce · quartier · calme · est"},{"fr":"Oui, c'est un quartier très calme.","tgt":"بله، محله‌ی خیلی آرامی است.","ro":"Bale, mahalle-ye kheyli ârâmi ast.","lit":"oui · quartier · [de] · très · calme · est"}],"tip":{"title":"« Âyâ » et l'intonation : poser une question","example":"Est-ce que vous êtes français ? — <b>آیا</b> شما فرانسوی هستید؟","body":"Pour transformer une affirmation en question, le persan a deux moyens, et le plus simple est le même qu'en français : faire monter la voix à la fin. « Pârk dur ast » veut dire le parc est loin, et « Pârk dur ast ? », avec la voix qui monte, veut dire le parc est loin ? Le second moyen consiste à placer le petit mot « âyâ » tout au début de la phrase, comme notre est-ce que. Décomposons « Âyâ shomâ farânsavi hastid ? » : « âyâ », est-ce que, « shomâ », vous, « farânsavi », français, « hastid », êtes. L'ordre des mots ne change pas du tout, on ne fait aucune inversion comme dans êtes-vous. Dans la conversation de tous les jours, on utilise surtout l'intonation, et « âyâ » sonne un peu plus soigné. Pour répondre, dites « bale », oui, ou « na », non. Astuce : pensez à « âyâ » comme à un petit drapeau levé qui annonce une question.","exampleRo":"Âyâ shomâ farânsavi hastid?","lit":"[question] · vous · français · êtes","say":{"Âyâ":"آیا","Pârk dur ast":"پارک دور است","Pârk dur ast ?":"پارک دور است؟","âyâ":"آیا","Âyâ shomâ farânsavi hastid ?":"آیا شما فرانسوی هستید؟","shomâ":"شما","farânsavi":"فرانسوی","hastid":"هستید","bale":"بله","na":"نه"}}},{"title":"Le grand bazar de Téhéran","phrases":[{"fr":"Le grand bazar est très animé.","tgt":"بازار بزرگ خیلی شلوغ است.","ro":"Bâzâr-e bozorg kheyli sholugh ast.","lit":"bazar · [de] · grand · très · animé · est"},{"fr":"Je cherche un tapis rouge.","tgt":"من دنبال یک فرش قرمز هستم.","ro":"Man donbâl-e yek farsh-e ghermez hastam.","lit":"moi · suite · [de] · un · tapis · [de] · rouge · suis"},{"fr":"Ce tapis persan est magnifique.","tgt":"این فرش ایرانی خیلی زیباست.","ro":"In farsh-e irâni kheyli zibâst.","lit":"ce · tapis · [de] · iranien · très · beau-est"},{"fr":"J'aime le thé noir.","tgt":"من چای سیاه دوست دارم.","ro":"Man chây-e siyâh dust dâram.","lit":"moi · thé · [de] · noir · ami · ai"},{"fr":"Le safran iranien est célèbre.","tgt":"زعفران ایرانی معروف است.","ro":"Za'farân-e irâni ma'ruf ast.","lit":"safran · [de] · iranien · célèbre · est"},{"fr":"Je voudrais une écharpe bleue.","tgt":"من یک شال آبی می‌خواهم.","ro":"Man yek shâl-e âbi mikhâham.","lit":"moi · une · écharpe · [de] · bleue · veux"},{"fr":"Ces pistaches fraîches sont délicieuses.","tgt":"این پسته‌های تازه خوشمزه هستند.","ro":"In pestehâ-ye tâze khoshmaze hastand.","lit":"ces · pistaches · [de] · fraîches · délicieuses · sont"},{"fr":"Le vieux marchand est très patient.","tgt":"فروشنده‌ی پیر خیلی صبور است.","ro":"Forushande-ye pir kheyli sabur ast.","lit":"marchand · [de] · vieux · très · patient · est"},{"fr":"C'est une jolie boutique.","tgt":"این مغازه‌ی قشنگی است.","ro":"In maghâze-ye ghashangi ast.","lit":"ceci · boutique · [de] · jolie · est"},{"fr":"Il fait chaud dans le vieux bazar.","tgt":"در بازار قدیمی هوا گرم است.","ro":"Dar bâzâr-e ghadimi havâ garm ast.","lit":"dans · bazar · [de] · ancien · air · chaud · est"}],"tip":{"title":"L'ezâfe « -e » : relier le nom et l'adjectif","example":"Je voudrais une écharpe bleue. — من یک <b>شال آبی</b> می‌خواهم.","body":"En persan, comme en français, l'adjectif se place après le nom : on dit écharpe bleue, et non bleue écharpe. Mais entre les deux, on glisse un petit son « e », qu'on appelle l'ezâfe, une sorte de colle qui relie le nom à ce qui le décrit. Décomposons « shâl-e âbi » : « shâl », écharpe, le petit « e » qui fait le lien, puis « âbi », bleue. De même, « bâzâr-e bozorg », le grand bazar, et « farsh-e ghermez », le tapis rouge. Quand le nom se termine déjà par une voyelle, le lien devient « ye » pour que ça reste fluide : « forushande-ye pir », le vieux marchand. Ce « e » est bref et léger, on ne s'y arrête jamais, il s'enchaîne directement avec le mot suivant. Si vous l'oubliez, on vous comprendra quand même, mais avec lui, vous sonnerez tout de suite plus naturel. Astuce : imaginez un petit trait d'union sonore entre le nom et l'adjectif, et dites les deux d'un seul souffle.","exampleRo":"Man yek shâl-e âbi mikhâham.","lit":"moi · une · écharpe · [de] · bleue · veux","say":{"shâl-e âbi":"شال آبی","shâl":"شال","âbi":"آبی","bâzâr-e bozorg":"بازار بزرگ","farsh-e ghermez":"فرش قرمز","forushande-ye pir":"فروشنده‌ی پیر"}}},{"title":"À qui est-ce ?","phrases":[{"fr":"C'est mon livre.","tgt":"این کتاب من است.","ro":"In ketâb-e man ast.","lit":"ceci · livre · [de] · moi · est"},{"fr":"Où est la clé de l'appartement ?","tgt":"کلید آپارتمان کجاست؟","ro":"Kelid-e âpârtemân kojâst?","lit":"clé · [de] · appartement · où-est"},{"fr":"La maison de Reza est grande.","tgt":"خانه‌ی رضا بزرگ است.","ro":"Khâne-ye Rezâ bozorg ast.","lit":"maison · [de] · Reza · grande · est"},{"fr":"Notre rue est très longue.","tgt":"خیابان ما خیلی طولانی است.","ro":"Khiyâbân-e mâ kheyli tulâni ast.","lit":"rue · [de] · nous · très · longue · est"},{"fr":"Tenez, voici votre clé.","tgt":"بفرمایید، این کلید شماست.","ro":"Befarmâyid, in kelid-e shomâst.","lit":"je vous en prie · ceci · clé · [de] · vous-est"},{"fr":"Le père de Sara est médecin.","tgt":"پدر سارا دکتر است.","ro":"Pedar-e Sârâ doktor ast.","lit":"père · [de] · Sara · médecin · est"},{"fr":"La voiture de notre voisin est blanche.","tgt":"ماشین همسایه‌ی ما سفید است.","ro":"Mâshin-e hamsâye-ye mâ sefid ast.","lit":"voiture · [de] · voisin · [de] · nous · blanche · est"},{"fr":"Le téléphone de Thomas est sur la table.","tgt":"گوشی توماس روی میز است.","ro":"Gushi-ye Tomâs ru-ye miz ast.","lit":"téléphone · [de] · Thomas · dessus · [de] · table · est"},{"fr":"Ma chambre est à côté de la cuisine.","tgt":"اتاق من کنار آشپزخانه است.","ro":"Otâgh-e man kenâr-e âshpazkhâne ast.","lit":"chambre · [de] · moi · côté · [de] · cuisine · est"},{"fr":"Comment s'appelle votre ami ?","tgt":"اسم دوست شما چیست؟","ro":"Esm-e dust-e shomâ chist?","lit":"nom · [de] · ami · [de] · vous · quoi-est"}],"tip":{"title":"L'ezâfe du possessif : « ketâb-e man »","example":"C'est mon livre. — این <b>کتاب من</b> است.","body":"Le petit « e » de l'ezâfe, que vous avez rencontré avec les adjectifs, sert aussi à dire à qui appartient quelque chose. Il joue alors le rôle de notre mot de. Pour dire mon livre, le persan dit en réalité le livre de moi : « ketâb-e man ». Décomposons « In ketâb-e man ast » : « in », ceci, « ketâb », livre, « e », de, « man », moi, et « ast », est. On peut ainsi dire « kelid-e shomâ », votre clé, « khiyâbân-e mâ », notre rue, ou avec un prénom, « pedar-e Sârâ », le père de Sara. L'ordre est donc le même qu'en français quand on dit la maison de Reza, « khâne-ye Rezâ », d'abord l'objet, puis le propriétaire. On peut même enchaîner plusieurs liens : « esm-e dust-e shomâ », le nom de l'ami de vous, c'est-à-dire le nom de votre ami. Astuce : chaque fois que vous pensez de en français, glissez un petit « e » entre les deux mots.","exampleRo":"In ketâb-e man ast.","lit":"ceci · livre · [de] · moi · est","say":{"ketâb-e man":"کتاب من","In ketâb-e man ast":"این کتاب من است","in":"این","ketâb":"کتاب","man":"من","ast":"است","kelid-e shomâ":"کلید شما","khiyâbân-e mâ":"خیابان ما","pedar-e Sârâ":"پدر سارا","khâne-ye Rezâ":"خانه‌ی رضا","esm-e dust-e shomâ":"اسم دوست شما"}}},{"title":"Parler de sa famille","phrases":[{"fr":"Ma sœur habite à Paris.","tgt":"خواهرم در پاریس زندگی می‌کند.","ro":"Khâharam dar Pâris zendegi mikonad.","lit":"sœur-ma · dans · Paris · vie · fait"},{"fr":"Ton thé est prêt.","tgt":"چایت آماده است.","ro":"Châyet âmâde ast.","lit":"thé-ton · prêt · est"},{"fr":"Son bureau est près d'ici.","tgt":"دفترش نزدیک اینجاست.","ro":"Daftaresh nazdik-e injâst.","lit":"bureau-son · près · [de] · ici-est"},{"fr":"Mon frère est ingénieur.","tgt":"برادرم مهندس است.","ro":"Barâdaram mohandes ast.","lit":"frère-mon · ingénieur · est"},{"fr":"Comment va ta mère ?","tgt":"مادرت چطور است؟","ro":"Mâdaret chetor ast?","lit":"mère-ta · comment · est"},{"fr":"Ta voiture est neuve ?","tgt":"ماشینت نو است؟","ro":"Mâshinet no ast?","lit":"voiture-ta · neuve · est"},{"fr":"Son fils a cinq ans.","tgt":"پسرش پنج سال دارد.","ro":"Pesaresh panj sâl dârad.","lit":"fils-son · cinq · an · a"},{"fr":"Mon appartement est petit mais joli.","tgt":"آپارتمانم کوچک ولی قشنگ است.","ro":"Âpârtemânam kuchek vali ghashang ast.","lit":"appartement-mon · petit · mais · joli · est"},{"fr":"Son mari travaille au bazar.","tgt":"شوهرش در بازار کار می‌کند.","ro":"Shoharesh dar bâzâr kâr mikonad.","lit":"mari-son · dans · bazar · travail · fait"},{"fr":"Ma clé est dans mon sac.","tgt":"کلیدم در کیفم است.","ro":"Kelidam dar kifam ast.","lit":"clé-ma · dans · sac-mon · est"}],"tip":{"title":"Les pronoms suffixés « -am », « -et », « -esh » : mon, ton, son","example":"Mon frère est ingénieur. — <b>برادرم</b> مهندس است.","body":"À côté de « ketâb-e man », il existe une façon plus courte et très courante de dire mon, ton et son : on colle une petite terminaison à la fin du nom. On ajoute « -am » pour mon ou ma, « -et » pour ton ou ta, et « -esh » pour son ou sa. Ainsi, « barâdar », frère, devient « barâdaram », mon frère, « mâdar », mère, devient « mâdaret », ta mère, et « pesar », fils, devient « pesaresh », son fils. Décomposons « Barâdaram mohandes ast » : « barâdar-am », frère-mon, « mohandes », ingénieur, « ast », est. Contrairement au français, il n'y a ni masculin ni féminin : « -am » sert aussi bien pour mon frère que pour ma sœur, « khâharam ». À l'oral, ces terminaisons sont bien plus fréquentes que la forme longue, qui sert plutôt à insister. On peut même en mettre deux dans une phrase : « Kelidam dar kifam ast », ma clé est dans mon sac. Astuce : « -am » finit par m comme moi, « -et » sonne un peu comme toi, et « -esh » rappelle le chuchotement de quelqu'un dont on parle.","exampleRo":"Barâdaram mohandes ast.","lit":"frère-mon · ingénieur · est","say":{"ketâb-e man":"کتاب من","barâdar":"برادر","barâdaram":"برادرم","mâdar":"مادر","mâdaret":"مادرت","pesar":"پسر","pesaresh":"پسرش","Barâdaram mohandes ast":"برادرم مهندس است","barâdar-am":"برادرم","mohandes":"مهندس","ast":"است","khâharam":"خواهرم","Kelidam dar kifam ast":"کلیدم در کیفم است"}}},{"title":"Au marché aux fruits","phrases":[{"fr":"Ceci est une grenade.","tgt":"این انار است.","ro":"In anâr ast.","lit":"ceci · grenade · est"},{"fr":"Et ça, là-bas, c'est quoi ?","tgt":"و آن چیست؟","ro":"Va ân chist?","lit":"et · cela · quoi-est"},{"fr":"Ces abricots sont très sucrés.","tgt":"این زردآلوها خیلی شیرین هستند.","ro":"In zardâluhâ kheyli shirin hastand.","lit":"ces · abricots · très · sucrés · sont"},{"fr":"Je préfère celui-là.","tgt":"من آن یکی را بیشتر دوست دارم.","ro":"Man ân yeki râ bishtar dust dâram.","lit":"moi · cela · un · [objet] · plus · ami · ai"},{"fr":"Combien coûte ce melon ?","tgt":"این خربزه چند است؟","ro":"In kharboze chand ast?","lit":"ce · melon · combien · est"},{"fr":"Ce marchand-là est très aimable.","tgt":"آن فروشنده خیلی خوش‌اخلاق است.","ro":"Ân forushande kheyli khoshakhlâgh ast.","lit":"ce-là · marchand · très · aimable · est"},{"fr":"Ces pommes-ci ou celles-là ?","tgt":"این سیب‌ها یا آن سیب‌ها؟","ro":"In sibhâ yâ ân sibhâ?","lit":"ces · pommes · ou · ces-là · pommes"},{"fr":"Cette rue est très animée.","tgt":"این خیابان خیلی شلوغ است.","ro":"In khiyâbân kheyli sholugh ast.","lit":"cette · rue · très · animée · est"},{"fr":"Ce n'est pas mon sac, c'est celui-là.","tgt":"این کیف من نیست، آن است.","ro":"In kif-e man nist, ân ast.","lit":"ceci · sac · [de] · moi · n'est pas · cela · est"},{"fr":"Ici c'est cher, là-bas c'est moins cher.","tgt":"اینجا گران است، آنجا ارزان‌تر است.","ro":"Injâ gerân ast, ânjâ arzântar ast.","lit":"ici · cher · est · là-bas · moins cher · est"}],"tip":{"title":"« In » et « ân » : ceci et cela","example":"Ceci est une grenade. — <b>این</b> انار است.","body":"Pour montrer quelque chose, le persan utilise deux petits mots très simples : « in » pour ce qui est proche, ceci, et « ân » pour ce qui est plus loin, cela. Ils se placent devant le nom, comme en français : « in kharboze », ce melon, « ân forushande », ce marchand-là. Décomposons « In anâr ast » : « in », ceci, « anâr », grenade, « ast », est. Bonne nouvelle, ces mots ne changent jamais : pas de masculin ni de féminin, et même au pluriel on garde « in », comme dans « in sibhâ », ces pommes. Seul le nom prend la marque du pluriel, « -hâ ». En ajoutant « -jâ », qui veut dire lieu, on obtient « injâ », ici, et « ânjâ », là-bas. Astuce pour retenir : « in » est court et proche comme le geste de la main qui touche, et « ân », avec son a long, s'étire vers le lointain, comme le bras qui montre au loin.","exampleRo":"In anâr ast.","lit":"ceci · grenade · est","say":{"In":"این","ân":"آن","in":"این","in kharboze":"این خربزه","ân forushande":"آن فروشنده","In anâr ast":"این انار است","anâr":"انار","ast":"است","in sibhâ":"این سیب‌ها","injâ":"اینجا","ânjâ":"آنجا","-hâ":"ها","-jâ":"جا"}}},{"title":"Les courses de la semaine","phrases":[{"fr":"Un kilo de tomates, s'il vous plaît.","tgt":"یک کیلو گوجه، لطفا.","ro":"Yek kilo gowje, lotfan.","lit":"un · kilo · tomate · s'il vous plaît"},{"fr":"Deux pains sangak, s'il vous plaît.","tgt":"دو نان سنگک، لطفا.","ro":"Do nân-e sangak, lotfan.","lit":"deux · pain · [de] · sangak · s'il vous plaît"},{"fr":"Il me faut trois kilos de riz.","tgt":"سه کیلو برنج لازم دارم.","ro":"Se kilo berenj lâzem dâram.","lit":"trois · kilo · riz · nécessaire · ai"},{"fr":"Je prends quatre bouteilles d'eau.","tgt":"چهار بطری آب برمی‌دارم.","ro":"Chahâr botri âb barmidâram.","lit":"quatre · bouteille · eau · prends"},{"fr":"Cinq œufs, ça suffit.","tgt":"پنج تخم‌مرغ کافی است.","ro":"Panj tokhm-e morgh kâfi ast.","lit":"cinq · œuf · [de] · poule · suffisant · est"},{"fr":"Six oranges, s'il vous plaît.","tgt":"شش پرتقال، لطفا.","ro":"Shesh porteghâl, lotfan.","lit":"six · orange · s'il vous plaît"},{"fr":"Le magasin ouvre à sept heures.","tgt":"مغازه ساعت هفت باز می‌شود.","ro":"Maghâze sâ'at-e haft bâz mishavad.","lit":"magasin · heure · [de] · sept · ouvert · devient"},{"fr":"La fille de la voisine a huit ans.","tgt":"دختر همسایه هشت سال دارد.","ro":"Dokhtar-e hamsâye hasht sâl dârad.","lit":"fille · [de] · voisine · huit · an · a"},{"fr":"Ça fait neuf mille tomans.","tgt":"می‌شود نه هزار تومان.","ro":"Mishavad noh hezâr tomân.","lit":"devient · neuf · mille · toman"},{"fr":"Un, deux, trois, jusqu'à dix !","tgt":"یک، دو، سه، تا ده!","ro":"Yek, do, se, tâ dah!","lit":"un · deux · trois · jusqu'à · dix"}],"tip":{"title":"Compter de un à dix : « yek », « do », « se »","example":"Il me faut trois kilos de riz. — <b>سه</b> کیلو برنج لازم دارم.","body":"Les chiffres persans sont courts et, pour certains, étonnamment familiers à l'oreille d'un francophone. On compte « yek, do, se », un, deux, trois, puis quatre se dit « tcha-hâr », en deux syllabes, et l'on continue avec « panj, shesh, haft, hasht, noh, dah », jusqu'à dix. Écoutez bien : « do » ressemble à deux, « shesh » rappelle six, « noh » rappelle neuf, et « dah » est un lointain cousin de dix. Retenez une règle très pratique : après un nombre, le nom reste au singulier. On dit donc « se kilo berenj », littéralement trois kilo riz, sans aucun pluriel. Décomposons « Se kilo berenj lâzem dâram » : « se », trois, « kilo », kilo, « berenj », riz, « lâzem », nécessaire, « dâram », j'ai, autrement dit il me faut trois kilos de riz. Au marché, ajoutez simplement « lotfan », s'il vous plaît, après votre nombre. Astuce : entraînez-vous à compter à voix haute en montant les escaliers de votre immeuble, une marche, un chiffre.","exampleRo":"Se kilo berenj lâzem dâram.","lit":"trois · kilo · riz · nécessaire · ai","say":{"yek":"یک","do":"دو","se":"سه","yek, do, se":"یک، دو، سه","tcha-hâr":"چهار","panj, shesh, haft, hasht, noh, dah":"پنج، شش، هفت، هشت، نه، ده","shesh":"شش","noh":"نه","dah":"ده","se kilo berenj":"سه کیلو برنج","Se kilo berenj lâzem dâram":"سه کیلو برنج لازم دارم","kilo":"کیلو","berenj":"برنج","lâzem":"لازم","dâram":"دارم","lotfan":"لطفاً"}}},{"title":"S'installer pour de bon","phrases":[{"fr":"J'ai un petit appartement.","tgt":"من یک آپارتمان کوچک دارم.","ro":"Man yek âpârtemân-e kuchek dâram.","lit":"moi · un · appartement · [de] · petit · ai"},{"fr":"Je n'ai pas de télévision.","tgt":"من تلویزیون ندارم.","ro":"Man televiziyon nadâram.","lit":"moi · télévision · [ne… pas] · ai"},{"fr":"Vous avez internet chez vous ?","tgt":"شما در خانه اینترنت دارید؟","ro":"Shomâ dar khâne internet dârid?","lit":"vous · dans · maison · internet · avez"},{"fr":"Nous avons deux chambres.","tgt":"ما دو اتاق خواب داریم.","ro":"Mâ do otâgh-e khâb dârim.","lit":"nous · deux · chambre · [de] · sommeil · avons"},{"fr":"L'appartement a un grand balcon.","tgt":"آپارتمان یک بالکن بزرگ دارد.","ro":"Âpârtemân yek bâlkon-e bozorg dârad.","lit":"appartement · un · balcon · [de] · grand · a"},{"fr":"Je n'ai pas encore de rideaux.","tgt":"هنوز پرده ندارم.","ro":"Hanuz parde nadâram.","lit":"encore · rideau · [ne… pas] · ai"},{"fr":"Tu as un marteau ?","tgt":"تو چکش داری؟","ro":"To chakosh dâri?","lit":"toi · marteau · as"},{"fr":"Il n'a pas la clé.","tgt":"او کلید ندارد.","ro":"U kelid nadârad.","lit":"lui · clé · [ne… pas] · a"},{"fr":"Ils ont un beau tapis.","tgt":"آن‌ها یک فرش قشنگ دارند.","ro":"Ânhâ yek farsh-e ghashang dârand.","lit":"eux · un · tapis · [de] · beau · ont"},{"fr":"La cuisine n'a pas de fenêtre.","tgt":"آشپزخانه پنجره ندارد.","ro":"Âshpazkhâne panjare nadârad.","lit":"cuisine · fenêtre · [ne… pas] · a"}],"tip":{"title":"« Dâram » et « nadâram » : avoir et ne pas avoir","example":"Je n'ai pas de télévision. — من تلویزیون <b>ندارم</b>.","body":"Le verbe avoir est l'un des plus utiles au quotidien, et il se conjugue avec les terminaisons que vous connaissez déjà : « dâram », j'ai, « dâri », tu as, « dârad », il a, « dârim », nous avons, « dârid », vous avez, « dârand », ils ont. Particularité à retenir : contrairement aux autres verbes, il ne prend pas le petit « mi- » au présent, on dit simplement « dâram ». Pour la négation, on ajoute « na- » devant : « nadâram », je n'ai pas, « nadârad », il n'a pas. Décomposons « Man televiziyon nadâram » : « man », moi, « televiziyon », télévision, « nadâram », je n'ai pas. Remarquez qu'il n'y a pas d'équivalent de notre de dans je n'ai pas de télévision, on pose simplement le nom devant le verbe. À l'oral, la voix appuie sur le « na », ce qui rend la réponse négative très claire. Astuce : retenez la paire « dâram, nadâram » comme un petit refrain, j'ai, je n'ai pas, et répétez-la en faisant l'inventaire de votre appartement.","exampleRo":"Man televiziyon nadâram.","lit":"moi · télévision · [ne… pas] · ai","say":{"Dâram":"دارم","nadâram":"ندارم","dâram":"دارم","dâri":"داری","dârad":"دارد","dârim":"داریم","dârid":"دارید","dârand":"دارند","nadârad":"ندارد","Man televiziyon nadâram":"من تلویزیون ندارم","man":"من","televiziyon":"تلویزیون","dâram, nadâram":"دارم، ندارم"}}},{"title":"Dans le métro de Téhéran","phrases":[{"fr":"Où se trouve la station de métro ?","tgt":"ایستگاه مترو کجاست؟","ro":"Istgâh-e metro kojâst?","lit":"station · [de] · métro · où-est"},{"fr":"Quand part le prochain train ?","tgt":"قطار بعدی کی حرکت می‌کند؟","ro":"Ghatâr-e ba'di key harekat mikonad?","lit":"train · [de] · suivant · quand · départ · fait"},{"fr":"Qui est ce monsieur, là-bas ?","tgt":"آن آقا کیست؟","ro":"Ân âghâ kist?","lit":"ce · monsieur · qui-est"},{"fr":"Comment s'appelle cette station ?","tgt":"اسم این ایستگاه چیست؟","ro":"Esm-e in istgâh chist?","lit":"nom · [de] · cette · station · quoi-est"},{"fr":"Vous allez où, madame ?","tgt":"خانم، کجا می‌روید؟","ro":"Khânom, kojâ miravid?","lit":"madame · où · allez"},{"fr":"Qu'est-ce que vous cherchez ?","tgt":"دنبال چی هستید؟","ro":"Donbâl-e chi hastid?","lit":"suite · [de] · quoi · êtes"},{"fr":"Qui vient avec nous ?","tgt":"کی با ما می‌آید؟","ro":"Ki bâ mâ miâyad?","lit":"qui · avec · nous · vient"},{"fr":"Quand est-ce que vous arrivez ?","tgt":"کی می‌رسید؟","ro":"Key miresid?","lit":"quand · arrivez"},{"fr":"La sortie, c'est par où ?","tgt":"خروجی کجاست؟","ro":"Khoruji kojâst?","lit":"sortie · où-est"},{"fr":"Qu'est-ce que c'est, cette carte ?","tgt":"این کارت چیست؟","ro":"In kârt chist?","lit":"cette · carte · quoi-est"}],"tip":{"title":"Les mots interrogatifs : « kojâ », « chi », « ki », « key »","example":"Vous allez où, madame ? — خانم، <b>کجا</b> می‌روید؟","body":"Quatre petits mots suffisent pour poser la plupart des questions : « kojâ », où, « chi », quoi, « ki », qui, et « key », quand. Le mot « chi » est la forme parlée de tous les jours, celle que vous entendrez partout à Téhéran. Le plus étonnant pour un francophone, c'est que le mot interrogatif reste à la place où se trouverait la réponse, sans rien inverser. On dit ainsi « Ghatâr-e ba'di key harekat mikonad ? », littéralement le train suivant quand part ?, avec « key » au milieu de la phrase. Décomposons « Khânom, kojâ miravid ? » : « khânom », madame, « kojâ », où, et « miravid », vous allez. Avec le verbe être, ces mots se soudent souvent à « ast » : « kojâst », où est, « chist », qu'est-ce que c'est, « kist », qui est-ce. Attention à bien distinguer « ki », qui, avec un i bref, et « key », quand, qui se termine comme le mot paye. Astuce : « kojâ » sonne comme une petite question qu'on lance en levant les yeux pour chercher son chemin.","exampleRo":"Khânom, kojâ miravid?","lit":"madame · où · allez","say":{"kojâ":"کجا","chi":"چی","ki":"کی","key":"کی","Ghatâr-e ba'di key harekat mikonad ?":"قطار بعدی کی حرکت می‌کند؟","Khânom, kojâ miravid ?":"خانم، کجا می‌روید؟","khânom":"خانم","miravid":"می‌روید","ast":"است","kojâst":"کجاست","chist":"چیست","kist":"کیست"}}},{"title":"Le marché aux épices","phrases":[{"fr":"Combien coûte le safran ?","tgt":"زعفران چند است؟","ro":"Za'farân chand ast?","lit":"safran · combien · est"},{"fr":"Je veux deux paquets de thé.","tgt":"دو تا بسته چای می‌خواهم.","ro":"Do tâ baste chây mikhâham.","lit":"deux · [unités] · paquet · thé · veux"},{"fr":"Combien de paquets voulez-vous ?","tgt":"چند تا بسته می‌خواهید؟","ro":"Chand tâ baste mikhâhid?","lit":"combien · [unités] · paquet · voulez"},{"fr":"Cinq, s'il vous plaît.","tgt":"پنج تا، لطفا.","ro":"Panj tâ, lotfan.","lit":"cinq · [unités] · s'il vous plaît"},{"fr":"Combien d'enfants avez-vous ?","tgt":"چند تا بچه دارید؟","ro":"Chand tâ bachche dârid?","lit":"combien · [unités] · enfant · avez"},{"fr":"J'ai deux enfants, un fils et une fille.","tgt":"دو تا بچه دارم، یک پسر و یک دختر.","ro":"Do tâ bachche dâram, yek pesar o yek dokhtar.","lit":"deux · [unités] · enfant · ai · un · fils · et · une · fille"},{"fr":"En tout, ça fait combien ?","tgt":"روی هم چند می‌شود؟","ro":"Ru-ye ham chand mishavad?","lit":"dessus · [de] · ensemble · combien · devient"},{"fr":"Ça fait trois cent mille tomans.","tgt":"می‌شود سیصد هزار تومان.","ro":"Mishavad sisad hezâr tomân.","lit":"devient · trois cents · mille · toman"},{"fr":"Je prends quatre grenades.","tgt":"چهار تا انار برمی‌دارم.","ro":"Chahâr tâ anâr barmidâram.","lit":"quatre · [unités] · grenade · prends"},{"fr":"Vous restez combien de temps à Téhéran ?","tgt":"چند وقت در تهران می‌مانید؟","ro":"Chand vaght dar Tehrân mimânid?","lit":"combien · temps · dans · Téhéran · restez"}],"tip":{"title":"« Chand » et « tâ » : combien, et le petit mot pour compter","example":"Combien de paquets voulez-vous ? — <b>چند تا</b> بسته می‌خواهید؟","body":"Pour demander combien, on utilise « chand », un mot que vous entendrez dix fois par jour au bazar : « Za'farân chand ast ? », combien coûte le safran ? Quand on compte des objets ou des personnes, les Iraniens glissent très souvent un petit mot entre le nombre et le nom : « tâ », qui veut dire à peu près unité ou pièce. On dit ainsi « do tâ baste », deux paquets, ou « chand tâ bachche », combien d'enfants. Décomposons « Chand tâ baste mikhâhid ? » : « chand », combien, « tâ », unités, « baste », paquet, « mikhâhid », vous voulez. Comme après tous les nombres, le nom reste au singulier, on ne dit jamais paquets au pluriel. Le mot « tâ » est surtout typique de la langue parlée, et il permet même de répondre sans répéter le nom : « Panj tâ », cinq, tout simplement. Astuce : pensez à « tâ » comme à un petit doigt qu'on lève pour compter, il accompagne presque chaque chiffre au marché.","exampleRo":"Chand tâ baste mikhâhid?","lit":"combien · [unités] · paquet · voulez","say":{"Chand":"چند","tâ":"تا","chand":"چند","Za'farân chand ast ?":"زعفران چند است؟","do tâ baste":"دو تا بسته","chand tâ bachche":"چند تا بچه","Chand tâ baste mikhâhid ?":"چند تا بسته می‌خواهید؟","baste":"بسته","mikhâhid":"می‌خواهید","Panj tâ":"پنج تا"}}},{"title":"L'heure et les horaires","phrases":[{"fr":"Pardon, quelle heure est-il ?","tgt":"ببخشید، ساعت چند است؟","ro":"Bebakhshid, sâ'at chand ast?","lit":"pardon · heure · combien · est"},{"fr":"Il est quelle heure ?","tgt":"ساعت چنده؟","ro":"Sâ'at chande?","lit":"heure · combien-est"},{"fr":"Il est huit heures.","tgt":"ساعت هشت است.","ro":"Sâ'at hasht ast.","lit":"heure · huit · est"},{"fr":"Il est neuf heures et demie.","tgt":"ساعت نه و نیم است.","ro":"Sâ'at noh o nim ast.","lit":"heure · neuf · et · demi · est"},{"fr":"Je vais au bureau à sept heures.","tgt":"من ساعت هفت به اداره می‌روم.","ro":"Man sâ'at-e haft be edâre miravam.","lit":"moi · heure · [de] · sept · [à] · bureau · vais"},{"fr":"Notre réunion est à dix heures.","tgt":"جلسه‌ی ما ساعت ده است.","ro":"Jalase-ye mâ sâ'at-e dah ast.","lit":"réunion · [de] · nous · heure · [de] · dix · est"},{"fr":"Je rentre à cinq heures et quart.","tgt":"ساعت پنج و ربع به خانه برمی‌گردم.","ro":"Sâ'at-e panj o rob' be khâne barmigardam.","lit":"heure · [de] · cinq · et · quart · [à] · maison · reviens"},{"fr":"Il est dix heures moins le quart.","tgt":"یک ربع به ده است.","ro":"Yek rob' be dah ast.","lit":"un · quart · [à] · dix · est"},{"fr":"Le métro arrive dans cinq minutes.","tgt":"مترو پنج دقیقه‌ی دیگر می‌رسد.","ro":"Metro panj daghighe-ye digar miresad.","lit":"métro · cinq · minute · [de] · autre · arrive"},{"fr":"Il est sept heures du soir.","tgt":"ساعت هفت شب است.","ro":"Sâ'at haft-e shab ast.","lit":"heure · sept · [de] · nuit · est"}],"tip":{"title":"L'heure : « sâ'at chande ? »","example":"Il est quelle heure ? — <b>ساعت چنده</b>؟","body":"Pour demander l'heure, le persan dit littéralement l'heure est combien : « sâ'at chand ast ? ». Dans la rue, à Téhéran, les deux derniers mots se fondent en un seul et l'on entend presque toujours « sâ'at chande ? », plus court et plus naturel. Pour répondre, on reprend simplement le même moule : « Sâ'at hasht ast », il est huit heures, littéralement l'heure huit est. Décomposons « Sâ'at chande ? » : « sâ'at », heure, et « chande », combien est. Pour la demie, on ajoute « o nim », et demi, et pour le quart, « o rob' » : « sâ'at noh o nim », neuf heures et demie. Pour dire moins le quart, on compte à l'envers avec « be » : « yek rob' be dah », un quart vers dix, c'est-à-dire dix heures moins le quart. Enfin, pour dire à huit heures, on relie avec l'ezâfe : « sâ'at-e hasht ». Astuce : retenez « chande ? » comme une petite chanson montante, c'est la question que tout le monde pose dans le métro.","exampleRo":"Sâ'at chande?","lit":"heure · combien-est","say":{"sâ'at chande ?":"ساعت چنده؟","sâ'at chand ast ?":"ساعت چند است؟","Sâ'at hasht ast":"ساعت هشت است","Sâ'at chande ?":"ساعت چنده؟","sâ'at":"ساعت","chande":"چنده","o nim":"و نیم","o rob'":"و ربع","sâ'at noh o nim":"ساعت نه و نیم","be":"به","yek rob' be dah":"یک ربع به ده","sâ'at-e hasht":"ساعت هشت","chande ?":"چنده؟"}}},{"title":"Une journée de travail","phrases":[{"fr":"Je prends le métro pour aller au bureau.","tgt":"من با مترو به اداره می‌روم.","ro":"Man bâ metro be edâre miravam.","lit":"moi · avec · métro · [à] · bureau · vais"},{"fr":"Je mange à midi avec mes collègues.","tgt":"ظهر با همکارانم غذا می‌خورم.","ro":"Zohr bâ hamkârânam ghazâ mikhoram.","lit":"midi · avec · collègues-mes · repas · mange"},{"fr":"Tu travailles où, toi ?","tgt":"تو کجا کار می‌کنی؟","ro":"To kojâ kâr mikoni?","lit":"toi · où · travail · fais"},{"fr":"Elle parle très bien français.","tgt":"او خیلی خوب فرانسه صحبت می‌کند.","ro":"U kheyli khub farânse sohbat mikonad.","lit":"elle · très · bien · français · conversation · fait"},{"fr":"Nous buvons du thé à dix heures.","tgt":"ما ساعت ده چای می‌خوریم.","ro":"Mâ sâ'at-e dah chây mikhorim.","lit":"nous · heure · [de] · dix · thé · buvons"},{"fr":"Mon collègue arrive toujours en retard.","tgt":"همکارم همیشه دیر می‌آید.","ro":"Hamkâram hamishe dir miâyad.","lit":"collègue-mon · toujours · tard · vient"},{"fr":"Je lis mes e-mails le matin.","tgt":"صبح‌ها ایمیل‌هایم را می‌خوانم.","ro":"Sobhhâ imeylhâyam râ mikhânam.","lit":"matins · e-mails-mes · [objet] · lis"},{"fr":"Ils rentrent à six heures.","tgt":"آن‌ها ساعت شش به خانه برمی‌گردند.","ro":"Ânhâ sâ'at-e shesh be khâne barmigardand.","lit":"eux · heure · [de] · six · [à] · maison · reviennent"},{"fr":"Vous comprenez le persan ?","tgt":"شما فارسی می‌فهمید؟","ro":"Shomâ fârsi mifahmid?","lit":"vous · persan · comprenez"},{"fr":"Je comprends un peu.","tgt":"کمی می‌فهمم.","ro":"Kami mifahmam.","lit":"un peu · comprends"}],"tip":{"title":"Le présent avec « mi- » : « miravam », « mikhoram »","example":"Je prends le métro pour aller au bureau. — من با مترو به اداره <b>می‌روم</b>.","body":"Pour parler de ce que l'on fait maintenant ou d'habitude, le persan utilise une recette toujours identique : le petit préfixe « mi- », puis la racine du verbe, puis la terminaison de la personne. Avec la racine « rav », aller, on obtient « miravam », je vais, « miravi », tu vas, « miravad », il va. Avec « khor », manger ou boire, on dit « mikhoram », je mange, et « mikhorim », nous mangeons. Décomposons « Man bâ metro be edâre miravam » : « man », moi, « bâ metro », avec le métro, « be edâre », au bureau, et « miravam », je vais, bien à la fin. Les terminaisons sont celles que vous connaissez déjà avec « hastam » : « -am, -i, -ad, -im, -id, -and ». À l'oral, la voix appuie volontiers sur le « mi », ce qui vous aide à reconnaître le présent à l'oreille. Ce même présent sert aussi pour un futur proche, comme notre je pars demain. Astuce : pensez au « mi » comme à un moteur qui se met en marche, l'action est en cours.","exampleRo":"Man bâ metro be edâre miravam.","lit":"moi · avec · métro · [à] · bureau · vais","say":{"miravam":"می‌روم","mikhoram":"می‌خورم","miravi":"می‌روی","miravad":"می‌رود","mikhorim":"می‌خوریم","Man bâ metro be edâre miravam":"من با مترو به اداره می‌روم","man":"من","bâ metro":"با مترو","be edâre":"به اداره","hastam":"هستم"}}},{"title":"Une pause au salon de thé","phrases":[{"fr":"Je voudrais un thé, s'il vous plaît.","tgt":"یک چای می‌خواهم، لطفا.","ro":"Yek chây mikhâham, lotfan.","lit":"un · thé · veux · s'il vous plaît"},{"fr":"Qu'est-ce que vous voulez ?","tgt":"شما چه می‌خواهید؟","ro":"Shomâ che mikhâhid?","lit":"vous · quoi · voulez"},{"fr":"Je voudrais un verre d'eau.","tgt":"یک لیوان آب می‌خواهم.","ro":"Yek livân âb mikhâham.","lit":"un · verre · eau · veux"},{"fr":"Nous voulons deux thés et des dattes.","tgt":"ما دو چای و خرما می‌خواهیم.","ro":"Mâ do chây o khormâ mikhâhim.","lit":"nous · deux · thé · et · datte · voulons"},{"fr":"Tu veux un sucre ?","tgt":"قند می‌خواهی؟","ro":"Ghand mikhâhi?","lit":"sucre · veux"},{"fr":"Non merci, je ne veux pas de sucre.","tgt":"نه ممنون، قند نمی‌خواهم.","ro":"Na mamnun, ghand nemikhâham.","lit":"non · merci · sucre · [ne… pas] · veux"},{"fr":"Il veut un gâteau au safran.","tgt":"او یک کیک زعفرانی می‌خواهد.","ro":"U yek keyk-e za'farâni mikhâhad.","lit":"lui · un · gâteau · [de] · safrané · veut"},{"fr":"Je voudrais l'addition.","tgt":"صورت‌حساب را می‌خواهم.","ro":"Surat hesâb râ mikhâham.","lit":"addition · [objet] · veux"},{"fr":"Elle veut un thé bien chaud.","tgt":"او یک چای داغ می‌خواهد.","ro":"U yek chây-e dâgh mikhâhad.","lit":"elle · un · thé · [de] · brûlant · veut"},{"fr":"Vous voulez autre chose ?","tgt":"چیز دیگری می‌خواهید؟","ro":"Chiz-e digari mikhâhid?","lit":"chose · [de] · autre · voulez"}],"tip":{"title":"« Mikhâham » : je veux, suivi d'un nom","example":"Je voudrais un verre d'eau. — یک لیوان آب <b>می‌خواهم</b>.","body":"Pour commander ou demander quelque chose, un seul verbe vous suffit : « mikhâham », je veux. Il suit la recette du présent, avec « mi- » devant et la terminaison à la fin : « mikhâhi », tu veux, « mikhâhad », il veut, « mikhâhim », nous voulons, « mikhâhid », vous voulez. Comme tous les verbes, il se place à la fin, et l'objet désiré vient juste avant. Décomposons « Yek livân âb mikhâham » : « yek », un, « livân », verre, « âb », eau, « mikhâham », je veux. En français, je veux peut sembler un peu direct, mais en persan c'est tout à fait poli, surtout si vous ajoutez « lotfan », s'il vous plaît, à la fin. Pour refuser gentiment, mettez la négation : « Na mamnun, ghand nemikhâham », non merci, je ne veux pas de sucre. Dans la rue, vous entendrez souvent une forme raccourcie, « mikhâm », mais la forme complète est toujours comprise. Astuce : imaginez le « khâ » du milieu comme le souffle de quelqu'un qui a très envie de son thé.","exampleRo":"Yek livân âb mikhâham.","lit":"un · verre · eau · veux","say":{"Mikhâham":"می‌خواهم","mikhâham":"می‌خواهم","mikhâhi":"می‌خواهی","mikhâhad":"می‌خواهد","mikhâhim":"می‌خواهیم","mikhâhid":"می‌خواهید","Yek livân âb mikhâham":"یک لیوان آب می‌خواهم","yek":"یک","livân":"لیوان","âb":"آب","lotfan":"لطفاً","Na mamnun, ghand nemikhâham":"نه ممنون، قند نمی‌خواهم","mikhâm":"می‌خوام"}}},{"title":"Au bureau","phrases":[{"fr":"Je vois le directeur demain.","tgt":"فردا مدیر را می‌بینم.","ro":"Fardâ modir râ mibinam.","lit":"demain · directeur · [objet] · vois"},{"fr":"Je ne trouve pas le dossier bleu.","tgt":"پرونده‌ی آبی را پیدا نمی‌کنم.","ro":"Parvande-ye âbi râ peydâ nemikonam.","lit":"dossier · [de] · bleu · [objet] · trouvé · [ne… pas] · fais"},{"fr":"Vous connaissez madame Ahmadi ?","tgt":"خانم احمدی را می‌شناسید؟","ro":"Khânom-e Ahmadi râ mishenâsid?","lit":"madame · [de] · Ahmadi · [objet] · connaissez"},{"fr":"J'ouvre la fenêtre.","tgt":"پنجره را باز می‌کنم.","ro":"Panjare râ bâz mikonam.","lit":"fenêtre · [objet] · ouvert · fais"},{"fr":"Je lis ce rapport aujourd'hui.","tgt":"امروز این گزارش را می‌خوانم.","ro":"Emruz in gozâresh râ mikhânam.","lit":"aujourd'hui · ce · rapport · [objet] · lis"},{"fr":"J'écris une lettre à mon ami.","tgt":"یک نامه به دوستم می‌نویسم.","ro":"Yek nâme be dustam minevisam.","lit":"une · lettre · [à] · ami-mon · écris"},{"fr":"J'envoie la lettre ce soir.","tgt":"امشب نامه را می‌فرستم.","ro":"Emshab nâme râ miferestam.","lit":"ce soir · lettre · [objet] · envoie"},{"fr":"Je ne vois pas mon téléphone.","tgt":"گوشی‌ام را نمی‌بینم.","ro":"Gushiam râ nemibinam.","lit":"téléphone-mon · [objet] · [ne… pas] · vois"},{"fr":"Mon collègue apporte les gâteaux.","tgt":"همکارم شیرینی‌ها را می‌آورد.","ro":"Hamkâram shirinihâ râ miâvarad.","lit":"collègue-mon · gâteaux · [objet] · apporte"},{"fr":"Nous finissons le travail à cinq heures.","tgt":"ما کار را ساعت پنج تمام می‌کنیم.","ro":"Mâ kâr râ sâ'at-e panj tamâm mikonim.","lit":"nous · travail · [objet] · heure · [de] · cinq · fini · faisons"}],"tip":{"title":"« Râ » : marquer l'objet précis","example":"J'envoie la lettre ce soir. — امشب نامه <b>را</b> می‌فرستم.","body":"Le persan n'a pas d'article comme le ou la, mais il possède un petit mot très précieux : « râ ». On le place juste après l'objet du verbe quand cet objet est précis, connu, bien identifié, un peu comme notre article défini. Comparez « Yek nâme minevisam », j'écris une lettre, une lettre quelconque, et « Emshab nâme râ miferestam », ce soir j'envoie la lettre, celle dont on parle. Décomposons cette seconde phrase : « emshab », ce soir, « nâme », lettre, « râ », la marque de l'objet précis, et « miferestam », j'envoie. On met aussi « râ » après un nom de personne, un objet possédé ou un objet montré : « Khânom-e Ahmadi râ mishenâsid ? », vous connaissez madame Ahmadi ? Dans la conversation à Téhéran, vous entendrez souvent « râ » se transformer en un simple « ro » ou « o » accroché au mot. Astuce : chaque fois que vous diriez le, la ou les devant l'objet en français, pensez à ajouter « râ » juste après lui.","exampleRo":"Emshab nâme râ miferestam.","lit":"ce soir · lettre · [objet] · envoie","say":{"Râ":"را","râ":"را","Yek nâme minevisam":"یک نامه می‌نویسم","Emshab nâme râ miferestam":"امشب نامه را می‌فرستم","emshab":"امشب","nâme":"نامه","miferestam":"می‌فرستم","Khânom-e Ahmadi râ mishenâsid ?":"خانم احمدی را می‌شناسید؟"}}},{"title":"Se déplacer en ville","phrases":[{"fr":"J'habite à Téhéran.","tgt":"من در تهران زندگی می‌کنم.","ro":"Man dar Tehrân zendegi mikonam.","lit":"moi · dans · Téhéran · vie · fais"},{"fr":"Je reviens du bazar.","tgt":"از بازار برمی‌گردم.","ro":"Az bâzâr barmigardam.","lit":"de · bazar · reviens"},{"fr":"On va au parc ce soir.","tgt":"امشب به پارک می‌رویم.","ro":"Emshab be pârk miravim.","lit":"ce soir · [à] · parc · allons"},{"fr":"Le bureau est dans ce bâtiment.","tgt":"دفتر در این ساختمان است.","ro":"Daftar dar in sâkhtemân ast.","lit":"bureau · dans · ce · bâtiment · est"},{"fr":"Je vais à Tajrish en taxi.","tgt":"با تاکسی به تجریش می‌روم.","ro":"Bâ tâksi be Tajrish miravam.","lit":"avec · taxi · [à] · Tajrish · vais"},{"fr":"De chez moi au bureau, il y a vingt minutes.","tgt":"از خانه‌ام تا اداره بیست دقیقه راه است.","ro":"Az khâneam tâ edâre bist daghighe râh ast.","lit":"de · maison-ma · jusqu'à · bureau · vingt · minute · chemin · est"},{"fr":"Le livre est dans le sac.","tgt":"کتاب در کیف است.","ro":"Ketâb dar kif ast.","lit":"livre · dans · sac · est"},{"fr":"Je donne le pain à la voisine.","tgt":"نان را به همسایه می‌دهم.","ro":"Nân râ be hamsâye midaham.","lit":"pain · [objet] · [à] · voisine · donne"},{"fr":"Elle sort de la boulangerie.","tgt":"او از نانوایی بیرون می‌آید.","ro":"U az nânvâyi birun miâyad.","lit":"elle · de · boulangerie · dehors · vient"},{"fr":"Le soir, je téléphone à ma mère.","tgt":"شب‌ها به مادرم زنگ می‌زنم.","ro":"Shabhâ be mâdaram zang mizanam.","lit":"nuits · [à] · mère-ma · sonnerie · frappe"}],"tip":{"title":"Les prépositions de base : « dar », « be », « az »","example":"Je vais à Tajrish en taxi. — با تاکسی <b>به</b> تجریش می‌روم.","body":"Trois petits mots vous permettent de situer presque tout dans l'espace : « dar », dans ou à, « be », vers ou à, et « az », de ou depuis. On utilise « dar » pour l'endroit où l'on se trouve : « Man dar Tehrân zendegi mikonam », j'habite à Téhéran. On utilise « be » pour la direction, l'endroit où l'on va : « be pârk », au parc, et aussi pour la personne à qui l'on donne ou parle : « be mâdaram », à ma mère. Enfin, « az » indique le point de départ : « az bâzâr », du bazar. Décomposons « Bâ tâksi be Tajrish miravam » : « bâ », avec, « tâksi », taxi, « be », vers, « Tajrish », le quartier de Tajrish, et « miravam », je vais. Ces prépositions se placent devant le nom, comme en français, et le verbe garde sa place à la fin. On peut même combiner départ et arrivée avec « az… tâ… », de… jusqu'à… Astuce : « dar » est dedans, « be » est une flèche qui part en avant, et « az » regarde derrière vers le point de départ.","exampleRo":"Bâ tâksi be Tajrish miravam.","lit":"avec · taxi · [à] · Tajrish · vais","say":{"dar":"در","be":"به","az":"از","Man dar Tehrân zendegi mikonam":"من در تهران زندگی می‌کنم","be pârk":"به پارک","be mâdaram":"به مادرم","az bâzâr":"از بازار","Bâ tâksi be Tajrish miravam":"با تاکسی به تجریش می‌روم","bâ":"با","tâksi":"تاکسی","Tajrish":"تجریش","miravam":"می‌روم","az… tâ…":"از... تا..."}}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Mille mercis pour votre aide.","tgt":"خیلی ممنون از کمک شما.","ro":"Kheyli mamnun az komak-e shomâ.","lit":"très · reconnaissant · de · aide · [de] · vous"},{"fr":"Je vous en prie.","tgt":"خواهش می‌کنم.","ro":"Khâhesh mikonam.","lit":"demande · fais"},{"fr":"Excusez-moi, mon persan n'est pas encore très bon.","tgt":"ببخشید، فارسی من هنوز خیلی خوب نیست.","ro":"Bebakhshid, fârsi-ye man hanuz kheyli khub nist.","lit":"pardonnez · persan · [de] · moi · encore · très · bon · n'est pas"},{"fr":"Merci, et à vous de même.","tgt":"مرسی، همچنین.","ro":"Mersi, hamchenin.","lit":"merci · de même"},{"fr":"J'apprends le persan chaque jour.","tgt":"من هر روز فارسی یاد می‌گیرم.","ro":"Man har ruz fârsi yâd migiram.","lit":"moi · chaque · jour · persan · souvenir · prends"},{"fr":"Le persan est une belle langue.","tgt":"فارسی زبان قشنگی است.","ro":"Fârsi zabân-e ghashangi ast.","lit":"persan · langue · [de] · belle · est"},{"fr":"Maintenant, je compte jusqu'à dix en persan.","tgt":"حالا تا ده به فارسی می‌شمارم.","ro":"Hâlâ tâ dah be fârsi mishomâram.","lit":"maintenant · jusqu'à · dix · [à] · persan · compte"},{"fr":"Pardon, vous pouvez répéter ?","tgt":"ببخشید، می‌شود تکرار کنید؟","ro":"Bebakhshid, mishavad tekrâr konid?","lit":"pardonnez · devient · répétition · fassiez"},{"fr":"Merci, c'est très gentil à vous.","tgt":"ممنون، شما خیلی لطف دارید.","ro":"Mamnun, shomâ kheyli lotf dârid.","lit":"merci · vous · très · gentillesse · avez"},{"fr":"Au revoir, à la prochaine leçon !","tgt":"خداحافظ، تا درس بعدی!","ro":"Khodâhâfez, tâ dars-e ba'di!","lit":"au revoir · jusqu'à · leçon · [de] · suivante"}],"tip":{"title":"Les formules magiques : « mersi », « mamnun », « bebakhshid », « khâhesh mikonam »","example":"Je vous en prie. — <b>خواهش می‌کنم</b>.","body":"Pour terminer ce premier module, voici les formules qui ouvrent toutes les portes en Iran, où la politesse compte énormément. Pour remercier, vous avez le choix entre « mersi », emprunté au français et très courant à Téhéran, et « mamnun », un peu plus chaleureux ; « kheyli mamnun » veut dire merci beaucoup. Pour vous excuser ou attirer l'attention de quelqu'un, dites « bebakhshid », pardon ou excusez-moi, en appuyant sur la dernière syllabe. La formule la plus étonnante est « khâhesh mikonam », qui veut dire à la fois s'il vous plaît et je vous en prie, en réponse à un merci. Décomposons-la : « khâhesh », demande polie, et « mikonam », je fais, littéralement je fais une demande. Pour un compliment, on répond souvent « shomâ lotf dârid », vous avez de la gentillesse, c'est très gentil à vous. Astuce : glissez « bebakhshid » au début et « mersi » à la fin de chaque échange, et vous serez déjà accueilli avec un grand sourire.","exampleRo":"Khâhesh mikonam.","lit":"demande · fais","say":{"mersi":"مرسی","mamnun":"ممنون","bebakhshid":"ببخشید","khâhesh mikonam":"خواهش می‌کنم","kheyli mamnun":"خیلی ممنون","khâhesh":"خواهش","mikonam":"می‌کنم","shomâ lotf dârid":"شما لطف دارید"}}}]},{"id":2,"name":"En voyage","desc":"Se déplacer, découvrir et gérer les imprévus en Iran.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à la gare routière d'Ispahan","phrases":[{"fr":"Bonjour, nous sommes à Ispahan.","tgt":"سلام، ما در اصفهان هستیم.","ro":"Salâm, mâ dar Esfahân hastim.","lit":"salut · nous · dans · Ispahan · sommes"},{"fr":"Ce terminal est très grand.","tgt":"این ترمینال خیلی بزرگ است.","ro":"In terminâl kheyli bozorg ast.","lit":"ce · terminal · très · grand · est"},{"fr":"Pardon, la sortie, c'est par où ?","tgt":"ببخشید، خروجی کجاست؟","ro":"Bebakhshid, khoruji kojâst?","lit":"excusez · sortie · où-est"},{"fr":"La sortie est de ce côté-là.","tgt":"خروجی آن طرف است.","ro":"Khoruji ân taraf ast.","lit":"sortie · ce · côté · est"},{"fr":"Mon sac est très lourd.","tgt":"کیفم خیلی سنگین است.","ro":"Kifam kheyli sangin ast.","lit":"sac-mon · très · lourd · est"},{"fr":"Où sont les taxis ?","tgt":"تاکسی‌ها کجا هستند؟","ro":"Tâksihâ kojâ hastand?","lit":"taxis · où · sont"},{"fr":"Les taxis sont devant la porte.","tgt":"تاکسی‌ها جلوی در هستند.","ro":"Tâksihâ jelo-ye dar hastand.","lit":"taxis · devant · [de] · porte · sont"},{"fr":"Vous avez une bouteille d'eau ?","tgt":"یک بطری آب دارید؟","ro":"Yek botri âb dârid?","lit":"une · bouteille · eau · avez"},{"fr":"Oui, voici de l'eau bien fraîche.","tgt":"بله، بفرمایید، آب خنک.","ro":"Bale, befarmâyid, âb-e khonak.","lit":"oui · je-vous-en-prie · eau · [de] · fraîche"},{"fr":"Ispahan est vraiment belle.","tgt":"اصفهان خیلی زیباست.","ro":"Esfahân kheyli zibâst.","lit":"Ispahan · très · belle-est"}]},{"title":"Des billets de bus pour Kashan","phrases":[{"fr":"Je voudrais un billet pour Kashan.","tgt":"یک بلیت برای کاشان می‌خواهم.","ro":"Yek belit barâye Kâshân mikhâham.","lit":"un · billet · pour · Kashan · veux"},{"fr":"Pour aujourd'hui ou pour demain ?","tgt":"برای امروز یا فردا؟","ro":"Barâye emruz yâ fardâ?","lit":"pour · aujourd'hui · ou · demain"},{"fr":"Pour demain matin, s'il vous plaît.","tgt":"برای فردا صبح، لطفا.","ro":"Barâye fardâ sobh, lotfan.","lit":"pour · demain · matin · s'il-vous-plaît"},{"fr":"Aujourd'hui, nous n'avons plus de place.","tgt":"امروز جا نداریم.","ro":"Emruz jâ nadârim.","lit":"aujourd'hui · place · [ne… pas]-avons"},{"fr":"Demain, il y a un bus à huit heures.","tgt":"فردا ساعت هشت یک اتوبوس هست.","ro":"Fardâ sâ'at-e hasht yek otobus hast.","lit":"demain · heure · [de] · huit · un · bus · il-y-a"},{"fr":"Hier, j'étais à Téhéran.","tgt":"دیروز در تهران بودم.","ro":"Diruz dar Tehrân budam.","lit":"hier · dans · Téhéran · étais"},{"fr":"Aujourd'hui, je suis à Ispahan.","tgt":"امروز در اصفهان هستم.","ro":"Emruz dar Esfahân hastam.","lit":"aujourd'hui · dans · Ispahan · suis"},{"fr":"Et demain, je vais à Kashan.","tgt":"و فردا به کاشان می‌روم.","ro":"Va fardâ be Kâshân miravam.","lit":"et · demain · [à] · Kashan · vais"},{"fr":"Le bus part de quel terminal ?","tgt":"اتوبوس از کدام ترمینال حرکت می‌کند؟","ro":"Otobus az kodâm terminâl harekat mikonad?","lit":"bus · de · quel · terminal · départ · fait"},{"fr":"Merci, alors à demain matin.","tgt":"ممنون، پس تا فردا صبح.","ro":"Mamnun, pas tâ fardâ sobh.","lit":"merci · donc · jusqu'à · demain · matin"}],"tip":{"title":"« Emruz », « fardâ », « diruz » : aujourd'hui, demain, hier","example":"Et demain, je vais à Kashan. — و <b>فردا</b> به کاشان می‌روم.","body":"En persan, les trois mots du temps sont très simples : « emruz » veut dire aujourd'hui, « fardâ » veut dire demain, et « diruz » veut dire hier. Écoutez bien : « emruz » et « diruz » contiennent tous les deux « ruz », le jour. On place souvent ces mots au tout début de la phrase, comme en français : « Va fardâ be Kâshân miravam », et demain je vais à Kashan, mot à mot et, demain, à, Kashan, je vais. Le verbe, lui, reste toujours à la fin. Vous pouvez aussi dire « fardâ sobh », demain matin, ou « emshab », ce soir, construit comme « emruz » avec « shab », la nuit. Pour hier, le verbe passe au passé : « Diruz dar Tehrân budam », hier j'étais à Téhéran. Astuce : retenez « ruz », le jour, et les deux autres mots viennent presque tout seuls.","exampleRo":"Va fardâ be Kâshân miravam.","lit":"et · demain · [à] · Kashan · vais","say":{"Emruz":"امروز","fardâ":"فردا","diruz":"دیروز","emruz":"امروز","ruz":"روز","Va fardâ be Kâshân miravam":"و فردا به کاشان می‌روم","fardâ sobh":"فردا صبح","emshab":"امشب","shab":"شب","Diruz dar Tehrân budam":"دیروز در تهران بودم"}}},{"title":"En taxi jusqu'à l'hôtel","phrases":[{"fr":"Monsieur, vous êtes libre ?","tgt":"آقا، آزاد هستید؟","ro":"Âghâ, âzâd hastid?","lit":"monsieur · libre · êtes"},{"fr":"Oui, montez, je vous en prie.","tgt":"بله، بفرمایید سوار شوید.","ro":"Bale, befarmâyid savâr shavid.","lit":"oui · je-vous-en-prie · monté · devenez"},{"fr":"À la place Naghsh-e Jahan, s'il vous plaît.","tgt":"میدان نقش جهان، لطفا.","ro":"Meydân-e Naghsh-e Jahân, lotfan.","lit":"place · [de] · Naghsh-e Jahan · s'il-vous-plaît"},{"fr":"Mon hôtel est à côté du bazar.","tgt":"هتلم کنار بازار است.","ro":"Hotelam kenâr-e bâzâr ast.","lit":"hôtel-mon · à-côté · [de] · bazar · est"},{"fr":"Le trajet prend combien de temps ?","tgt":"چقدر طول می‌کشد؟","ro":"Cheghadr tul mikeshad?","lit":"combien · longueur · tire"},{"fr":"Environ vingt minutes.","tgt":"حدود بیست دقیقه.","ro":"Hodud-e bist daghighe.","lit":"environ · [de] · vingt · minute"},{"fr":"Aujourd'hui, la circulation est dense.","tgt":"امروز ترافیک سنگین است.","ro":"Emruz terâfik sangin ast.","lit":"aujourd'hui · circulation · lourde · est"},{"fr":"L'hôtel est là-bas, sur la droite.","tgt":"هتل آنجاست، سمت راست.","ro":"Hotel ânjâst, samt-e râst.","lit":"hôtel · là-bas-est · côté · [de] · droite"},{"fr":"Arrêtez-vous ici, s'il vous plaît.","tgt":"لطفا اینجا نگه دارید.","ro":"Lotfan injâ negah dârid.","lit":"s'il-vous-plaît · ici · arrêt · tenez"},{"fr":"Merci, monsieur, au revoir.","tgt":"ممنون آقا، خداحافظ.","ro":"Mamnun âghâ, khodâhâfez.","lit":"merci · monsieur · au-revoir"}]},{"title":"À la réception de l'hôtel","phrases":[{"fr":"Bonjour, j'ai réservé au nom de Martin.","tgt":"سلام، به اسم مارتن رزرو دارم.","ro":"Salâm, be esm-e Mârten rezerv dâram.","lit":"bonjour · [à] · nom · [de] · Martin · réservation · ai"},{"fr":"Votre nom de famille, s'il vous plaît ?","tgt":"فامیلی شما، لطفا؟","ro":"Fâmili-ye shomâ, lotfan?","lit":"nom-de-famille · [de] · vous · s'il-vous-plaît"},{"fr":"Votre passeport aussi, s'il vous plaît.","tgt":"پاسپورتتان را هم، لطفا.","ro":"Pâsportetân râ ham, lotfan.","lit":"passeport-votre · [objet] · aussi · s'il-vous-plaît"},{"fr":"Le voici, c'est mon passeport.","tgt":"بفرمایید، این پاسپورت من است.","ro":"Befarmâyid, in pâsport-e man ast.","lit":"je-vous-en-prie · ceci · passeport · [de] · moi · est"},{"fr":"Une chambre pour deux nuits, s'il vous plaît.","tgt":"یک اتاق برای دو شب، لطفا.","ro":"Yek otâgh barâye do shab, lotfan.","lit":"une · chambre · pour · deux · nuit · s'il-vous-plaît"},{"fr":"Avec le petit-déjeuner, s'il vous plaît.","tgt":"لطفا با صبحانه.","ro":"Lotfan bâ sobhâne.","lit":"s'il-vous-plaît · avec · petit-déjeuner"},{"fr":"Votre chambre est au deuxième étage.","tgt":"اتاقتان در طبقه دوم است.","ro":"Otâghetân dar tabaghe-ye dovvom ast.","lit":"chambre-votre · dans · étage · [de] · deuxième · est"},{"fr":"Et voici la clé de votre chambre.","tgt":"این هم کلید اتاقتان.","ro":"In ham kelid-e otâghetân.","lit":"ceci · aussi · clé · [de] · chambre-votre"},{"fr":"Le code du wifi, s'il vous plaît ?","tgt":"رمز وای‌فای، لطفا؟","ro":"Ramz-e vâyfây, lotfan?","lit":"code · [de] · wifi · s'il-vous-plaît"},{"fr":"Un thé bien chaud pour moi, s'il vous plaît.","tgt":"لطفا یک چای داغ برای من.","ro":"Lotfan yek chây-e dâgh barâye man.","lit":"s'il-vous-plaît · un · thé · [de] · brûlant · pour · moi"}],"tip":{"title":"« Lotfan » : s'il vous plaît","example":"Une chambre pour deux nuits, s'il vous plaît. — یک اتاق برای دو شب، <b>لطفا</b>.","body":"« Lotfan » est la formule magique pour demander poliment : elle veut dire s'il vous plaît. Le mot vient de « lotf », la gentillesse, et on retrouve ce mot dans la jolie phrase « kheyli lotf dârid », vous êtes très aimable. On peut placer « lotfan » au début ou à la fin de la phrase, comme en français : « Lotfan bâ sobhâne », avec le petit-déjeuner s'il vous plaît, ou « Yek otâgh barâye do shab, lotfan ». Mot à mot : une, chambre, pour, deux, nuit, s'il vous plaît. Remarquez qu'après un nombre, le nom reste au singulier : « do shab », deux nuit. Prononcez « lot » avec un « o » bref, puis « fan » en faisant bien sonner le « n », sans le nasaliser comme en français. En Iran, la politesse compte beaucoup, alors n'hésitez pas à en mettre partout. Astuce : « lotfan » pour demander, « mamnun » pour remercier, et vous voilà déjà très bien élevé.","exampleRo":"Yek otâgh barâye do shab, lotfan.","lit":"une · chambre · pour · deux · nuit · s'il-vous-plaît","say":{"Lotfan":"لطفاً","lotf":"لطف","kheyli lotf dârid":"خیلی لطف دارید","lotfan":"لطفاً","Lotfan bâ sobhâne":"لطفاً با صبحانه","Yek otâgh barâye do shab, lotfan":"یک اتاق برای دو شب، لطفاً","do shab":"دو شب","mamnun":"ممنون"}}},{"title":"Dans la chambre d'hôtel","phrases":[{"fr":"Notre chambre est propre et calme.","tgt":"اتاق ما تمیز و آرام است.","ro":"Otâgh-e mâ tamiz va ârâm ast.","lit":"chambre · [de] · nous · propre · et · calme · est"},{"fr":"La fenêtre donne sur la place.","tgt":"پنجره رو به میدان است.","ro":"Panjare ru be meydân ast.","lit":"fenêtre · face · [à] · place · est"},{"fr":"Le lit est très confortable.","tgt":"تخت خیلی راحت است.","ro":"Takht kheyli râhat ast.","lit":"lit · très · confortable · est"},{"fr":"Il n'y a pas de serviette dans la salle de bain.","tgt":"در حمام حوله نیست.","ro":"Dar hammâm hole nist.","lit":"dans · salle-de-bain · serviette · [ne… pas]-est"},{"fr":"Le climatiseur de la chambre ne marche pas.","tgt":"کولر اتاق کار نمی‌کند.","ro":"Kuler-e otâgh kâr nemikonad.","lit":"climatiseur · [de] · chambre · travail · [ne… pas]-fait"},{"fr":"L'eau chaude ne vient pas.","tgt":"آب گرم نمی‌آید.","ro":"Âb-e garm nemiâyad.","lit":"eau · [de] · chaude · [ne… pas]-vient"},{"fr":"Je voudrais une autre couverture.","tgt":"یک پتوی دیگر می‌خواهم.","ro":"Yek patu-ye digar mikhâham.","lit":"une · couverture · [de] · autre · veux"},{"fr":"Le petit-déjeuner, c'est à quelle heure ?","tgt":"صبحانه ساعت چند است؟","ro":"Sobhâne sâ'at-e chand ast?","lit":"petit-déjeuner · heure · [de] · combien · est"},{"fr":"À sept heures, au rez-de-chaussée.","tgt":"ساعت هفت، در طبقه همکف.","ro":"Sâ'at-e haft, dar tabaghe-ye hamkaf.","lit":"heure · [de] · sept · dans · étage · [de] · rez-de-chaussée"},{"fr":"La vue sur la place est superbe.","tgt":"منظره میدان خیلی زیباست.","ro":"Manzare-ye meydân kheyli zibâst.","lit":"vue · [de] · place · très · belle-est"}]},{"title":"Au bazar des artisans","phrases":[{"fr":"Ce plateau en cuivre est très joli.","tgt":"این سینی مسی خیلی قشنگ است.","ro":"In sini-ye mesi kheyli ghashang ast.","lit":"ce · plateau · [de] · en-cuivre · très · joli · est"},{"fr":"Ça coûte combien de tomans ?","tgt":"چند تومان است؟","ro":"Chand tomân ast?","lit":"combien · toman · est"},{"fr":"Ce plateau fait huit cent mille tomans.","tgt":"این سینی هشتصد هزار تومان است.","ro":"In sini hashtsad hezâr tomân ast.","lit":"ce · plateau · huit-cents · mille · toman · est"},{"fr":"C'est un peu cher pour moi.","tgt":"برای من کمی گران است.","ro":"Barâye man kami gerân ast.","lit":"pour · moi · un-peu · cher · est"},{"fr":"Et ce petit vase, combien de tomans ?","tgt":"و این گلدان کوچک چند تومان است؟","ro":"Va in goldân-e kuchak chand tomân ast?","lit":"et · ce · vase · [de] · petit · combien · toman · est"},{"fr":"Seulement trois cent mille tomans.","tgt":"فقط سیصد هزار تومان.","ro":"Faghat sisad hezâr tomân.","lit":"seulement · trois-cents · mille · toman"},{"fr":"Ce petit tapis coûte combien ?","tgt":"این قالیچه چند است؟","ro":"In ghâliche chand ast?","lit":"ce · petit-tapis · combien · est"},{"fr":"C'est combien, votre dernier prix ?","tgt":"آخرش چند؟","ro":"Âkharesh chand?","lit":"fin-sa · combien"},{"fr":"Pour vous, quatre cent mille tomans.","tgt":"برای شما، چهارصد هزار تومان.","ro":"Barâye shomâ, chahârsad hezâr tomân.","lit":"pour · vous · quatre-cents · mille · toman"},{"fr":"Bon, je prends le vase.","tgt":"خب، گلدان را می‌خرم.","ro":"Khob, goldân râ mikharam.","lit":"bon · vase · [objet] · achète"}],"tip":{"title":"« Chand tomân ? » : demander un prix, les tomans","example":"Ça coûte combien de tomans ? — <b>چند تومان</b> است؟","body":"Pour demander un prix, la formule la plus simple est « Chand tomân ast ? », mot à mot combien, toman, est. « Chand » veut dire combien, et « tomân » est l'unité qu'on utilise à l'oral pour parler d'argent. Sur certaines étiquettes, vous verrez des rials, mais un toman vaut dix rials, et au quotidien tout le monde compte en tomans. Comme les prix sont élevés, vous entendrez souvent « hezâr », mille : « sisad hezâr tomân », trois cent mille tomans. Au bazar, on peut aussi demander « Âkharesh chand ? », c'est combien en dernier prix, pour commencer à négocier gentiment. Le vendeur répond souvent sans verbe, juste le nombre suivi de « tomân » : « Faghat sisad hezâr tomân », seulement trois cent mille tomans. Astuce : « chand » sert aussi pour l'heure, « sâ'at chand ast ? », alors un seul petit mot vous ouvre deux questions.","exampleRo":"Chand tomân ast?","lit":"combien · toman · est","say":{"Chand tomân ?":"چند تومان؟","Chand tomân ast ?":"چند تومان است؟","Chand":"چند","tomân":"تومان","hezâr":"هزار","sisad hezâr tomân":"سیصد هزار تومان","Âkharesh chand ?":"آخرش چند؟","Faghat sisad hezâr tomân":"فقط سیصد هزار تومان","chand":"چند","sâ'at chand ast ?":"ساعت چند است؟"}}},{"title":"Changer de l'argent et payer","phrases":[{"fr":"Où se trouve un bureau de change ?","tgt":"صرافی کجاست؟","ro":"Sarrâfi kojâst?","lit":"bureau-de-change · où-est"},{"fr":"Il y a un bureau de change près du bazar.","tgt":"نزدیک بازار یک صرافی هست.","ro":"Nazdik-e bâzâr yek sarrâfi hast.","lit":"près · [de] · bazar · un · bureau-de-change · il-y-a"},{"fr":"Je voudrais changer cent euros.","tgt":"می‌خواهم صد یورو عوض کنم.","ro":"Mikhâham sad yuro avaz konam.","lit":"veux · cent · euro · échange · que-je-fasse"},{"fr":"Les prix sont en tomans ou en rials ?","tgt":"قیمت‌ها به تومان است یا ریال؟","ro":"Gheymathâ be tomân ast yâ riyâl?","lit":"prix · [à] · toman · est · ou · rial"},{"fr":"En tomans, bien sûr.","tgt":"البته به تومان.","ro":"Albatte be tomân.","lit":"bien-sûr · [à] · toman"},{"fr":"Un toman, c'est dix rials.","tgt":"هر تومان ده ریال است.","ro":"Har tomân dah riyâl ast.","lit":"chaque · toman · dix · rial · est"},{"fr":"Désolé, je n'ai pas de monnaie sur moi.","tgt":"ببخشید، پول خرد ندارم.","ro":"Bebakhshid, pul-e khord nadâram.","lit":"excusez · argent · [de] · menu · [ne… pas]-ai"},{"fr":"Je paie en liquide.","tgt":"نقد می‌دهم.","ro":"Naghd midaham.","lit":"comptant · donne"},{"fr":"Tenez, voici votre reçu.","tgt":"بفرمایید، این رسید شماست.","ro":"Befarmâyid, in resid-e shomâst.","lit":"je-vous-en-prie · ceci · reçu · [de] · vous-est"},{"fr":"Cet argent suffit pour aujourd'hui.","tgt":"این پول برای امروز کافی است.","ro":"In pul barâye emruz kâfi ast.","lit":"cet · argent · pour · aujourd'hui · suffisant · est"}]},{"title":"Sur la place Naghsh-e Jahan","phrases":[{"fr":"La place Naghsh-e Jahan est immense.","tgt":"میدان نقش جهان خیلی بزرگ است.","ro":"Meydân-e Naghsh-e Jahân kheyli bozorg ast.","lit":"place · [de] · Naghsh-e Jahan · très · grande · est"},{"fr":"De l'hôtel jusqu'à la place, nous allons à pied.","tgt":"از هتل تا میدان پیاده می‌رویم.","ro":"Az hotel tâ meydân piyâde miravim.","lit":"de · hôtel · jusqu'à · place · à-pied · allons"},{"fr":"La place est animée du matin au soir.","tgt":"میدان از صبح تا شب شلوغ است.","ro":"Meydân az sobh tâ shab sholugh ast.","lit":"place · de · matin · jusqu'à · nuit · animée · est"},{"fr":"Le palais Ali Qapu est juste en face.","tgt":"کاخ عالی‌قاپو روبه‌رو است.","ro":"Kâkh-e Âli Ghâpu ruberu ast.","lit":"palais · [de] · Ali-Qapu · en-face · est"},{"fr":"C'est ouvert de neuf heures à cinq heures.","tgt":"از ساعت نه تا پنج باز است.","ro":"Az sâ'at-e noh tâ panj bâz ast.","lit":"de · heure · [de] · neuf · jusqu'à · cinq · ouvert · est"},{"fr":"Les calèches font le tour de la place.","tgt":"درشکه‌ها دور میدان می‌چرخند.","ro":"Doroshkehâ dor-e meydân micharkhand.","lit":"calèches · autour · [de] · place · tournent"},{"fr":"Nous marchons du palais jusqu'au bazar.","tgt":"از کاخ تا بازار قدم می‌زنیم.","ro":"Az kâkh tâ bâzâr ghadam mizanim.","lit":"de · palais · jusqu'à · bazar · pas · frappons"},{"fr":"Les fontaines sont très belles.","tgt":"فواره‌ها خیلی زیبا هستند.","ro":"Favvârehâ kheyli zibâ hastand.","lit":"fontaines · très · belles · sont"},{"fr":"Le soir, il y a beaucoup de familles ici.","tgt":"شب‌ها اینجا خانواده‌های زیادی هستند.","ro":"Shabhâ injâ khânevâdehâ-ye ziyâdi hastand.","lit":"nuits · ici · familles · [de] · nombreuses · sont"},{"fr":"De Téhéran à Ispahan, il y a cinq heures de route.","tgt":"از تهران تا اصفهان پنج ساعت راه است.","ro":"Az Tehrân tâ Esfahân panj sâ'at râh ast.","lit":"de · Téhéran · jusqu'à · Ispahan · cinq · heure · route · est"}],"tip":{"title":"« Az... tâ... » : de... à...","example":"De Téhéran à Ispahan, il y a cinq heures de route. — <b>از</b> تهران <b>تا</b> اصفهان پنج ساعت راه است.","body":"Pour dire de... à..., le persan utilise deux petits mots : « az », qui veut dire de ou depuis, et « tâ », qui veut dire jusqu'à. Ils se placent devant les mots, exactement comme en français : « az hotel tâ meydân », de l'hôtel à la place. Prenons la phrase « Az Tehrân tâ Esfahân panj sâ'at râh ast ». Mot à mot : de, Téhéran, jusqu'à, Ispahan, cinq, heure, route, est. Autrement dit, il y a cinq heures de route. La même construction marche pour le temps : « az sobh tâ shab », du matin au soir, ou « az sâ'at-e noh tâ panj », de neuf heures à cinq heures. Vous connaissez même déjà « tâ » tout seul dans « tâ fardâ », à demain, littéralement jusqu'à demain. Astuce : imaginez un trajet en bus, « az » c'est le point de départ, et « tâ » c'est la ligne d'arrivée.","exampleRo":"Az Tehrân tâ Esfahân panj sâ'at râh ast.","lit":"de · Téhéran · jusqu'à · Ispahan · cinq · heure · route · est","say":{"Az... tâ...":"از... تا...","az":"از","tâ":"تا","az hotel tâ meydân":"از هتل تا میدان","Az Tehrân tâ Esfahân panj sâ'at râh ast":"از تهران تا اصفهان پنج ساعت راه است","az sobh tâ shab":"از صبح تا شب","az sâ'at-e noh tâ panj":"از ساعت نه تا پنج","tâ fardâ":"تا فردا"}}},{"title":"Les ponts sur la rivière","phrases":[{"fr":"La rivière s'appelle Zayandeh Roud.","tgt":"اسم رودخانه زاینده‌رود است.","ro":"Esm-e rudkhâne Zâyande-rud ast.","lit":"nom · [de] · rivière · Zayandeh-Roud · est"},{"fr":"Le pont Si-o-se Pol a trente-trois arches.","tgt":"سی‌وسه‌پل سی و سه دهانه دارد.","ro":"Si-o-se pol si-o-se dahâne dârad.","lit":"Si-o-se-Pol · trente · et · trois · arche · a"},{"fr":"Le pont Khadjou est très ancien.","tgt":"پل خواجو خیلی قدیمی است.","ro":"Pol-e Khâju kheyli ghadimi ast.","lit":"pont · [de] · Khadjou · très · ancien · est"},{"fr":"Il y a de l'eau dans la rivière aujourd'hui ?","tgt":"امروز رودخانه آب دارد؟","ro":"Emruz rudkhâne âb dârad?","lit":"aujourd'hui · rivière · eau · a"},{"fr":"Oui, aujourd'hui, il y a de l'eau.","tgt":"بله، امروز آب دارد.","ro":"Bale, emruz âb dârad.","lit":"oui · aujourd'hui · eau · a"},{"fr":"Des gens chantent sous le pont.","tgt":"مردم زیر پل آواز می‌خوانند.","ro":"Mardom zir-e pol âvâz mikhânand.","lit":"gens · sous · [de] · pont · chant · lisent"},{"fr":"Le soir, les lumières du pont sont jolies.","tgt":"شب‌ها چراغ‌های پل قشنگ است.","ro":"Shabhâ cherâghhâ-ye pol ghashang ast.","lit":"nuits · lumières · [de] · pont · joli · est"},{"fr":"Nous nous asseyons ici un moment.","tgt":"کمی اینجا می‌نشینیم.","ro":"Kami injâ mineshinim.","lit":"un-peu · ici · asseyons"},{"fr":"Il y a une maison de thé près du pont.","tgt":"نزدیک پل یک چای‌خانه هست.","ro":"Nazdik-e pol yek châykhâne hast.","lit":"près · [de] · pont · une · maison-de-thé · il-y-a"},{"fr":"Un thé avec vue sur la rivière !","tgt":"چای با منظره رودخانه!","ro":"Chây bâ manzare-ye rudkhâne!","lit":"thé · avec · vue · [de] · rivière"}]},{"title":"Trouver un hôtel","phrases":[{"fr":"Je cherche un hôtel près d'ici.","tgt":"دنبال هتلی نزدیک اینجا هستم.","ro":"Donbâl-e hoteli nazdik-e injâ hastam.","lit":"recherche · [de] · hôtel-[un] · près · [de] · ici · suis"},{"fr":"Il y a un hôtel derrière le bazar.","tgt":"پشت بازار هتلی هست.","ro":"Posht-e bâzâr hoteli hast.","lit":"derrière · [de] · bazar · hôtel-[un] · il-y-a"},{"fr":"Excusez-moi, j'ai une petite question.","tgt":"ببخشید، سوالی دارم.","ro":"Bebakhshid, so'âli dâram.","lit":"excusez · question-[une] · ai"},{"fr":"Vous avez une chambre avec vue sur la rivière ?","tgt":"اتاقی با منظره رودخانه دارید؟","ro":"Otâghi bâ manzare-ye rudkhâne dârid?","lit":"chambre-[une] · avec · vue · [de] · rivière · avez"},{"fr":"Nous n'avons qu'une chambre pour ce soir.","tgt":"فقط یک اتاق برای امشب داریم.","ro":"Faghat yek otâgh barâye emshab dârim.","lit":"seulement · une · chambre · pour · ce-soir · avons"},{"fr":"Ici, c'est une vieille maison.","tgt":"اینجا خانه‌ای قدیمی است.","ro":"Injâ khâne'i ghadimi ast.","lit":"ici · maison-[une] · ancienne · est"},{"fr":"La cour a un petit bassin.","tgt":"حیاط یک حوض کوچک دارد.","ro":"Hayât yek hoz-e kuchak dârad.","lit":"cour · un · bassin · [de] · petit · a"},{"fr":"Y a-t-il une pharmacie dans le coin ?","tgt":"این نزدیکی داروخانه‌ای هست؟","ro":"In nazdiki dârukhâne'i hast?","lit":"ce · voisinage · pharmacie-[une] · il-y-a"},{"fr":"Je connais un bon hôtel à Kashan.","tgt":"هتل خوبی در کاشان می‌شناسم.","ro":"Hotel-e khubi dar Kâshân mishenâsam.","lit":"hôtel · [de] · bon-[un] · dans · Kashan · connais"},{"fr":"C'est une très bonne idée.","tgt":"فکر خیلی خوبی است.","ro":"Fekr-e kheyli khubi ast.","lit":"idée · [de] · très · bonne-[une] · est"}],"tip":{"title":"Le « -i » indéfini : « hotel-i », un hôtel","example":"Je cherche un hôtel près d'ici. — دنبال <b>هتلی</b> نزدیک اینجا هستم.","body":"Pour dire un ou une devant un nom, le persan a une astuce très économique : on colle simplement un « -i » à la fin du mot. « Hotel » veut dire l'hôtel, et « hotel-i » veut dire un hôtel, n'importe lequel. Écoutez la phrase « Donbâl-e hoteli nazdik-e injâ hastam », je cherche un hôtel près d'ici. Mot à mot : recherche, de, un hôtel, près, de, ici, je suis. De la même façon, « so'âl » veut dire question, et « so'âli dâram », c'est j'ai une question. Quand le mot finit déjà par un son « e », on glisse un petit appui : « khâne », la maison, devient « khâne'i », une maison. Parfois, le « -i » se pose sur l'adjectif : « hotel-e khubi », un bon hôtel. À l'oral, on entend aussi très souvent « yek », un, devant le nom, comme dans « yek otâgh », une chambre. Astuce : pensez au « -i » comme à une petite étiquette qui dit un parmi d'autres.","exampleRo":"Donbâl-e hoteli nazdik-e injâ hastam.","lit":"recherche · [de] · hôtel-[un] · près · [de] · ici · suis","say":{"hotel-i":"هتلی","Hotel":"هتل","Donbâl-e hoteli nazdik-e injâ hastam":"دنبال هتلی نزدیک اینجا هستم","so'âl":"سؤال","so'âli dâram":"سؤالی دارم","khâne":"خانه","khâne'i":"خانه‌ای","hotel-e khubi":"هتل خوبی","yek":"یک","yek otâgh":"یک اتاق"}}},{"title":"Au restaurant traditionnel","phrases":[{"fr":"Une table pour deux personnes, près de la fenêtre.","tgt":"یک میز برای دو نفر، کنار پنجره.","ro":"Yek miz barâye do nafar, kenâr-e panjare.","lit":"une · table · pour · deux · personne · à-côté · [de] · fenêtre"},{"fr":"Le menu est seulement en persan.","tgt":"منو فقط فارسی است.","ro":"Menu faghat fârsi ast.","lit":"menu · seulement · persan · est"},{"fr":"Quel plat nous conseillez-vous ?","tgt":"چه غذایی پیشنهاد می‌کنید؟","ro":"Che ghazâyi pishnahâd mikonid?","lit":"quel · plat-[un] · suggestion · faites"},{"fr":"Le beryan d'Ispahan est célèbre.","tgt":"بریان اصفهان معروف است.","ro":"Beryân-e Esfahân ma'ruf ast.","lit":"beryan · [de] · Ispahan · célèbre · est"},{"fr":"Alors, moi, je prends le beryan.","tgt":"پس من بریان می‌خواهم.","ro":"Pas man beryân mikhâham.","lit":"donc · moi · beryan · veux"},{"fr":"Et comme boisson, que voulez-vous ?","tgt":"نوشیدنی چه می‌خواهید؟","ro":"Nushidani che mikhâhid?","lit":"boisson · quoi · voulez"},{"fr":"Un doogh bien frais, s'il vous plaît.","tgt":"یک دوغ خنک، لطفا.","ro":"Yek dugh-e khonak, lotfan.","lit":"un · doogh · [de] · frais · s'il-vous-plaît"},{"fr":"Le pain est chaud et délicieux.","tgt":"نان گرم و خوشمزه است.","ro":"Nân garm va khoshmaze ast.","lit":"pain · chaud · et · délicieux · est"},{"fr":"Mon amie ne mange pas de viande.","tgt":"دوستم گوشت نمی‌خورد.","ro":"Dustam gusht nemikhorad.","lit":"amie-mon · viande · [ne… pas]-mange"},{"fr":"On paie à la caisse ?","tgt":"سر صندوق حساب می‌کنیم؟","ro":"Sar-e sandugh hesâb mikonim?","lit":"tête · [de] · caisse · compte · faisons"}]},{"title":"Demander son chemin","phrases":[{"fr":"Excusez-moi, comment aller au bazar ?","tgt":"ببخشید، چطور به بازار بروم؟","ro":"Bebakhshid, chetor be bâzâr beravam?","lit":"excusez · comment · [à] · bazar · que-j'aille"},{"fr":"Allez tout droit, puis à gauche.","tgt":"مستقیم بروید، بعد دست چپ.","ro":"Mostaghim beravid, ba'd dast-e chap.","lit":"droit · allez · après · main · [de] · gauche"},{"fr":"Comment allons-nous jusqu'au pont Khadjou ?","tgt":"تا پل خواجو چطور برویم؟","ro":"Tâ pol-e Khâju chetor beravim?","lit":"jusqu'à · pont · [de] · Khadjou · comment · que-nous-allions"},{"fr":"Comment est votre hôtel ?","tgt":"هتلتان چطور است؟","ro":"Hoteletân chetor ast?","lit":"hôtel-votre · comment · est"},{"fr":"Il est très bien, merci.","tgt":"خیلی خوب است، ممنون.","ro":"Kheyli khub ast, mamnun.","lit":"très · bien · est · merci"},{"fr":"Et vous, comment allez-vous aujourd'hui ?","tgt":"شما امروز حالتان چطور است؟","ro":"Shomâ emruz hâletân chetor ast?","lit":"vous · aujourd'hui · état-votre · comment · est"},{"fr":"La deuxième rue, à droite.","tgt":"خیابان دوم، دست راست.","ro":"Khiyâbân-e dovvom, dast-e râst.","lit":"rue · [de] · deuxième · main · [de] · droite"},{"fr":"Le bazar est juste derrière la place.","tgt":"بازار درست پشت میدان است.","ro":"Bâzâr dorost posht-e meydân ast.","lit":"bazar · juste · derrière · [de] · place · est"},{"fr":"Et comment je vais au terminal de bus ?","tgt":"و چطور به ترمینال اتوبوس بروم؟","ro":"Va chetor be terminâl-e otobus beravam?","lit":"et · comment · [à] · terminal · [de] · bus · que-j'aille"},{"fr":"Merci, c'est très gentil de votre part.","tgt":"خیلی لطف دارید.","ro":"Kheyli lotf dârid.","lit":"beaucoup · gentillesse · avez"}],"tip":{"title":"« Chetor » : comment, et comment aller quelque part","example":"Excusez-moi, comment aller au bazar ? — ببخشید، <b>چطور</b> به بازار بروم؟","body":"« Chetor » est le mot pour dire comment. On le prononce un peu comme tchétor, avec un « o » bien rond. Il sert d'abord à demander son chemin : « Chetor be bâzâr beravam ? », comment aller au bazar ? Mot à mot : comment, à, bazar, que j'aille. Le dernier verbe, « beravam », est une forme qu'on étudiera plus tard ; pour l'instant, retenez la formule toute faite. « Chetor » sert aussi à demander comment est quelque chose : « Hoteletân chetor ast ? », comment est votre hôtel ? Et bien sûr, pour prendre des nouvelles : « Hâletân chetor ast ? », comment allez-vous, littéralement votre état est comment. Entre amis, vous entendrez la version courte « chetori ? », ça va ? Remarquez que « chetor » se place juste avant ce qu'on demande, mais le verbe, lui, reste toujours à la fin. Astuce : glissez « chetor » là où vous diriez comment, et gardez le verbe pour la fin.","exampleRo":"Bebakhshid, chetor be bâzâr beravam?","lit":"excusez · comment · [à] · bazar · que-j'aille","say":{"Chetor":"چطور","Chetor be bâzâr beravam ?":"چطور به بازار بروم؟","beravam":"بروم","Hoteletân chetor ast ?":"هتلتان چطور است؟","Hâletân chetor ast ?":"حالتان چطور است؟","chetori ?":"چطوری؟","chetor":"چطور"}}},{"title":"Le kebab et le riz au safran","phrases":[{"fr":"Ça sent bon le kebab ici.","tgt":"اینجا بوی کباب می‌آید.","ro":"Injâ bu-ye kabâb miâyad.","lit":"ici · odeur · [de] · kebab · vient"},{"fr":"Je voudrais un chelow kebab.","tgt":"یک چلوکباب می‌خواهم.","ro":"Yek chelokabâb mikhâham.","lit":"un · chelow-kebab · veux"},{"fr":"Le riz au safran est très bon.","tgt":"برنج زعفرانی خیلی خوشمزه است.","ro":"Berenj-e za'farâni kheyli khoshmaze ast.","lit":"riz · [de] · safrané · très · délicieux · est"},{"fr":"Avec une tomate grillée, s'il vous plaît.","tgt":"با گوجه کبابی، لطفا.","ro":"Bâ goje-ye kabâbi, lotfan.","lit":"avec · tomate · [de] · grillée · s'il-vous-plaît"},{"fr":"Le kebab koobideh est tendre.","tgt":"کباب کوبیده نرم است.","ro":"Kabâb-e kubide narm ast.","lit":"kebab · [de] · haché · tendre · est"},{"fr":"Vous avez aussi du yaourt ?","tgt":"ماست هم دارید؟","ro":"Mâst ham dârid?","lit":"yaourt · aussi · avez"},{"fr":"Le safran d'ici est très célèbre.","tgt":"زعفران ایران معروف است.","ro":"Za'farân-e Irân ma'ruf ast.","lit":"safran · [de] · Iran · célèbre · est"},{"fr":"Je n'ai plus faim du tout.","tgt":"دیگر اصلا گرسنه نیستم.","ro":"Digar aslan gorosne nistam.","lit":"plus · du-tout · affamé · [ne… pas]-suis"},{"fr":"C'était vraiment délicieux.","tgt":"واقعا خوشمزه بود.","ro":"Vâghe'an khoshmaze bud.","lit":"vraiment · délicieux · était"},{"fr":"Vous prenez un thé après le repas ?","tgt":"بعد از غذا چای می‌خورید؟","ro":"Ba'd az ghazâ chây mikhorid?","lit":"après · de · repas · thé · prenez"}]},{"title":"Au palais Chehel Sotoun","phrases":[{"fr":"Je peux acheter deux billets ?","tgt":"می‌توانم دو بلیت بخرم؟","ro":"Mitavânam do belit bekharam?","lit":"peux · deux · billet · que-j'achète"},{"fr":"Oui, vous pouvez payer ici.","tgt":"بله، می‌توانید اینجا پول بدهید.","ro":"Bale, mitavânid injâ pul bedahid.","lit":"oui · pouvez · ici · argent · que-vous-donniez"},{"fr":"Est-ce que je peux prendre une photo du jardin ?","tgt":"می‌توانم از باغ عکس بگیرم؟","ro":"Mitavânam az bâgh aks begiram?","lit":"peux · de · jardin · photo · que-je-prenne"},{"fr":"Oui, mais sans flash.","tgt":"بله، ولی بدون فلاش.","ro":"Bale, vali bedun-e felâsh.","lit":"oui · mais · sans · [de] · flash"},{"fr":"Le palais a vingt colonnes en bois.","tgt":"کاخ بیست ستون چوبی دارد.","ro":"Kâkh bist sotun-e chubi dârad.","lit":"palais · vingt · colonne · [de] · en-bois · a"},{"fr":"Avec leur reflet dans l'eau, on en voit quarante.","tgt":"با عکسشان در آب، چهل ستون می‌بینیم.","ro":"Bâ aksashân dar âb, chehel sotun mibinim.","lit":"avec · reflet-leur · dans · eau · quarante · colonne · voyons"},{"fr":"Je ne peux pas voir les peintures.","tgt":"نمی‌توانم نقاشی‌ها را ببینم.","ro":"Nemitavânam naghghâshihâ râ bebinam.","lit":"[ne… pas]-peux · peintures · [objet] · que-je-voie"},{"fr":"Vous pouvez avancer un peu.","tgt":"می‌توانید کمی جلوتر بروید.","ro":"Mitavânid kami jelotar beravid.","lit":"pouvez · un-peu · plus-avant · que-vous-alliez"},{"fr":"Je peux m'asseoir dans le jardin ?","tgt":"می‌توانم در باغ بنشینم؟","ro":"Mitavânam dar bâgh beneshinam?","lit":"peux · dans · jardin · que-je-m'asseye"},{"fr":"Bien sûr, le jardin est ouvert à tous.","tgt":"البته، باغ برای همه باز است.","ro":"Albatte, bâgh barâye hame bâz ast.","lit":"bien-sûr · jardin · pour · tous · ouvert · est"}],"tip":{"title":"« Mitavânam » : pouvoir, je peux","example":"Est-ce que je peux prendre une photo du jardin ? — <b>می‌توانم</b> از باغ عکس بگیرم؟","body":"« Mitavânam » veut dire je peux. C'est la forme polie et complète ; dans la rue, à Téhéran, on entend souvent la version raccourcie « mitunam ». La fin du mot change selon la personne : « mitavânid », vous pouvez, et pour la négation on remplace le début par « ne- » : « nemitavânam », je ne peux pas. Après « mitavânam », le second verbe prend une forme spéciale qui commence souvent par « be- » : « Mitavânam az bâgh aks begiram ? », je peux prendre une photo du jardin ? Mot à mot : je peux, de, jardin, photo, que je prenne. Retenez ces petites formes en bloc : « bekharam », que j'achète, « bebinam », que je voie, « beneshinam », que je m'asseye. Pour poser la question, il suffit de monter la voix à la fin, sans changer l'ordre des mots. Astuce : commencez par « mitavânam », et tout ce qui suit devient une demande polie.","exampleRo":"Mitavânam az bâgh aks begiram?","lit":"peux · de · jardin · photo · que-je-prenne","say":{"Mitavânam":"می‌توانم","mitunam":"می‌تونم","mitavânid":"می‌توانید","nemitavânam":"نمی‌توانم","mitavânam":"می‌توانم","Mitavânam az bâgh aks begiram ?":"می‌توانم از باغ عکس بگیرم؟","bekharam":"بخرم","bebinam":"ببینم","beneshinam":"بنشینم"}}},{"title":"Un petit souci de santé","phrases":[{"fr":"Ce matin, je ne me sens pas bien.","tgt":"امروز صبح حالم خوب نیست.","ro":"Emruz sobh hâlam khub nist.","lit":"aujourd'hui · matin · état-mon · bien · [ne… pas]-est"},{"fr":"J'ai mal au ventre depuis hier soir.","tgt":"از دیشب دلم درد می‌کند.","ro":"Az dishab delam dard mikonad.","lit":"depuis · hier-soir · ventre-mon · douleur · fait"},{"fr":"Et j'ai aussi un peu de fièvre.","tgt":"و کمی هم تب دارم.","ro":"Va kami ham tab dâram.","lit":"et · un-peu · aussi · fièvre · ai"},{"fr":"Il fait très chaud à Ispahan.","tgt":"هوای اصفهان خیلی گرم است.","ro":"Havâ-ye Esfahân kheyli garm ast.","lit":"air · [de] · Ispahan · très · chaud · est"},{"fr":"Buvez beaucoup d'eau fraîche.","tgt":"زیاد آب خنک بخورید.","ro":"Ziyâd âb-e khonak bekhorid.","lit":"beaucoup · eau · [de] · fraîche · prenez"},{"fr":"Avez-vous un médicament contre la fièvre ?","tgt":"داروی تب دارید؟","ro":"Dâru-ye tab dârid?","lit":"médicament · [de] · fièvre · avez"},{"fr":"Prenez ce comprimé deux fois par jour.","tgt":"روزی دو بار این قرص را بخورید.","ro":"Ruzi do bâr in ghors râ bekhorid.","lit":"jour-[un] · deux · fois · ce · comprimé · [objet] · prenez"},{"fr":"Je le prends avant ou après le repas ?","tgt":"قبل از غذا بخورم یا بعد از غذا؟","ro":"Ghabl az ghazâ bekhoram yâ ba'd az ghazâ?","lit":"avant · de · repas · que-je-prenne · ou · après · de · repas"},{"fr":"Après le repas, avec de l'eau.","tgt":"بعد از غذا، با آب.","ro":"Ba'd az ghazâ, bâ âb.","lit":"après · de · repas · avec · eau"},{"fr":"Reposez-vous bien à l'hôtel.","tgt":"در هتل خوب استراحت کنید.","ro":"Dar hotel khub esterâhat konid.","lit":"dans · hôtel · bien · repos · faites"}]},{"title":"En bus, en train ou en taxi ?","phrases":[{"fr":"Nous allons à Kashan en bus.","tgt":"با اتوبوس به کاشان می‌رویم.","ro":"Bâ otobus be Kâshân miravim.","lit":"avec · bus · [à] · Kashan · allons"},{"fr":"Le train pour Kashan part le matin.","tgt":"قطار کاشان صبح حرکت می‌کند.","ro":"Ghatâr-e Kâshân sobh harekat mikonad.","lit":"train · [de] · Kashan · matin · départ · fait"},{"fr":"En train, c'est plus calme.","tgt":"با قطار آرام‌تر است.","ro":"Bâ ghatâr ârâmtar ast.","lit":"avec · train · plus-calme · est"},{"fr":"Moi, je préfère le taxi.","tgt":"من تاکسی را ترجیح می‌دهم.","ro":"Man tâksi râ tarjih midaham.","lit":"moi · taxi · [objet] · préférence · donne"},{"fr":"En taxi, c'est plus cher.","tgt":"با تاکسی گران‌تر است.","ro":"Bâ tâksi gerântar ast.","lit":"avec · taxi · plus-cher · est"},{"fr":"Vous venez en voiture ?","tgt":"با ماشین می‌آیید؟","ro":"Bâ mâshin miâyid?","lit":"avec · voiture · venez"},{"fr":"Non, nous venons à pied.","tgt":"نه، پیاده می‌آییم.","ro":"Na, piyâde miâyim.","lit":"non · à-pied · venons"},{"fr":"À Ispahan, il y a aussi un métro.","tgt":"اصفهان مترو هم دارد.","ro":"Esfahân metro ham dârad.","lit":"Ispahan · métro · aussi · a"},{"fr":"En métro, nous arrivons vite au centre-ville.","tgt":"با مترو زود به مرکز شهر می‌رسیم.","ro":"Bâ metro zud be markaz-e shahr miresim.","lit":"avec · métro · vite · [à] · centre · [de] · ville · arrivons"},{"fr":"Ce soir, nous rentrons à l'hôtel à vélo.","tgt":"امشب با دوچرخه به هتل برمی‌گردیم.","ro":"Emshab bâ docharkhe be hotel barmigardim.","lit":"ce-soir · avec · vélo · [à] · hôtel · revenons"}],"tip":{"title":"« Bâ » + moyen de transport : en bus, en train, en taxi","example":"Nous allons à Kashan en bus. — <b>با</b> اتوبوس به کاشان می‌رویم.","body":"Pour dire en bus ou en train, le persan utilise « bâ », qui veut dire avec. On voyage donc littéralement avec le bus : « bâ otobus », en bus, « bâ ghatâr », en train, « bâ tâksi », en taxi. Prenons « Bâ otobus be Kâshân miravim », nous allons à Kashan en bus. Mot à mot : avec, bus, à, Kashan, nous allons. Vous voyez l'ordre : d'abord le moyen de transport, puis la destination avec « be », et le verbe tout à la fin. Il n'y a pas d'article devant le véhicule, c'est très simple. Une seule exception à retenir : à pied se dit « piyâde », sans « bâ ». Et « bâ » garde aussi son sens habituel, comme dans « bâ sobhâne », avec le petit-déjeuner. Astuce : en persan, on ne prend pas le bus, on part avec lui, comme avec un compagnon de voyage.","exampleRo":"Bâ otobus be Kâshân miravim.","lit":"avec · bus · [à] · Kashan · allons","say":{"Bâ":"با","bâ":"با","bâ otobus":"با اتوبوس","bâ ghatâr":"با قطار","bâ tâksi":"با تاکسی","Bâ otobus be Kâshân miravim":"با اتوبوس به کاشان می‌رویم","be":"به","piyâde":"پیاده","bâ sobhâne":"با صبحانه"}}},{"title":"Une excursion à Kashan","phrases":[{"fr":"Kashan est une ville au bord du désert.","tgt":"کاشان شهری کویری است.","ro":"Kâshân shahri kaviri ast.","lit":"Kashan · ville-[une] · désertique · est"},{"fr":"Le jardin de Fin est très célèbre.","tgt":"باغ فین خیلی معروف است.","ro":"Bâgh-e Fin kheyli ma'ruf ast.","lit":"jardin · [de] · Fin · très · célèbre · est"},{"fr":"Dans le jardin, l'eau coule partout.","tgt":"در باغ همه‌جا آب جاری است.","ro":"Dar bâgh hamejâ âb jâri ast.","lit":"dans · jardin · partout · eau · courante · est"},{"fr":"Les maisons anciennes de Kashan sont splendides.","tgt":"خانه‌های قدیمی کاشان خیلی زیبا هستند.","ro":"Khânehâ-ye ghadimi-ye Kâshân kheyli zibâ hastand.","lit":"maisons · [de] · anciennes · [de] · Kashan · très · belles · sont"},{"fr":"Kashan est connue pour son eau de rose.","tgt":"کاشان به گلاب معروف است.","ro":"Kâshân be golâb ma'ruf ast.","lit":"Kashan · [à] · eau-de-rose · célèbre · est"},{"fr":"Je voudrais une petite bouteille d'eau de rose.","tgt":"یک شیشه گلاب کوچک می‌خواهم.","ro":"Yek shishe golâb-e kuchak mikhâham.","lit":"une · bouteille · eau-de-rose · [de] · petite · veux"},{"fr":"Il fait chaud, mais l'air est sec.","tgt":"هوا گرم است، ولی خشک است.","ro":"Havâ garm ast, vali khoshk ast.","lit":"air · chaud · est · mais · sec · est"},{"fr":"Le bazar de Kashan est couvert.","tgt":"بازار کاشان سرپوشیده است.","ro":"Bâzâr-e Kâshân sarpushide ast.","lit":"bazar · [de] · Kashan · couvert · est"},{"fr":"En fin d'après-midi, nous rentrons à Ispahan.","tgt":"عصر به اصفهان برمی‌گردیم.","ro":"Asr be Esfahân barmigardim.","lit":"fin-d'après-midi · [à] · Ispahan · revenons"},{"fr":"Kashan me plaît beaucoup.","tgt":"از کاشان خیلی خوشم می‌آید.","ro":"Az Kâshân kheyli khosham miâyad.","lit":"de · Kashan · beaucoup · plaisir-mon · vient"}]},{"title":"Loin ou près ?","phrases":[{"fr":"Notre hôtel est tout près de la place.","tgt":"هتل ما خیلی نزدیک میدان است.","ro":"Hotel-e mâ kheyli nazdik-e meydân ast.","lit":"hôtel · [de] · nous · très · près · [de] · place · est"},{"fr":"Le bazar est loin d'ici ?","tgt":"بازار از اینجا دور است؟","ro":"Bâzâr az injâ dur ast?","lit":"bazar · de · ici · loin · est"},{"fr":"Non, ce n'est pas loin.","tgt":"نه، دور نیست.","ro":"Na, dur nist.","lit":"non · loin · [ne… pas]-est"},{"fr":"C'est tout près, à cinq minutes.","tgt":"خیلی نزدیک است، پنج دقیقه.","ro":"Kheyli nazdik ast, panj daghighe.","lit":"très · près · est · cinq · minute"},{"fr":"Kashan est loin d'Ispahan ?","tgt":"کاشان از اصفهان دور است؟","ro":"Kâshân az Esfahân dur ast?","lit":"Kashan · de · Ispahan · loin · est"},{"fr":"Pas très loin, environ trois heures.","tgt":"خیلی دور نیست، حدود سه ساعت.","ro":"Kheyli dur nist, hodud-e se sâ'at.","lit":"très · loin · [ne… pas]-est · environ · [de] · trois · heure"},{"fr":"Y a-t-il une boulangerie près de l'hôtel ?","tgt":"نزدیک هتل نانوایی هست؟","ro":"Nazdik-e hotel nânvâyi hast?","lit":"près · [de] · hôtel · boulangerie · il-y-a"},{"fr":"Le désert est loin de la ville.","tgt":"کویر از شهر دور است.","ro":"Kavir az shahr dur ast.","lit":"désert · de · ville · loin · est"},{"fr":"La gare ferroviaire est loin du centre-ville.","tgt":"ایستگاه قطار از مرکز شهر دور است.","ro":"Istgâh-e ghatâr az markaz-e shahr dur ast.","lit":"gare · [de] · train · de · centre · [de] · ville · loin · est"},{"fr":"Avec le métro, rien n'est loin.","tgt":"با مترو هیچ‌جا دور نیست.","ro":"Bâ metro hichjâ dur nist.","lit":"avec · métro · nulle-part · loin · [ne… pas]-est"}],"tip":{"title":"« Dur » et « nazdik » : loin et près","example":"Le bazar est loin d'ici ? — بازار از اینجا <b>دور</b> است؟","body":"« Dur » veut dire loin et « nazdik » veut dire près. Pour dire près de quelque chose, on relie « nazdik » au lieu avec le petit « -e » de l'ezâfe : « nazdik-e meydân », près de la place. Pour dire loin de, on utilise plutôt « az », de, placé devant le lieu : « az injâ dur ast », c'est loin d'ici. Prenons « Bâzâr az injâ dur ast ? », le bazar est loin d'ici ? Mot à mot : bazar, de, ici, loin, est. Pour répondre non, on garde le mot et on met le verbe au négatif : « Na, dur nist », non, ce n'est pas loin. Pour insister, ajoutez « kheyli », très : « kheyli nazdik ast », c'est tout près. Et pour une question, pas besoin de changer l'ordre, la voix monte simplement à la fin. Astuce : « dur » se prononce comme le mot français dur, et c'est vrai que c'est dur quand c'est loin.","exampleRo":"Bâzâr az injâ dur ast?","lit":"bazar · de · ici · loin · est","say":{"Dur":"دور","nazdik":"نزدیک","nazdik-e meydân":"نزدیک میدان","az":"از","az injâ dur ast":"از اینجا دور است","Bâzâr az injâ dur ast ?":"بازار از اینجا دور است؟","Na, dur nist":"نه، دور نیست","kheyli":"خیلی","kheyli nazdik ast":"خیلی نزدیک است","dur":"دور"}}},{"title":"Souvenirs du bazar","phrases":[{"fr":"Le bazar d'Ispahan est très ancien.","tgt":"بازار اصفهان خیلی قدیمی است.","ro":"Bâzâr-e Esfahân kheyli ghadimi ast.","lit":"bazar · [de] · Ispahan · très · ancien · est"},{"fr":"Cet artisan grave le cuivre.","tgt":"این استاد روی مس قلم‌زنی می‌کند.","ro":"In ostâd ru-ye mes ghalamzani mikonad.","lit":"ce · maître · sur · [de] · cuivre · gravure · fait"},{"fr":"Son atelier est petit mais charmant.","tgt":"کارگاهش کوچک ولی قشنگ است.","ro":"Kârgâhash kuchak vali ghashang ast.","lit":"atelier-son · petit · mais · joli · est"},{"fr":"Ces miniatures sont faites à la main.","tgt":"این مینیاتورها کار دست است.","ro":"In miniyâtorhâ kâr-e dast ast.","lit":"ces · miniatures · travail · [de] · main · est"},{"fr":"Je voudrais du gaz, le nougat d'Ispahan.","tgt":"گز اصفهان می‌خواهم.","ro":"Gaz-e Esfahân mikhâham.","lit":"gaz · [de] · Ispahan · veux"},{"fr":"Vous pouvez l'emballer en cadeau ?","tgt":"می‌توانید کادو کنید؟","ro":"Mitavânid kâdo konid?","lit":"pouvez · cadeau · que-vous-fassiez"},{"fr":"C'est pour ma mère, en France.","tgt":"برای مادرم در فرانسه است.","ro":"Barâye mâdaram dar Farânse ast.","lit":"pour · mère-ma · dans · France · est"},{"fr":"Cette nappe imprimée à la main est très jolie.","tgt":"این رومیزی قلمکار خیلی قشنگ است.","ro":"In rumizi-ye ghalamkâr kheyli ghashang ast.","lit":"cette · nappe · [de] · imprimée-main · très · jolie · est"},{"fr":"Je prends la nappe et deux boîtes de gaz.","tgt":"رومیزی و دو جعبه گز را می‌خرم.","ro":"Rumizi va do ja'be gaz râ mikharam.","lit":"nappe · et · deux · boîte · gaz · [objet] · achète"},{"fr":"Mon sac est plein de souvenirs.","tgt":"کیفم پر از سوغاتی است.","ro":"Kifam por az soghâti ast.","lit":"sac-mon · plein · de · souvenir · est"}]},{"title":"Fin du module : un bilan du voyage","phrases":[{"fr":"Ce module compte vingt leçons.","tgt":"این بخش بیست درس دارد.","ro":"In bakhsh bist dars dârad.","lit":"cette · partie · vingt · leçon · a"},{"fr":"Et deux cents phrases en persan !","tgt":"و دویست جمله به فارسی!","ro":"Va devist jomle be fârsi!","lit":"et · deux-cents · phrase · [à] · persan"},{"fr":"Maintenant, je connais cent mots de persan.","tgt":"حالا صد کلمه فارسی بلدم.","ro":"Hâlâ sad kalame-ye fârsi baladam.","lit":"maintenant · cent · mot · [de] · persan · sais"},{"fr":"Je sais demander un prix en tomans.","tgt":"می‌توانم قیمت را به تومان بپرسم.","ro":"Mitavânam gheymat râ be tomân beporsam.","lit":"peux · prix · [objet] · [à] · toman · que-je-demande"},{"fr":"Le billet pour Kashan coûte trois cent mille tomans.","tgt":"بلیت کاشان سیصد هزار تومان است.","ro":"Belit-e Kâshân sisad hezâr tomân ast.","lit":"billet · [de] · Kashan · trois-cents · mille · toman · est"},{"fr":"Le pont Si-o-se Pol a plus de quatre cents ans.","tgt":"سی‌وسه‌پل بیش از چهارصد سال دارد.","ro":"Si-o-se pol bish az chahârsad sâl dârad.","lit":"Si-o-se-Pol · plus · de · quatre-cents · an · a"},{"fr":"Un déjeuner au restaurant coûte environ cinq cent mille tomans.","tgt":"ناهار در رستوران حدود پانصد هزار تومان است.","ro":"Nâhâr dar resturân hodud-e pânsad hezâr tomân ast.","lit":"déjeuner · dans · restaurant · environ · [de] · cinq-cents · mille · toman · est"},{"fr":"Vingt, trente, quarante, cinquante !","tgt":"بیست، سی، چهل، پنجاه!","ro":"Bist, si, chehel, panjâh!","lit":"vingt · trente · quarante · cinquante"},{"fr":"Le persan devient plus facile chaque jour.","tgt":"فارسی هر روز آسان‌تر می‌شود.","ro":"Fârsi har ruz âsântar mishavad.","lit":"persan · chaque · jour · plus-facile · devient"},{"fr":"Au revoir, et à bientôt pour le module suivant !","tgt":"تا بخش بعدی، خداحافظ!","ro":"Tâ bakhsh-e ba'di, khodâhâfez!","lit":"jusqu'à · partie · [de] · suivante · au-revoir"}],"tip":{"title":"Les nombres au-delà de dix : « bist », « sad », « hezâr »","example":"Le billet pour Kashan coûte trois cent mille tomans. — بلیت کاشان <b>سیصد هزار</b> تومان است.","body":"Après dix, les nombres persans se construisent comme des briques. D'abord les dizaines : « bist », vingt, « si », trente, « chehel », quarante, « panjâh », cinquante. Pour vingt et un, on relie les deux nombres avec un petit « o », qui veut dire et : « bist-o yek ». Ensuite les centaines : « sad », cent, « devist », deux cents, « sisad », trois cents, « pânsad », cinq cents. Et mille se dit « hezâr ». Prenons « Belit-e Kâshân sisad hezâr tomân ast ». Mot à mot : billet, de, Kashan, trois cents, mille, toman, est. Comme en français, on dit d'abord le nombre, puis « hezâr » : « sisad hezâr », trois cent mille. Après un nombre, le nom reste au singulier : « sad kalame », cent mot. Astuce : au bazar, guettez d'abord le mot « hezâr », il vous annonce tout de suite que le prix se compte en milliers.","exampleRo":"Belit-e Kâshân sisad hezâr tomân ast.","lit":"billet · [de] · Kashan · trois-cents · mille · toman · est","say":{"bist":"بیست","sad":"صد","hezâr":"هزار","si":"سی","chehel":"چهل","panjâh":"پنجاه","bist-o yek":"بیست و یک","devist":"دویست","sisad":"سیصد","pânsad":"پانصد","Belit-e Kâshân sisad hezâr tomân ast":"بلیت کاشان سیصد هزار تومان است","sisad hezâr":"سیصد هزار","sad kalame":"صد کلمه"}}}]},{"id":3,"name":"Conversation sociale","desc":"Faire connaissance, se présenter, échanger avec aisance.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Une invitation à la maison","phrases":[{"fr":"Salut Maryam, merci pour l'invitation !","tgt":"سلام مریم، مرسی بابت دعوت!","ro":"Salâm Maryam, mersi bâbat-e da'vat!","lit":"salut · Maryam · merci · pour · [de] · invitation"},{"fr":"Bienvenue, entre donc !","tgt":"خوش اومدی، بیا تو!","ro":"Khosh umadi, biyâ tu!","lit":"bien · tu es venu · viens · dedans"},{"fr":"Ta maison est vraiment belle.","tgt":"خونه‌ت خیلی قشنگه.","ro":"Khunat kheyli ghashange.","lit":"maison-ta · très · belle-est"},{"fr":"Ces fleurs sont pour ta mère.","tgt":"این گل‌ها برای مادرته.","ro":"In golhâ barâye mâdarete.","lit":"ces · fleurs · pour · mère-ta-est"},{"fr":"Tout le monde est dans le salon.","tgt":"همه تو سالن هستن.","ro":"Hame tu sâlon hastan.","lit":"tous · dans · salon · sont"},{"fr":"Assieds-toi, je t'en prie.","tgt":"بشین، خواهش می‌کنم.","ro":"Beshin, khâhesh mikonam.","lit":"assieds-toi · prière · je fais"},{"fr":"Tu veux un thé ?","tgt":"چای می‌خوای؟","ro":"Châi mikhâi?","lit":"thé · tu veux"},{"fr":"Oui, avec grand plaisir.","tgt":"آره، با کمال میل.","ro":"Âre, bâ kamâl-e meyl.","lit":"oui · avec · perfection · [de] · envie"},{"fr":"Il fait chaud à Chiraz aujourd'hui.","tgt":"امروز هوای شیراز گرمه.","ro":"Emruz havâ-ye Shirâz garme.","lit":"aujourd'hui · air · [de] · Chiraz · chaud-est"},{"fr":"Je suis très heureux d'être ici.","tgt":"خیلی خوشحالم که اینجام.","ro":"Kheyli khoshhâlam ke injâm.","lit":"très · heureux-suis · que · ici-suis"}]},{"title":"Se présenter","phrases":[{"fr":"Comment tu t'appelles ?","tgt":"اسمت چیه؟","ro":"Esmet chie?","lit":"nom-ton · quoi-est"},{"fr":"Je m'appelle Marc.","tgt":"اسم من مارکه.","ro":"Esm-e man Mârk-e.","lit":"nom · [de] · moi · Marc-est"},{"fr":"Et vous, quel est votre nom ?","tgt":"شما چی؟ اسمتون چیه؟","ro":"Shomâ chi? Esmetun chie?","lit":"vous · quoi · nom-votre · quoi-est"},{"fr":"Je m'appelle Dariush, je suis le père de Maryam.","tgt":"اسم من داریوشه، پدر مریمم.","ro":"Esm-e man Dâriush-e, pedar-e Maryamam.","lit":"nom · [de] · moi · Dariush-est · père · [de] · Maryam-suis"},{"fr":"Très heureux de vous connaître.","tgt":"از آشنایی‌تون خوشوقتم.","ro":"Az âshnâyitun khoshvaghtam.","lit":"de · connaissance-votre · enchanté-suis"},{"fr":"Moi de même.","tgt":"منم همین‌طور.","ro":"Manam hamintor.","lit":"moi-aussi · de même"},{"fr":"Mon nom de famille, c'est Dupont.","tgt":"فامیلی من دوپونه.","ro":"Fâmili-ye man Dupon-e.","lit":"nom de famille · [de] · moi · Dupont-est"},{"fr":"Comment s'appelle ta sœur ?","tgt":"اسم خواهرت چیه؟","ro":"Esm-e khâharet chie?","lit":"nom · [de] · sœur-ta · quoi-est"},{"fr":"Elle s'appelle Shirin.","tgt":"اسمش شیرینه.","ro":"Esmesh Shirin-e.","lit":"nom-son · Shirin-est"},{"fr":"Shirin, c'est un très joli prénom.","tgt":"شیرین اسم خیلی قشنگیه.","ro":"Shirin esm-e kheyli ghashangie.","lit":"Shirin · nom · [de] · très · joli-un-est"}],"tip":{"title":"Se présenter : « esm-e man... e » et « esmetun chie ? »","example":"Je m'appelle Marc. — <b>اسم</b> من <b>مارکه</b>.","body":"Pour dire votre prénom en persan, la formule la plus naturelle est « esm-e man... e », mot à mot « nom de moi... est ». « Esm » veut dire nom, le petit « -e » qui suit relie ce nom à « man », moi, comme notre « de », et le « -e » final est le verbe être de la langue parlée, collé au prénom. Ainsi « esm-e man Mârk-e » se décompose en « esm », nom, « -e », de, « man », moi, puis « Mârk-e », Marc est : mon nom est Marc. Pour poser la question poliment, on dit « esmetun chie ? », avec « esm », nom, « -etun », votre, et « chie », qu'est-ce que c'est. Entre amis, on raccourcit en « esmet chie ? », ton nom, c'est quoi. Pour parler de quelqu'un d'autre, on dit « esmesh Shirin-e », son nom est Shirin. Retenez la petite musique de la phrase : un « e » pour relier, un « e » pour conclure.","exampleRo":"Esm-e man Mârk-e.","lit":"nom · [de] · moi · Marc-est","say":{"esmetun chie ?":"اسمتون چیه؟","Esm":"اسم","man":"من","esm-e man Mârk-e":"اسم من مارکه","esm":"اسم","Mârk-e":"مارکه","chie":"چیه","esmet chie ?":"اسمت چیه؟","esmesh Shirin-e":"اسمش شیرینه"}}},{"title":"Parler de soi et de la France","phrases":[{"fr":"Et toi, tu es originaire d'où ?","tgt":"اهل کجایی؟","ro":"Ahl-e kojâi?","lit":"originaire · [de] · où-es-tu"},{"fr":"Je suis français, originaire de Lyon.","tgt":"فرانسوی‌ام، اهل لیون.","ro":"Farânsavi-am, ahl-e Liyon.","lit":"français-suis · originaire · [de] · Lyon"},{"fr":"Lyon, c'est une grande ville ?","tgt":"لیون شهر بزرگیه؟","ro":"Liyon shahr-e bozorgie?","lit":"Lyon · ville · [de] · grande-une-est"},{"fr":"Oui, et on y mange très bien.","tgt":"آره، غذاش هم خیلی خوبه.","ro":"Âre, ghazâsh ham kheyli khube.","lit":"oui · nourriture-sa · aussi · très · bonne-est"},{"fr":"Tu habites à Paris maintenant ?","tgt":"الان پاریس زندگی می‌کنی؟","ro":"Alân Pâris zendegi mikoni?","lit":"maintenant · Paris · vie · tu fais"},{"fr":"Non, j'habite toujours à Lyon.","tgt":"نه، هنوز لیون زندگی می‌کنم.","ro":"Na, hanuz Liyon zendegi mikonam.","lit":"non · encore · Lyon · vie · je fais"},{"fr":"La France est très loin d'ici.","tgt":"فرانسه از اینجا خیلی دوره.","ro":"Farânse az injâ kheyli dure.","lit":"France · de · ici · très · loin-est"},{"fr":"C'est ton premier voyage en Iran ?","tgt":"اولین سفرت به ایرانه؟","ro":"Avvalin safaret be Irân-e?","lit":"premier · voyage-ton · [à] · Iran-est"},{"fr":"Oui, et j'adore déjà Chiraz.","tgt":"آره، از الان عاشق شیرازم.","ro":"Âre, az alân âshegh-e Shirâzam.","lit":"oui · dès · maintenant · amoureux · [de] · Chiraz-suis"},{"fr":"Je parle un petit peu persan.","tgt":"یه کم فارسی حرف می‌زنم.","ro":"Ye kam fârsi harf mizanam.","lit":"un · peu · persan · parole · je frappe"}]},{"title":"Parler de ses loisirs","phrases":[{"fr":"Qu'est-ce que tu aimes, toi ?","tgt":"تو چی دوست داری؟","ro":"To chi dust dâri?","lit":"toi · quoi · ami · tu as"},{"fr":"J'aime la musique et la lecture.","tgt":"موسیقی و کتاب خوندن رو دوست دارم.","ro":"Musighi o ketâb khundan ro dust dâram.","lit":"musique · et · livre · lire · [objet] · ami · j'ai"},{"fr":"Tu aimes le football ?","tgt":"فوتبال دوست داری؟","ro":"Futbâl dust dâri?","lit":"football · ami · tu as"},{"fr":"Pas trop, je préfère la marche.","tgt":"نه زیاد، پیاده‌روی رو بیشتر دوست دارم.","ro":"Na ziyâd, piyâderavi ro bishtar dust dâram.","lit":"non · beaucoup · marche · [objet] · plus · ami · j'ai"},{"fr":"Mon frère adore la natation.","tgt":"برادرم شنا رو خیلی دوست داره.","ro":"Barâdaram shenâ ro kheyli dust dâre.","lit":"frère-mon · natation · [objet] · très · ami · a"},{"fr":"Je n'aime pas la télévision.","tgt":"تلویزیون رو دوست ندارم.","ro":"Televiziyon ro dust nadâram.","lit":"télévision · [objet] · ami · [ne… pas]-j'ai"},{"fr":"Le vendredi, je me balade à vélo.","tgt":"جمعه‌ها دوچرخه‌سواری می‌کنم.","ro":"Jom'ehâ docharkhesavâri mikonam.","lit":"vendredis · vélo · je fais"},{"fr":"Tu aimes la cuisine iranienne ?","tgt":"غذای ایرانی دوست داری؟","ro":"Ghazâ-ye irâni dust dâri?","lit":"nourriture · [de] · iranienne · ami · tu as"},{"fr":"Oui, j'aime beaucoup le kebab.","tgt":"آره، کباب رو خیلی دوست دارم.","ro":"Âre, kabâb ro kheyli dust dâram.","lit":"oui · kebab · [objet] · très · ami · j'ai"},{"fr":"Nous aimons tous les deux la photographie.","tgt":"هر دوتامون عکاسی رو دوست داریم.","ro":"Har dotâmun akkâsi ro dust dârim.","lit":"chaque · deux-de-nous · photographie · [objet] · ami · nous avons"}],"tip":{"title":"« Dust dâram » : aimer","example":"Tu aimes le football ? — فوتبال <b>دوست داری</b>؟","body":"En persan, aimer se dit littéralement « avoir en ami » : « dust dâram », mot à mot « ami j'ai ». Seul le second mot change selon la personne : « dust dâram », j'aime, « dust dâri », tu aimes, « dust dâre », il ou elle aime, « dust dârim », nous aimons. La chose aimée se place avant, au début de la phrase, souvent suivie du petit mot « ro » quand elle est précise : « musighi ro dust dâram », j'aime la musique. Pour la négation, on ajoute simplement « na- » devant le verbe avoir : « dust nadâram », je n'aime pas. Pour dire que l'on adore, il suffit de glisser « kheyli », très, juste avant : « kabâb ro kheyli dust dâram ». Pour poser la question, gardez la même phrase et montez la voix à la fin : « futbâl dust dâri ? ». Astuce pour retenir : en persan, ce que vous aimez devient votre ami.","exampleRo":"Futbâl dust dâri?","lit":"football · ami · tu as","say":{"Dust dâram":"دوست دارم","dust dâram":"دوست دارم","dust dâri":"دوست داری","dust dâre":"دوست داره","dust dârim":"دوست داریم","musighi ro dust dâram":"موسیقی رو دوست دارم","dust nadâram":"دوست ندارم","kheyli":"خیلی","kabâb ro kheyli dust dâram":"کباب رو خیلی دوست دارم","futbâl dust dâri ?":"فوتبال دوست داری؟"}}},{"title":"Le travail et les études","phrases":[{"fr":"Quel est ton métier, au fait ?","tgt":"چی‌کاره‌ای؟","ro":"Chikâre-i?","lit":"quel-métier-es-tu"},{"fr":"Moi, je suis prof de français.","tgt":"معلم فرانسه‌ام.","ro":"Mo'allem-e farânse-am.","lit":"professeur · [de] · français-suis"},{"fr":"Et toi, tu travailles ?","tgt":"تو چی؟ کار می‌کنی؟","ro":"To chi? Kâr mikoni?","lit":"toi · quoi · travail · tu fais"},{"fr":"Non, je suis encore étudiante.","tgt":"نه، هنوز دانشجوام.","ro":"Na, hanuz dâneshju-am.","lit":"non · encore · étudiante-suis"},{"fr":"J'étudie l'architecture à Chiraz.","tgt":"تو شیراز معماری می‌خونم.","ro":"Tu Shirâz me'mâri mikhunam.","lit":"dans · Chiraz · architecture · je lis"},{"fr":"C'est un métier passionnant.","tgt":"شغل جالبیه.","ro":"Shoghl-e jâlebie.","lit":"métier · [de] · intéressant-un-est"},{"fr":"Mon bureau est près de la maison.","tgt":"دفترم نزدیک خونه‌ست.","ro":"Daftaram nazdik-e khunast.","lit":"bureau-mon · près · [de] · maison-est"},{"fr":"Tu travailles le jeudi ?","tgt":"پنجشنبه‌ها کار می‌کنی؟","ro":"Panjshanbehâ kâr mikoni?","lit":"jeudis · travail · tu fais"},{"fr":"Seulement le matin.","tgt":"فقط صبح‌ها.","ro":"Faghat sobhhâ.","lit":"seulement · matins"},{"fr":"J'aime beaucoup mon travail.","tgt":"کارم رو خیلی دوست دارم.","ro":"Kâram ro kheyli dust dâram.","lit":"travail-mon · [objet] · très · ami · j'ai"}]},{"title":"Parler de sa famille","phrases":[{"fr":"Voici mon père et ma mère.","tgt":"اینا پدر و مادرم هستن.","ro":"Inâ pedar o mâdaram hastan.","lit":"ceux-ci · père · et · mère-ma · sont"},{"fr":"Tu as des frères et sœurs ?","tgt":"خواهر و برادر داری؟","ro":"Khâhar o barâdar dâri?","lit":"sœur · et · frère · tu as"},{"fr":"J'ai un frère, et aussi une sœur.","tgt":"یه برادر و یه خواهر دارم.","ro":"Ye barâdar o ye khâhar dâram.","lit":"un · frère · et · une · sœur · j'ai"},{"fr":"Mon frère habite à Téhéran.","tgt":"برادرم تهران زندگی می‌کنه.","ro":"Barâdaram Tehrân zendegi mikone.","lit":"frère-mon · Téhéran · vie · fait"},{"fr":"Ma sœur a dix-neuf ans.","tgt":"خواهرم نوزده سالشه.","ro":"Khâharam nuzdah sâleshe.","lit":"sœur-ma · dix-neuf · an-son-est"},{"fr":"Ta mère est très gentille.","tgt":"مادرت خیلی مهربونه.","ro":"Mâdaret kheyli mehrabune.","lit":"mère-ta · très · gentille-est"},{"fr":"Mon père, lui, est médecin.","tgt":"پدرم دکتره.","ro":"Pedaram doktore.","lit":"père-mon · médecin-est"},{"fr":"Tes parents habitent à Lyon ?","tgt":"پدر و مادرت لیون زندگی می‌کنن؟","ro":"Pedar o mâdaret Liyon zendegi mikonan?","lit":"père · et · mère-ta · Lyon · vie · font"},{"fr":"Oui, avec ma grand-mère.","tgt":"آره، با مادربزرگم.","ro":"Âre, bâ mâdarbozorgam.","lit":"oui · avec · grand-mère-ma"},{"fr":"Ma famille n'est pas très grande.","tgt":"خانواده‌م خیلی بزرگ نیست.","ro":"Khânevâdam kheyli bozorg nist.","lit":"famille-ma · très · grande · n'est pas"}],"tip":{"title":"La famille : « pedar », « mâdar », « barâdar », « khâhar »","example":"Voici mon père et ma mère. — اینا <b>پدر</b> و <b>مادرم</b> هستن.","body":"Bonne nouvelle : les mots de la famille en persan ressemblent beaucoup aux nôtres, car ils ont une origine commune très ancienne. « Pedar », le père, rappelle « paternel », « mâdar », la mère, sonne comme « maternel », et « barâdar », le frère, ressemble à « fraternel ». Seule « khâhar », la sœur, est plus surprenante, avec son « kh » qui se prononce du fond de la gorge. Pour dire mon père, on colle simplement « -am » à la fin du mot : « pedaram », « mâdaram », « barâdaram », « khâharam ». Avec « -et », on obtient ton ou ta : « mâdaret », ta mère. Les parents se disent « pedar o mâdar », mot à mot père et mère, avec un petit « o » pour dire et. Les grands-parents ajoutent « bozorg », grand : « pedarbozorg », grand-père, et « mâdarbozorg », grand-mère. Astuce : pensez à paternel, maternel et fraternel, et la moitié du travail est déjà faite.","exampleRo":"Inâ pedar o mâdaram hastan.","lit":"ceux-ci · père · et · mère-ma · sont","say":{"pedar":"پدر","mâdar":"مادر","barâdar":"برادر","khâhar":"خواهر","Pedar":"پدر","pedaram":"پدرم","mâdaram":"مادرم","barâdaram":"برادرم","khâharam":"خواهرم","mâdaret":"مادرت","pedar o mâdar":"پدر و مادر","bozorg":"بزرگ","pedarbozorg":"پدربزرگ","mâdarbozorg":"مادربزرگ"}}},{"title":"Visiter la maison","phrases":[{"fr":"Elle est où, ta chambre ?","tgt":"اتاقت کجاست؟","ro":"Otâghet kojâst?","lit":"chambre-ta · où-est"},{"fr":"En haut, à côté de la cuisine.","tgt":"بالاست، کنار آشپزخونه.","ro":"Bâlâst, kenâr-e âshpazkhune.","lit":"en haut-est · à côté · [de] · cuisine"},{"fr":"La maison a une petite cour.","tgt":"خونه یه حیاط کوچیک داره.","ro":"Khune ye hayât-e kuchik dâre.","lit":"maison · une · cour · [de] · petite · a"},{"fr":"Il y a un bassin au milieu de la cour.","tgt":"وسط حیاط یه حوض هست.","ro":"Vasat-e hayât ye hoz hast.","lit":"milieu · [de] · cour · un · bassin · il y a"},{"fr":"J'aime beaucoup ces tapis.","tgt":"این فرش‌ها رو خیلی دوست دارم.","ro":"In farshhâ ro kheyli dust dâram.","lit":"ces · tapis · [objet] · très · ami · j'ai"},{"fr":"Ce tapis vient de Chiraz ?","tgt":"این فرش مال شیرازه؟","ro":"In farsh mâl-e Shirâz-e?","lit":"ce · tapis · propriété · [de] · Chiraz-est"},{"fr":"Oui, il est à ma grand-mère.","tgt":"آره، مال مادربزرگمه.","ro":"Âre, mâl-e mâdarbozorgame.","lit":"oui · propriété · [de] · grand-mère-ma-est"},{"fr":"Le salon est très lumineux.","tgt":"سالن خیلی روشنه.","ro":"Sâlon kheyli roshane.","lit":"salon · très · lumineux-est"},{"fr":"On s'assoit par terre ou sur le canapé ?","tgt":"رو زمین می‌شینیم یا رو مبل؟","ro":"Ru zamin mishinim yâ ru mobl?","lit":"sur · sol · nous nous asseyons · ou · sur · canapé"},{"fr":"Ici, tu es comme chez toi.","tgt":"اینجا مثل خونه‌ی خودته.","ro":"Injâ mesl-e khune-ye khodete.","lit":"ici · comme · maison · [de] · toi-même-est"}]},{"title":"Qu'est-ce que tu fais en ce moment ?","phrases":[{"fr":"Tu es en train de faire quoi ?","tgt":"داری چی کار می‌کنی؟","ro":"Dâri chi kâr mikoni?","lit":"tu as · quoi · travail · tu fais"},{"fr":"Je suis en train de préparer le thé.","tgt":"دارم چای درست می‌کنم.","ro":"Dâram châi dorost mikonam.","lit":"j'ai · thé · prêt · je fais"},{"fr":"Maman est en train de cuisiner.","tgt":"مامان داره غذا می‌پزه.","ro":"Mâmân dâre ghazâ mipaze.","lit":"maman · a · nourriture · cuit"},{"fr":"Les enfants sont en train de jouer dans la cour.","tgt":"بچه‌ها دارن تو حیاط بازی می‌کنن.","ro":"Bachehâ dâran tu hayât bâzi mikonan.","lit":"enfants · ont · dans · cour · jeu · font"},{"fr":"Mon père est en train de lire le journal.","tgt":"پدرم داره روزنامه می‌خونه.","ro":"Pedaram dâre ruznâme mikhune.","lit":"père-mon · a · journal · lit"},{"fr":"Tu es en train de manger ?","tgt":"داری غذا می‌خوری؟","ro":"Dâri ghazâ mikhori?","lit":"tu as · nourriture · tu manges"},{"fr":"Non, j'envoie un message à ma sœur.","tgt":"نه، دارم به خواهرم پیام می‌دم.","ro":"Na, dâram be khâharam payâm midam.","lit":"non · j'ai · [à] · sœur-ma · message · je donne"},{"fr":"Regarde, il commence à pleuvoir.","tgt":"نگاه کن، داره بارون میاد.","ro":"Negâh kon, dâre bârun miyâd.","lit":"regard · fais · a · pluie · vient"},{"fr":"Nous sommes en train d'écouter de la musique.","tgt":"داریم موسیقی گوش می‌دیم.","ro":"Dârim musighi gush midim.","lit":"nous avons · musique · oreille · nous donnons"},{"fr":"J'arrive, je mets mes chaussures.","tgt":"دارم میام، دارم کفش می‌پوشم.","ro":"Dâram miyâm, dâram kafsh mipusham.","lit":"j'ai · je viens · j'ai · chaussure · je mets"}],"tip":{"title":"« Dâram mikhoram » : être en train de","example":"Je suis en train de préparer le thé. — <b>دارم</b> چای درست <b>می‌کنم</b>.","body":"Pour dire qu'une action se passe en ce moment même, le persan parlé utilise une construction très imagée : le verbe avoir, « dâram », suivi du verbe au présent. « Dâram mikhoram » veut dire mot à mot « j'ai je mange », c'est-à-dire je suis en train de manger. Les deux verbes changent ensemble selon la personne : « dâri mikhori », tu es en train de manger, « dâre mikhore », il est en train de manger, « dârim mikhorim », nous sommes en train de manger. Prenons « dâram châi dorost mikonam » : « dâram », j'ai, « châi », du thé, « dorost mikonam », je prépare, donc je suis en train de préparer le thé. Remarquez que l'objet se glisse entre les deux verbes. C'est très courant à l'oral, par exemple « dâre bârun miyâd », il est en train de pleuvoir, ou « dâram miyâm », j'arrive. Astuce : pensez à un écho, le verbe avoir annonce l'action et le second verbe répond avec la même personne.","exampleRo":"Dâram châi dorost mikonam.","lit":"j'ai · thé · prêt · je fais","say":{"Dâram mikhoram":"دارم می‌خورم","dâram":"دارم","dâri mikhori":"داری می‌خوری","dâre mikhore":"داره می‌خوره","dârim mikhorim":"داریم می‌خوریم","dâram châi dorost mikonam":"دارم چای درست می‌کنم","châi":"چای","dorost mikonam":"درست می‌کنم","dâre bârun miyâd":"داره بارون میاد","dâram miyâm":"دارم میام"}}},{"title":"Le thé et les douceurs","phrases":[{"fr":"Le thé est prêt !","tgt":"چای حاضره!","ro":"Châi hâzere!","lit":"thé · prêt-est"},{"fr":"Tu prends du sucre ?","tgt":"شکر می‌خوای؟","ro":"Shekar mikhâi?","lit":"sucre · tu veux"},{"fr":"Non merci, je veux du nabat.","tgt":"نه مرسی، نبات می‌خوام.","ro":"Na mersi, nabât mikhâm.","lit":"non · merci · sucre candi · je veux"},{"fr":"Ce thé sent vraiment bon.","tgt":"این چای خیلی بوی خوبی داره.","ro":"In châi kheyli bu-ye khubi dâre.","lit":"ce · thé · très · odeur · [de] · bonne-une · a"},{"fr":"Ta mère fait ces gâteaux elle-même ?","tgt":"مادرت این شیرینی‌ها رو خودش درست می‌کنه؟","ro":"Mâdaret in shirinihâ ro khodesh dorost mikone?","lit":"mère-ta · ces · gâteaux · [objet] · elle-même · prêt · fait"},{"fr":"Goûte ce gâteau, il est délicieux.","tgt":"این شیرینی رو بخور، خیلی خوشمزه‌ست.","ro":"In shirini ro bokhor, kheyli khoshmazast.","lit":"ce · gâteau · [objet] · mange · très · délicieux-est"},{"fr":"Encore un verre de thé ?","tgt":"یه چای دیگه؟","ro":"Ye châi-ye dige?","lit":"un · thé · [de] · autre"},{"fr":"Merci, ça me suffit.","tgt":"مرسی، دیگه بسه.","ro":"Mersi, dige basse.","lit":"merci · désormais · suffisant-est"},{"fr":"Les Iraniens boivent du thé toute la journée.","tgt":"ایرانی‌ها تمام روز چای می‌خورن.","ro":"Irânihâ tamâm-e ruz châi mikhoran.","lit":"Iraniens · toute · [de] · journée · thé · mangent"},{"fr":"Chez nous, on boit plutôt du café.","tgt":"ما تو خونه بیشتر قهوه می‌خوریم.","ro":"Mâ tu khune bishtar ghahve mikhorim.","lit":"nous · dans · maison · plus · café · mangeons"}]},{"title":"Les jardins de Chiraz","phrases":[{"fr":"Le jardin d'Eram est magnifique.","tgt":"باغ ارم خیلی قشنگه.","ro":"Bâgh-e Eram kheyli ghashange.","lit":"jardin · [de] · Eram · très · beau-est"},{"fr":"Il est plus grand que le jardin de Narenjestan.","tgt":"از باغ نارنجستان بزرگ‌تره.","ro":"Az bâgh-e Nârenjestân bozorgtare.","lit":"de · jardin · [de] · Narenjestan · grand-plus-est"},{"fr":"Ce jardin est plus calme que la rue.","tgt":"این باغ از خیابون آروم‌تره.","ro":"In bâgh az khiyâbun ârumtare.","lit":"ce · jardin · de · rue · calme-plus-est"},{"fr":"Ici, l'air est plus frais.","tgt":"اینجا هوا خنک‌تره.","ro":"Injâ havâ khonaktare.","lit":"ici · air · frais-plus-est"},{"fr":"Les fleurs d'ici sentent meilleur que les nôtres.","tgt":"گل‌های اینجا از گل‌های ما خوشبوترن.","ro":"Golhâ-ye injâ az golhâ-ye mâ khoshbutaran.","lit":"fleurs · [de] · ici · de · fleurs · [de] · nous · parfumées-plus-sont"},{"fr":"Ici, le printemps est plus beau que l'été.","tgt":"اینجا بهار از تابستون قشنگ‌تره.","ro":"Injâ bahâr az tâbestun ghashangtare.","lit":"ici · printemps · de · été · beau-plus-est"},{"fr":"Ce cyprès est plus vieux que la maison.","tgt":"این سرو از خونه قدیمی‌تره.","ro":"In sarv az khune ghadimitare.","lit":"ce · cyprès · de · maison · vieux-plus-est"},{"fr":"Mon jardin à Lyon est plus petit.","tgt":"باغچه‌ی من تو لیون کوچیک‌تره.","ro":"Bâghche-ye man tu Liyon kuchiktare.","lit":"jardinet · [de] · moi · dans · Lyon · petit-plus-est"},{"fr":"À ton avis, quel jardin est le plus beau ?","tgt":"به نظرت کدوم باغ قشنگ‌تره؟","ro":"Be nazaret kodum bâgh ghashangtare?","lit":"[à] · avis-ton · quel · jardin · beau-plus-est"},{"fr":"Pour moi, le jardin d'Eram est mieux.","tgt":"به نظر من باغ ارم بهتره.","ro":"Be nazar-e man bâgh-e Eram behtare.","lit":"[à] · avis · [de] · moi · jardin · [de] · Eram · meilleur-est"}],"tip":{"title":"Comparer avec « -tar » et « az »","example":"Ce jardin est plus calme que la rue. — این باغ <b>از</b> خیابون <b>آروم‌تره</b>.","body":"Pour comparer, le persan est d'une simplicité étonnante : on ajoute « -tar » à la fin de l'adjectif, comme on dirait plus en français. « Bozorg », grand, devient « bozorgtar », plus grand, et « kuchik », petit, devient « kuchiktar », plus petit. Ce à quoi on compare est introduit par « az », qui veut dire de, et se place avant l'adjectif. Ainsi « in bâgh az khiyâbun ârumtare » se lit mot à mot « ce jardin, de la rue, plus calme est » : ce jardin est plus calme que la rue. L'ordre est donc l'inverse du français, la comparaison vient d'abord, l'adjectif ensuite, et le verbe à la toute fin. Attention à une exception très courante : bon, « khub », donne « behtar », meilleur ou mieux. Autres exemples utiles : « garmtar », plus chaud, et « ghashangtar », plus beau. Astuce : « tar » arrive toujours tard, collé à la fin de l'adjectif.","exampleRo":"In bâgh az khiyâbun ârumtare.","lit":"ce · jardin · de · rue · calme-plus-est","say":{"az":"از","Bozorg":"بزرگ","bozorgtar":"بزرگ‌تر","kuchik":"کوچیک","kuchiktar":"کوچیک‌تر","in bâgh az khiyâbun ârumtare":"این باغ از خیابون آروم‌تره","khub":"خوب","behtar":"بهتر","garmtar":"گرم‌تر","ghashangtar":"قشنگ‌تر"}}},{"title":"Parler du temps et des saisons","phrases":[{"fr":"Qu'il fait beau aujourd'hui !","tgt":"امروز هوا چه خوبه!","ro":"Emruz havâ che khube!","lit":"aujourd'hui · air · comme · bon-est"},{"fr":"Au printemps, Chiraz sent la fleur d'oranger.","tgt":"بهار، شیراز بوی بهارنارنج می‌ده.","ro":"Bahâr, Shirâz bu-ye bahârnârenj mide.","lit":"printemps · Chiraz · odeur · [de] · fleur d'oranger · donne"},{"fr":"En été, il fait très chaud ici.","tgt":"تابستون اینجا خیلی گرمه.","ro":"Tâbestun injâ kheyli garme.","lit":"été · ici · très · chaud-est"},{"fr":"Est-ce qu'il neige à Chiraz en hiver ?","tgt":"زمستون تو شیراز برف میاد؟","ro":"Zemestun tu Shirâz barf miyâd?","lit":"hiver · dans · Chiraz · neige · vient"},{"fr":"Très rarement, mais les nuits sont froides.","tgt":"خیلی کم، ولی شب‌ها سرده.","ro":"Kheyli kam, vali shabhâ sarde.","lit":"très · peu · mais · nuits · froid-est"},{"fr":"À Lyon, il pleut souvent.","tgt":"لیون زیاد بارون میاد.","ro":"Liyon ziyâd bârun miyâd.","lit":"Lyon · beaucoup · pluie · vient"},{"fr":"Quelle saison tu préfères ?","tgt":"کدوم فصل رو بیشتر دوست داری؟","ro":"Kodum fasl ro bishtar dust dâri?","lit":"quelle · saison · [objet] · plus · ami · tu as"},{"fr":"Moi, je préfère l'automne.","tgt":"من پاییز رو بیشتر دوست دارم.","ro":"Man pâiz ro bishtar dust dâram.","lit":"moi · automne · [objet] · plus · ami · j'ai"},{"fr":"Le ciel est tout bleu aujourd'hui.","tgt":"امروز آسمون خیلی آبیه.","ro":"Emruz âsemun kheyli âbie.","lit":"aujourd'hui · ciel · très · bleu-est"},{"fr":"Le soir, il fait bon dans la cour.","tgt":"عصرها تو حیاط هوا خوبه.","ro":"Asrhâ tu hayât havâ khube.","lit":"soirs · dans · cour · air · bon-est"}]},{"title":"Les projets du week-end","phrases":[{"fr":"Qu'est-ce que tu fais vendredi ?","tgt":"جمعه چی کار می‌کنی؟","ro":"Jom'e chi kâr mikoni?","lit":"vendredi · quoi · travail · tu fais"},{"fr":"Je vais à Persépolis avec mes amis.","tgt":"با دوستام می‌رم تخت جمشید.","ro":"Bâ dustâm miram Takht-e Jamshid.","lit":"avec · amis-mes · je vais · Persépolis"},{"fr":"On part tôt, parce qu'il fait chaud.","tgt":"زود می‌ریم، چون هوا گرمه.","ro":"Zud mirim, chon havâ garme.","lit":"tôt · nous allons · parce que · air · chaud-est"},{"fr":"Je reste à la maison, parce que je suis fatigué.","tgt":"خونه می‌مونم، چون خسته‌ام.","ro":"Khune mimunam, chon khaste-am.","lit":"maison · je reste · parce que · fatigué-suis"},{"fr":"Mon frère vient, donc on prépare des kebabs.","tgt":"برادرم میاد، برای همین کباب درست می‌کنیم.","ro":"Barâdaram miyâd, barâye hamin kabâb dorost mikonim.","lit":"frère-mon · vient · pour · cela même · kebab · prêt · nous faisons"},{"fr":"Pourquoi tu ne viens pas avec nous ?","tgt":"چرا با ما نمیای؟","ro":"Cherâ bâ mâ nemiyâi?","lit":"pourquoi · avec · nous · [ne… pas]-tu viens"},{"fr":"Parce que j'ai du travail samedi.","tgt":"چون شنبه کار دارم.","ro":"Chon shanbe kâr dâram.","lit":"parce que · samedi · travail · j'ai"},{"fr":"Il pleut, donc on reste à l'intérieur.","tgt":"بارون میاد، برای همین تو خونه می‌مونیم.","ro":"Bârun miyâd, barâye hamin tu khune mimunim.","lit":"pluie · vient · pour · cela même · dans · maison · nous restons"},{"fr":"J'aime le vendredi, parce qu'on se repose.","tgt":"جمعه رو دوست دارم، چون استراحت می‌کنیم.","ro":"Jom'e ro dust dâram, chon esterâhat mikonim.","lit":"vendredi · [objet] · ami · j'ai · parce que · repos · nous faisons"},{"fr":"Le jardin ferme tard, donc on a le temps.","tgt":"باغ دیر می‌بنده، برای همین وقت داریم.","ro":"Bâgh dir mibande, barâye hamin vaght dârim.","lit":"jardin · tard · ferme · pour · cela même · temps · nous avons"}],"tip":{"title":"« Chon » et « barâye hamin » : parce que, donc","example":"Il pleut, donc on reste à l'intérieur. — بارون میاد، <b>برای همین</b> تو خونه می‌مونیم.","body":"Pour expliquer vos raisons, deux petites formules suffisent. « Chon » veut dire parce que, et s'utilise exactement comme en français : « khune mimunam, chon khaste-am », je reste à la maison parce que je suis fatigué. On peut aussi commencer une réponse par « chon », juste après la question « cherâ ? », pourquoi. Pour annoncer la conséquence, on dit « barâye hamin », mot à mot « pour cela même », c'est-à-dire donc, ou c'est pour ça. Décomposons « bârun miyâd, barâye hamin tu khune mimunim » : la pluie vient, pour cela même, dans la maison nous restons. Les deux formules ne changent jamais, quelle que soit la personne. Elles permettent de relier deux phrases simples sans grammaire compliquée, ce qui est idéal pour converser. Astuce : « chon » donne la cause, « barâye hamin » tire la conclusion, comme les deux bouts d'un même fil.","exampleRo":"Bârun miyâd, barâye hamin tu khune mimunim.","lit":"pluie · vient · pour · cela même · dans · maison · nous restons","say":{"Chon":"چون","barâye hamin":"برای همین","khune mimunam, chon khaste-am":"خونه می‌مونم، چون خسته‌ام","chon":"چون","cherâ ?":"چرا؟","bârun miyâd, barâye hamin tu khune mimunim":"بارون میاد، برای همین تو خونه می‌مونیم"}}},{"title":"Parler de musique","phrases":[{"fr":"Tu joues d'un instrument ?","tgt":"سازی می‌زنی؟","ro":"Sâzi mizani?","lit":"instrument-un · tu frappes"},{"fr":"Oui, je joue du setar.","tgt":"آره، سه‌تار می‌زنم.","ro":"Âre, setâr mizanam.","lit":"oui · setar · je frappe"},{"fr":"Mon oncle joue du tar.","tgt":"دایی‌م تار می‌زنه.","ro":"Dâyim târ mizane.","lit":"oncle-mon · tar · frappe"},{"fr":"J'adore la musique traditionnelle.","tgt":"موسیقی سنتی رو خیلی دوست دارم.","ro":"Musighi-ye sonnati ro kheyli dust dâram.","lit":"musique · [de] · traditionnelle · [objet] · très · ami · j'ai"},{"fr":"Ce chanteur a une voix superbe.","tgt":"این خواننده صدای خیلی قشنگی داره.","ro":"In khânande sedâ-ye kheyli ghashangi dâre.","lit":"ce · chanteur · voix · [de] · très · belle-une · a"},{"fr":"Tu écoutes quoi, d'habitude ?","tgt":"معمولا چی گوش می‌دی؟","ro":"Ma'mulan chi gush midi?","lit":"d'habitude · quoi · oreille · tu donnes"},{"fr":"J'écoute de la musique française.","tgt":"موسیقی فرانسوی گوش می‌دم.","ro":"Musighi-ye farânsavi gush midam.","lit":"musique · [de] · française · oreille · je donne"},{"fr":"Tu nous joues un morceau ?","tgt":"یه آهنگ برامون می‌زنی؟","ro":"Ye âhang barâmun mizani?","lit":"un · morceau · pour-nous · tu frappes"},{"fr":"Volontiers, mais je ne joue pas très bien.","tgt":"با کمال میل، ولی خیلی خوب نمی‌زنم.","ro":"Bâ kamâl-e meyl, vali kheyli khub nemizanam.","lit":"avec · perfection · [de] · envie · mais · très · bien · [ne… pas]-je frappe"},{"fr":"Ici, la musique et la poésie vont toujours ensemble.","tgt":"اینجا موسیقی و شعر همیشه با هم‌ان.","ro":"Injâ musighi o she'r hamishe bâ ham-an.","lit":"ici · musique · et · poésie · toujours · avec · ensemble-sont"}]},{"title":"Le dîner en famille","phrases":[{"fr":"Le dîner est prêt !","tgt":"شام حاضره!","ro":"Shâm hâzere!","lit":"dîner · prêt-est"},{"fr":"Mesdames et messieurs, à table !","tgt":"خانم‌ها و آقایان، بفرمایید شام!","ro":"Khânomhâ va âghâyân, befarmâyid shâm!","lit":"dames · et · messieurs · je vous en prie · dîner"},{"fr":"Les enfants, venez dîner !","tgt":"بچه‌ها، بیاین شام!","ro":"Bachehâ, biyâin shâm!","lit":"enfants · venez · dîner"},{"fr":"Les assiettes sont sur la nappe.","tgt":"بشقاب‌ها رو سفره‌ان.","ro":"Boshghâbhâ ru sofre-an.","lit":"assiettes · sur · nappe-sont"},{"fr":"On a du riz aux baies d'épine-vinette avec du poulet.","tgt":"زرشک‌پلو با مرغ داریم.","ro":"Zereshkpolo bâ morgh dârim.","lit":"riz-épine-vinette · avec · poulet · nous avons"},{"fr":"Les invités sont dans le salon.","tgt":"مهمون‌ها تو سالنن.","ro":"Mehmunhâ tu sâlonan.","lit":"invités · dans · salon-sont"},{"fr":"Ces plats sont délicieux.","tgt":"این غذاها خیلی خوشمزه‌ان.","ro":"In ghazâhâ kheyli khoshmaze-an.","lit":"ces · plats · très · délicieux-sont"},{"fr":"Les arbres du jardin sont très vieux.","tgt":"درختان باغ خیلی قدیمی‌ان.","ro":"Derakhtân-e bâgh kheyli ghadimi-an.","lit":"arbres · [de] · jardin · très · vieux-sont"},{"fr":"Chers amis, soyez les bienvenus !","tgt":"دوستان عزیز، خوش اومدین!","ro":"Dustân-e aziz, khosh umadin!","lit":"amis · [de] · chers · bien · vous êtes venus"},{"fr":"Les fruits sont dans la cuisine.","tgt":"میوه‌ها تو آشپزخونه‌ان.","ro":"Mivehâ tu âshpazkhune-an.","lit":"fruits · dans · cuisine-sont"}],"tip":{"title":"Le pluriel : « -hâ » et « -ân »","example":"Mesdames et messieurs, à table ! — <b>خانم‌ها</b> و <b>آقایان</b>، بفرمایید شام!","body":"En persan, le pluriel se fait presque toujours en ajoutant « -hâ » à la fin du mot. « Gol », la fleur, devient « golhâ », les fleurs, « bache », l'enfant, devient « bachehâ », les enfants, et « boshghâb », l'assiette, devient « boshghâbhâ ». Dans la conversation rapide, le « h » s'efface souvent et l'on entend « golâ » ou « dustâ », mais « -hâ » est toujours compris. Il existe une seconde terminaison, « -ân », plus élégante, qu'on entend dans les discours, les formules de politesse et la poésie. « Âghâ », monsieur, donne « âghâyân », messieurs, et « dust », ami, donne « dustân », amis. Ainsi « khânomhâ va âghâyân » veut dire mesdames et messieurs, avec les deux pluriels côte à côte. Détail utile : après un nombre, le nom reste au singulier, on dit « do barâdar », mot à mot deux frère. Astuce : « -hâ » pour tous les jours, « -ân » pour les grandes occasions.","exampleRo":"Khânomhâ va âghâyân, befarmâyid shâm!","lit":"dames · et · messieurs · je vous en prie · dîner","say":{"Gol":"گل","golhâ":"گل‌ها","bache":"بچه","bachehâ":"بچه‌ها","boshghâb":"بشقاب","boshghâbhâ":"بشقاب‌ها","golâ":"گلا","dustâ":"دوستا","Âghâ":"آقا","âghâyân":"آقایان","dust":"دوست","dustân":"دوستان","khânomhâ va âghâyân":"خانم‌ها و آقایان","do barâdar":"دو برادر","-hâ":"ها"}}},{"title":"La poésie de Hafez","phrases":[{"fr":"Tu connais Hafez ?","tgt":"حافظ رو می‌شناسی؟","ro":"Hâfez ro mishenâsi?","lit":"Hafez · [objet] · tu connais"},{"fr":"Oui, c'est le grand poète de Chiraz.","tgt":"آره، شاعر بزرگ شیرازه.","ro":"Âre, shâ'er-e bozorg-e Shirâz-e.","lit":"oui · poète · [de] · grand · [de] · Chiraz-est"},{"fr":"Le tombeau de Hafez est près d'ici.","tgt":"آرامگاه حافظ نزدیک اینجاست.","ro":"Ârâmgâh-e Hâfez nazdik-e injâst.","lit":"tombeau · [de] · Hafez · près · [de] · ici-est"},{"fr":"Le soir, il y a beaucoup de monde là-bas.","tgt":"عصرها اونجا خیلی شلوغه.","ro":"Asrhâ unjâ kheyli sholughe.","lit":"soirs · là-bas · très · animé-est"},{"fr":"Mon père lit Hafez tous les soirs.","tgt":"پدرم هر شب حافظ می‌خونه.","ro":"Pedaram har shab Hâfez mikhune.","lit":"père-mon · chaque · nuit · Hafez · lit"},{"fr":"Dans chaque maison, il y a un recueil de Hafez.","tgt":"تو هر خونه یه دیوان حافظ هست.","ro":"Tu har khune ye divân-e Hâfez hast.","lit":"dans · chaque · maison · un · recueil · [de] · Hafez · il y a"},{"fr":"Tu me lis un poème ?","tgt":"یه شعر برام می‌خونی؟","ro":"Ye she'r barâm mikhuni?","lit":"un · poème · pour-moi · tu lis"},{"fr":"Je ne comprends pas tous les mots.","tgt":"همه‌ی کلمه‌ها رو نمی‌فهمم.","ro":"Hame-ye kalamehâ ro nemifahmam.","lit":"tous · [de] · mots · [objet] · [ne… pas]-je comprends"},{"fr":"Pas grave, la musique des mots suffit.","tgt":"مهم نیست، آهنگ کلمه‌ها کافیه.","ro":"Mohem nist, âhang-e kalamehâ kâfie.","lit":"important · n'est pas · musique · [de] · mots · suffisante-est"},{"fr":"Les Iraniens aiment beaucoup la poésie.","tgt":"ایرانی‌ها شعر رو خیلی دوست دارن.","ro":"Irânihâ she'r ro kheyli dust dâran.","lit":"Iraniens · poésie · [objet] · très · ami · ont"}]},{"title":"Entre amis ou avec les aînés","phrases":[{"fr":"Tu peux me tutoyer.","tgt":"می‌تونی به من «تو» بگی.","ro":"Mituni be man «to» begi.","lit":"tu peux · [à] · moi · « tu » · que tu dises"},{"fr":"Vous êtes la mère de Maryam ?","tgt":"شما مادر مریم هستین؟","ro":"Shomâ mâdar-e Maryam hastin?","lit":"vous · mère · [de] · Maryam · êtes"},{"fr":"Oui. Et toi, tu es Marc ?","tgt":"بله. تو مارکی؟","ro":"Bale. To Mârki?","lit":"oui · toi · Marc-es"},{"fr":"Comment allez-vous, madame ?","tgt":"حالتون چطوره، خانم؟","ro":"Hâletun chetore, khânom?","lit":"état-votre · comment-est · madame"},{"fr":"Et toi, ça va ?","tgt":"تو چطوری؟","ro":"To chetori?","lit":"toi · comment-es"},{"fr":"Avec les amis, on dit « to ».","tgt":"با دوستا «تو» می‌گیم.","ro":"Bâ dustâ «to» migim.","lit":"avec · amis · « tu » · nous disons"},{"fr":"Avec les grands-parents, on dit « shomâ ».","tgt":"با پدربزرگ و مادربزرگ «شما» می‌گیم.","ro":"Bâ pedarbozorg o mâdarbozorg «shomâ» migim.","lit":"avec · grand-père · et · grand-mère · « vous » · nous disons"},{"fr":"Monsieur, vous désirez un thé ?","tgt":"آقا، چای میل دارین؟","ro":"Âghâ, châi meyl dârin?","lit":"monsieur · thé · envie · vous avez"},{"fr":"Tu veux un fruit ?","tgt":"میوه می‌خوای؟","ro":"Mive mikhâi?","lit":"fruit · tu veux"},{"fr":"Vous comprenez un peu le français ?","tgt":"شما یه کم فرانسه می‌فهمین؟","ro":"Shomâ ye kam farânse mifahmin?","lit":"vous · un · peu · français · vous comprenez"}],"tip":{"title":"« To » et « shomâ » : tutoyer ou vouvoyer","example":"Vous êtes la mère de Maryam ? — <b>شما</b> مادر مریم <b>هستین</b>؟","body":"Comme le français, le persan distingue le tutoiement et le vouvoiement. « To » correspond à tu, et s'emploie avec les amis proches, les enfants et la famille du même âge. « Shomâ » correspond à vous, c'est la forme de respect pour les aînés, les inconnus et les parents de vos amis. Le verbe suit : « to chetori ? », comment vas-tu, mais « hâletun chetore ? », comment allez-vous, mot à mot « état votre, comment est ». Les terminaisons changent aussi : « mikhâi », tu veux, devient « mikhâin », vous voulez, et « hasti », tu es, devient « hastin », vous êtes. En Iran, on vouvoie plus facilement qu'en France, et même entre amis on revient parfois à « shomâ » par politesse. Dans le doute, choisissez « shomâ », personne ne vous en voudra. Astuce : si un ami iranien vous dit « mituni be man to begi », il vous invite à le tutoyer.","exampleRo":"Shomâ mâdar-e Maryam hastin?","lit":"vous · mère · [de] · Maryam · êtes","say":{"To":"تو","shomâ":"شما","Shomâ":"شما","to chetori ?":"تو چطوری؟","hâletun chetore ?":"حالتون چطوره؟","mikhâi":"می‌خوای","mikhâin":"می‌خواین","hasti":"هستی","hastin":"هستین","mituni be man to begi":"می‌تونی به من تو بگی"}}},{"title":"Faire un compliment","phrases":[{"fr":"Ce repas est vraiment délicieux.","tgt":"این غذا واقعا خوشمزه‌ست.","ro":"In ghazâ vâghe'an khoshmazast.","lit":"ce · repas · vraiment · délicieux-est"},{"fr":"Tu cuisines très bien.","tgt":"خیلی خوب آشپزی می‌کنی.","ro":"Kheyli khub âshpazi mikoni.","lit":"très · bien · cuisine · tu fais"},{"fr":"Ta chemise te va très bien.","tgt":"پیرهنت خیلی بهت میاد.","ro":"Pirhanet kheyli behet miyâd.","lit":"chemise-ta · très · à-toi · vient"},{"fr":"Ton persan est déjà très bon.","tgt":"فارسیت خیلی خوبه.","ro":"Fârsit kheyli khube.","lit":"persan-ton · très · bon-est"},{"fr":"Vraiment ? Tu me gênes, là.","tgt":"واقعا؟ شرمنده‌م می‌کنی.","ro":"Vâghe'an? Sharmandam mikoni.","lit":"vraiment · confus-me · tu fais"},{"fr":"Tes enfants sont très polis.","tgt":"بچه‌هات خیلی مؤدبن.","ro":"Bachehât kheyli mo'addaban.","lit":"enfants-tes · très · polis-sont"},{"fr":"Votre maison est pleine de lumière.","tgt":"خونه‌تون پر از نوره.","ro":"Khunatun por az nure.","lit":"maison-votre · pleine · de · lumière-est"},{"fr":"Tu as une jolie voix.","tgt":"صدات قشنگه.","ro":"Sedât ghashange.","lit":"voix-ta · jolie-est"},{"fr":"Tes photos de Chiraz sont superbes.","tgt":"عکس‌هات از شیراز معرکه‌ان.","ro":"Akshât az Shirâz ma'reke-an.","lit":"photos-tes · de · Chiraz · superbes-sont"},{"fr":"Merci, tu es trop gentil.","tgt":"مرسی، خیلی لطف داری.","ro":"Mersi, kheyli lotf dâri.","lit":"merci · très · bonté · tu as"}]},{"title":"Une promenade au bazar","phrases":[{"fr":"Ça me fait très plaisir de te voir.","tgt":"از دیدنت خیلی خوشحالم.","ro":"Az didanet kheyli khoshhâlam.","lit":"de · voir-te · très · content-suis"},{"fr":"Le bazar Vakil est très animé.","tgt":"بازار وکیل خیلی شلوغه.","ro":"Bâzâr-e Vakil kheyli sholughe.","lit":"bazar · [de] · Vakil · très · animé-est"},{"fr":"Non, ce n'est pas très loin.","tgt":"خیلی دور نیست.","ro":"Kheyli dur nist.","lit":"très · loin · n'est pas"},{"fr":"Tu marches beaucoup ?","tgt":"زیاد پیاده‌روی می‌کنی؟","ro":"Ziyâd piyâderavi mikoni?","lit":"beaucoup · marche · tu fais"},{"fr":"Oui, à Lyon, je marche beaucoup.","tgt":"آره، تو لیون خیلی پیاده‌روی می‌کنم.","ro":"Âre, tu Liyon kheyli piyâderavi mikonam.","lit":"oui · dans · Lyon · beaucoup · marche · je fais"},{"fr":"Chiraz a beaucoup de jardins.","tgt":"شیراز خیلی باغ داره.","ro":"Shirâz kheyli bâgh dâre.","lit":"Chiraz · beaucoup · jardin · a"},{"fr":"Le soir, je ne mange pas beaucoup.","tgt":"شب‌ها زیاد غذا نمی‌خورم.","ro":"Shabhâ ziyâd ghazâ nemikhoram.","lit":"nuits · beaucoup · nourriture · [ne… pas]-je mange"},{"fr":"Ne mets pas trop de sucre.","tgt":"زیاد شکر نریز.","ro":"Ziyâd shekar nariz.","lit":"beaucoup · sucre · [ne… pas]-verse"},{"fr":"Aujourd'hui, je n'ai pas beaucoup de temps.","tgt":"امروز زیاد وقت ندارم.","ro":"Emruz ziyâd vaght nadâram.","lit":"aujourd'hui · beaucoup · temps · [ne… pas]-j'ai"},{"fr":"Un grand merci pour tout.","tgt":"خیلی ممنون بابت همه‌چیز.","ro":"Kheyli mamnun bâbat-e hame chiz.","lit":"très · reconnaissant · pour · [de] · toute · chose"}],"tip":{"title":"« Kheyli » et « ziyâd » : très et beaucoup","example":"Le soir, je ne mange pas beaucoup. — شب‌ها <b>زیاد</b> غذا نمی‌خورم.","body":"« Kheyli » est sans doute le mot que vous entendrez le plus souvent en Iran. Il veut dire très devant un adjectif, « kheyli khube », c'est très bien, mais aussi beaucoup devant un nom, « Shirâz kheyli bâgh dâre », Chiraz a beaucoup de jardins. « Ziyâd » veut dire beaucoup ou trop, et s'emploie surtout avec un verbe : « ziyâd ghazâ nemikhoram », je ne mange pas beaucoup. On l'entend aussi dans la petite réponse « na ziyâd », pas trop. Mot à mot, « kheyli dur nist » donne « très loin n'est pas » : ce n'est pas très loin. Les deux mots se placent avant ce qu'ils renforcent, jamais après. Et pour remercier chaleureusement, on dit « kheyli mamnun », merci beaucoup, ou tout simplement « kheyli mersi ». Astuce : quand vous hésitez, « kheyli » marche presque partout.","exampleRo":"Shabhâ ziyâd ghazâ nemikhoram.","lit":"nuits · beaucoup · nourriture · [ne… pas]-je mange","say":{"Kheyli":"خیلی","ziyâd":"زیاد","kheyli khube":"خیلی خوبه","Shirâz kheyli bâgh dâre":"شیراز خیلی باغ داره","Ziyâd":"زیاد","ziyâd ghazâ nemikhoram":"زیاد غذا نمی‌خورم","na ziyâd":"نه زیاد","kheyli dur nist":"خیلی دور نیست","kheyli mamnun":"خیلی ممنون","kheyli mersi":"خیلی مرسی","kheyli":"خیلی"}}},{"title":"Se dire au revoir après la soirée","phrases":[{"fr":"Il est tard, je dois y aller.","tgt":"دیروقته، باید برم.","ro":"Dirvaghte, bâyad beram.","lit":"tard-est · il faut · que j'aille"},{"fr":"Déjà ? Reste encore un peu !","tgt":"به این زودی؟ یه کم دیگه بمون!","ro":"Be in zudi? Ye kam dige bemun!","lit":"[à] · cette · rapidité · un · peu · autre · reste"},{"fr":"Merci pour cette si belle soirée.","tgt":"مرسی بابت این شب قشنگ.","ro":"Mersi bâbat-e in shab-e ghashang.","lit":"merci · pour · [de] · cette · soirée · [de] · belle"},{"fr":"Je t'appelle un taxi.","tgt":"برات تاکسی می‌گیرم.","ro":"Barât tâksi migiram.","lit":"pour-toi · taxi · je prends"},{"fr":"Non merci, mon hôtel est tout près.","tgt":"نه مرسی، هتلم همین نزدیکیه.","ro":"Na mersi, hotelam hamin nazdikie.","lit":"non · merci · hôtel-mon · juste · tout près-est"},{"fr":"Passe le bonjour à tes parents de ma part.","tgt":"سلام منو به پدر و مادرت برسون.","ro":"Salâm-e mano be pedar o mâdaret berasun.","lit":"salut · [de] · moi-[objet] · [à] · père · et · mère-ta · fais parvenir"},{"fr":"Reviens nous voir bientôt.","tgt":"بازم به ما سر بزن.","ro":"Bâzam be mâ sar bezan.","lit":"encore · [à] · nous · tête · frappe"},{"fr":"C'est promis, je reviens au printemps.","tgt":"حتما، بهار برمی‌گردم.","ro":"Hatman, bahâr barmigardam.","lit":"sûrement · printemps · je reviens"},{"fr":"Bonne nuit, et à vendredi !","tgt":"شب بخیر، تا جمعه!","ro":"Shab bekheyr, tâ jom'e!","lit":"nuit · au bien · jusqu'à · vendredi"},{"fr":"Au revoir, prends soin de toi.","tgt":"خداحافظ، مواظب خودت باش.","ro":"Khodâhâfez, movâzeb-e khodet bâsh.","lit":"au revoir · attentif · [de] · toi-même · sois"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Maintenant, je sais me présenter en persan.","tgt":"الان می‌تونم به فارسی خودم رو معرفی کنم.","ro":"Alân mitunam be fârsi khodam ro mo'arrefi konam.","lit":"maintenant · je peux · [à] · persan · moi-même · [objet] · présentation · que je fasse"},{"fr":"Ce n'est pas digne de vous.","tgt":"قابل شما رو نداره.","ro":"Ghâbel-e shomâ ro nadâre.","lit":"digne · [de] · vous · [objet] · [ne… pas]-a"},{"fr":"Asseyez-vous, je vous en prie.","tgt":"بفرمایید بشینین.","ro":"Befarmâyid beshinin.","lit":"je vous en prie · asseyez-vous"},{"fr":"Après vous, je vous en prie.","tgt":"بفرمایید، اول شما.","ro":"Befarmâyid, avval shomâ.","lit":"je vous en prie · d'abord · vous"},{"fr":"Merci pour ce joli cadeau !","tgt":"مرسی بابت این هدیه‌ی قشنگ!","ro":"Mersi bâbat-e in hedye-ye ghashang!","lit":"merci · pour · [de] · ce · cadeau · [de] · joli"},{"fr":"Oh, ce n'est pas grand-chose.","tgt":"قابل نداره.","ro":"Ghâbel nadâre.","lit":"digne · [ne… pas]-a"},{"fr":"Je vous en prie, servez-vous.","tgt":"بفرمایید، میل کنین.","ro":"Befarmâyid, meyl konin.","lit":"je vous en prie · envie · faites"},{"fr":"En Iran, le ta'arof est un véritable art.","tgt":"تعارف تو ایران یه هنره.","ro":"Ta'ârof tu Irân ye honare.","lit":"ta'arof · dans · Iran · un · art-est"},{"fr":"J'aime beaucoup parler persan avec toi.","tgt":"حرف زدن به فارسی با تو رو خیلی دوست دارم.","ro":"Harf zadan be fârsi bâ to ro kheyli dust dâram.","lit":"parole · frapper · [à] · persan · avec · toi · [objet] · très · ami · j'ai"},{"fr":"Mon persan s'améliore chaque jour.","tgt":"فارسیم هر روز بهتر می‌شه.","ro":"Fârsim har ruz behtar mishe.","lit":"persan-mon · chaque · jour · meilleur · devient"}],"tip":{"title":"Le ta'ârof : « befarmâyid », « ghâbel nadâre »","example":"Asseyez-vous, je vous en prie. — <b>بفرمایید</b> بشینین.","body":"Le ta'ârof est l'art iranien de la politesse : on offre, on refuse, on insiste, et chacun se montre plus modeste que l'autre. Le mot clé est « befarmâyid », je vous en prie, qui sert à presque tout : inviter à entrer, à s'asseoir, à se servir ou à passer devant. « Befarmâyid beshinin » signifie asseyez-vous, je vous en prie, et « befarmâyid, avval shomâ », après vous. Quand on vous remercie pour un cadeau, la réponse polie est « ghâbel nadâre », mot à mot « digne n'a pas », c'est-à-dire ça ne mérite pas qu'on en parle. La version complète, « ghâbel-e shomâ ro nadâre », veut dire ce n'est pas digne de vous. Si l'on vous propose quelque chose, il est d'usage de refuser poliment une première fois, puis d'accepter quand votre hôte insiste. Un commerçant peut même vous dire « ghâbel nadâre » au moment de payer : c'est une formule, pas une offre. Astuce : dans le doute, souriez et dites « befarmâyid ».","exampleRo":"Befarmâyid beshinin.","lit":"je vous en prie · asseyez-vous","say":{"befarmâyid":"بفرمایید","ghâbel nadâre":"قابل نداره","Befarmâyid beshinin":"بفرمایید بشینین","befarmâyid, avval shomâ":"بفرمایید، اول شما","ghâbel-e shomâ ro nadâre":"قابل شما رو نداره"}}}]}]},{"id":2,"name":"Niveau 2","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours, avec un vocabulaire plus riche.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Une journée de travail à Tabriz","phrases":[{"fr":"Je travaille dans un bureau près de la gare de Tabriz.","tgt":"من در یک دفتر نزدیک ایستگاه قطار تبریز کار می‌کنم.","ro":"Man dar yek daftar nazdik-e istgâh-e ghatâr-e Tabriz kâr mikonam."},{"fr":"Chaque matin, je pars de chez moi à sept heures et demie.","tgt":"هر روز صبح ساعت هفت و نیم از خانه بیرون می‌روم.","ro":"Har ruz sobh sâ'at-e haft o nim az khâne birun miravam."},{"fr":"Le trajet en bus dure à peu près vingt minutes.","tgt":"راه با اتوبوس حدود بیست دقیقه طول می‌کشد.","ro":"Râh bâ otobus hodud-e bist daghighe tul mikeshad."},{"fr":"Mes collègues sont sympathiques et très travailleurs.","tgt":"همکارانم مهربان و خیلی سخت‌کوش هستند.","ro":"Hamkârânam mehrabân va kheyli sakhtkush hastand."},{"fr":"Vers dix heures, nous prenons toujours un thé ensemble.","tgt":"حدود ساعت ده همیشه با هم چای می‌خوریم.","ro":"Hodud-e sâ'at-e dah hamishe bâ ham châi mikhorim."},{"fr":"Le directeur organise une réunion tous les mardis.","tgt":"مدیر سه‌شنبه‌ها جلسه می‌گذارد.","ro":"Modir seshanbehâ jalase migozârad."},{"fr":"À midi, je mange souvent au restaurant d'en face.","tgt":"ظهر اغلب در رستوران روبه‌رو غذا می‌خورم.","ro":"Zohr aghlab dar resturân-e ruberu ghazâ mikhoram."},{"fr":"Cette semaine, j'ai énormément de travail.","tgt":"این هفته خیلی کار دارم.","ro":"In hafte kheyli kâr dâram."},{"fr":"Je finis généralement vers cinq heures.","tgt":"معمولا حدود ساعت پنج کارم تمام می‌شود.","ro":"Ma'mulan hodud-e sâ'at-e panj kâram tamâm mishavad."},{"fr":"En fin d'après-midi, je rentre fatigué mais content.","tgt":"عصر خسته ولی راضی به خانه برمی‌گردم.","ro":"Asr khaste vali râzi be khâne barmigardam."}]},{"title":"Hier au bureau","phrases":[{"fr":"Hier, je suis allé au bureau à pied.","tgt":"دیروز پیاده به دفتر رفتم.","ro":"Diruz piyâde be daftar raftam."},{"fr":"En chemin, j'ai acheté du pain frais.","tgt":"سر راه نان تازه خریدم.","ro":"Sar-e râh nân-e tâze kharidam."},{"fr":"J'ai mangé mon petit-déjeuner à mon bureau.","tgt":"صبحانه‌ام را پشت میزم خوردم.","ro":"Sobhâne-am râ posht-e mizam khordam."},{"fr":"Ensuite, j'ai lu tous mes messages.","tgt":"بعد همه‌ی پیام‌هایم را خواندم.","ro":"Ba'd hame-ye payâmhâyam râ khândam."},{"fr":"À midi, nous avons déjeuné avec un client.","tgt":"ظهر با یک مشتری ناهار خوردیم.","ro":"Zohr bâ yek moshtari nâhâr khordim."},{"fr":"L'après-midi, j'ai téléphoné à deux entreprises.","tgt":"بعدازظهر به دو شرکت زنگ زدم.","ro":"Ba'dazzohr be do sherkat zang zadam."},{"fr":"La réunion a duré deux heures.","tgt":"جلسه دو ساعت طول کشید.","ro":"Jalase do sâ'at tul keshid."},{"fr":"Avez-vous terminé le rapport hier ?","tgt":"دیروز گزارش را تمام کردید؟","ro":"Diruz gozâresh râ tamâm kardid?"},{"fr":"Non, je ne l'ai pas fini, j'étais trop fatigué.","tgt":"نه، تمامش نکردم، خیلی خسته بودم.","ro":"Na, tamâmash nakardam, kheyli khaste budam."},{"fr":"Je suis rentré à la maison vers six heures.","tgt":"حدود ساعت شش به خانه برگشتم.","ro":"Hodud-e sâ'at-e shesh be khâne bargashtam."}],"tip":{"title":"Le passé simple : « raftam », « khordam »","example":"Hier, je suis allé au bureau à pied. — دیروز پیاده به دفتر <b>رفتم</b>.","body":"Pour parler d'une action terminée, le persan part d'une racine du passé, comme « raft » pour aller ou « khord » pour manger, et lui ajoute simplement la terminaison de la personne. On dit donc « raftam », je suis allé, « rafti », tu es allé, « raft », il est allé, et « raftim », nous sommes allés. Dans notre exemple, « diruz piyâde be daftar raftam » se décompose en hier, à pied, au bureau, je suis allé : le verbe arrive tout à la fin. Contrairement au français, il n'y a pas d'auxiliaire : un seul mot suffit, là où nous disons « je suis allé » ou « j'ai mangé ». Pour la négation, on colle « na » devant : « naraftam », je n'y suis pas allé, « nakhordam », je n'ai pas mangé. Astuce : la terminaison « -am » est la même qu'au présent dans « miravam », seule la racine change.","exampleRo":"Diruz piyâde be daftar raftam.","lit":"hier · à pied · [à] · bureau · suis allé","say":{"raftam":"رفتم","khordam":"خوردم","raft":"رفت","khord":"خورد","rafti":"رفتی","raftim":"رفتیم","diruz piyâde be daftar raftam":"دیروز پیاده به دفتر رفتم","naraftam":"نرفتم","nakhordam":"نخوردم","miravam":"می‌روم"}}},{"title":"Au grand bazar couvert","phrases":[{"fr":"Le bazar de Tabriz est l'un des plus grands bazars couverts du monde.","tgt":"بازار تبریز یکی از بزرگ‌ترین بازارهای سرپوشیده‌ی دنیاست.","ro":"Bâzâr-e Tabriz yeki az bozorgtarin bâzârhâ-ye sarpushide-ye donyâst."},{"fr":"Ses allées en brique sont magnifiques.","tgt":"راهروهای آجری‌اش خیلی زیبا هستند.","ro":"Râhrowhâ-ye âjori-ash kheyli zibâ hastand."},{"fr":"Je cherche l'allée des bijoutiers.","tgt":"دنبال راسته‌ی طلافروش‌ها می‌گردم.","ro":"Donbâl-e râste-ye talâforushhâ migardam."},{"fr":"Combien coûte ce plateau en cuivre ?","tgt":"این سینی مسی چند است؟","ro":"In sini-ye mesi chand ast?"},{"fr":"Il coûte trois cent mille tomans.","tgt":"سیصد هزار تومان است.","ro":"Sisad hezâr tomân ast."},{"fr":"C'est un peu cher, vous pouvez faire un prix ?","tgt":"کمی گران است، تخفیف می‌دهید؟","ro":"Kami gerân ast, takhfif midahid?"},{"fr":"Pour vous, je le laisse à deux cent cinquante mille tomans.","tgt":"برای شما دویست و پنجاه هزار تومان حساب می‌کنم.","ro":"Barâye shomâ devist o panjâh hezâr tomân hesâb mikonam."},{"fr":"Entendu, je le prends.","tgt":"قبول است، آن را می‌خرم.","ro":"Ghabul ast, ân râ mikharam."},{"fr":"Ce marchand vend des tapis depuis quarante ans.","tgt":"این فروشنده چهل سال است که فرش می‌فروشد.","ro":"In forushande chehel sâl ast ke farsh miforushad."},{"fr":"Le bazar ferme vers six heures du soir.","tgt":"بازار حدود ساعت شش عصر تعطیل می‌شود.","ro":"Bâzâr hodud-e sâ'at-e shesh-e asr ta'til mishavad."}]},{"title":"Épices et fruits secs","phrases":[{"fr":"Je voudrais un kilo de pistaches, s'il vous plaît.","tgt":"یک کیلو پسته می‌خواهم، لطفا.","ro":"Yek kilo peste mikhâham, lotfan."},{"fr":"D'où viennent ces amandes ?","tgt":"این بادام‌ها مال کجا هستند؟","ro":"In bâdâmhâ mâl-e kojâ hastand?"},{"fr":"Elles viennent des vergers autour de Tabriz.","tgt":"از باغ‌های اطراف تبریز هستند.","ro":"Az bâghhâ-ye atrâf-e Tabriz hastand."},{"fr":"Est-ce que je peux goûter ces abricots secs ?","tgt":"می‌شود از این برگه‌ها بچشم؟","ro":"Mishavad az in bargehâ bechesham?"},{"fr":"Bien sûr, servez-vous.","tgt":"البته، بفرمایید.","ro":"Albatte, befarmâyid."},{"fr":"Il me faut aussi du safran pour le riz.","tgt":"برای برنج زعفران هم لازم دارم.","ro":"Barâye berenj za'farân ham lâzem dâram."},{"fr":"Le safran se vend au gramme.","tgt":"زعفران را گرمی می‌فروشند.","ro":"Za'farân râ gerami miforushand."},{"fr":"Mettez-moi aussi un peu de cannelle.","tgt":"کمی دارچین هم بدهید.","ro":"Kami dârchin ham bedahid."},{"fr":"Je vous dois combien pour le tout ?","tgt":"جمعا چقدر می‌شود؟","ro":"Jam'an cheghadr mishavad?"},{"fr":"Ça fait cent quatre-vingt mille tomans.","tgt":"صد و هشتاد هزار تومان می‌شود.","ro":"Sad o hashtâd hezâr tomân mishavad."}]},{"title":"Ce que j'ai déjà vu à Tabriz","phrases":[{"fr":"Êtes-vous déjà allé à Kandovan ?","tgt":"تا حالا به کندوان رفته‌اید؟","ro":"Tâ hâlâ be Kandovân rafte-id?"},{"fr":"Oui, j'y suis allé à deux reprises.","tgt":"بله، دو بار آنجا رفته‌ام.","ro":"Bale, do bâr ânjâ rafte-am."},{"fr":"Je n'ai jamais vu de maisons aussi étranges.","tgt":"هیچ‌وقت چنین خانه‌های عجیبی ندیده‌ام.","ro":"Hichvaght chenin khânehâ-ye ajibi nadide-am."},{"fr":"Avez-vous déjà goûté le kufteh tabrizi ?","tgt":"تا حالا کوفته‌ی تبریزی خورده‌اید؟","ro":"Tâ hâlâ kufte-ye tabrizi khorde-id?"},{"fr":"Non, je n'en ai encore jamais mangé.","tgt":"نه، هیچ‌وقت نخورده‌ام.","ro":"Na, hichvaght nakhorde-am."},{"fr":"Ma voisine nous en a préparé plusieurs fois.","tgt":"همسایه‌ام چند بار برای ما درست کرده است.","ro":"Hamsâye-am chand bâr barâye mâ dorost karde ast."},{"fr":"J'ai beaucoup entendu parler de ce plat.","tgt":"درباره‌ی این غذا خیلی شنیده‌ام.","ro":"Darbâre-ye in ghazâ kheyli shenide-am."},{"fr":"Depuis mon arrivée, j'ai appris beaucoup de choses.","tgt":"از وقتی آمده‌ام چیزهای زیادی یاد گرفته‌ام.","ro":"Az vaghti âmade-am chizhâ-ye ziyâdi yâd gerefte-am."},{"fr":"Avez-vous déjà vu le vieux bâtiment de la mairie ?","tgt":"تا حالا عمارت شهرداری را دیده‌اید؟","ro":"Tâ hâlâ emârat-e shahrdâri râ dide-id?"},{"fr":"Pas encore, mais j'en ai vu des photos.","tgt":"هنوز نه، ولی عکس‌هایش را دیده‌ام.","ro":"Hanuz na, vali akshâyash râ dide-am."}],"tip":{"title":"Le passé composé : « rafte-am », j'y suis déjà allé","example":"Oui, j'y suis allé à deux reprises. — بله، دو بار آنجا <b>رفته‌ام</b>.","body":"Pour parler d'une expérience, de ce que l'on a déjà fait dans sa vie, le persan utilise une autre forme du passé. On prend la racine du passé, on ajoute un « e », puis la terminaison de la personne : « rafte-am », je suis allé, « dide-am », j'ai vu, « khorde-am », j'ai mangé. Dans « bale, do bâr ânjâ rafte-am », on entend oui, deux fois, là-bas, j'y suis allé : la phrase raconte une expérience, pas un moment précis. La différence ressemble à celle entre « je suis allé à Kandovan hier », qui se dit avec « raftam », et « je suis déjà allé à Kandovan », qui se dit avec « rafte-am ». Avec « tâ hâlâ », jusqu'à maintenant, vous obtenez la question idéale : « tâ hâlâ rafte-id ? », vous y êtes déjà allé ? Astuce : dès que vous pensez « déjà » ou « jamais », glissez ce petit « e » avant la terminaison.","exampleRo":"Bale, do bâr ânjâ rafte-am.","lit":"oui · deux · fois · là-bas · suis allé (déjà)","say":{"rafte-am":"رفته‌ام","dide-am":"دیده‌ام","khorde-am":"خورده‌ام","bale, do bâr ânjâ rafte-am":"بله، دو بار آنجا رفته‌ام","raftam":"رفتم","tâ hâlâ":"تا حالا","tâ hâlâ rafte-id ?":"تا حالا رفته‌اید؟"}}},{"title":"Des projets pour vendredi","phrases":[{"fr":"Ce vendredi, je veux aller au parc El Goli.","tgt":"این جمعه می‌خواهم به پارک ائل‌گلی بروم.","ro":"In jom'e mikhâham be pârk-e El Goli beravam."},{"fr":"Voulez-vous venir avec nous ?","tgt":"می‌خواهید با ما بیایید؟","ro":"Mikhâhid bâ mâ biyâyid?"},{"fr":"Avec plaisir, mais je dois d'abord faire les courses.","tgt":"با کمال میل، ولی اول باید خرید کنم.","ro":"Bâ kamâl-e meyl, vali avval bâyad kharid konam."},{"fr":"Ma sœur veut préparer un pique-nique.","tgt":"خواهرم می‌خواهد یک پیک‌نیک آماده کند.","ro":"Khâharam mikhâhad yek piknik âmâde konad."},{"fr":"Nous voulons partir tôt pour trouver une place à l'ombre.","tgt":"می‌خواهیم زود راه بیفتیم تا جایی در سایه پیدا کنیم.","ro":"Mikhâhim zud râh biyoftim tâ jâyi dar sâye peydâ konim."},{"fr":"Je préfère prendre un taxi plutôt que le bus.","tgt":"ترجیح می‌دهم به جای اتوبوس تاکسی بگیرم.","ro":"Tarjih midaham be jâ-ye otobus tâksi begiram."},{"fr":"Il faut que nous apportions une natte et du thé.","tgt":"باید یک زیرانداز و چای با خودمان ببریم.","ro":"Bâyad yek zirandâz va châi bâ khodemân bebarim."},{"fr":"Peut-être que mon frère pourra venir aussi.","tgt":"شاید برادرم هم بتواند بیاید.","ro":"Shâyad barâdaram ham betavânad biyâyad."},{"fr":"J'aimerais faire de la barque sur le lac.","tgt":"دوست دارم در دریاچه قایق‌سواری کنم.","ro":"Dust dâram dar daryâche ghâyeghsavâri konam."},{"fr":"Le soir, nous voulons dîner au restaurant du parc.","tgt":"شب می‌خواهیم در رستوران پارک شام بخوریم.","ro":"Shab mikhâhim dar resturân-e pârk shâm bokhorim."}],"tip":{"title":"Le subjonctif : « mikhâham beravam », vouloir faire","example":"Ce vendredi, je veux aller au parc El Goli. — این جمعه <b>می‌خواهم</b> به پارک ائل‌گلی <b>بروم</b>.","body":"Après « mikhâham », je veux, le persan ne met pas d'infinitif comme le français : il conjugue aussi le deuxième verbe, au subjonctif. On dit littéralement « je veux que j'aille », « mikhâham beravam », et chaque verbe porte la marque de la personne. Le subjonctif se reconnaît à l'oreille grâce au petit « be » du début, qui devient parfois « bo » : « beravam », que j'aille, « bekharam », que j'achète, « bokhoram », que je mange. Notre exemple, « in jom'e mikhâham be pârk-e El Goli beravam », se décompose en ce vendredi, je veux, au parc El Goli, que j'aille. On l'emploie aussi après « bâyad », il faut, et « shâyad », peut-être : « bâyad beravam », je dois partir. Astuce : dès que vous dites vouloir, devoir ou pouvoir, préparez le « be » du verbe suivant.","exampleRo":"In jom'e mikhâham be pârk-e El Goli beravam.","lit":"ce · vendredi · veux · [à] · parc · [de] · El Goli · que j'aille","say":{"mikhâham beravam":"می‌خواهم بروم","mikhâham":"می‌خواهم","beravam":"بروم","bekharam":"بخرم","bokhoram":"بخورم","in jom'e mikhâham be pârk-e El Goli beravam":"این جمعه می‌خواهم به پارک ائل‌گلی بروم","bâyad":"باید","shâyad":"شاید","bâyad beravam":"باید بروم"}}},{"title":"Cuisiner à la maison","phrases":[{"fr":"Ce soir, je prépare des kufteh tabrizi à la maison.","tgt":"امشب در خانه کوفته‌ی تبریزی درست می‌کنم.","ro":"Emshab dar khâne kufte-ye tabrizi dorost mikonam."},{"fr":"Il faut de la viande hachée, du riz et des pois cassés.","tgt":"گوشت چرخ‌کرده، برنج و لپه لازم است.","ro":"Gusht-e charkhkarde, berenj va lape lâzem ast."},{"fr":"Ma mère met aussi des noix et des pruneaux à l'intérieur.","tgt":"مادرم داخلش گردو و آلو هم می‌گذارد.","ro":"Mâdaram dâkhelash gerdu va âlu ham migozârad."},{"fr":"Je fais d'abord cuire le riz et les pois cassés.","tgt":"اول برنج و لپه را می‌پزم.","ro":"Avval berenj va lape râ mipazam."},{"fr":"Ensuite, je mélange tout avec les mains.","tgt":"بعد همه را با دست مخلوط می‌کنم.","ro":"Ba'd hame râ bâ dast makhlut mikonam."},{"fr":"Les boulettes doivent être vraiment grosses.","tgt":"کوفته‌ها باید خیلی بزرگ باشند.","ro":"Kuftehâ bâyad kheyli bozorg bâshand."},{"fr":"La sauce mijote une heure à feu doux.","tgt":"سس یک ساعت روی حرارت کم می‌جوشد.","ro":"Sos yek sâ'at ru-ye harârat-e kam mijushad."},{"fr":"Cette recette demande beaucoup de patience.","tgt":"این دستور پخت خیلی حوصله می‌خواهد.","ro":"In dastur-e pokht kheyli hosele mikhâhad."},{"fr":"Ça sent déjà très bon dans la cuisine.","tgt":"آشپزخانه از همین حالا بوی خوبی می‌دهد.","ro":"Âshpazkhâne az hamin hâlâ bu-ye khubi midahad."},{"fr":"Nous dînerons tous ensemble vers neuf heures.","tgt":"حدود ساعت نه همه با هم شام می‌خوریم.","ro":"Hodud-e sâ'at-e noh hame bâ ham shâm mikhorim."}]},{"title":"Chez le médecin","phrases":[{"fr":"J'ai mal à la gorge depuis trois jours.","tgt":"سه روز است گلودرد دارم.","ro":"Se ruz ast galudard dâram."},{"fr":"Avez-vous aussi de la fièvre ?","tgt":"تب هم دارید؟","ro":"Tab ham dârid?"},{"fr":"Oui, un peu, surtout la nuit.","tgt":"بله، کمی، مخصوصا شب‌ها.","ro":"Bale, kami, makhsusan shabhâ."},{"fr":"Ouvrez grand la bouche, je vous prie.","tgt":"لطفا دهانتان را باز کنید.","ro":"Lotfan dahânetân râ bâz konid."},{"fr":"Votre gorge est un peu rouge.","tgt":"گلویتان کمی قرمز است.","ro":"Galuyetân kami ghermez ast."},{"fr":"Ce n'est qu'un simple rhume.","tgt":"فقط یک سرماخوردگی ساده است.","ro":"Faghat yek sarmâkhordegi-ye sâde ast."},{"fr":"Je vais vous prescrire un sirop.","tgt":"برایتان یک شربت می‌نویسم.","ro":"Barâyetân yek sharbat minevisam."},{"fr":"Je le prends combien de fois dans la journée ?","tgt":"روزی چند بار باید بخورمش؟","ro":"Ruzi chand bâr bâyad bokhoramash?"},{"fr":"Trois fois dans la journée, après manger.","tgt":"روزی سه بار، بعد از غذا.","ro":"Ruzi se bâr, ba'd az ghazâ."},{"fr":"Revenez me voir si ça ne va pas mieux.","tgt":"اگر بهتر نشدید، دوباره پیش من بیایید.","ro":"Agar behtar nashodid, dobâre pish-e man biyâyid."}]},{"title":"À la pharmacie","phrases":[{"fr":"Connaissez-vous une pharmacie ouverte dans le coin ?","tgt":"این نزدیکی داروخانه‌ی بازی سراغ دارید؟","ro":"In nazdiki dârukhâne-ye bâzi sorâgh dârid?"},{"fr":"Voici mon ordonnance.","tgt":"این نسخه‌ی من است.","ro":"In noskhe-ye man ast."},{"fr":"Ce médicament n'est pas disponible aujourd'hui.","tgt":"این دارو امروز موجود نیست.","ro":"In dâru emruz mojud nist."},{"fr":"Nous avons un équivalent tout aussi efficace.","tgt":"یک داروی مشابه داریم که به همان اندازه مؤثر است.","ro":"Yek dâru-ye moshâbeh dârim ke be hamân andâze mo'asser ast."},{"fr":"Je dois le prendre avant ou après le repas ?","tgt":"قبل از غذا بخورم یا بعد از غذا؟","ro":"Ghabl az ghazâ bokhoram yâ ba'd az ghazâ?"},{"fr":"Après le repas, avec un grand verre d'eau.","tgt":"بعد از غذا، با یک لیوان بزرگ آب.","ro":"Ba'd az ghazâ, bâ yek livân-e bozorg âb."},{"fr":"Avez-vous aussi quelque chose contre la toux ?","tgt":"برای سرفه هم چیزی دارید؟","ro":"Barâye sorfe ham chizi dârid?"},{"fr":"Ce sirop au miel est très doux.","tgt":"این شربت عسل خیلی ملایم است.","ro":"In sharbat-e asal kheyli molâyem ast."},{"fr":"Je voudrais aussi une boîte de pansements.","tgt":"یک بسته چسب زخم هم می‌خواهم.","ro":"Yek baste chasb-e zakhm ham mikhâham."},{"fr":"J'espère que vous irez vite mieux.","tgt":"امیدوارم زود خوب شوید.","ro":"Omidvâram zud khub shavid."}]},{"title":"Une promenade au parc El Goli","phrases":[{"fr":"Le parc El Goli est le plus célèbre de Tabriz.","tgt":"پارک ائل‌گلی معروف‌ترین پارک تبریز است.","ro":"Pârk-e El Goli ma'ruftarin pârk-e Tabriz ast."},{"fr":"Il y a un grand bassin au milieu du parc.","tgt":"وسط پارک یک استخر بزرگ هست.","ro":"Vasat-e pârk yek estakhr-e bozorg hast."},{"fr":"Un beau pavillon se dresse au centre de l'eau.","tgt":"وسط آب یک عمارت زیبا قرار دارد.","ro":"Vasat-e âb yek emârat-e zibâ gharâr dârad."},{"fr":"En fin de journée, les familles viennent se promener ici.","tgt":"عصرها خانواده‌ها برای قدم زدن به اینجا می‌آیند.","ro":"Asrhâ khânevâdehâ barâye ghadam zadan be injâ miâyand."},{"fr":"Les enfants courent sur l'herbe.","tgt":"بچه‌ها روی چمن می‌دوند.","ro":"Bachehâ ru-ye chaman midavand."},{"fr":"Asseyons-nous un moment sur ce banc.","tgt":"بیایید کمی روی این نیمکت بنشینیم.","ro":"Biyâyid kami ru-ye in nimkat beneshinim."},{"fr":"L'air est bien plus frais ici qu'en ville.","tgt":"هوای اینجا خیلی خنک‌تر از شهر است.","ro":"Havâ-ye injâ kheyli khonaktar az shahr ast."},{"fr":"Un vendeur propose du maïs grillé.","tgt":"یک فروشنده بلال کبابی می‌فروشد.","ro":"Yek forushande balâl-e kabâbi miforushad."},{"fr":"On en achète deux épis ?","tgt":"دو تا بلال بخریم؟","ro":"Do tâ balâl bekharim?"},{"fr":"J'adore cet endroit au coucher du soleil.","tgt":"غروب‌ها اینجا را خیلی دوست دارم.","ro":"Ghorubhâ injâ râ kheyli dust dâram."}]},{"title":"La salle de sport du quartier","phrases":[{"fr":"Je me suis inscrit dans une salle de sport près de chez moi.","tgt":"در یک باشگاه نزدیک خانه‌ام ثبت‌نام کردم.","ro":"Dar yek bâshgâh nazdik-e khâne-am sabtenâm kardam."},{"fr":"Je m'y entraîne trois fois chaque semaine.","tgt":"هفته‌ای سه بار آنجا تمرین می‌کنم.","ro":"Hafte-i se bâr ânjâ tamrin mikonam."},{"fr":"Ils demandent cinq cent mille tomans par mois.","tgt":"ماهی پانصد هزار تومان می‌گیرند.","ro":"Mâhi pânsad hezâr tomân migirand."},{"fr":"Le matin, la salle est moins bondée.","tgt":"صبح‌ها شلوغی کمتر است.","ro":"Sobhhâ sholughi kamtar ast."},{"fr":"Je commence toujours par dix minutes de course.","tgt":"همیشه با ده دقیقه دویدن شروع می‌کنم.","ro":"Hamishe bâ dah daghighe davidan shoru' mikonam."},{"fr":"L'entraîneur nous montre les bons mouvements.","tgt":"مربی حرکت‌های درست را به ما نشان می‌دهد.","ro":"Morabbi harekathâ-ye dorost râ be mâ neshân midahad."},{"fr":"Après le sport, je bois beaucoup d'eau.","tgt":"بعد از ورزش خیلی آب می‌خورم.","ro":"Ba'd az varzesh kheyli âb mikhoram."},{"fr":"Ma sœur, elle, préfère la natation.","tgt":"خواهرم شنا را ترجیح می‌دهد.","ro":"Khâharam shenâ râ tarjih midahad."},{"fr":"Le football est très populaire à Tabriz.","tgt":"فوتبال در تبریز خیلی محبوب است.","ro":"Futbâl dar Tabriz kheyli mahbub ast."},{"fr":"Depuis un mois, mon sommeil est bien meilleur.","tgt":"از یک ماه پیش خوابم خیلی بهتر شده است.","ro":"Az yek mâh pish khâbam kheyli behtar shode ast."}]},{"title":"Un dîner chez des amis","phrases":[{"fr":"Entre donc, sois le bienvenu !","tgt":"بیا تو، خوش آمدی!","ro":"Biyâ tu, khosh âmadi!"},{"fr":"Donne-moi ta veste.","tgt":"کتت را به من بده.","ro":"Katat râ be man bede."},{"fr":"Assieds-toi ici, près de la fenêtre.","tgt":"اینجا کنار پنجره بنشین.","ro":"Injâ kenâr-e panjare beneshin."},{"fr":"Bois un thé, il vient d'infuser.","tgt":"یک چای بخور، تازه دم است.","ro":"Yek châi bokhor, tâze dam ast."},{"fr":"Reprends un peu de riz !","tgt":"باز هم برنج بخور!","ro":"Bâz ham berenj bokhor!"},{"fr":"Goûte ce ragoût aux herbes, c'est ma mère qui l'a fait.","tgt":"این قورمه‌سبزی را بچش، مادرم پخته است.","ro":"In ghormesabzi râ bechesh, mâdaram pokhte ast."},{"fr":"Va chercher les assiettes dans la cuisine, s'il te plaît.","tgt":"لطفا برو بشقاب‌ها را از آشپزخانه بیاور.","ro":"Lotfan boro boshghâbhâ râ az âshpazkhâne biyâvar."},{"fr":"Asseyez-vous, je vous en prie, faites comme chez vous.","tgt":"بفرمایید بنشینید، راحت باشید.","ro":"Befarmâyid beneshinid, râhat bâshid."},{"fr":"Servez-vous de salade.","tgt":"از سالاد بفرمایید.","ro":"Az sâlâd befarmâyid."},{"fr":"Reste encore un peu, il est tôt !","tgt":"کمی دیگر بمان، هنوز زود است!","ro":"Kami digar bemân, hanuz zud ast!"}],"tip":{"title":"L'impératif : « boro », « biyâ », « bokhor »","example":"Reprends un peu de riz ! — باز هم برنج <b>بخور</b>!","body":"Pour donner un ordre ou lancer une invitation à un ami, le persan prend la racine du présent et la fait précéder du même petit « be » que le subjonctif. Ainsi « boro » veut dire va, « biyâ » viens, « bokhor » mange, et « beneshin » assieds-toi. Avec une personne que l'on vouvoie, on ajoute simplement « -id » à la fin : « beravid », « biyâyid », « bokhorid », allez, venez, mangez. Dans l'exemple « bâz ham berenj bokhor », on entend encore, aussi, du riz, mange : le verbe reste à la fin, comme toujours. Chez des Iraniens, on vous dira sans cesse « bokhor » ou « befarmâyid », servez-vous : c'est la générosité de l'hôte, et il est poli de se faire un peu prier. Astuce : un ordre tient souvent en un seul mot, alors entraînez-vous à le lancer avec un sourire.","exampleRo":"Bâz ham berenj bokhor!","lit":"encore · aussi · riz · mange","say":{"boro":"برو","biyâ":"بیا","bokhor":"بخور","beneshin":"بنشین","beravid":"بروید","biyâyid":"بیایید","bokhorid":"بخورید","bâz ham berenj bokhor":"باز هم برنج بخور","befarmâyid":"بفرمایید"}}},{"title":"Une fuite d'eau","phrases":[{"fr":"De l'eau goutte sous l'évier de la cuisine.","tgt":"زیر سینک آب چکه می‌کند.","ro":"Zir-e sink âb chekke mikonad."},{"fr":"J'ai appelé un plombier ce matin.","tgt":"امروز صبح به یک لوله‌کش زنگ زدم.","ro":"Emruz sobh be yek lulekesh zang zadam."},{"fr":"Il a dit qu'il passerait vers midi.","tgt":"گفت حدود ظهر می‌آید.","ro":"Goft hodud-e zohr miâyad."},{"fr":"En attendant, j'ai fermé le robinet principal.","tgt":"فعلا شیر اصلی را بستم.","ro":"Fe'lan shir-e asli râ bastam."},{"fr":"Le plombier est arrivé avec une heure de retard.","tgt":"لوله‌کش یک ساعت دیر رسید.","ro":"Lulekesh yek sâ'at dir resid."},{"fr":"Il a remplacé un vieux tuyau.","tgt":"یک لوله‌ی کهنه را عوض کرد.","ro":"Yek lule-ye kohne râ avaz kard."},{"fr":"Combien vous dois-je pour la réparation ?","tgt":"چقدر تقدیم کنم؟","ro":"Cheghadr taghdim konam?"},{"fr":"Deux cent mille tomans, pièce comprise.","tgt":"با قطعه‌اش دویست هزار تومان می‌شود.","ro":"Bâ ghat'e-ash devist hezâr tomân mishavad."},{"fr":"Merci, vous avez fait du très bon travail.","tgt":"دستتان درد نکند، کارتان عالی بود.","ro":"Dastetân dard nakonad, kâretân âli bud."},{"fr":"Maintenant, tout fonctionne de nouveau.","tgt":"حالا همه چیز دوباره درست کار می‌کند.","ro":"Hâlâ hame chiz dobâre dorost kâr mikonad."}]},{"title":"Le thé chez la voisine","phrases":[{"fr":"Ma voisine m'a invité à prendre le thé.","tgt":"همسایه‌ام مرا به چای دعوت کرد.","ro":"Hamsâye-am marâ be châi da'vat kard."},{"fr":"Elle habite au deuxième étage depuis vingt ans.","tgt":"بیست سال است که در طبقه‌ی دوم زندگی می‌کند.","ro":"Bist sâl ast ke dar tabaghe-ye dovvom zendegi mikonad."},{"fr":"Elle sert le thé dans de petits verres.","tgt":"چای را در استکان‌های کوچک می‌ریزد.","ro":"Châi râ dar estekânhâ-ye kuchek mirizad."},{"fr":"Ici, on boit le thé avec un morceau de sucre.","tgt":"چای را با حبه‌ی قند می‌خورند.","ro":"Châi râ bâ habbe-ye ghand mikhorand."},{"fr":"Elle m'a raconté l'histoire du quartier.","tgt":"داستان محله را برایم تعریف کرد.","ro":"Dâstân-e mahalle râ barâyam ta'rif kard."},{"fr":"Autrefois, il y avait des jardins partout ici.","tgt":"قدیم اینجا همه جا باغ بود.","ro":"Ghadim injâ hame jâ bâgh bud."},{"fr":"Ses petits-enfants viennent la voir chaque vendredi.","tgt":"نوه‌هایش هر جمعه به دیدنش می‌آیند.","ro":"Novehâyash har jom'e be didanash miâyand."},{"fr":"Prenez donc encore une pâtisserie !","tgt":"یک شیرینی دیگر بردارید!","ro":"Yek shirini-ye digar bardârid!"},{"fr":"Merci, je n'ai vraiment plus faim.","tgt":"ممنون، واقعا دیگر سیرم.","ro":"Mamnun, vâghe'an digar siram."},{"fr":"Vous êtes toujours la bienvenue.","tgt":"همیشه قدمتان روی چشم است.","ro":"Hamishe ghadametân ru-ye cheshm ast."}]},{"title":"Le vendredi en famille","phrases":[{"fr":"Le vendredi, toute la famille se réunit chez mes parents.","tgt":"جمعه‌ها همه‌ی خانواده خانه‌ی پدر و مادرم جمع می‌شوند.","ro":"Jom'ehâ hame-ye khânevâde khâne-ye pedar o mâdaram jam' mishavand."},{"fr":"Mon père fait griller des kebabs dans la cour.","tgt":"پدرم در حیاط کباب درست می‌کند.","ro":"Pedaram dar hayât kabâb dorost mikonad."},{"fr":"Ma grand-mère raconte des histoires d'autrefois.","tgt":"مادربزرگم قصه‌های قدیمی تعریف می‌کند.","ro":"Mâdarbozorgam ghessehâ-ye ghadimi ta'rif mikonad."},{"fr":"Les cousins jouent au ballon dans la ruelle.","tgt":"پسرعموها در کوچه توپ‌بازی می‌کنند.","ro":"Pesaramuhâ dar kuche tupbâzi mikonand."},{"fr":"Après le déjeuner, nous faisons une petite sieste.","tgt":"بعد از ناهار کمی می‌خوابیم.","ro":"Ba'd az nâhâr kami mikhâbim."},{"fr":"L'après-midi, nous buvons du thé au jardin.","tgt":"بعدازظهر در باغچه چای می‌نوشیم.","ro":"Ba'dazzohr dar bâghche châi minushim."},{"fr":"Mon oncle récite parfois un poème de Hafez.","tgt":"عمویم گاهی شعری از حافظ می‌خواند.","ro":"Amuyam gâhi she'ri az Hâfez mikhânad."},{"fr":"Tout le monde l'écoute en silence.","tgt":"همه در سکوت گوش می‌دهند.","ro":"Hame dar sokut gush midahand."},{"fr":"Le soir, chacun rentre chez soi.","tgt":"شب هر کس به خانه‌اش برمی‌گردد.","ro":"Shab har kas be khâne-ash barmigardad."},{"fr":"Ces vendredis me sont très chers.","tgt":"این جمعه‌ها برایم خیلی عزیزند.","ro":"In jom'ehâ barâyam kheyli azizand."}]},{"title":"En taxi dans Tabriz","phrases":[{"fr":"Je voudrais aller au bazar, ça coûte combien ?","tgt":"می‌خواهم به بازار بروم، چقدر می‌شود؟","ro":"Mikhâham be bâzâr beravam, cheghadr mishavad?"},{"fr":"Montez, c'est quarante mille tomans.","tgt":"بفرمایید، چهل هزار تومان.","ro":"Befarmâyid, chehel hezâr tomân."},{"fr":"Il y a beaucoup de circulation à cette heure-ci.","tgt":"این ساعت ترافیک خیلی سنگین است.","ro":"In sâ'at terâfik kheyli sangin ast."},{"fr":"Pouvez-vous prendre un autre chemin ?","tgt":"می‌شود از راه دیگری بروید؟","ro":"Mishavad az râh-e digari beravid?"},{"fr":"Arrêtez-vous au coin de la ruelle, s'il vous plaît.","tgt":"لطفا سر کوچه نگه دارید.","ro":"Lotfan sar-e kuche negah dârid."},{"fr":"Désolé, je n'ai pas de monnaie.","tgt":"ببخشید، پول خرد ندارم.","ro":"Bebakhshid, pul-e khord nadâram."},{"fr":"Pas de souci, vous pouvez payer par carte.","tgt":"اشکالی ندارد، می‌توانید با کارت پرداخت کنید.","ro":"Eshkâli nadârad, mitavânid bâ kârt pardâkht konid."},{"fr":"Dans les taxis collectifs, la course coûte moins cher.","tgt":"در تاکسی‌های خطی کرایه ارزان‌تر است.","ro":"Dar tâksihâ-ye khatti kerâye arzântar ast."},{"fr":"Le chauffeur m'a parlé de sa ville natale.","tgt":"راننده درباره‌ی زادگاهش برایم حرف زد.","ro":"Rânande darbâre-ye zâdgâhash barâyam harf zad."},{"fr":"Merci beaucoup, bon courage à vous !","tgt":"خیلی ممنون، خسته نباشید!","ro":"Kheyli mamnun, khaste nabâshid!"}]},{"title":"Chez le marchand de tapis","phrases":[{"fr":"Tabriz est célèbre pour ses tapis faits main.","tgt":"تبریز به خاطر فرش‌های دستبافش معروف است.","ro":"Tabriz be khâter-e farshhâ-ye dastbâfash ma'ruf ast."},{"fr":"Ce tapis a demandé un an de travail.","tgt":"بافتن این فرش یک سال طول کشیده است.","ro":"Bâftan-e in farsh yek sâl tul keshide ast."},{"fr":"Regardez la finesse de ces motifs.","tgt":"به ظرافت این نقش‌ها نگاه کنید.","ro":"Be zerâfat-e in naghshhâ negâh konid."},{"fr":"Les couleurs viennent de plantes naturelles.","tgt":"رنگ‌هایش از گیاهان طبیعی است.","ro":"Ranghâyash az giyâhân-e tabi'i ast."},{"fr":"Je cherche un petit tapis pour mon salon.","tgt":"دنبال یک فرش کوچک برای پذیرایی‌ام هستم.","ro":"Donbâl-e yek farsh-e kuchek barâye pazirâyi-am hastam."},{"fr":"Celui-ci mesure deux mètres sur trois.","tgt":"این یکی دو در سه متر است.","ro":"In yeki do dar se metr ast."},{"fr":"Il est en laine ou en soie ?","tgt":"پشمی است یا ابریشمی؟","ro":"Pashmi ast yâ abrishami?"},{"fr":"La trame est en soie, et les nœuds en laine.","tgt":"تارش ابریشم است و گره‌هایش پشم.","ro":"Târash abrisham ast va gerehâyash pashm."},{"fr":"Je vais y réfléchir et revenir demain.","tgt":"فکر می‌کنم و فردا برمی‌گردم.","ro":"Fekr mikonam va fardâ barmigardam."},{"fr":"Réfléchissez tranquillement, rien ne presse.","tgt":"سر فرصت فکر کنید، عجله‌ای نیست.","ro":"Sar-e forsat fekr konid, ajale-i nist."}]},{"title":"Souvenirs de la semaine passée","phrases":[{"fr":"La semaine dernière a été très chargée.","tgt":"هفته‌ی گذشته خیلی شلوغ بود.","ro":"Hafte-ye gozashte kheyli sholugh bud."},{"fr":"Lundi, je suis allé chez le dentiste.","tgt":"دوشنبه پیش دندانپزشک رفتم.","ro":"Doshanbe pish-e dandânpezeshk raftam."},{"fr":"Mardi, mes amis sont venus dîner.","tgt":"سه‌شنبه دوستانم برای شام آمدند.","ro":"Seshanbe dustânam barâye shâm âmadand."},{"fr":"Mercredi, il a neigé toute la journée.","tgt":"چهارشنبه تمام روز برف آمد.","ro":"Chahârshanbe tamâm-e ruz barf âmad."},{"fr":"Les rues étaient blanches et silencieuses.","tgt":"خیابان‌ها سفید و ساکت بودند.","ro":"Khiyâbânhâ sefid va sâket budand."},{"fr":"Jeudi, un collègue et moi sommes allés à l'Arg de Tabriz.","tgt":"پنجشنبه با یک همکار به ارگ تبریز رفتیم.","ro":"Panjshanbe bâ yek hamkâr be Arg-e Tabriz raftim."},{"fr":"Je n'avais jamais vu des murs aussi hauts.","tgt":"تا آن روز چنین دیوارهای بلندی ندیده بودم.","ro":"Tâ ân ruz chenin divârhâ-ye bolandi nadide budam."},{"fr":"Vendredi, je me suis reposé à la maison.","tgt":"جمعه در خانه استراحت کردم.","ro":"Jom'e dar khâne esterâhat kardam."},{"fr":"Et vous, qu'avez-vous fait la semaine dernière ?","tgt":"شما هفته‌ی گذشته چه کار کردید؟","ro":"Shomâ hafte-ye gozashte che kâr kardid?"},{"fr":"Rien de spécial, j'ai surtout travaillé.","tgt":"چیز خاصی نه، بیشتر کار کردم.","ro":"Chiz-e khâsi na, bishtar kâr kardam."}]},{"title":"Les consignes du médecin","phrases":[{"fr":"Ne faites pas de sport pendant une semaine.","tgt":"تا یک هفته ورزش نکنید.","ro":"Tâ yek hafte varzesh nakonid."},{"fr":"Ne sors pas sans manteau, il fait froid.","tgt":"بدون پالتو بیرون نرو، هوا سرد است.","ro":"Bedun-e pâlto birun naro, havâ sard ast."},{"fr":"Ne mange pas trop gras le soir.","tgt":"شب‌ها غذای چرب نخور.","ro":"Shabhâ ghazâ-ye charb nakhor."},{"fr":"Ne travaille pas jusqu'à minuit.","tgt":"تا نیمه‌شب کار نکن.","ro":"Tâ nimeshab kâr nakon."},{"fr":"Ne bois pas de café après six heures.","tgt":"بعد از ساعت شش قهوه نخور.","ro":"Ba'd az sâ'at-e shesh ghahve nakhor."},{"fr":"Ne t'inquiète pas, ce n'est rien de grave.","tgt":"نگران نباش، چیز مهمی نیست.","ro":"Negarân nabâsh, chiz-e mohemmi nist."},{"fr":"Surtout, n'oubliez pas vos médicaments.","tgt":"مخصوصا داروهایتان را فراموش نکنید.","ro":"Makhsusan dâruhâyetân râ farâmush nakonid."},{"fr":"Ne va pas au travail demain, reste au lit.","tgt":"فردا سر کار نرو، در رختخواب بمان.","ro":"Fardâ sar-e kâr naro, dar rakhtekhâb bemân."},{"fr":"Ne portez rien de lourd pour l'instant.","tgt":"فعلا چیز سنگینی بلند نکنید.","ro":"Fe'lan chiz-e sangini boland nakonid."},{"fr":"Et n'utilisez pas trop votre téléphone.","tgt":"و زیاد با گوشی کار نکنید.","ro":"Va ziyâd bâ gushi kâr nakonid."}],"tip":{"title":"« Nakon » et « naro » : l'interdiction","example":"Ne va pas au travail demain, reste au lit. — فردا سر کار <b>نرو</b>، در رختخواب بمان.","body":"Pour interdire quelque chose, on remplace simplement le petit « be » de l'impératif par « na ». « Boro », va, devient « naro », ne va pas ; « bokhor », mange, devient « nakhor », ne mange pas ; et « bokon », fais, devient « nakon », ne fais pas. Avec « shomâ », on ajoute « -id » : « naravid », « nakonid », n'allez pas, ne faites pas. Dans « fardâ sar-e kâr naro », on entend demain, au travail, ne va pas : une seule syllabe suffit à changer l'ordre en interdiction. Retenez aussi la formule très utile « negarân nabâsh », ne t'inquiète pas, que l'on entend partout pour rassurer. Astuce : « na » veut dire non, alors pensez simplement à dire non au verbe.","exampleRo":"Fardâ sar-e kâr naro, dar rakhtekhâb bemân.","lit":"demain · tête [de] · travail · [ne… pas] va · dans · lit · reste","say":{"Nakon":"نکن","naro":"نرو","Boro":"برو","bokhor":"بخور","nakhor":"نخور","bokon":"بکن","nakon":"نکن","shomâ":"شما","naravid":"نروید","nakonid":"نکنید","fardâ sar-e kâr naro":"فردا سر کار نرو","negarân nabâsh":"نگران نباش"}}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module touche à sa fin.","tgt":"این بخش دارد تمام می‌شود.","ro":"In bakhsh dârad tamâm mishavad."},{"fr":"Maintenant, je sais raconter ma journée d'hier en persan.","tgt":"حالا می‌توانم روز دیروزم را به فارسی تعریف کنم.","ro":"Hâlâ mitavânam ruz-e diruzam râ be fârsi ta'rif konam."},{"fr":"Je sais dire ce que j'ai déjà fait dans ma vie.","tgt":"می‌توانم بگویم چه کارهایی کرده‌ام.","ro":"Mitavânam beguyam che kârhâyi karde-am."},{"fr":"Je peux expliquer ce que je veux faire.","tgt":"می‌توانم بگویم چه کاری می‌خواهم بکنم.","ro":"Mitavânam beguyam che kâri mikhâham bokonam."},{"fr":"Je sais aussi donner des conseils et des ordres simples.","tgt":"بلدم دستورهای ساده بدهم و نصیحت کنم.","ro":"Baladam dasturhâ-ye sâde bedaham va nasihat konam."},{"fr":"Le persan me devient de plus en plus familier.","tgt":"فارسی برایم روز به روز آشناتر می‌شود.","ro":"Fârsi barâyam ruz be ruz âshnâtar mishavad."},{"fr":"La prononciation reste parfois difficile.","tgt":"تلفظ هنوز گاهی سخت است.","ro":"Talaffoz hanuz gâhi sakht ast."},{"fr":"Je m'entraîne chaque jour pendant mon trajet.","tgt":"هر روز در راه تمرین می‌کنم.","ro":"Har ruz dar râh tamrin mikonam."},{"fr":"Le prochain module parlera des voyages.","tgt":"بخش بعدی درباره‌ی سفر است.","ro":"Bakhsh-e ba'di darbâre-ye safar ast."},{"fr":"Bravo, et à très bientôt !","tgt":"آفرین، به امید دیدار!","ro":"Âfarin, be omid-e didâr!"}]}]},{"id":2,"name":"En voyage","desc":"Des situations de voyage plus variées et plus complexes.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à Yazd","phrases":[{"fr":"Nous sommes enfin arrivés à Yazd.","tgt":"ما بالاخره به یزد رسیدیم.","ro":"Mâ belâkhare be Yazd residim."},{"fr":"Le trajet en bus depuis Ispahan a duré cinq heures.","tgt":"سفر با اتوبوس از اصفهان پنج ساعت طول کشید.","ro":"Safar bâ otobus az Esfahân panj sâ'at tul keshid."},{"fr":"Il fait beaucoup plus chaud ici qu'à Ispahan.","tgt":"اینجا خیلی گرم‌تر از اصفهان است.","ro":"Injâ kheyli garmtar az Esfahân ast."},{"fr":"L'air est très sec dans cette ville.","tgt":"هوای این شهر خیلی خشک است.","ro":"Havâ-ye in shahr kheyli khoshk ast."},{"fr":"Pouvez-vous nous conduire à la vieille ville ?","tgt":"می‌توانید ما را به بافت قدیمی شهر ببرید؟","ro":"Mitavânid mâ râ be bâft-e ghadimi-ye shahr bebarid?"},{"fr":"Notre maison d'hôtes se trouve près de la place Amir Chakhmaq.","tgt":"اقامتگاه ما نزدیک میدان امیرچخماق است.","ro":"Eghâmatgâh-e mâ nazdik-e meydân-e Amir Chakhmâgh ast."},{"fr":"Le chauffeur connaît bien la ville.","tgt":"راننده شهر را خوب می‌شناسد.","ro":"Rânande shahr râ khub mishenâsad."},{"fr":"Combien de temps faut-il pour y aller ?","tgt":"تا آنجا چقدر طول می‌کشد؟","ro":"Tâ ânjâ cheghadr tul mikeshad?"},{"fr":"Les maisons ont toutes la couleur de la terre.","tgt":"خانه‌ها همه رنگ خاک هستند.","ro":"Khânehâ hame rang-e khâk hastand."},{"fr":"C'est comme être dans un autre monde.","tgt":"انگار در دنیای دیگری هستیم.","ro":"Engâr dar donyâ-ye digari hastim."}]},{"title":"La vieille ville en terre crue","phrases":[{"fr":"Les ruelles de la vieille ville sont étroites et sinueuses.","tgt":"کوچه‌های بافت قدیمی باریک و پیچ در پیچ هستند.","ro":"Kuchehâ-ye bâft-e ghadimi bârik va pich dar pich hastand."},{"fr":"Les murs sont faits de terre et de paille.","tgt":"دیوارها از کاهگل ساخته شده‌اند.","ro":"Divârhâ az kâhgel sâkhte shode-and."},{"fr":"On se perd facilement dans ces ruelles.","tgt":"در این کوچه‌ها آدم راحت گم می‌شود.","ro":"Dar in kuchehâ âdam râhat gom mishavad."},{"fr":"Les toits ressemblent à de petites coupoles.","tgt":"سقف خانه‌ها مثل گنبدهای کوچک است.","ro":"Saghf-e khânehâ mesl-e gonbadhâ-ye kuchek ast."},{"fr":"Montons sur ce toit pour voir toute la ville.","tgt":"بیایید روی این بام برویم تا کل شهر را ببینیم.","ro":"Biyâyid ru-ye in bâm beravim tâ kol-e shahr râ bebinim."},{"fr":"D'ici, on voit des dizaines de tours du vent.","tgt":"از اینجا ده‌ها بادگیر می‌بینیم.","ro":"Az injâ dahhâ bâdgir mibinim."},{"fr":"Une tour du vent rafraîchit la maison sans électricité.","tgt":"بادگیر خانه را بدون برق خنک می‌کند.","ro":"Bâdgir khâne râ bedun-e bargh khonak mikonad."},{"fr":"Ces vieilles portes ont deux heurtoirs différents.","tgt":"این درهای قدیمی دو کوبه‌ی متفاوت دارند.","ro":"In darhâ-ye ghadimi do kube-ye motefâvet dârand."},{"fr":"Le guide nous explique l'histoire de chaque maison.","tgt":"راهنما تاریخچه‌ی هر خانه را برای ما توضیح می‌دهد.","ro":"Râhnamâ târikhche-ye har khâne râ barâye mâ towzih midahad."},{"fr":"Cette ville est l'une des plus anciennes du monde.","tgt":"این شهر یکی از قدیمی‌ترین شهرهای دنیاست.","ro":"In shahr yeki az ghadimitarin shahrhâ-ye donyâst."}]},{"title":"Le programme des prochains jours","phrases":[{"fr":"Demain, nous visiterons le jardin de Dowlat Abad.","tgt":"فردا از باغ دولت‌آباد بازدید خواهیم کرد.","ro":"Fardâ az bâgh-e Dowlatâbâd bâzdid khâhim kard."},{"fr":"Après-demain, nous partirons dans le désert.","tgt":"پس‌فردا به کویر خواهیم رفت.","ro":"Pasfardâ be kavir khâhim raft."},{"fr":"Je prendrai beaucoup de photos des tours du vent.","tgt":"از بادگیرها عکس‌های زیادی خواهم گرفت.","ro":"Az bâdgirhâ akshâ-ye ziyâdi khâham gereft."},{"fr":"Le guide viendra nous chercher à huit heures.","tgt":"راهنما ساعت هشت دنبال ما خواهد آمد.","ro":"Râhnamâ sâ'at-e hasht donbâl-e mâ khâhad âmad."},{"fr":"Nous resterons deux nuits dans la maison d'hôtes.","tgt":"دو شب در اقامتگاه خواهیم ماند.","ro":"Do shab dar eghâmatgâh khâhim mând."},{"fr":"Ensuite, nous prendrons la route de Persépolis.","tgt":"بعد به سمت تخت جمشید حرکت خواهیم کرد.","ro":"Ba'd be samt-e Takht-e Jamshid harekat khâhim kard."},{"fr":"Vous verrez, ce voyage vous plaira.","tgt":"خواهید دید، این سفر را دوست خواهید داشت.","ro":"Khâhid did, in safar râ dust khâhid dâsht."},{"fr":"Il ne pleuvra pas cette semaine.","tgt":"این هفته باران نخواهد بارید.","ro":"In hafte bârân nakhâhad bârid."},{"fr":"À quelle heure partirons-nous demain matin ?","tgt":"فردا صبح ساعت چند راه خواهیم افتاد؟","ro":"Fardâ sobh sâ'at-e chand râh khâhim oftâd?"},{"fr":"On en parlera ce soir autour d'un thé.","tgt":"امشب سر چای درباره‌اش صحبت خواهیم کرد.","ro":"Emshab sar-e chây darbâre-ash sohbat khâhim kard."}],"tip":{"title":"Le futur : « khâham raft »","example":"Après-demain, nous partirons dans le désert. — پس‌فردا به کویر <b>خواهیم رفت</b>.","body":"Pour parler du futur, le persan se sert du verbe « khâstan », vouloir, comme d'un auxiliaire : « khâham » pour je, « khâhi » pour tu, « khâhad » pour il ou elle, « khâhim » pour nous, « khâhid » pour vous, « khâhand » pour eux. Derrière, on ajoute une forme courte du verbe, celle du passé, qui ne change jamais : « khâham raft », j'irai, « khâhad âmad », il viendra. Notre exemple, « pasfardâ be kavir khâhim raft », se décompose ainsi : après-demain, au désert, nous allons, partir, avec le verbe toujours à la fin. Pour la négation, on colle « na- » devant l'auxiliaire : « nakhâham raft », je n'irai pas. Dans la conversation de tous les jours, les Iraniens disent souvent le futur avec le simple présent, comme « fardâ miravim », demain on y va, mais « khâham raft » reste la forme soignée des projets et des promesses. Astuce : le futur persan, c'est vouloir plus le passé, comme si l'on voulait déjà que ce soit fait.","exampleRo":"Pasfardâ be kavir khâhim raft.","lit":"après-demain · [à] · désert · [futur : nous] · partir","say":{"khâham raft":"خواهم رفت","khâstan":"خواستن","khâham":"خواهم","khâhi":"خواهی","khâhad":"خواهد","khâhim":"خواهیم","khâhid":"خواهید","khâhand":"خواهند","khâhad âmad":"خواهد آمد","pasfardâ be kavir khâhim raft":"پس‌فردا به کویر خواهیم رفت","nakhâham raft":"نخواهم رفت","fardâ miravim":"فردا می‌رویم"}}},{"title":"La maison d'hôtes traditionnelle","phrases":[{"fr":"Notre chambre donne sur la cour intérieure.","tgt":"اتاق ما رو به حیاط مرکزی است.","ro":"Otâgh-e mâ ru be hayât-e markazi ast."},{"fr":"Il y a un bassin et des orangers au milieu de la cour.","tgt":"وسط حیاط یک حوض و چند درخت نارنج هست.","ro":"Vasat-e hayât yek howz va chand derakht-e nârenj hast."},{"fr":"On prend le petit-déjeuner sur une banquette en bois.","tgt":"صبحانه را روی تخت چوبی می‌خوریم.","ro":"Sobhâne râ ru-ye takht-e chubi mikhorim."},{"fr":"La propriétaire nous a offert du thé à la cardamome.","tgt":"خانم صاحب‌خانه به ما چای هل‌دار تعارف کرد.","ro":"Khânom-e sâhebkhâne be mâ chây-e heldâr ta'ârof kard."},{"fr":"Les plafonds sont hauts et les murs restent frais.","tgt":"سقف‌ها بلند هستند و دیوارها خنک می‌مانند.","ro":"Saghfhâ boland hastand va divârhâ khonak mimânand."},{"fr":"Avez-vous une chambre avec salle de bains ?","tgt":"اتاقی با حمام دارید؟","ro":"Otâghi bâ hammâm dârid?"},{"fr":"Internet ne marche que dans le salon.","tgt":"اینترنت فقط در سالن کار می‌کند.","ro":"Internet faghat dar sâlon kâr mikonad."},{"fr":"Les fenêtres ont des vitraux de toutes les couleurs.","tgt":"پنجره‌ها شیشه‌های رنگی دارند.","ro":"Panjarehâ shishehâ-ye rangi dârand."},{"fr":"Le soir, les voyageurs bavardent ensemble dans la cour.","tgt":"شب‌ها مسافرها در حیاط با هم گپ می‌زنند.","ro":"Shabhâ mosâferhâ dar hayât bâ ham gap mizanand."},{"fr":"Ici, je me sens comme chez moi.","tgt":"اینجا احساس می‌کنم در خانه‌ی خودم هستم.","ro":"Injâ ehsâs mikonam dar khâne-ye khodam hastam."}]},{"title":"Yazd autrefois","phrases":[{"fr":"Autrefois, les gens buvaient l'eau des qanats.","tgt":"قدیم‌ها مردم آب قنات می‌خوردند.","ro":"Ghadimhâ mardom âb-e ghanât mikhordand."},{"fr":"Les familles dormaient sur les toits en été.","tgt":"تابستان‌ها خانواده‌ها روی بام می‌خوابیدند.","ro":"Tâbestânhâ khânevâdehâ ru-ye bâm mikhâbidand."},{"fr":"En hiver, on gardait la glace dans des glacières en terre.","tgt":"زمستان‌ها یخ را در یخچال‌های خشتی نگه می‌داشتند.","ro":"Zemestânhâ yakh râ dar yakhchâlhâ-ye kheshti negah midâshtand."},{"fr":"Le grand-père de notre hôte tissait de la soie.","tgt":"پدربزرگ میزبان ما پارچه‌ی ابریشمی می‌بافت.","ro":"Pedarbozorg-e mizbân-e mâ pârche-ye abrishami mibâft."},{"fr":"Les caravanes s'arrêtaient ici avant de traverser le désert.","tgt":"کاروان‌ها قبل از عبور از کویر اینجا توقف می‌کردند.","ro":"Kârvânhâ ghabl az obur az kavir injâ tavaghof mikardand."},{"fr":"Quand j'étais enfant, je rêvais toujours du désert.","tgt":"وقتی بچه بودم، همیشه خواب کویر را می‌دیدم.","ro":"Vaghti bachche budam, hamishe khâb-e kavir râ mididam."},{"fr":"Les enfants jouaient dans ces ruelles toute la journée.","tgt":"بچه‌ها تمام روز در این کوچه‌ها بازی می‌کردند.","ro":"Bachchehâ tamâm-e ruz dar in kuchehâ bâzi mikardand."},{"fr":"L'eau passait sous la maison et rafraîchissait l'air.","tgt":"آب از زیر خانه می‌گذشت و هوا را خنک می‌کرد.","ro":"Âb az zir-e khâne migozasht va havâ râ khonak mikard."},{"fr":"Chaque quartier avait sa propre citerne.","tgt":"هر محله آب‌انبار خودش را داشت.","ro":"Har mahalle âbanbâr-e khodash râ dâsht."},{"fr":"Notre hôte nous racontait ces histoires en souriant.","tgt":"میزبانمان با لبخند این داستان‌ها را برای ما تعریف می‌کرد.","ro":"Mizbânemân bâ labkhand in dâstânhâ râ barâye mâ ta'rif mikard."}],"tip":{"title":"L'imparfait avec « mi- » : « miraftam »","example":"Les familles dormaient sur les toits en été. — تابستان‌ها خانواده‌ها روی بام <b>می‌خوابیدند</b>.","body":"Pour décrire une habitude passée ou une scène qui durait, le persan prend le passé simple et lui ajoute le petit préfixe « mi- », le même que pour le présent. « Raftam », je suis allé, devient « miraftam », j'allais ; « khordand », ils ont bu, devient « mikhordand », ils buvaient. Notre exemple, « tâbestânhâ khânevâdehâ ru-ye bâm mikhâbidand », se décompose en : les étés, les familles, sur le toit, dormaient, avec le verbe bien rangé à la fin. C'est exactement l'imparfait français, celui des souvenirs et des descriptions, comme « kâr mikard », il travaillait, ou « bâzi mikardand », ils jouaient. Attention, le verbe être se passe de « mi- » : on dit simplement « budam », j'étais, et de même « dâsht », il avait. Astuce : « mi- » signale une action qui dure ou se répète, au présent comme au passé.","exampleRo":"Tâbestânhâ khânevâdehâ ru-ye bâm mikhâbidand.","lit":"étés · familles · sur · toit · [mi-] dormaient","say":{"miraftam":"می‌رفتم","Raftam":"رفتم","khordand":"خوردند","mikhordand":"می‌خوردند","tâbestânhâ khânevâdehâ ru-ye bâm mikhâbidand":"تابستان‌ها خانواده‌ها روی بام می‌خوابیدند","kâr mikard":"کار می‌کرد","bâzi mikardand":"بازی می‌کردند","budam":"بودم","dâsht":"داشت"}}},{"title":"Le bazar et les douceurs de Yazd","phrases":[{"fr":"Yazd est célèbre pour ses pâtisseries.","tgt":"یزد به خاطر شیرینی‌هایش معروف است.","ro":"Yazd be khâter-e shirinihâyash ma'ruf ast."},{"fr":"Je voudrais goûter les baklavas de Yazd.","tgt":"می‌خواهم باقلوای یزدی را امتحان کنم.","ro":"Mikhâham bâghlavâ-ye yazdi râ emtehân konam."},{"fr":"Ces petits gâteaux s'appellent des ghottab.","tgt":"اسم این شیرینی‌های کوچک قطاب است.","ro":"Esm-e in shirinihâ-ye kuchek ghottâb ast."},{"fr":"Donnez-m'en un demi-kilo, s'il vous plaît.","tgt":"لطفا نیم کیلو بدهید.","ro":"Lotfan nim kilo bedahid."},{"fr":"Ces tissus de termeh sont-ils tissés à la main ?","tgt":"این پارچه‌های ترمه دست‌باف هستند؟","ro":"In pârchehâ-ye terme dastbâf hastand?"},{"fr":"Combien coûte cette nappe brodée ?","tgt":"این رومیزی چند است؟","ro":"In rumizi chand ast?"},{"fr":"Elle coûte huit cent mille tomans.","tgt":"هشتصد هزار تومان است.","ro":"Hashtsad hezâr tomân ast."},{"fr":"C'est un peu cher, vous me faites un prix ?","tgt":"کمی گران است، تخفیف می‌دهید؟","ro":"Kami gerân ast, takhfif midahid?"},{"fr":"Je la prends pour ma mère.","tgt":"آن را برای مادرم برمی‌دارم.","ro":"Ân râ barâye mâdaram barmidâram."},{"fr":"Le marchand nous a donné un verre de sorbet.","tgt":"فروشنده یک لیوان شربت به ما داد.","ro":"Forushande yek livân sharbat be mâ dâd."}]},{"title":"Réserver une excursion dans le désert","phrases":[{"fr":"Je voudrais réserver une excursion dans le désert.","tgt":"می‌خواهم یک تور کویر رزرو کنم.","ro":"Mikhâham yek tur-e kavir rezerv konam."},{"fr":"Combien de personnes y a-t-il dans le groupe ?","tgt":"گروه چند نفر است؟","ro":"Goruh chand nafar ast?"},{"fr":"Nous sommes quatre, dont deux enfants.","tgt":"ما چهار نفریم، دو تا بچه هم داریم.","ro":"Mâ chahâr nafarim, do tâ bachche ham dârim."},{"fr":"Le départ est prévu à quelle heure ?","tgt":"حرکت ساعت چند است؟","ro":"Harekat sâ'at-e chand ast?"},{"fr":"Le prix comprend-il le dîner et la nuit ?","tgt":"آیا شام و اقامت شب در قیمت حساب شده است؟","ro":"Âyâ shâm va eghâmat-e shab dar gheymat hesâb shode ast?"},{"fr":"Oui, et aussi la promenade à dos de chameau.","tgt":"بله، شترسواری هم هست.","ro":"Bale, shotorsavâri ham hast."},{"fr":"Peut-on payer en espèces ?","tgt":"می‌توانیم نقدی پرداخت کنیم؟","ro":"Mitavânim naghdi pardâkht konim?"},{"fr":"Pouvez-vous m'envoyer les détails par message ?","tgt":"می‌توانید اطلاعات را برایم پیامک کنید؟","ro":"Mitavânid ettelâ'ât râ barâyam payâmak konid?"},{"fr":"Le quatre-quatre viendra nous chercher devant la maison d'hôtes.","tgt":"ماشین شاسی‌بلند جلوی اقامتگاه دنبال ما می‌آید.","ro":"Mâshin-e shâsiboland jelo-ye eghâmatgâh donbâl-e mâ miâyad."},{"fr":"Parfait, c'est réservé pour samedi.","tgt":"عالی است، برای شنبه رزرو شد.","ro":"Âli ast, barâye shanbe rezerv shod."}]},{"title":"Si le vent se lève","phrases":[{"fr":"Si le vent se lève, nous ne pourrons pas voir les dunes.","tgt":"اگر باد بیاید، نمی‌توانیم تپه‌های شنی را ببینیم.","ro":"Agar bâd biyâyad, nemitavânim tappehâ-ye sheni râ bebinim."},{"fr":"Si vous avez froid la nuit, il y a des couvertures.","tgt":"اگر شب سردتان شد، پتو هست.","ro":"Agar shab sardetân shod, patu hast."},{"fr":"Si nous partons tôt, nous verrons le lever du soleil.","tgt":"اگر زود حرکت کنیم، طلوع آفتاب را می‌بینیم.","ro":"Agar zud harekat konim, tolu'-e âftâb râ mibinim."},{"fr":"Si vous voulez, nous pouvons monter sur la grande dune.","tgt":"اگر بخواهید، می‌توانیم از تپه‌ی بزرگ بالا برویم.","ro":"Agar bekhâhid, mitavânim az tappe-ye bozorg bâlâ beravim."},{"fr":"Si vous n'avez pas de chapeau, achetez-en un au village.","tgt":"اگر کلاه ندارید، در روستا یکی بخرید.","ro":"Agar kolâh nadârid, dar rustâ yeki bekharid."},{"fr":"Que ferons-nous s'il fait trop chaud ?","tgt":"اگر هوا خیلی گرم باشد، چه کار کنیم؟","ro":"Agar havâ kheyli garm bâshad, che kâr konim?"},{"fr":"S'il fait trop chaud, nous resterons à l'ombre jusqu'à quatre heures.","tgt":"اگر خیلی گرم باشد، تا ساعت چهار در سایه می‌مانیم.","ro":"Agar kheyli garm bâshad, tâ sâ'at-e chahâr dar sâye mimânim."},{"fr":"Buvez beaucoup d'eau, sinon vous serez fatigués.","tgt":"زیاد آب بخورید، وگرنه خسته می‌شوید.","ro":"Ziyâd âb bekhorid, vagarna khaste mishavid."},{"fr":"Si le guide est d'accord, nous dormirons dehors.","tgt":"اگر راهنما موافق باشد، بیرون می‌خوابیم.","ro":"Agar râhnamâ movâfegh bâshad, birun mikhâbim."},{"fr":"Si le ciel est dégagé, nous verrons des milliers d'étoiles.","tgt":"اگر آسمان صاف باشد، هزاران ستاره خواهیم دید.","ro":"Agar âsemân sâf bâshad, hezârân setâre khâhim did."}],"tip":{"title":"« Agar » : si... alors","example":"Si nous partons tôt, nous verrons le lever du soleil. — <b>اگر</b> زود حرکت کنیم، طلوع آفتاب را می‌بینیم.","body":"« Agar » veut dire si, et il se place en tête de phrase, comme en français. Juste après, le verbe se met le plus souvent au subjonctif, cette forme en « be- » que vous connaissez déjà : « agar bekhâhid », si vous voulez, « agar zud harekat konim », si nous partons tôt, mot à mot si, tôt, départ, nous fassions. La deuxième partie se dit au présent ou au futur, sans aucun mot pour alors : « tolu'-e âftâb râ mibinim », nous verrons le lever du soleil. Avec le verbe être, on emploie « bâshad » : « agar havâ garm bâshad », s'il fait chaud ; avec avoir, on garde le présent : « agar kolâh nadârid », si vous n'avez pas de chapeau. Astuce : le « si » persan aime le subjonctif, alors que le « si » français le refuse, c'est le seul piège à retenir.","exampleRo":"Agar zud harekat konim, tolu'-e âftâb râ mibinim.","lit":"si · tôt · départ · fassions · lever · [de] · soleil · [objet] · voyons","say":{"Agar":"اگر","agar bekhâhid":"اگر بخواهید","agar zud harekat konim":"اگر زود حرکت کنیم","tolu'-e âftâb râ mibinim":"طلوع آفتاب را می‌بینیم","bâshad":"باشد","agar havâ garm bâshad":"اگر هوا گرم باشد","agar kolâh nadârid":"اگر کلاه ندارید"}}},{"title":"En route vers le désert","phrases":[{"fr":"La route traverse des villages abandonnés.","tgt":"جاده از روستاهای متروکه می‌گذرد.","ro":"Jâdde az rustâhâ-ye matruke migozarad."},{"fr":"Le chauffeur roule vite sur la piste.","tgt":"راننده در جاده‌ی خاکی تند می‌راند.","ro":"Rânande dar jâdde-ye khâki tond mirânad."},{"fr":"Nous faisons une pause dans un vieux caravansérail.","tgt":"در یک کاروانسرای قدیمی توقف می‌کنیم.","ro":"Dar yek kârvânsarâ-ye ghadimi tavaghof mikonim."},{"fr":"Ici, le téléphone ne capte plus.","tgt":"اینجا آنتن نیست.","ro":"Injâ ânten nist."},{"fr":"Le paysage devient peu à peu plus vide.","tgt":"منظره کم‌کم خالی‌تر می‌شود.","ro":"Manzare kamkam khâlitar mishavad."},{"fr":"Regardez, il y a un mirage là-bas !","tgt":"نگاه کنید، آنجا سراب است!","ro":"Negâh konid, ânjâ sarâb ast!"},{"fr":"On dirait un lac au milieu du sable.","tgt":"مثل یک دریاچه وسط شن‌هاست.","ro":"Mesl-e yek daryâche vasat-e shenhâst."},{"fr":"Le sel brille comme de la neige.","tgt":"نمک مثل برف برق می‌زند.","ro":"Namak mesl-e barf bargh mizanad."},{"fr":"Nous sommes à deux heures de la ville la plus proche.","tgt":"تا نزدیک‌ترین شهر دو ساعت راه داریم.","ro":"Tâ nazdiktarin shahr do sâ'at râh dârim."},{"fr":"Le silence ici est incroyable.","tgt":"سکوت اینجا باورنکردنی است.","ro":"Sokut-e injâ bâvarnakardani ast."}]},{"title":"Les dunes et les chameaux","phrases":[{"fr":"Les dunes changent de couleur selon l'heure.","tgt":"رنگ تپه‌های شنی در ساعت‌های مختلف عوض می‌شود.","ro":"Rang-e tappehâ-ye sheni dar sâ'athâ-ye mokhtalef avaz mishavad."},{"fr":"Enlevez vos chaussures, le sable est doux.","tgt":"کفش‌هایتان را دربیاورید، شن نرم است.","ro":"Kafshhâyetân râ darbiyâvarid, shen narm ast."},{"fr":"Monter la dune est plus dur que je ne pensais.","tgt":"بالا رفتن از تپه سخت‌تر از چیزی است که فکر می‌کردم.","ro":"Bâlâ raftan az tappe sakhttar az chizi ast ke fekr mikardam."},{"fr":"Les chameaux attendent à l'ombre des palmiers.","tgt":"شترها در سایه‌ی نخل‌ها منتظرند.","ro":"Shotorhâ dar sâye-ye nakhlhâ montazerand."},{"fr":"Comment s'appelle ce chameau ?","tgt":"اسم این شتر چیست؟","ro":"Esm-e in shotor chist?"},{"fr":"Tenez-vous bien quand il se lève.","tgt":"وقتی بلند می‌شود، محکم بگیرید.","ro":"Vaghti boland mishavad, mohkam begirid."},{"fr":"J'ai eu un peu peur au début.","tgt":"اولش کمی ترسیدم.","ro":"Avvalash kami tarsidam."},{"fr":"Le chamelier chante une vieille chanson.","tgt":"ساربان یک آواز قدیمی می‌خواند.","ro":"Sârbân yek âvâz-e ghadimi mikhânad."},{"fr":"Les enfants glissent sur le sable.","tgt":"بچه‌ها روی شن سر می‌خورند.","ro":"Bachchehâ ru-ye shen sor mikhorand."},{"fr":"Quelle journée extraordinaire !","tgt":"چه روز فوق‌العاده‌ای!","ro":"Che ruz-e fogholâde-i!"}]},{"title":"Une nuit sous les étoiles","phrases":[{"fr":"Le soleil se couche derrière les dunes.","tgt":"خورشید پشت تپه‌ها غروب می‌کند.","ro":"Khorshid posht-e tappehâ ghorub mikonad."},{"fr":"Dès que la nuit tombe, il fait beaucoup plus frais.","tgt":"همین که شب می‌شود، هوا خیلی خنک‌تر می‌شود.","ro":"Hamin ke shab mishavad, havâ kheyli khonaktar mishavad."},{"fr":"Le guide allume un feu pour le dîner.","tgt":"راهنما برای شام آتش روشن می‌کند.","ro":"Râhnamâ barâye shâm âtash roshan mikonad."},{"fr":"Pour le dîner, il y a du riz et des kebabs au feu de bois.","tgt":"برای شام برنج و کباب روی آتش داریم.","ro":"Barâye shâm berenj va kabâb ru-ye âtash dârim."},{"fr":"Je n'ai jamais vu autant d'étoiles.","tgt":"تا حالا این همه ستاره ندیده‌ام.","ro":"Tâ hâlâ in hame setâre nadide-am."},{"fr":"On voit très bien la Voie lactée.","tgt":"کهکشان راه شیری را خیلی خوب می‌بینیم.","ro":"Kahkeshân-e Râh-e Shiri râ kheyli khub mibinim."},{"fr":"Regardez, une étoile filante !","tgt":"ببینید، یک شهاب!","ro":"Bebinid, yek shahâb!"},{"fr":"Faites vite un vœu !","tgt":"زود آرزو کنید!","ro":"Zud ârezu konid!"},{"fr":"Le guide nous lit un poème de Hafez.","tgt":"راهنما برایمان شعری از حافظ می‌خواند.","ro":"Râhnamâ barâyemân she'ri az Hâfez mikhânad."},{"fr":"Nous dormons dans des sacs de couchage sur le sable.","tgt":"در کیسه‌خواب روی شن می‌خوابیم.","ro":"Dar kisekhâb ru-ye shen mikhâbim."}]},{"title":"Une crevaison sur la piste","phrases":[{"fr":"La voiture fait un bruit bizarre.","tgt":"ماشین صدای عجیبی می‌دهد.","ro":"Mâshin sedâ-ye ajibi midahad."},{"fr":"Nous devons nous arrêter tout de suite.","tgt":"باید فورا نگه داریم.","ro":"Bâyad fowran negah dârim."},{"fr":"Un des pneus est crevé.","tgt":"یکی از لاستیک‌ها پنچر شده است.","ro":"Yeki az lâstikhâ panchar shode ast."},{"fr":"Il faut changer la roue.","tgt":"باید چرخ را عوض کنیم.","ro":"Bâyad charkh râ avaz konim."},{"fr":"Il faut attendre un mécanicien du village.","tgt":"باید منتظر یک مکانیک از روستا بمانیم.","ro":"Bâyad montazer-e yek mekânik az rustâ bemânim."},{"fr":"En attendant, vous devez rester à l'ombre.","tgt":"تا آن موقع باید در سایه بمانید.","ro":"Tâ ân mowghe' bâyad dar sâye bemânid."},{"fr":"Je dois prévenir la maison d'hôtes.","tgt":"باید به اقامتگاه خبر بدهم.","ro":"Bâyad be eghâmatgâh khabar bedaham."},{"fr":"Nous n'aurions pas dû partir si tard.","tgt":"نباید این‌قدر دیر راه می‌افتادیم.","ro":"Nabâyad inghadr dir râh mioftâdim."},{"fr":"Un camion s'arrête pour nous aider.","tgt":"یک کامیون نگه می‌دارد تا به ما کمک کند.","ro":"Yek kâmiyon negah midârad tâ be mâ komak konad."},{"fr":"Heureusement, nous devons juste payer cent mille tomans.","tgt":"خوشبختانه فقط باید صد هزار تومان بدهیم.","ro":"Khoshbakhtâne faghat bâyad sad hezâr tomân bedahim."}],"tip":{"title":"« Bâyad » : devoir, il faut","example":"Il faut changer la roue. — <b>باید</b> چرخ را عوض کنیم.","body":"« Bâyad » est un mot très pratique : il ne change jamais, quelle que soit la personne. Il veut dire il faut ou devoir, et c'est le verbe qui suit, toujours au subjonctif, qui indique qui doit agir : « bâyad beravam », je dois partir, « bâyad beravid », vous devez partir. Notre exemple, « bâyad charkh râ avaz konim », se décompose en : il faut, la roue, objet, changement, que nous fassions ; avec les verbes composés comme « avaz kardan », changer, le préfixe « be- » disparaît le plus souvent. Pour l'interdiction, on ajoute « na- » : « nabâyad », il ne faut pas. Et pour un regret, on le fait suivre de l'imparfait : « nabâyad dir râh mioftâdim », nous n'aurions pas dû partir tard. Astuce : « bâyad » se pose en tête comme un panneau, et le reste de la phrase suit dans l'ordre habituel.","exampleRo":"Bâyad charkh râ avaz konim.","lit":"il faut · roue · [objet] · changement · fassions","say":{"Bâyad":"باید","bâyad beravam":"باید بروم","bâyad beravid":"باید بروید","bâyad charkh râ avaz konim":"باید چرخ را عوض کنیم","avaz kardan":"عوض کردن","nabâyad":"نباید","nabâyad dir râh mioftâdim":"نباید دیر راه می‌افتادیم","bâyad":"باید"}}},{"title":"Le jardin de Dowlat Abad","phrases":[{"fr":"Ce jardin possède la plus haute tour du vent d'Iran.","tgt":"این باغ بلندترین بادگیر ایران را دارد.","ro":"In bâgh bolandtarin bâdgir-e Irân râ dârad."},{"fr":"Elle mesure plus de trente mètres.","tgt":"بیش از سی متر ارتفاع دارد.","ro":"Bish az si metr ertefâ' dârad."},{"fr":"L'eau coule le long d'une grande allée.","tgt":"آب در طول یک خیابان بلند جاری است.","ro":"Âb dar tul-e yek khiyâbân-e boland jâri ast."},{"fr":"Les cyprès sont alignés des deux côtés.","tgt":"درخت‌های سرو در دو طرف ردیف شده‌اند.","ro":"Derakhthâ-ye sarv dar do taraf radif shode-and."},{"fr":"Asseyons-nous un moment sous les grenadiers.","tgt":"بیایید کمی زیر درخت‌های انار بنشینیم.","ro":"Biyâyid kami zir-e derakhthâ-ye anâr beneshinim."},{"fr":"Il fait étonnamment frais sous la tour.","tgt":"زیر بادگیر هوا به طرز عجیبی خنک است.","ro":"Zir-e bâdgir havâ be tarz-e ajibi khonak ast."},{"fr":"Le billet d'entrée coûte combien ?","tgt":"بلیت ورودی چند است؟","ro":"Belit-e vorudi chand ast?"},{"fr":"Les étudiants ont droit à une réduction.","tgt":"دانشجوها تخفیف دارند.","ro":"Dâneshjuhâ takhfif dârand."},{"fr":"Ce jardin est inscrit au patrimoine mondial.","tgt":"این باغ ثبت جهانی شده است.","ro":"In bâgh sabt-e jahâni shode ast."},{"fr":"C'est l'endroit idéal pour une photo de famille.","tgt":"اینجا بهترین جا برای عکس خانوادگی است.","ro":"Injâ behtarin jâ barâye aks-e khânevâdegi ast."}]},{"title":"La route vers Persépolis","phrases":[{"fr":"Nous quittons Yazd tôt ce matin.","tgt":"امروز صبح زود از یزد راه می‌افتیم.","ro":"Emruz sobh zud az Yazd râh mioftim."},{"fr":"Le trajet jusqu'à Persépolis dure environ six heures.","tgt":"سفر تا تخت جمشید حدود شش ساعت طول می‌کشد.","ro":"Safar tâ Takht-e Jamshid hodud-e shesh sâ'at tul mikeshad."},{"fr":"En chemin, on s'arrête à Abarkouh.","tgt":"سر راه در ابرکوه توقف می‌کنیم.","ro":"Sar-e râh dar Abarkuh tavaghof mikonim."},{"fr":"Il y a là un cyprès vieux de quatre mille ans.","tgt":"آنجا یک سرو چهار هزار ساله هست.","ro":"Ânjâ yek sarv-e chahâr hezâr sâle hast."},{"fr":"C'est l'un des plus vieux arbres du monde.","tgt":"یکی از پیرترین درخت‌های دنیاست.","ro":"Yeki az pirtarin derakhthâ-ye donyâst."},{"fr":"Vers le sud, le paysage devient plus vert.","tgt":"به سمت جنوب، منظره سرسبزتر می‌شود.","ro":"Be samt-e jonub, manzare sarsabztar mishavad."},{"fr":"Arrêtons-nous au bord de la route pour boire un thé.","tgt":"بیایید کنار جاده توقف کنیم و چای بخوریم.","ro":"Biyâyid kenâr-e jâdde tavaghof konim va chây bekhorim."},{"fr":"Le chauffeur connaît un bon restaurant de kebabs.","tgt":"راننده یک کبابی خوب می‌شناسد.","ro":"Rânande yek kabâbi-ye khub mishenâsad."},{"fr":"Combien de kilomètres reste-t-il ?","tgt":"چند کیلومتر دیگر مانده است؟","ro":"Chand kilometr digar mânde ast?"},{"fr":"Nous arriverons à Chiraz pour le dîner.","tgt":"برای شام به شیراز می‌رسیم.","ro":"Barâye shâm be Shirâz miresim."}]},{"title":"Visiter Persépolis","phrases":[{"fr":"Persépolis a plus de deux mille cinq cents ans.","tgt":"تخت جمشید بیش از دو هزار و پانصد سال قدمت دارد.","ro":"Takht-e Jamshid bish az do hezâr o pânsad sâl ghedmat dârad."},{"fr":"Mieux vaut arriver tôt, avant la chaleur.","tgt":"بهتر است زود برسیم، قبل از گرما.","ro":"Behtar ast zud beresim, ghabl az garmâ."},{"fr":"Ces escaliers sont immenses.","tgt":"این پله‌ها خیلی عظیم هستند.","ro":"In pellehâ kheyli azim hastand."},{"fr":"Les bas-reliefs montrent des peuples qui apportent des cadeaux.","tgt":"نقش‌برجسته‌ها مردمانی را نشان می‌دهند که هدیه می‌آورند.","ro":"Naghshbarjastehâ mardomâni râ neshân midahand ke hediye miâvarand."},{"fr":"Les détails sont encore très bien conservés.","tgt":"جزئیات هنوز خیلی سالم مانده‌اند.","ro":"Joz'iyât hanuz kheyli sâlem mânde-and."},{"fr":"Ce palais a été construit par Darius.","tgt":"این کاخ را داریوش ساخت.","ro":"In kâkh râ Dâriush sâkht."},{"fr":"Pourriez-vous nous prendre en photo devant cette colonne ?","tgt":"می‌شود جلوی این ستون از ما عکس بگیرید؟","ro":"Mishavad jelo-ye in sotun az mâ aks begirid?"},{"fr":"Je n'imaginais pas que c'était si grand.","tgt":"فکر نمی‌کردم این‌قدر بزرگ باشد.","ro":"Fekr nemikardam inghadr bozorg bâshad."},{"fr":"Avez-vous un audioguide en français ?","tgt":"راهنمای صوتی به زبان فرانسوی دارید؟","ro":"Râhnamâ-ye sowti be zabân-e farânsavi dârid?"},{"fr":"Ici, on sent vraiment le poids de l'histoire.","tgt":"اینجا واقعا سنگینی تاریخ را حس می‌کنیم.","ro":"Injâ vâghe'an sangini-ye târikh râ hes mikonim."}]},{"title":"Un problème de réservation","phrases":[{"fr":"Bien que nous ayons réservé, la chambre n'est pas prête.","tgt":"با اینکه رزرو کرده‌ایم، ولی اتاق آماده نیست.","ro":"Bâ inke rezerv karde-im, vali otâgh âmâde nist."},{"fr":"Excusez-nous, il y a eu une erreur dans le système.","tgt":"ببخشید، در سیستم اشتباهی پیش آمده است.","ro":"Bebakhshid, dar sistem eshtebâhi pish âmade ast."},{"fr":"Bien qu'il soit tard, nous allons vous trouver une solution.","tgt":"با اینکه دیر است، ولی برایتان راه‌حلی پیدا می‌کنیم.","ro":"Bâ inke dir ast, vali barâyetân râhhali peydâ mikonim."},{"fr":"Bien que l'hôtel soit complet, il reste une suite.","tgt":"با اینکه هتل پر است، ولی یک سوئیت خالی مانده است.","ro":"Bâ inke hotel por ast, vali yek su'it khâli mânde ast."},{"fr":"Elle est plus chère, mais pour vous c'est le même prix.","tgt":"گران‌تر است، ولی برای شما همان قیمت است.","ro":"Gerântar ast, vali barâye shomâ hamân gheymat ast."},{"fr":"Vous êtes vraiment très aimable.","tgt":"خیلی لطف دارید.","ro":"Kheyli lotf dârid."},{"fr":"Bien que je sois fatigué, j'ai envie de me promener.","tgt":"با اینکه خسته‌ام، ولی دلم می‌خواهد قدم بزنم.","ro":"Bâ inke khaste-am, vali delam mikhâhad ghadam bezanam."},{"fr":"Bien que la chambre soit petite, elle est très propre.","tgt":"با اینکه اتاق کوچک است، ولی خیلی تمیز است.","ro":"Bâ inke otâgh kuchek ast, vali kheyli tamiz ast."},{"fr":"Le petit-déjeuner est servi de sept à dix heures.","tgt":"صبحانه از ساعت هفت تا ده سرو می‌شود.","ro":"Sobhâne az sâ'at-e haft tâ dah serv mishavad."},{"fr":"Finalement, tout s'est bien terminé.","tgt":"در نهایت همه چیز به خوبی تمام شد.","ro":"Dar nahâyat hame chiz be khubi tamâm shod."}],"tip":{"title":"« Bâ inke... vali... » : bien que, mais","example":"Bien que la chambre soit petite, elle est très propre. — <b>با اینکه</b> اتاق کوچک است، <b>ولی</b> خیلی تمیز است.","body":"Pour dire bien que, le persan utilise « bâ inke », mot à mot avec ceci que. Particularité amusante : là où le français s'arrête à bien que, le persan aime ajouter « vali », mais, au début de la deuxième partie, comme si l'on disait bien que la chambre est petite, mais elle est propre. Notre exemple se décompose ainsi : « bâ inke », bien que, « otâgh kuchek ast », la chambre est petite, puis « vali kheyli tamiz ast », mais elle est très propre. Bonne nouvelle, pas de subjonctif ici : on garde le verbe normal, comme dans « bâ inke khaste-am », bien que je sois fatigué, mot à mot bien que fatigué je suis. Le « vali » n'est pas obligatoire, mais il rend la phrase très naturelle à l'oral. Astuce : imaginez une balance, « bâ inke » pose un poids d'un côté et « vali » la fait pencher de l'autre.","exampleRo":"Bâ inke otâgh kuchek ast, vali kheyli tamiz ast.","lit":"[bien que] · chambre · petite · est · [mais] · très · propre · est","say":{"Bâ inke... vali...":"با اینکه... ولی...","bâ inke":"با اینکه","vali":"ولی","otâgh kuchek ast":"اتاق کوچک است","vali kheyli tamiz ast":"ولی خیلی تمیز است","bâ inke khaste-am":"با اینکه خسته‌ام"}}},{"title":"Préparer le retour","phrases":[{"fr":"Demain, nous rentrons à Téhéran.","tgt":"فردا به تهران برمی‌گردیم.","ro":"Fardâ be Tehrân barmigardim."},{"fr":"La valise est beaucoup plus lourde qu'à l'aller.","tgt":"چمدان خیلی سنگین‌تر از موقع رفتن است.","ro":"Chamedân kheyli sangintar az mowghe'-e raftan ast."},{"fr":"J'ai acheté beaucoup de souvenirs à Yazd.","tgt":"در یزد خیلی سوغاتی خریدم.","ro":"Dar Yazd kheyli sowghâti kharidam."},{"fr":"Où est-ce que je mets la nappe en termeh ?","tgt":"رومیزی ترمه را کجا بگذارم؟","ro":"Rumizi-ye terme râ kojâ begozâram?"},{"fr":"Mettez-la au fond de la valise.","tgt":"آن را ته چمدان بگذارید.","ro":"Ân râ tah-e chamedân begozârid."},{"fr":"On met les boîtes de pâtisseries dans le sac à dos.","tgt":"جعبه‌های شیرینی را در کوله‌پشتی می‌گذاریم.","ro":"Ja'behâ-ye shirini râ dar kulehposhti migozârim."},{"fr":"N'oubliez pas vos lunettes de soleil.","tgt":"عینک آفتابی‌تان را فراموش نکنید.","ro":"Eynak-e âftâbitân râ farâmush nakonid."},{"fr":"Avez-vous vérifié l'heure du bus ?","tgt":"ساعت اتوبوس را چک کردید؟","ro":"Sâ'at-e otobus râ chek kardid?"},{"fr":"Oui, il part demain à neuf heures du matin.","tgt":"بله، فردا ساعت نه صبح حرکت می‌کند.","ro":"Bale, fardâ sâ'at-e noh-e sobh harekat mikonad."},{"fr":"Je suis un peu triste de quitter le sud.","tgt":"کمی ناراحتم که از جنوب می‌روم.","ro":"Kami nârâhatam ke az jonub miravam."}]},{"title":"Un bus annulé","phrases":[{"fr":"Notre bus pour Téhéran a été annulé.","tgt":"اتوبوس ما به تهران لغو شده است.","ro":"Otobus-e mâ be Tehrân laghv shode ast."},{"fr":"Y a-t-il un autre bus aujourd'hui ?","tgt":"امروز اتوبوس دیگری هست؟","ro":"Emruz otobus-e digari hast?"},{"fr":"Non, tous les bus sont complets jusqu'à demain.","tgt":"نه، همه‌ی اتوبوس‌ها تا فردا پر هستند.","ro":"Na, hame-ye otobushâ tâ fardâ por hastand."},{"fr":"Puis-je me faire rembourser mon billet ?","tgt":"می‌توانم پول بلیتم را پس بگیرم؟","ro":"Mitavânam pul-e belitam râ pas begiram?"},{"fr":"Oui, on vous rembourse à la gare routière.","tgt":"بله، پولتان را در ترمینال پس می‌دهند.","ro":"Bale, puletân râ dar terminâl pas midahand."},{"fr":"Alors, prenons le train de nuit.","tgt":"پس با قطار شب برویم.","ro":"Pas bâ ghatâr-e shab beravim."},{"fr":"Il reste deux couchettes dans un compartiment de quatre.","tgt":"در یک کوپه‌ی چهارنفره دو تخت خالی مانده است.","ro":"Dar yek kupe-ye chahârnafare do takht khâli mânde ast."},{"fr":"Le train est plus confortable, mais plus lent.","tgt":"قطار راحت‌تر است، ولی کندتر.","ro":"Ghatâr râhattar ast, vali kondtar."},{"fr":"À quelle heure arriverons-nous à Téhéran ?","tgt":"ساعت چند به تهران می‌رسیم؟","ro":"Sâ'at-e chand be Tehrân miresim?"},{"fr":"Je vais dire à nos amis que nous serons en retard.","tgt":"به دوستانمان خبر می‌دهم که دیر می‌رسیم.","ro":"Be dustânemân khabar midaham ke dir miresim."}]},{"title":"Raconter le voyage","phrases":[{"fr":"Allô, c'est moi ! Je vous appelle du train de nuit.","tgt":"الو، منم! از قطار شب به شما زنگ می‌زنم.","ro":"Alo, manam! Az ghatâr-e shab be shomâ zang mizanam."},{"fr":"Le voyage s'est très bien passé.","tgt":"سفر خیلی خوب گذشت.","ro":"Safar kheyli khub gozasht."},{"fr":"Nous avons passé une nuit dans le désert.","tgt":"یک شب را در کویر گذراندیم.","ro":"Yek shab râ dar kavir gozarândim."},{"fr":"Il faisait froid, mais le ciel était magnifique.","tgt":"هوا سرد بود، ولی آسمان فوق‌العاده بود.","ro":"Havâ sard bud, vali âsemân fogholâde bud."},{"fr":"Nous avons aussi crevé un pneu en chemin.","tgt":"سر راه ماشینمان پنچر هم شد.","ro":"Sar-e râh mâshinemân panchar ham shod."},{"fr":"Heureusement, un camionneur nous a aidés.","tgt":"خوشبختانه یک راننده‌ی کامیون به ما کمک کرد.","ro":"Khoshbakhtâne yek rânande-ye kâmiyon be mâ komak kard."},{"fr":"Les gens ont été très accueillants partout.","tgt":"مردم همه جا خیلی مهمان‌نواز بودند.","ro":"Mardom hame jâ kheyli mehmânnavâz budand."},{"fr":"À Yazd, j'ai mangé des pâtisseries délicieuses.","tgt":"در یزد شیرینی‌های خوشمزه‌ای خوردم.","ro":"Dar Yazd shirinihâ-ye khoshmaze-i khordam."},{"fr":"Je vous montrerai les photos à mon retour.","tgt":"وقتی برگشتم، عکس‌ها را به شما نشان خواهم داد.","ro":"Vaghti bargashtam, akshâ râ be shomâ neshân khâham dâd."},{"fr":"Vous me manquez un peu, quand même.","tgt":"با این حال، کمی دلم برایتان تنگ شده است.","ro":"Bâ in hâl, kami delam barâyetân tang shode ast."}]},{"title":"Fin du module : un bilan de voyage","phrases":[{"fr":"Ce module nous a emmenés de Yazd jusqu'à Persépolis.","tgt":"این بخش ما را از یزد تا تخت جمشید برد.","ro":"In bakhsh mâ râ az Yazd tâ Takht-e Jamshid bord."},{"fr":"Maintenant, je sais parler du futur en persan.","tgt":"حالا می‌توانم به فارسی درباره‌ی آینده صحبت کنم.","ro":"Hâlâ mitavânam be fârsi darbâre-ye âyande sohbat konam."},{"fr":"Je sais raconter comment on vivait autrefois.","tgt":"بلدم تعریف کنم که مردم قدیم چطور زندگی می‌کردند.","ro":"Baladam ta'rif konam ke mardom-e ghadim chetor zendegi mikardand."},{"fr":"Je sais dire ce qu'il faut faire en cas de problème.","tgt":"بلدم بگویم که موقع مشکل چه کار باید کرد.","ro":"Baladam beguyam ke mowghe'-e moshkel che kâr bâyad kard."},{"fr":"Les imprévus du voyage ne me font plus peur.","tgt":"دیگر از اتفاق‌های غیرمنتظره‌ی سفر نمی‌ترسم.","ro":"Digar az ettefâghhâ-ye gheyremontazere-ye safar nemitarsam."},{"fr":"Je fais des phrases plus longues qu'avant.","tgt":"جمله‌های بلندتری از قبل می‌سازم.","ro":"Jomlehâ-ye bolandtari az ghabl misâzam."},{"fr":"Le persan me paraît peu à peu plus naturel.","tgt":"فارسی کم‌کم برایم طبیعی‌تر می‌شود.","ro":"Fârsi kamkam barâyam tabi'itar mishavad."},{"fr":"Le désert de Yazd restera dans ma mémoire.","tgt":"کویر یزد در خاطرم خواهد ماند.","ro":"Kavir-e Yazd dar khâteram khâhad mând."},{"fr":"Félicitations, vous avez fait un beau voyage en persan.","tgt":"تبریک می‌گویم، سفر زیبایی به زبان فارسی داشتید.","ro":"Tabrik miguyam, safar-e zibâyi be zabân-e fârsi dâshtid."},{"fr":"Rendez-vous au prochain module pour parler entre amis.","tgt":"در بخش بعدی برای گفتگو با دوستان می‌بینمتان.","ro":"Dar bakhsh-e ba'di barâye goftogu bâ dustân mibinametân."}]}]},{"id":3,"name":"Conversation sociale","desc":"Des échanges sociaux plus nuancés et plus naturels.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Retrouver ses amis à Kashan","phrases":[{"fr":"Salut Nima, ça fait longtemps qu'on ne s'est pas vus !","tgt":"سلام نیما، خیلی وقته همدیگه رو ندیدیم!","ro":"Salâm Nimâ, kheyli vaghte hamdige ro nadidim!"},{"fr":"Je suis arrivé à Kashan hier soir en bus.","tgt":"دیشب با اتوبوس رسیدم کاشان.","ro":"Dishab bâ otobus residam Kâshân."},{"fr":"Tu as l'air en pleine forme, quoi de neuf ?","tgt":"خیلی سرحالی، چه خبرا؟","ro":"Kheyli sarhâli, che khabarâ?"},{"fr":"Rien de spécial, je travaille toujours à la pharmacie.","tgt":"خبر خاصی نیست، هنوز تو داروخونه کار می‌کنم.","ro":"Khabar-e khâssi nist, hanuz tu dârukhune kâr mikonam."},{"fr":"Assieds-toi, je te sers un thé.","tgt":"بشین، برات چای می‌ریزم.","ro":"Beshin, barât chây mirizam."},{"fr":"Comment va ta famille à Téhéran ?","tgt":"خونواده‌ت تو تهران چطورن؟","ro":"Khunevâdat tu Tehrân chetoran?"},{"fr":"Tout le monde va bien, ils te passent le bonjour.","tgt":"همه خوبن، بهت سلام رسوندن.","ro":"Hame khuban, behet salâm resundan."},{"fr":"Tu restes combien de jours ici ?","tgt":"چند روز اینجا می‌مونی؟","ro":"Chand ruz injâ mimuni?"},{"fr":"Je reste une semaine, jusqu'à vendredi prochain.","tgt":"یه هفته می‌مونم، تا جمعه‌ی بعد.","ro":"Ye hafte mimunam, tâ jom'e-ye ba'd."},{"fr":"Super, on aura le temps de sortir ensemble.","tgt":"عالیه، وقت داریم با هم بریم بیرون.","ro":"Âliye, vaght dârim bâ ham berim birun."}]},{"title":"Des projets pour le week-end","phrases":[{"fr":"Qu'est-ce que tu veux faire ce week-end ?","tgt":"آخر هفته می‌خوای چی کار کنی؟","ro":"Âkhar-e hafte mikhây chi kâr koni?"},{"fr":"Je veux aller au jardin de Fin vendredi matin.","tgt":"می‌خوام جمعه صبح برم باغ فین.","ro":"Mikhâm jom'e sobh beram bâgh-e Fin."},{"fr":"Moi, je vais au bazar samedi avec ma sœur.","tgt":"من شنبه با خواهرم می‌رم بازار.","ro":"Man shanbe bâ khâharam miram bâzâr."},{"fr":"C'est quoi, ton programme pour samedi soir ?","tgt":"برنامه‌ت برای شنبه شب چیه؟","ro":"Barnâmat barâye shanbe shab chie?"},{"fr":"Ce soir, on va dans un café près du bazar.","tgt":"امشب می‌ریم یه کافه نزدیک بازار.","ro":"Emshab mirim ye kâfe nazdik-e bâzâr."},{"fr":"Tu veux venir avec nous ?","tgt":"می‌خوای با ما بیای؟","ro":"Mikhây bâ mâ biyây?"},{"fr":"Oui, pourquoi pas, vous partez à quelle heure ?","tgt":"آره، چرا که نه، ساعت چند می‌رین؟","ro":"Âre, cherâ ke na, sâ'at-e chand mirin?"},{"fr":"C'est quoi, le nom de ce café ?","tgt":"اسم اون کافه چیه؟","ro":"Esm-e un kâfe chie?"},{"fr":"Je ne sais pas, mais Reza veut y aller depuis longtemps.","tgt":"نمی‌دونم، ولی رضا خیلی وقته می‌خواد بره اونجا.","ro":"Nemidunam, vali Rezâ kheyli vaghte mikhâd bere unjâ."},{"fr":"Bon, je rentre à la maison me changer.","tgt":"خب، من می‌رم خونه لباس عوض کنم.","ro":"Khob, man miram khune lebâs avaz konam."}],"tip":{"title":"Le parler de Téhéran entre amis : « mikhâm », « miram », « chie »","example":"Je veux aller au jardin de Fin vendredi matin. — <b>می‌خوام</b> جمعه صبح <b>برم</b> باغ فین.","body":"Entre amis, les Iraniens ne parlent pas comme dans les livres : les mots se raccourcissent et s'adoucissent. « Je veux », qui se dit « mikhâham » dans la langue soignée, devient « mikhâm », et « je vais », « miravam », devient « miram ». De même, « qu'est-ce que c'est » se dit « chie » au lieu de « chist », et le son « ân » devient souvent « un » : « khâne », la maison, se dit « khune ». Décomposons « Mikhâm jom'e sobh beram bâgh-e Fin » : « mikhâm », je veux, « jom'e sobh », vendredi matin, « beram », que j'aille, puis « bâgh-e Fin », le jardin de Fin ; le verbe qui suit « mikhâm » prend la forme en « be- ». Vous entendrez sans cesse « Mikhây biyây ? », tu veux venir, « Miram khune », je rentre à la maison, ou « Esmet chie ? », c'est quoi ton nom. Pour retenir, pensez au français parlé, où l'on dit « chuis » plutôt que « je suis » : les Téhéranais font exactement pareil.","exampleRo":"Mikhâm jom'e sobh beram bâgh-e Fin.","lit":"je veux · vendredi · matin · que j'aille · jardin [de] · Fin","say":{"mikhâm":"می‌خوام","miram":"می‌رم","chie":"چیه","mikhâham":"می‌خواهم","miravam":"می‌روم","chist":"چیست","khâne":"خانه","khune":"خونه","Mikhâm jom'e sobh beram bâgh-e Fin":"می‌خوام جمعه صبح برم باغ فین","jom'e sobh":"جمعه صبح","beram":"برم","bâgh-e Fin":"باغ فین","Mikhây biyây ?":"می‌خوای بیای؟","Miram khune":"می‌رم خونه","Esmet chie ?":"اسمت چیه؟"}}},{"title":"Le jardin de Fin","phrases":[{"fr":"Le jardin de Fin est le plus beau jardin de Kashan.","tgt":"باغ فین قشنگ‌ترین باغ کاشانه.","ro":"Bâgh-e Fin ghashangtarin bâgh-e Kâshâne."},{"fr":"Tu y es déjà allé ?","tgt":"تا حالا رفتی اونجا؟","ro":"Tâ hâlâ rafti unjâ?"},{"fr":"Oui, j'y suis allé il y a deux ans avec mes parents.","tgt":"آره، دو سال پیش با پدر و مادرم رفتم.","ro":"Âre, do sâl pish bâ pedar o mâdaram raftam."},{"fr":"L'eau coule partout dans de petits canaux.","tgt":"آب همه‌جا تو جوی‌های کوچیک جاریه.","ro":"Âb hamejâ tu juyhâ-ye kuchik jâriye."},{"fr":"Le bruit de l'eau est très apaisant.","tgt":"صدای آب خیلی آرامش‌بخشه.","ro":"Sedâ-ye âb kheyli ârâmeshbakhshe."},{"fr":"Les vieux cyprès donnent beaucoup d'ombre.","tgt":"سروهای قدیمی خیلی سایه دارن.","ro":"Sarvhâ-ye ghadimi kheyli sâye dâran."},{"fr":"Allons-y tôt le matin, avant la foule.","tgt":"بیا صبح زود بریم، قبل از شلوغی.","ro":"Biyâ sobh-e zud berim, ghabl az sholughi."},{"fr":"En été, il fait chaud l'après-midi.","tgt":"تابستون بعدازظهرها هوا گرمه.","ro":"Tâbestun ba'dazzohrhâ havâ garme."},{"fr":"On pourra prendre des photos près du bassin.","tgt":"می‌تونیم کنار حوض عکس بگیریم.","ro":"Mitunim kenâr-e howz aks begirim."},{"fr":"Après, on boira un thé dans le salon de thé du jardin.","tgt":"بعدش تو چایخونه‌ی باغ چای می‌خوریم.","ro":"Ba'desh tu châykhune-ye bâgh chây mikhorim."}]},{"title":"La saison de l'eau de rose","phrases":[{"fr":"Au printemps, c'est la saison de l'eau de rose à Kashan.","tgt":"بهار فصل گلاب‌گیری کاشانه.","ro":"Bahâr fasl-e golâbgiri-ye Kâshâne."},{"fr":"Les gens cueillent les roses très tôt le matin.","tgt":"مردم صبح خیلی زود گل‌ها رو می‌چینن.","ro":"Mardom sobh kheyli zud golhâ ro michinan."},{"fr":"Mon oncle a un petit champ de roses à Ghamsar.","tgt":"عموم تو قمصر یه باغ گل کوچیک داره.","ro":"Amum tu Ghamsar ye bâgh-e gol-e kuchik dâre."},{"fr":"À cette période, toute la ville sent la rose.","tgt":"این موقع کل شهر بوی گل می‌ده.","ro":"In moghe' kol-e shahr bu-ye gol mide."},{"fr":"On fait bouillir les pétales dans de grandes marmites.","tgt":"گلبرگ‌ها رو تو دیگ‌های بزرگ می‌جوشونن.","ro":"Golbarghâ ro tu dighâ-ye bozorg mijushunan."},{"fr":"Tu as déjà goûté le thé à l'eau de rose ?","tgt":"تا حالا چای با گلاب خوردی؟","ro":"Tâ hâlâ chây bâ golâb khordi?"},{"fr":"Ma grand-mère en met dans tous ses desserts.","tgt":"مادربزرگم تو همه‌ی دسرهاش گلاب می‌ریزه.","ro":"Mâdarbozorgam tu hame-ye deserhâsh golâb mirize."},{"fr":"L'année dernière, j'ai rapporté trois bouteilles à Paris.","tgt":"پارسال سه تا شیشه گلاب بردم پاریس.","ro":"Pârsâl se tâ shishe golâb bordam Pâris."},{"fr":"Si tu veux, on ira à Ghamsar la semaine prochaine.","tgt":"اگه بخوای، هفته‌ی بعد می‌ریم قمصر.","ro":"Age bekhây, hafte-ye ba'd mirim Ghamsar."},{"fr":"Il faut y aller tôt, parce qu'il y a beaucoup de monde.","tgt":"باید زود بریم، چون خیلی شلوغه.","ro":"Bâyad zud berim, chun kheyli sholughe."}]},{"title":"Des projets incertains","phrases":[{"fr":"Peut-être que je viendrai demain soir.","tgt":"شاید فردا شب بیام.","ro":"Shâyad fardâ shab biyâm."},{"fr":"Peut-être qu'il pleuvra ce week-end.","tgt":"شاید آخر هفته بارون بیاد.","ro":"Shâyad âkhar-e hafte bârun biyâd."},{"fr":"Leyla viendra peut-être avec son frère.","tgt":"شاید لیلا با برادرش بیاد.","ro":"Shâyad Leylâ bâ barâdaresh biyâd."},{"fr":"Je ne sais pas encore, je resterai peut-être à la maison.","tgt":"هنوز نمی‌دونم، شاید خونه بمونم.","ro":"Hanuz nemidunam, shâyad khune bemunam."},{"fr":"On ira peut-être à Abyaneh en voiture.","tgt":"شاید با ماشین بریم ابیانه.","ro":"Shâyad bâ mâshin berim Abyâne."},{"fr":"Tu changeras peut-être d'avis demain.","tgt":"شاید فردا نظرت عوض بشه.","ro":"Shâyad fardâ nazaret avaz beshe."},{"fr":"Peut-être qu'elle n'a pas reçu mon message.","tgt":"شاید پیامم بهش نرسیده.","ro":"Shâyad payâmam behesh naraside."},{"fr":"Je t'appelle ce soir, on se verra peut-être.","tgt":"امشب بهت زنگ می‌زنم، شاید همدیگه رو ببینیم.","ro":"Emshab behet zang mizanam, shâyad hamdige ro bebinim."},{"fr":"Peut-être, mais je ne te promets rien.","tgt":"شاید، ولی قول نمی‌دم.","ro":"Shâyad, vali ghol nemidam."},{"fr":"Préviens-moi si tu es libre.","tgt":"اگه وقت داشتی خبرم کن.","ro":"Age vaght dâshti khabaram kon."}],"tip":{"title":"« Shâyad » : peut-être, avec le subjonctif","example":"Peut-être qu'il pleuvra ce week-end. — <b>شاید</b> آخر هفته بارون <b>بیاد</b>.","body":"« Shâyad » veut dire peut-être, et il entraîne presque toujours le subjonctif, une forme du verbe qui commence par « be- » ou « bi- ». Là où le français dit « il pleuvra peut-être », le persan dit en quelque sorte « peut-être que la pluie vienne » : « Shâyad bârun biyâd ». Décomposons : « shâyad », peut-être, « âkhar-e hafte », la fin de la semaine, « bârun », la pluie, et « biyâd », qu'elle vienne. Avec « je », on obtient « Shâyad biyâm », je viendrai peut-être, ou « Shâyad khune bemunam », je resterai peut-être à la maison. Pour retenir, dites-vous que le doute appelle le « be- » : dès que vous prononcez « shâyad », préparez ce petit son au début du verbe.","exampleRo":"Shâyad âkhar-e hafte bârun biyâd.","lit":"peut-être · fin [de] · semaine · pluie · qu'elle vienne","say":{"Shâyad":"شاید","Shâyad bârun biyâd":"شاید بارون بیاد","shâyad":"شاید","âkhar-e hafte":"آخر هفته","bârun":"بارون","biyâd":"بیاد","Shâyad biyâm":"شاید بیام","Shâyad khune bemunam":"شاید خونه بمونم","bi-":"بی"}}},{"title":"Au café dans une vieille maison","phrases":[{"fr":"Ce café se trouve dans une maison historique.","tgt":"این کافه تو یه خونه‌ی تاریخیه.","ro":"In kâfe tu ye khune-ye târikhiye."},{"fr":"Regarde ces vitraux de couleur, c'est magnifique !","tgt":"این شیشه‌های رنگی رو ببین، محشره!","ro":"In shishehâ-ye rangi ro bebin, mahshare!"},{"fr":"Qu'est-ce que tu prends, un thé ou un café ?","tgt":"چی می‌خوری، چای یا قهوه؟","ro":"Chi mikhori, chây yâ ghahve?"},{"fr":"Je vais prendre un café et une part de gâteau.","tgt":"من یه قهوه با یه تیکه کیک می‌خورم.","ro":"Man ye ghahve bâ ye tike keyk mikhoram."},{"fr":"Leurs gâteaux à l'eau de rose sont célèbres.","tgt":"کیک‌های گلابیشون معروفه.","ro":"Keykhâ-ye golâbishun ma'rufe."},{"fr":"On va s'asseoir dans la cour, près du bassin ?","tgt":"بریم تو حیاط بشینیم، کنار حوض؟","ro":"Berim tu hayât beshinim, kenâr-e howz?"},{"fr":"Le soir, il y a une belle ambiance ici.","tgt":"شب‌ها اینجا حال و هوای خوبی داره.","ro":"Shabhâ injâ hâl o havâ-ye khubi dâre."},{"fr":"Le serveur est très gentil et il sourit toujours.","tgt":"گارسونش خیلی مهربونه و همیشه می‌خنده.","ro":"Gârsunesh kheyli mehrabune va hamishe mikhande."},{"fr":"Aujourd'hui, c'est moi qui t'invite.","tgt":"امروز مهمون منی.","ro":"Emruz mehmun-e mani."},{"fr":"Merci, la prochaine fois, c'est pour moi.","tgt":"مرسی، دفعه‌ی بعد با من.","ro":"Mersi, daf'e-ye ba'd bâ man."}]},{"title":"Parler de cinéma","phrases":[{"fr":"Tu as vu un bon film ces derniers temps ?","tgt":"این اواخر فیلم خوبی دیدی؟","ro":"In avâkher film-e khubi didi?"},{"fr":"Oui, la semaine dernière, j'ai vu un film iranien au cinéma.","tgt":"آره، هفته‌ی پیش یه فیلم ایرانی تو سینما دیدم.","ro":"Âre, hafte-ye pish ye film-e irâni tu sinemâ didam."},{"fr":"Ça parle de quoi, l'histoire ?","tgt":"داستانش درباره‌ی چیه؟","ro":"Dâstânesh darbâre-ye chie?"},{"fr":"C'est l'histoire d'une famille qui s'installe à Kashan.","tgt":"درباره‌ی یه خونواده‌ست که به کاشان اسباب‌کشی می‌کنه.","ro":"Darbâre-ye ye khunevâdast ke be Kâshân asbâbkeshi mikone."},{"fr":"Les acteurs de ce film jouent remarquablement bien.","tgt":"بازیگرهای این فیلم فوق‌العاده بازی می‌کنن.","ro":"Bâzigarhâ-ye in film fogholâde bâzi mikonan."},{"fr":"La fin de l'histoire m'a fait pleurer.","tgt":"آخر داستان گریه‌م گرفت.","ro":"Âkhar-e dâstân geryam gereft."},{"fr":"Moi, je préfère les comédies.","tgt":"من فیلم‌های کمدی رو بیشتر دوست دارم.","ro":"Man filmhâ-ye komedi ro bishtar dust dâram."},{"fr":"Le cinéma iranien est très connu en France.","tgt":"سینمای ایران تو فرانسه خیلی معروفه.","ro":"Sinemâ-ye Irân tu Farânse kheyli ma'rufe."},{"fr":"On va voir un film ensemble jeudi soir ?","tgt":"پنجشنبه شب بریم با هم فیلم ببینیم؟","ro":"Panjshanbe shab berim bâ ham film bebinim?"},{"fr":"D'accord, je réserve les places sur mon téléphone.","tgt":"باشه، بلیت‌ها رو با گوشیم رزرو می‌کنم.","ro":"Bâshe, belithâ ro bâ gushim rezerv mikonam."}]},{"title":"Parler de musique","phrases":[{"fr":"Tu écoutes quel genre de musique, en général ?","tgt":"بیشتر چه جور موسیقی‌ای گوش می‌دی؟","ro":"Bishtar che jur musighi-i gush midi?"},{"fr":"J'adore la musique traditionnelle persane.","tgt":"عاشق موسیقی سنتی ایرانی‌ام.","ro":"Âshegh-e musighi-ye sonnati-ye irâni-am."},{"fr":"Mon père joue du setar depuis trente ans.","tgt":"پدرم سی ساله سه‌تار می‌زنه.","ro":"Pedaram si sâle setâr mizane."},{"fr":"Le son du setar me rend nostalgique.","tgt":"صدای سه‌تار منو دلتنگ می‌کنه.","ro":"Sedâ-ye setâr mano deltang mikone."},{"fr":"Ma sœur préfère la pop, et elle chante très bien.","tgt":"خواهرم پاپ رو بیشتر دوست داره و خیلی خوب می‌خونه.","ro":"Khâharam pâp ro bishtar dust dâre va kheyli khub mikhune."},{"fr":"Tu sais jouer d'un instrument ?","tgt":"تو سازی بلدی بزنی؟","ro":"To sâzi baladi bezani?"},{"fr":"Quand j'étais petit, j'allais à des cours de piano.","tgt":"بچه که بودم کلاس پیانو می‌رفتم.","ro":"Bachche ke budam kelâs-e piyâno miraftam."},{"fr":"Vendredi soir, il y a un concert dans le jardin.","tgt":"جمعه شب تو باغ کنسرت هست.","ro":"Jom'e shab tu bâgh konsert hast."},{"fr":"Les billets coûtent deux cent mille tomans.","tgt":"بلیت‌هاش دویست هزار تومنه.","ro":"Belithâsh devist hezâr tomane."},{"fr":"Ça vaut le coup, achetons-en deux.","tgt":"می‌ارزه، بیا دو تا بخریم.","ro":"Miarze, biyâ do tâ bekharim."}]},{"title":"Les goûts de chacun","phrases":[{"fr":"Pendant ton temps libre, tu aimes faire quoi ?","tgt":"تو وقت آزادت دوست داری چی کار کنی؟","ro":"Tu vaght-e âzâdet dust dâri chi kâr koni?"},{"fr":"J'aime me promener dans les vieilles ruelles de la ville.","tgt":"دوست دارم تو کوچه‌های قدیمی شهر قدم بزنم.","ro":"Dust dâram tu kuchehâ-ye ghadimi-ye shahr ghadam bezanam."},{"fr":"Arash adore cuisiner pour ses amis.","tgt":"آرش عاشق آشپزی برای دوستاشه.","ro":"Ârash âshegh-e âshpazi barâye dustâshe."},{"fr":"Moi, je n'aime pas trop les endroits bruyants.","tgt":"من جاهای شلوغ رو زیاد دوست ندارم.","ro":"Man jâhâ-ye sholugh ro ziyâd dust nadâram."},{"fr":"Le week-end, je déteste me lever tôt.","tgt":"آخر هفته از زود بیدار شدن بدم میاد.","ro":"Âkhar-e hafte az zud bidâr shodan badam miyâd."},{"fr":"Tu préfères la montagne ou le désert ?","tgt":"کوه رو بیشتر دوست داری یا کویر رو؟","ro":"Kuh ro bishtar dust dâri yâ kavir ro?"},{"fr":"Le désert, surtout les nuits sous les étoiles.","tgt":"کویر، به‌خصوص شب‌ها زیر ستاره‌ها.","ro":"Kavir, bekhosus shabhâ zir-e setârehâ."},{"fr":"Toi et moi, on a les mêmes goûts.","tgt":"من و تو سلیقه‌مون یکیه.","ro":"Man o to salighemun yekiye."},{"fr":"Mon frère, lui, ne pense qu'au football.","tgt":"برادرم فقط به فوتبال فکر می‌کنه.","ro":"Barâdaram faghat be futbâl fekr mikone."},{"fr":"Chacun ses goûts, comme on dit.","tgt":"به قول معروف، هر کسی یه سلیقه‌ای داره.","ro":"Be ghol-e ma'ruf, har kasi ye salighe-i dâre."}]},{"title":"Donner des conseils à un ami","phrases":[{"fr":"Tu as l'air fatigué ces jours-ci.","tgt":"این چند روز خسته به نظر میای.","ro":"In chand ruz khaste be nazar miyây."},{"fr":"Oui, je dors mal à cause du travail.","tgt":"آره، به خاطر کار بد می‌خوابم.","ro":"Âre, be khâter-e kâr bad mikhâbam."},{"fr":"Tu devrais te reposer quelques jours, crois-moi.","tgt":"باور کن، باید چند روز استراحت کنی.","ro":"Bâvar kon, bâyad chand ruz esterâhat koni."},{"fr":"Si j'étais toi, j'en parlerais à mon chef.","tgt":"اگه جای تو بودم، با رئیسم حرف می‌زدم.","ro":"Age jâ-ye to budam, bâ ra'isam harf mizadam."},{"fr":"Ne bois pas trop de café le soir.","tgt":"شب‌ها زیاد قهوه نخور.","ro":"Shabhâ ziyâd ghahve nakhor."},{"fr":"Va marcher un peu dans le jardin après le dîner.","tgt":"بعد از شام یه کم تو باغ قدم بزن.","ro":"Ba'd az shâm ye kam tu bâgh ghadam bezan."},{"fr":"C'est un bon conseil, merci beaucoup.","tgt":"نصیحت خوبیه، خیلی ممنون.","ro":"Nasihat-e khubiye, kheyli mamnun."},{"fr":"Ne t'inquiète pas, tout va s'arranger.","tgt":"نگران نباش، همه‌چی درست می‌شه.","ro":"Negarân nabâsh, hamechi dorost mishe."},{"fr":"Appelle-moi si tu as besoin de parler.","tgt":"اگه خواستی حرف بزنی، بهم زنگ بزن.","ro":"Age khâsti harf bezani, behem zang bezan."},{"fr":"Tu sais, tu es un vrai ami.","tgt":"می‌دونی، تو یه دوست واقعی هستی.","ro":"Miduni, to ye dust-e vâghe'i hasti."}]},{"title":"Une mauvaise journée","phrases":[{"fr":"Quelle mauvaise journée j'ai eue aujourd'hui !","tgt":"امروز چه روز بدی داشتم!","ro":"Emruz che ruz-e badi dâshtam!"},{"fr":"Raconte, qu'est-ce qui s'est passé ?","tgt":"تعریف کن، چی شده؟","ro":"Ta'rif kon, chi shode?"},{"fr":"J'ai raté le bus et je suis arrivé en retard au travail.","tgt":"اتوبوس رو از دست دادم و دیر رسیدم سر کار.","ro":"Otobus ro az dast dâdam va dir residam sar-e kâr."},{"fr":"Ensuite, j'ai perdu mes clés au bazar.","tgt":"بعدش کلیدهام رو تو بازار گم کردم.","ro":"Ba'desh kelidhâm ro tu bâzâr gom kardam."},{"fr":"Oh non, tu les as retrouvées ?","tgt":"ای وای، پیداشون کردی؟","ro":"Ey vây, peydâshun kardi?"},{"fr":"Oui, un marchand de tapis les avait gardées pour moi.","tgt":"آره، یه فرش‌فروش برام نگهشون داشته بود.","ro":"Âre, ye farshforush barâm negahshun dâshte bud."},{"fr":"Les gens de Kashan sont vraiment gentils.","tgt":"مردم کاشان خیلی مهربونن.","ro":"Mardom-e Kâshân kheyli mehrabunan."},{"fr":"Viens, on va manger quelque chose pour te changer les idées.","tgt":"بیا بریم یه چیزی بخوریم که حالت عوض بشه.","ro":"Biyâ berim ye chizi bekhorim ke hâlet avaz beshe."},{"fr":"Bonne idée, j'ai très faim.","tgt":"فکر خوبیه، خیلی گشنمه.","ro":"Fekr-e khubiye, kheyli goshname."},{"fr":"Tu verras, demain ira beaucoup mieux.","tgt":"می‌بینی، فردا خیلی بهتر می‌شه.","ro":"Mibini, fardâ kheyli behtar mishe."}]},{"title":"Les nouvelles des amis","phrases":[{"fr":"J'ai entendu dire que Sara s'était mariée.","tgt":"شنیدم که سارا ازدواج کرده.","ro":"Shenidam ke Sârâ ezdevâj karde."},{"fr":"Oui, c'était une très belle fête dans un jardin.","tgt":"آره، یه جشن خیلی قشنگ تو یه باغ بود.","ro":"Âre, ye jashn-e kheyli ghashang tu ye bâgh bud."},{"fr":"J'ai entendu dire que Babak avait trouvé un nouveau travail.","tgt":"شنیدم که بابک یه کار جدید پیدا کرده.","ro":"Shenidam ke Bâbak ye kâr-e jadid peydâ karde."},{"fr":"Maintenant, il travaille à Ispahan, dans une agence de voyages.","tgt":"الان تو اصفهان، تو یه آژانس مسافرتی کار می‌کنه.","ro":"Alân tu Esfahân, tu ye âzhâns-e mosâferati kâr mikone."},{"fr":"Tu as entendu dire que Maryam avait eu un bébé ?","tgt":"شنیدی که مریم بچه‌دار شده؟","ro":"Shenidi ke Maryam bachchedâr shode?"},{"fr":"Non, je ne savais pas, quelle bonne nouvelle !","tgt":"نه، نمی‌دونستم، چه خبر خوبی!","ro":"Na, nemidunestam, che khabar-e khubi!"},{"fr":"On m'a dit que Nima allait partir en France pour ses études.","tgt":"شنیدم که نیما قراره برای درس بره فرانسه.","ro":"Shenidam ke Nimâ gharâre barâye dars bere Farânse."},{"fr":"Il paraît que le vieux café du bazar a fermé.","tgt":"شنیدم که کافه‌ی قدیمی بازار بسته شده.","ro":"Shenidam ke kâfe-ye ghadimi-ye bâzâr baste shode."},{"fr":"Dommage, on y allait souvent ensemble.","tgt":"حیف شد، خیلی با هم می‌رفتیم اونجا.","ro":"Heyf shod, kheyli bâ ham miraftim unjâ."},{"fr":"Raconte-moi plus souvent ce que tout le monde devient !","tgt":"بیشتر بهم خبر بده که همه چی کار می‌کنن!","ro":"Bishtar behem khabar bede ke hame chi kâr mikonan!"}],"tip":{"title":"« Shenidam ke » : j'ai entendu dire que","example":"J'ai entendu dire que Sara s'était mariée. — <b>شنیدم که</b> سارا ازدواج کرده.","body":"« Shenidam ke » signifie « j'ai entendu que », et c'est la formule idéale pour partager les nouvelles des amis. « Shenidam » vient du verbe « shenidan », entendre, avec la terminaison « -am » de « je », et « ke » joue exactement le rôle de notre « que ». Dans « Shenidam ke Sârâ ezdevâj karde », on a mot à mot : j'ai entendu, que, Sara, mariage, a fait ; « karde » est le passé composé parlé, parfait pour rapporter une nouvelle. Pour poser la question, il suffit de changer la terminaison : « Shenidi ke Maryam bachchedâr shode ? », tu as entendu que Maryam a eu un bébé ? On dit aussi « Shenidam ke kâfe baste shode », il paraît que le café a fermé. Astuce : à l'oral, « ke » disparaît souvent, et « Shenidam Bâbak kâr peydâ karde » reste parfaitement naturel.","exampleRo":"Shenidam ke Sârâ ezdevâj karde.","lit":"j'ai entendu · que · Sara · mariage · a fait","say":{"Shenidam ke":"شنیدم که","Shenidam":"شنیدم","shenidan":"شنیدن","ke":"که","Shenidam ke Sârâ ezdevâj karde":"شنیدم که سارا ازدواج کرده","karde":"کرده","Shenidi ke Maryam bachchedâr shode ?":"شنیدی که مریم بچه‌دار شده؟","Shenidam ke kâfe baste shode":"شنیدم که کافه بسته شده","Shenidam Bâbak kâr peydâ karde":"شنیدم بابک کار پیدا کرده"}}},{"title":"Parler d'un voyage marquant","phrases":[{"fr":"Quel voyage t'est resté le plus en mémoire ?","tgt":"کدوم سفر از همه بیشتر یادت مونده؟","ro":"Kodum safar az hame bishtar yâdet munde?"},{"fr":"Mon voyage dans le désert de Maranjab, il y a trois ans.","tgt":"سفرم به کویر مرنجاب، سه سال پیش.","ro":"Safaram be kavir-e Maranjâb, se sâl pish."},{"fr":"On a dormi dans un vieux caravansérail.","tgt":"تو یه کاروانسرای قدیمی خوابیدیم.","ro":"Tu ye kârvânsarâ-ye ghadimi khâbidim."},{"fr":"La nuit, le ciel était plein d'étoiles.","tgt":"شب آسمون پر از ستاره بود.","ro":"Shab âsemun por az setâre bud."},{"fr":"Au coucher du soleil, on est montés à dos de chameau.","tgt":"دم غروب شترسواری کردیم.","ro":"Dam-e ghorub shotorsavâri kardim."},{"fr":"Je n'oublierai jamais ce silence.","tgt":"هیچ وقت اون سکوت رو فراموش نمی‌کنم.","ro":"Hich vaght un sokut ro farâmush nemikonam."},{"fr":"Tu y étais allé avec qui ?","tgt":"با کی رفته بودی؟","ro":"Bâ ki rafte budi?"},{"fr":"Avec deux collègues et un guide de la région.","tgt":"با دو تا همکار و یه راهنمای محلی.","ro":"Bâ do tâ hamkâr va ye râhnamâ-ye mahalli."},{"fr":"Ça me donne envie d'y aller, moi aussi.","tgt":"دلم می‌خواد منم برم.","ro":"Delam mikhâd manam beram."},{"fr":"Si on y va, emportons des vêtements chauds.","tgt":"اگه رفتیم، لباس گرم ببریم.","ro":"Age raftim, lebâs-e garm bebarim."}]},{"title":"Choisir un restaurant","phrases":[{"fr":"Ce restaurant sert à la fois des kebabs et des plats maison.","tgt":"این رستوران هم کباب داره هم غذای خونگی.","ro":"In resturân ham kabâb dâre ham ghazâ-ye khunegi."},{"fr":"Cet endroit est à la fois bon et pas cher.","tgt":"اینجا هم خوشمزه‌ست هم ارزون.","ro":"Injâ ham khoshmazast ham arzun."},{"fr":"Je veux à la fois du riz au safran et une salade.","tgt":"هم پلو زعفرانی می‌خوام هم سالاد.","ro":"Ham polo za'farâni mikhâm ham sâlâd."},{"fr":"On peut s'asseoir aussi bien dedans que dehors.","tgt":"هم می‌شه داخل نشست هم بیرون.","ro":"Ham mishe dâkhel neshast ham birun."},{"fr":"Tu veux du dough ou du thé ?","tgt":"دوغ می‌خوای یا چای؟","ro":"Dugh mikhây yâ chây?"},{"fr":"Les deux : du dough avec le repas et du thé après.","tgt":"هر دو: هم دوغ با غذا، هم چای بعدش.","ro":"Har do: ham dugh bâ ghazâ, ham chây ba'desh."},{"fr":"Mon amie est à la fois végétarienne et très gourmande.","tgt":"دوستم هم گیاه‌خواره هم خیلی شکمو.","ro":"Dustam ham giyâhkhâre ham kheyli shekamu."},{"fr":"Ici, il y a des plats pour elle comme pour nous.","tgt":"اینجا هم برای اون غذا هست هم برای ما.","ro":"Injâ ham barâye un ghazâ hast ham barâye mâ."},{"fr":"Monsieur, vous pouvez nous apporter l'addition ?","tgt":"آقا، می‌شه صورتحساب رو بیارید؟","ro":"Âghâ, mishe surathesâb ro biyârid?"},{"fr":"C'était à la fois délicieux et bon marché.","tgt":"هم خوشمزه بود هم ارزون.","ro":"Ham khoshmaze bud ham arzun."}],"tip":{"title":"« Ham... ham... » : à la fois l'un et l'autre","example":"Ce restaurant sert à la fois des kebabs et des plats maison. — این رستوران <b>هم</b> کباب داره <b>هم</b> غذای خونگی.","body":"Pour dire « à la fois l'un et l'autre », le persan répète simplement le petit mot « ham », qui veut dire aussi, devant chaque élément. Là où le français dit « ce restaurant sert à la fois des kebabs et des plats maison », le persan dit « In resturân ham kabâb dâre ham ghazâ-ye khunegi », mot à mot : ce restaurant, aussi kebab a, aussi nourriture de maison. Remarquez qu'on n'ajoute pas de « et » entre les deux parties : les deux « ham » suffisent, avec une petite montée de la voix sur le premier. On l'emploie avec des adjectifs, « ham khoshmaze ham arzun », à la fois délicieux et pas cher, ou avec des choses, « ham dugh ham chây », du dough et du thé. Pour retenir, imaginez une balance avec un « ham » sur chaque plateau, bien équilibrée.","exampleRo":"In resturân ham kabâb dâre ham ghazâ-ye khunegi.","lit":"ce · restaurant · aussi · kebab · a · aussi · nourriture [de] · maison","say":{"Ham... ham...":"هم... هم...","ham":"هم","In resturân ham kabâb dâre ham ghazâ-ye khunegi":"این رستوران هم کباب داره هم غذای خونگی","ham khoshmaze ham arzun":"هم خوشمزه هم ارزون","ham dugh ham chây":"هم دوغ هم چای"}}},{"title":"Un rêve d'enfance","phrases":[{"fr":"Quand j'étais petit, je voulais devenir pilote.","tgt":"بچه که بودم، می‌خواستم خلبان بشم.","ro":"Bachche ke budam, mikhâstam khalabân besham."},{"fr":"Et toi, c'était quoi ton rêve ?","tgt":"تو چی؟ آرزوت چی بود؟","ro":"To chi? Ârezut chi bud?"},{"fr":"Je voulais ouvrir une petite librairie à Kashan.","tgt":"می‌خواستم یه کتاب‌فروشی کوچیک تو کاشان باز کنم.","ro":"Mikhâstam ye ketâbforushi-ye kuchik tu Kâshân bâz konam."},{"fr":"Il n'est pas trop tard pour le faire.","tgt":"هنوز برای این کار دیر نیست.","ro":"Hanuz barâye in kâr dir nist."},{"fr":"Dans cinq ans, j'aimerais vivre près de la mer Caspienne.","tgt":"دوست دارم پنج سال دیگه نزدیک دریای خزر زندگی کنم.","ro":"Dust dâram panj sâl-e dige nazdik-e daryâ-ye Khazar zendegi konam."},{"fr":"Ma femme rêve d'une maison avec un petit jardin.","tgt":"زنم آرزو داره یه خونه با باغچه داشته باشه.","ro":"Zanam ârezu dâre ye khune bâ bâghche dâshte bâshe."},{"fr":"Si on met de l'argent de côté, on pourra l'acheter.","tgt":"اگه پس‌انداز کنیم، می‌تونیم بخریمش.","ro":"Age pasandâz konim, mitunim bekharimesh."},{"fr":"Mon petit frère veut devenir musicien.","tgt":"برادر کوچیکم می‌خواد نوازنده بشه.","ro":"Barâdar-e kuchikam mikhâd navâzande beshe."},{"fr":"Nos parents nous ont toujours encouragés.","tgt":"پدر و مادرمون همیشه تشویقمون کردن.","ro":"Pedar o mâdaremun hamishe tashvighemun kardan."},{"fr":"Il faut garder ses rêves, même en grandissant.","tgt":"آدم باید آرزوهاش رو نگه داره، حتی وقتی بزرگ می‌شه.","ro":"Âdam bâyad ârezuhâsh ro negah dâre, hattâ vaghti bozorg mishe."}]},{"title":"Au bazar de Kashan entre amis","phrases":[{"fr":"Regarde la coupole du bazar, elle est superbe !","tgt":"گنبد بازار رو ببین، فوق‌العاده‌ست!","ro":"Gonbad-e bâzâr ro bebin, fogholâdast!"},{"fr":"Je cherche un petit cadeau pour ma mère à Paris.","tgt":"دنبال یه کادوی کوچیک برای مادرم تو پاریس می‌گردم.","ro":"Donbâl-e ye kâdo-ye kuchik barâye mâdaram tu Pâris migardam."},{"fr":"Que dirais-tu d'un petit tapis de Kashan ?","tgt":"یه فرش کوچیک کاشان چطوره؟","ro":"Ye farsh-e kuchik-e Kâshân chetore?"},{"fr":"C'est trop cher pour moi en ce moment.","tgt":"الان برام خیلی گرونه.","ro":"Alân barâm kheyli gerune."},{"fr":"Alors achète-lui de l'eau de rose et des pâtisseries.","tgt":"پس براش گلاب و شیرینی بخر.","ro":"Pas barâsh golâb o shirini bekhar."},{"fr":"Ce vendeur connaît mon père depuis des années.","tgt":"این فروشنده سال‌هاست پدرم رو می‌شناسه.","ro":"In forushande sâlhâst pedaram ro mishnâse."},{"fr":"Je suis sûr qu'il nous fera une réduction.","tgt":"مطمئنم بهمون تخفیف می‌ده.","ro":"Motma'enam behemun takhfif mide."},{"fr":"Tu peux m'aider à porter les sacs ?","tgt":"می‌تونی کمکم کنی کیسه‌ها رو بیارم؟","ro":"Mituni komakam koni kisehâ ro biyâram?"},{"fr":"Bien sûr, donne-m'en un.","tgt":"البته، یکیش رو بده به من.","ro":"Albatte, yekish ro bede be man."},{"fr":"On fait une petite pause dans le salon de thé du bazar ?","tgt":"یه استراحتی تو چایخونه‌ی بازار بکنیم؟","ro":"Ye esterâhati tu châykhune-ye bâzâr bokonim?"}]},{"title":"Organiser des retrouvailles","phrases":[{"fr":"Et si on réunissait toute la bande le mois prochain ?","tgt":"چطوره ماه بعد همه‌ی بچه‌ها رو جمع کنیم؟","ro":"Chetore mâh-e ba'd hame-ye bachchehâ ro jam' konim?"},{"fr":"Si tout le monde est libre, on pourrait se retrouver chez Reza.","tgt":"اگه همه وقت داشته باشن، می‌تونیم خونه‌ی رضا جمع شیم.","ro":"Age hame vaght dâshte bâshan, mitunim khune-ye Rezâ jam' shim."},{"fr":"Sa maison a une grande cour avec un bassin.","tgt":"خونه‌ش یه حیاط بزرگ با حوض داره.","ro":"Khunash ye hayât-e bozorg bâ howz dâre."},{"fr":"Je me charge d'envoyer un message à tout le monde.","tgt":"من به همه پیام می‌دم.","ro":"Man be hame payâm midam."},{"fr":"Chacun apportera un plat.","tgt":"هر کی یه غذا میاره.","ro":"Har ki ye ghazâ miyâre."},{"fr":"Moi, je ferai un riz aux baies d'épine-vinette avec du poulet.","tgt":"من زرشک‌پلو با مرغ درست می‌کنم.","ro":"Man zereshkpolo bâ morgh dorost mikonam."},{"fr":"Même si Nima est à Ispahan, il viendra en train.","tgt":"حتی اگه نیما اصفهان باشه، با قطار میاد.","ro":"Hattâ age Nimâ Esfahân bâshe, bâ ghatâr miyâd."},{"fr":"Ça fait des années qu'on n'a pas été tous réunis.","tgt":"سال‌هاست همه با هم نبودیم.","ro":"Sâlhâst hame bâ ham nabudim."},{"fr":"Ce sera comme au bon vieux temps.","tgt":"مثل قدیما می‌شه.","ro":"Mesl-e ghadimâ mishe."},{"fr":"J'ai hâte de revoir toute la bande !","tgt":"بی‌صبرانه منتظرم همه‌ی بچه‌ها رو ببینم!","ro":"Bisabrâne montazeram hame-ye bachchehâ ro bebinam!"}]},{"title":"Le travail et les coups de fil","phrases":[{"fr":"Je t'ai appelé hier, mais tu n'as pas répondu.","tgt":"دیروز بهت زنگ زدم، ولی جواب ندادی.","ro":"Diruz behet zang zadam, vali javâb nadâdi."},{"fr":"Désolé, je travaillais tard au bureau.","tgt":"ببخشید، تا دیروقت تو اداره کار می‌کردم.","ro":"Bebakhshid, tâ dirvaght tu edâre kâr mikardam."},{"fr":"Tu travailles où, maintenant ?","tgt":"الان کجا کار می‌کنی؟","ro":"Alân kojâ kâr mikoni?"},{"fr":"Je travaille dans un hôtel près du jardin de Fin.","tgt":"تو یه هتل نزدیک باغ فین کار می‌کنم.","ro":"Tu ye hotel nazdik-e bâgh-e Fin kâr mikonam."},{"fr":"Mes clients m'appellent même le week-end.","tgt":"مشتری‌هام حتی آخر هفته هم بهم زنگ می‌زنن.","ro":"Moshtarihâm hattâ âkhar-e hafte ham behem zang mizanan."},{"fr":"Tu devrais éteindre ton téléphone le vendredi.","tgt":"بهتره جمعه‌ها گوشیت رو خاموش کنی.","ro":"Behtare jom'ehâ gushit ro khâmush koni."},{"fr":"Tu as raison, je vais essayer dès cette semaine.","tgt":"حق با توئه، از همین هفته سعی می‌کنم.","ro":"Hagh bâ to'e, az hamin hafte sa'y mikonam."},{"fr":"Rappelle-moi ce soir, on parlera tranquillement.","tgt":"امشب بهم زنگ بزن، راحت حرف بزنیم.","ro":"Emshab behem zang bezan, râhat harf bezanim."},{"fr":"D'accord, je t'appelle vers neuf heures.","tgt":"باشه، حدود ساعت نه بهت زنگ می‌زنم.","ro":"Bâshe, hodud-e sâ'at-e noh behet zang mizanam."},{"fr":"Ne travaille pas trop, prends soin de toi !","tgt":"زیاد کار نکن، مواظب خودت باش!","ro":"Ziyâd kâr nakon, movâzeb-e khodet bâsh!"}],"tip":{"title":"Les verbes composés : « zang zadan », « kâr kardan »","example":"Je t'ai appelé hier, mais tu n'as pas répondu. — دیروز بهت <b>زنگ زدم</b>، ولی جواب ندادی.","body":"Beaucoup de verbes persans sont des verbes composés : un nom suivi d'un petit verbe très courant, comme « zadan », frapper, ou « kardan », faire. « Zang zadan », téléphoner, veut dire mot à mot « frapper la sonnerie », et « kâr kardan », travailler, veut dire « faire du travail ». Seul le petit verbe se conjugue, le nom ne bouge jamais : « zang zadam », j'ai appelé, « zang mizanam », j'appelle, « zang bezan », appelle. Dans « Diruz behet zang zadam », on a : hier, à toi, sonnerie, j'ai frappé. La négation se colle elle aussi au petit verbe : « kâr nakon », ne travaille pas, « javâb nadâdi », tu n'as pas répondu. Astuce : apprenez ces verbes comme des blocs de deux mots, et vous en connaîtrez vite des dizaines.","exampleRo":"Diruz behet zang zadam, vali javâb nadâdi.","lit":"hier · [à] toi · sonnerie · j'ai frappé · mais · réponse · tu n'as pas donné","say":{"zang zadan":"زنگ زدن","kâr kardan":"کار کردن","zadan":"زدن","kardan":"کردن","Zang zadan":"زنگ زدن","zang zadam":"زنگ زدم","zang mizanam":"زنگ می‌زنم","zang bezan":"زنگ بزن","Diruz behet zang zadam":"دیروز بهت زنگ زدم","kâr nakon":"کار نکن","javâb nadâdi":"جواب ندادی"}}},{"title":"Dernière soirée sur les toits","phrases":[{"fr":"Ce soir, on monte sur les toits du bazar pour le coucher du soleil.","tgt":"امشب برای غروب می‌ریم روی پشت‌بوم‌های بازار.","ro":"Emshab barâye ghorub mirim ru-ye poshtbumhâ-ye bâzâr."},{"fr":"La vue sur les coupoles est incroyable.","tgt":"منظره‌ی گنبدها باورنکردنیه.","ro":"Manzare-ye gonbadhâ bâvarnakardaniye."},{"fr":"Mon séjour à Kashan touche à sa fin.","tgt":"سفرم به کاشان داره تموم می‌شه.","ro":"Safaram be Kâshân dâre tamum mishe."},{"fr":"Je repars à Paris lundi.","tgt":"دوشنبه برمی‌گردم پاریس.","ro":"Doshanbe barmigardam Pâris."},{"fr":"Tu vas beaucoup me manquer.","tgt":"خیلی دلم برات تنگ می‌شه.","ro":"Kheyli delam barât tang mishe."},{"fr":"Moi aussi, reviens vite nous voir !","tgt":"منم همین‌طور، زود برگرد پیش ما!","ro":"Manam hamintor, zud bargard pish-e mâ!"},{"fr":"Merci pour tout, vous m'avez si bien reçu.","tgt":"مرسی برای همه‌چی، خیلی خوب ازم پذیرایی کردین.","ro":"Mersi barâye hamechi, kheyli khub azam pazirâyi kardin."},{"fr":"On restera en contact par message.","tgt":"با پیام در تماس می‌مونیم.","ro":"Bâ payâm dar tamâs mimunim."},{"fr":"La prochaine fois, viens au printemps, pour les roses.","tgt":"دفعه‌ی بعد بهار بیا، برای گل‌ها.","ro":"Daf'e-ye ba'd bahâr biyâ, barâye golhâ."},{"fr":"C'est promis, je reviendrai l'année prochaine.","tgt":"قول می‌دم سال دیگه برگردم.","ro":"Ghol midam sâl-e dige bargardam."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Avec ce module, on sait maintenant bavarder entre amis en persan.","tgt":"با این بخش، حالا می‌تونیم به فارسی با دوستامون گپ بزنیم.","ro":"Bâ in bakhsh, hâlâ mitunim be fârsi bâ dustâmun gap bezanim."},{"fr":"On parle de cinéma, de musique et de nos goûts.","tgt":"از سینما و موسیقی و سلیقه‌هامون حرف می‌زنیم.","ro":"Az sinemâ va musighi va salighehâmun harf mizanim."},{"fr":"Le parler de Téhéran nous est désormais plus familier.","tgt":"لهجه‌ی تهرونی حالا برامون آشناتره.","ro":"Lahje-ye tehruni hâlâ barâmun âshenâtare."},{"fr":"On sait dire « peut-être » et raconter les nouvelles.","tgt":"بلدیم بگیم «شاید» و خبرها رو تعریف کنیم.","ro":"Baladim begim «shâyad» va khabarhâ ro ta'rif konim."},{"fr":"Les verbes composés ne nous font plus peur.","tgt":"فعل‌های مرکب دیگه برامون سخت نیستن.","ro":"Fe'lhâ-ye morakkab dige barâmun sakht nistan."},{"fr":"Kashan et ses roses resteront un beau souvenir.","tgt":"کاشان و گل‌هاش یه خاطره‌ی قشنگ می‌مونه.","ro":"Kâshân va golhâsh ye khâtere-ye ghashang mimune."},{"fr":"Ici s'achève le deuxième niveau.","tgt":"سطح دوم همین‌جا تموم می‌شه.","ro":"Sath-e dovvom haminjâ tamum mishe."},{"fr":"Bravo pour tout ce travail accompli.","tgt":"آفرین به خاطر این همه تلاش.","ro":"Âfarin be khâter-e in hame talâsh."},{"fr":"Au niveau suivant, notre persan sera encore meilleur.","tgt":"تو سطح بعد، فارسیمون از این هم بهتر می‌شه.","ro":"Tu sath-e ba'd, fârsimun az in ham behtar mishe."},{"fr":"À bientôt pour la suite du voyage !","tgt":"تا بعد، برای ادامه‌ی سفر!","ro":"Tâ ba'd, barâye edâme-ye safar!"}]}]}]},{"id":3,"name":"Niveau 3","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"Une vie quotidienne installée en Iran, avec ses subtilités.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Le nouveau bureau","phrases":[{"fr":"Notre nouveau bureau a été construit l'année dernière.","tgt":"دفتر جدید ما سال گذشته ساخته شد.","ro":"Daftar-e jadid-e mâ sâl-e gozashte sâkhte shod."},{"fr":"Ce bâtiment a été conçu par un architecte iranien.","tgt":"این ساختمان توسط یک معمار ایرانی طراحی شد.","ro":"In sâkhtemân tavassot-e yek me'mâr-e irâni tarrâhi shod."},{"fr":"Les bureaux ont été repeints pendant l'été.","tgt":"دفترها در تابستان دوباره رنگ شدند.","ro":"Daftarhâ dar tâbestân dobâre rang shodand."},{"fr":"Un bureau près de la fenêtre m'a été attribué.","tgt":"یک میز کنار پنجره به من داده شد.","ro":"Yek miz kenâr-e panjare be man dâde shod."},{"fr":"Tous les ordinateurs ont été changés le mois dernier.","tgt":"همه‌ی کامپیوترها ماه پیش عوض شدند.","ro":"Hame-ye kâmpiyuterhâ mâh-e pish avaz shodand."},{"fr":"La salle de réunion est nettoyée chaque matin.","tgt":"اتاق جلسه هر روز صبح تمیز می‌شود.","ro":"Otâgh-e jalase har ruz sobh tamiz mishavad."},{"fr":"Le thé est servi vers dix heures.","tgt":"چای حدود ساعت ده سرو می‌شود.","ro":"Chây hodud-e sâ'at-e dah serv mishavad."},{"fr":"Les clés seront remises aux employés demain.","tgt":"کلیدها فردا به کارمندان تحویل داده می‌شوند.","ro":"Kelidhâ fardâ be kârmandân tahvil dâde mishavand."},{"fr":"Ce quartier a beaucoup changé ces dernières années.","tgt":"این محله در چند سال اخیر خیلی تغییر کرده است.","ro":"In mahalle dar chand sâl-e akhir kheyli taghyir karde ast."},{"fr":"Depuis la fenêtre, on voit les montagnes de l'Alborz.","tgt":"از پنجره، کوه‌های البرز دیده می‌شوند.","ro":"Az panjare, kuhhâ-ye Alborz dide mishavand."}],"tip":{"title":"Le passif avec « shodan » : « sâkhte shod »","example":"Notre nouveau bureau a été construit l'année dernière. — دفتر جدید ما سال گذشته <b>ساخته</b> <b>شد</b>.","body":"Pour dire qu'une chose « a été faite », le persan prend le participe passé du verbe et lui ajoute le verbe « shodan », devenir. « Sâkhtan » veut dire construire, son participe est « sâkhte », construit, et « sâkhte shod » signifie mot à mot « construit devint », c'est-à-dire « a été construit ». Au présent, on dit « mishavad » : « tamiz mishavad », est nettoyé, « dide mishavad », est vu, ou plus simplement « on voit ». C'est exactement comme notre « être » du passif, sauf qu'on pense « devenir ». Pour dire par qui, on ajoute « tavassot-e », par : « tavassot-e yek me'mâr », par un architecte. Astuce : dès que vous entendez « shod » ou « mishavad » juste après un participe en « -e », pensez « a été » ou « est ».","exampleRo":"Daftar-e jadid-e mâ sâl-e gozashte sâkhte shod.","lit":"bureau · [de] nouveau · [de] nous · année · [de] passée · construit · devint","say":{"shodan":"شدن","sâkhte shod":"ساخته شد","Sâkhtan":"ساختن","sâkhte":"ساخته","mishavad":"می‌شود","tamiz mishavad":"تمیز می‌شود","dide mishavad":"دیده می‌شود","tavassot-e yek me'mâr":"توسط یک معمار","shod":"شد"}}},{"title":"La réunion du samedi matin","phrases":[{"fr":"En Iran, la semaine de travail commence le samedi.","tgt":"در ایران هفته‌ی کاری از شنبه شروع می‌شود.","ro":"Dar Irân hafte-ye kâri az shanbe shoru' mishavad."},{"fr":"La réunion d'équipe a lieu chaque samedi à neuf heures.","tgt":"جلسه‌ی تیم هر شنبه ساعت نه برگزار می‌شود.","ro":"Jalase-ye tim har shanbe sâ'at-e noh bargozâr mishavad."},{"fr":"Le directeur présente d'abord les objectifs de la semaine.","tgt":"مدیر اول اهداف هفته را توضیح می‌دهد.","ro":"Modir avval ahdâf-e hafte râ tozih midahad."},{"fr":"Ensuite, chacun dit où en est son projet.","tgt":"بعد هر کس می‌گوید پروژه‌اش به کجا رسیده است.","ro":"Ba'd har kas miguyad porozhe-ash be kojâ reside ast."},{"fr":"Je prends des notes pendant toute la réunion.","tgt":"من در تمام جلسه یادداشت برمی‌دارم.","ro":"Man dar tamâm-e jalase yâddâsht barmidâram."},{"fr":"Pourriez-vous répéter ce dernier point, s'il vous plaît ?","tgt":"ممکن است لطفا نکته‌ی آخر را تکرار کنید؟","ro":"Momken ast lotfan nokte-ye âkhar râ tekrâr konid?"},{"fr":"Je ne suis pas tout à fait d'accord avec cette proposition.","tgt":"من با این پیشنهاد کاملا موافق نیستم.","ro":"Man bâ in pishnahâd kâmelan movâfegh nistam."},{"fr":"Nous devons prendre une décision avant jeudi.","tgt":"باید قبل از پنجشنبه تصمیم بگیریم.","ro":"Bâyad ghabl az panjshanbe tasmim begirim."},{"fr":"La réunion a duré plus longtemps que prévu.","tgt":"جلسه بیشتر از آنچه فکر می‌کردیم طول کشید.","ro":"Jalase bishtar az ânche fekr mikardim tul keshid."},{"fr":"Le compte rendu sera envoyé à tous cet après-midi.","tgt":"گزارش جلسه امروز بعدازظهر برای همه فرستاده می‌شود.","ro":"Gozâresh-e jalase emruz ba'dazzohr barâye hame ferestâde mishavad."}]},{"title":"Former un stagiaire","phrases":[{"fr":"J'ai fait comprendre au stagiaire comment marche le logiciel.","tgt":"به کارآموز فهماندم که نرم‌افزار چطور کار می‌کند.","ro":"Be kârâmuz fahmândam ke narmafzâr chetor kâr mikonad."},{"fr":"Le chauffeur de l'entreprise m'a déposé devant la banque.","tgt":"راننده‌ی شرکت مرا جلوی بانک رساند.","ro":"Rânande-ye sherkat marâ jelo-ye bânk resând."},{"fr":"Pourriez-vous faire parvenir ce dossier au directeur ?","tgt":"می‌شود این پرونده را به دست مدیر برسانید؟","ro":"Mishavad in parvande râ be dast-e modir beresânid?"},{"fr":"Ses blagues font rire toute l'équipe.","tgt":"شوخی‌هایش همه‌ی تیم را می‌خنداند.","ro":"Shukhihâyash hame-ye tim râ mikhandânad."},{"fr":"La secrétaire a fait asseoir les visiteurs dans la salle d'attente.","tgt":"منشی مهمان‌ها را در اتاق انتظار نشاند.","ro":"Monshi mehmânhâ râ dar otâgh-e entezâr neshând."},{"fr":"Au début, ce gros dossier m'a fait peur.","tgt":"این پرونده‌ی بزرگ اول مرا ترساند.","ro":"In parvande-ye bozorg avval marâ tarsând."},{"fr":"Il fait tourner seul tout le service informatique.","tgt":"او به تنهایی کل بخش فناوری اطلاعات را می‌گرداند.","ro":"U be tanhâyi kol-e bakhsh-e fanâvari-ye ettelâ'ât râ migardânad."},{"fr":"N'oubliez pas de coller l'étiquette sur le carton.","tgt":"یادتان نرود برچسب را روی جعبه بچسبانید.","ro":"Yâdetân naravad barchasb râ ru-ye ja'be bechasbânid."},{"fr":"Le stagiaire apprend vite et pose de bonnes questions.","tgt":"کارآموز زود یاد می‌گیرد و سؤال‌های خوبی می‌پرسد.","ro":"Kârâmuz zud yâd migirad va so'âlhâ-ye khubi miporsad."},{"fr":"En fin de journée, je l'ai raccompagné jusqu'au métro.","tgt":"آخر روز او را تا مترو رساندم.","ro":"Âkhar-e ruz u râ tâ metro resândam."}],"tip":{"title":"Faire faire : le causatif en « -ândan »","example":"J'ai fait comprendre au stagiaire comment marche le logiciel. — به کارآموز <b>فهماندم</b> که نرم‌افزار چطور کار می‌کند.","body":"Là où le français dit « faire faire », le persan glisse simplement la syllabe « -ân » dans le verbe. « Fahmidan », comprendre, devient « fahmândan », faire comprendre : « fahmândam », j'ai fait comprendre, se décompose en « fahm », la racine, « ând », le faire faire, et « am », je. De même, « khandidan », rire, donne « khandândan », faire rire, « neshastan », s'asseoir, donne « neshândan », faire asseoir, et « residan », arriver, donne « resândan », faire arriver, c'est-à-dire déposer quelqu'un ou faire parvenir quelque chose. Au présent, la marque reste : « mikhandânad », il fait rire. Astuce : entendez ce petit « ân » comme un coup de pouce donné à quelqu'un d'autre pour qu'il agisse.","exampleRo":"Be kârâmuz fahmândam ke narmafzâr chetor kâr mikonad.","lit":"[à] · stagiaire · fis-comprendre · que · logiciel · comment · travail · fait","say":{"Fahmidan":"فهمیدن","fahmândan":"فهماندن","fahmândam":"فهماندم","fahm":"فهم","khandidan":"خندیدن","khandândan":"خنداندن","neshastan":"نشستن","neshândan":"نشاندن","residan":"رسیدن","resândan":"رساندن","mikhandânad":"می‌خنداند"}}},{"title":"Les courriels du bureau","phrases":[{"fr":"Je reçois une cinquantaine de courriels par jour.","tgt":"هر روز حدود پنجاه ایمیل دریافت می‌کنم.","ro":"Har ruz hodud-e panjâh imeyl dariyâft mikonam."},{"fr":"Je commence toujours par répondre aux messages urgents.","tgt":"همیشه اول به پیام‌های فوری جواب می‌دهم.","ro":"Hamishe avval be payâmhâ-ye fori javâb midaham."},{"fr":"Un courriel formel commence souvent par une formule de respect.","tgt":"ایمیل رسمی معمولا با «با سلام و احترام» شروع می‌شود.","ro":"Imeyl-e rasmi ma'mulan bâ «bâ salâm va ehterâm» shoru' mishavad."},{"fr":"Pourriez-vous m'envoyer le fichier en pièce jointe ?","tgt":"ممکن است فایل را به صورت پیوست برایم بفرستید؟","ro":"Momken ast fâyl râ be surat-e peyvast barâyam beferestid?"},{"fr":"J'ai oublié de mettre mon responsable en copie.","tgt":"یادم رفت مدیرم را در رونوشت بگذارم.","ro":"Yâdam raft modiram râ dar runevesht begozâram."},{"fr":"Votre message a bien été reçu.","tgt":"پیام شما دریافت شد.","ro":"Payâm-e shomâ dariyâft shod."},{"fr":"Je vous répondrai à la première occasion.","tgt":"در اولین فرصت به شما جواب خواهم داد.","ro":"Dar avvalin forsat be shomâ javâb khâham dâd."},{"fr":"Ce courriel est trop long, je dois le raccourcir.","tgt":"این ایمیل خیلی طولانی است و باید کوتاه‌ترش کنم.","ro":"In imeyl kheyli tulâni ast va bâyad kutâhtarash konam."},{"fr":"Le soir, j'essaie de ne plus regarder mes courriels.","tgt":"شب‌ها سعی می‌کنم دیگر ایمیل‌هایم را نگاه نکنم.","ro":"Shabhâ sa'y mikonam digar imeylhâyam râ negâh nakonam."},{"fr":"Un courriel clair et précis fait gagner du temps à tout le monde.","tgt":"یک ایمیل روشن و دقیق در وقت همه صرفه‌جویی می‌کند.","ro":"Yek imeyl-e roshan va daghigh dar vaght-e hame sarfejuyi mikonad."}]},{"title":"La fin d'une longue journée","phrases":[{"fr":"Ce soir, je suis vraiment fatigué.","tgt":"امشب واقعا خسته‌ام.","ro":"Emshab vâghe'an khaste-am."},{"fr":"À cette heure-ci, la porte du bureau est fermée.","tgt":"این ساعت در دفتر بسته است.","ro":"In sâ'at dar-e daftar baste ast."},{"fr":"Tous les magasins de cette rue sont fermés le vendredi.","tgt":"همه‌ی مغازه‌های این خیابان جمعه‌ها بسته‌اند.","ro":"Hame-ye maghâzehâ-ye in khiyâbân jom'ehâ baste-and."},{"fr":"L'écran de mon téléphone est cassé.","tgt":"صفحه‌ی گوشی‌ام شکسته است.","ro":"Safhe-ye gushi-am shekaste ast."},{"fr":"Les feuilles tombées couvrent le trottoir.","tgt":"برگ‌های افتاده پیاده‌رو را پوشانده‌اند.","ro":"Barghâ-ye oftâde piyâderow râ pushânde-and."},{"fr":"Le dossier signé est sur votre bureau.","tgt":"پرونده‌ی امضاشده روی میز شماست.","ro":"Parvande-ye emzâshode ru-ye miz-e shomâst."},{"fr":"Le directeur est assis dans son bureau depuis ce matin.","tgt":"مدیر از صبح در اتاقش نشسته است.","ro":"Modir az sobh dar otâghash neshaste ast."},{"fr":"Mon collègue fatigué est rentré tôt chez lui.","tgt":"همکار خسته‌ام زود به خانه رفت.","ro":"Hamkâr-e khaste-am zud be khâne raft."},{"fr":"La route du nord est encore fermée à cause de la neige.","tgt":"جاده‌ی شمال هنوز به خاطر برف بسته است.","ro":"Jâdde-ye shomâl hanuz be khâter-e barf baste ast."},{"fr":"Après une telle journée, j'ai besoin d'une soirée tranquille.","tgt":"بعد از چنین روزی، به یک شب آرام احتیاج دارم.","ro":"Ba'd az chenin ruzi, be yek shab-e ârâm ehtiyâj dâram."}],"tip":{"title":"Le participe passé comme adjectif : « baste », « khaste »","example":"Ce soir, je suis vraiment fatigué. — امشب واقعا <b>خسته‌ام</b>.","body":"En persan, le participe passé se forme en ajoutant un « -e » à la racine du passé, et il s'emploie très souvent comme un simple adjectif, comme en français. « Bastan », fermer, donne « baste », fermé ; « shekastan », casser, donne « shekaste », cassé ; « neshastan », s'asseoir, donne « neshaste », assis. On le place après le nom avec l'ezâfe : « hamkâr-e khaste », le collègue fatigué, ou avec le verbe être : « dar baste ast », la porte est fermée. Le mot « khaste », fatigué, vient lui-même d'un vieux verbe qui voulait dire blesser. Dans « khaste-am », je suis fatigué, le « -am » final remplace « hastam » : c'est la forme la plus naturelle à l'oral. Astuce : un mot qui finit en « -e » et qui décrit un état, c'est très souvent un participe.","exampleRo":"Emshab vâghe'an khaste-am.","lit":"ce soir · vraiment · fatigué-suis","say":{"baste":"بسته","khaste":"خسته","Bastan":"بستن","shekastan":"شکستن","shekaste":"شکسته","neshastan":"نشستن","neshaste":"نشسته","hamkâr-e khaste":"همکار خسته","dar baste ast":"در بسته است","khaste-am":"خسته‌ام","hastam":"هستم"}}},{"title":"Les embouteillages de Téhéran","phrases":[{"fr":"À Téhéran, les embouteillages commencent dès sept heures du matin.","tgt":"در تهران ترافیک از ساعت هفت صبح شروع می‌شود.","ro":"Dar Tehrân terâfik az sâ'at-e haft-e sobh shoru' mishavad."},{"fr":"Il me faut parfois une heure et demie pour aller au travail.","tgt":"گاهی یک ساعت و نیم طول می‌کشد تا به سر کار برسم.","ro":"Gâhi yek sâ'at va nim tul mikeshad tâ be sar-e kâr beresam."},{"fr":"Je prends souvent le métro pour ne pas rester coincé.","tgt":"اغلب با مترو می‌روم تا در ترافیک نمانم.","ro":"Aghlab bâ metro miravam tâ dar terâfik namânam."},{"fr":"Ce matin, l'autoroute vers le nord est complètement bloquée.","tgt":"امروز صبح اتوبان شمال کاملا قفل است.","ro":"Emruz sobh otobân-e shomâl kâmelan ghofl ast."},{"fr":"Les taxis collectifs sont pratiques mais souvent pleins.","tgt":"تاکسی‌های خطی راحت‌اند ولی اغلب پرند.","ro":"Tâksihâ-ye khatti râhat-and vali aghlab por-and."},{"fr":"Un chauffeur de taxi m'a raconté toute sa vie pendant le trajet.","tgt":"راننده‌ی تاکسی در طول راه کل زندگی‌اش را برایم تعریف کرد.","ro":"Rânande-ye tâksi dar tul-e râh kol-e zendegi-ash râ barâyam ta'rif kard."},{"fr":"Pour entrer dans le centre-ville, il faut une autorisation spéciale.","tgt":"برای ورود به مرکز شهر مجوز طرح ترافیک لازم است.","ro":"Barâye vorud be markaz-e shahr mojavvez-e tarh-e terâfik lâzem ast."},{"fr":"Les motos se faufilent entre les voitures.","tgt":"موتورها از لای ماشین‌ها رد می‌شوند.","ro":"Motorhâ az lâ-ye mâshinhâ rad mishavand."},{"fr":"Demain, je partirai plus tôt pour éviter les bouchons.","tgt":"فردا زودتر راه می‌افتم تا به ترافیک نخورم.","ro":"Fardâ zudtar râh mioftam tâ be terâfik nakhoram."},{"fr":"Dans les bouchons, j'écoute des podcasts pour apprendre.","tgt":"در ترافیک پادکست گوش می‌دهم تا چیزی یاد بگیرم.","ro":"Dar terâfik pâdkast gush midaham tâ chizi yâd begiram."}]},{"title":"Un vendredi dans la montagne","phrases":[{"fr":"Le vendredi, beaucoup de Téhéranais vont marcher dans la montagne.","tgt":"جمعه‌ها خیلی از تهرانی‌ها برای کوه‌پیمایی به کوه می‌روند.","ro":"Jom'ehâ kheyli az tehrânihâ barâye kuhpeymâyi be kuh miravand."},{"fr":"Nous nous retrouvons à sept heures sur la place de Tajrish.","tgt":"ساعت هفت در میدان تجریش همدیگر را می‌بینیم.","ro":"Sâ'at-e haft dar meydân-e Tajrish hamdigar râ mibinim."},{"fr":"Le sentier de Darband longe une petite rivière.","tgt":"مسیر دربند در کنار یک رودخانه‌ی کوچک است.","ro":"Masir-e Darband dar kenâr-e yek rudkhâne-ye kuchek ast."},{"fr":"Il y a beaucoup de petits salons de thé le long du chemin.","tgt":"در طول مسیر قهوه‌خانه‌های کوچک زیادی هست.","ro":"Dar tul-e masir ghahvekhânehâ-ye kuchek-e ziyâdi hast."},{"fr":"On s'arrête pour boire un thé et grignoter des fruits secs.","tgt":"برای خوردن چای و آجیل توقف می‌کنیم.","ro":"Barâye khordan-e chây va âjil tavaghghof mikonim."},{"fr":"Le téléphérique du Tochal monte très haut au-dessus de la ville.","tgt":"تله‌کابین توچال تا ارتفاع خیلی بالایی می‌رود.","ro":"Telekâbin-e Tochâl tâ ertefâ'-e kheyli bâlâyi miravad."},{"fr":"En hiver, on peut skier tout près de Téhéran.","tgt":"زمستان‌ها نزدیک تهران می‌شود اسکی کرد.","ro":"Zemestânhâ nazdik-e Tehrân mishavad eski kard."},{"fr":"Là-haut, l'air est beaucoup plus pur qu'en ville.","tgt":"هوای آن بالا خیلی تمیزتر از هوای شهر است.","ro":"Havâ-ye ân bâlâ kheyli tamiztar az havâ-ye shahr ast."},{"fr":"Nous redescendons vers midi, avant la foule.","tgt":"حدود ظهر، قبل از شلوغی، پایین می‌آییم.","ro":"Hodud-e zohr, ghabl az sholughi, pâyin miâyim."},{"fr":"Ces sorties me donnent de l'énergie pour toute la semaine.","tgt":"این گردش‌ها برای کل هفته به من انرژی می‌دهد.","ro":"In gardeshhâ barâye kol-e hafte be man enerzhi midahad."}]},{"title":"Chercher un appartement","phrases":[{"fr":"Les loyers ont beaucoup augmenté, même dans les quartiers du sud.","tgt":"اجاره‌ها حتی در محله‌های جنوب شهر هم خیلی بالا رفته است.","ro":"Ejârehâ hattâ dar mahallehâ-ye jonub-e shahr ham kheyli bâlâ rafte ast."},{"fr":"Dans le nord de la ville, même un petit appartement coûte cher.","tgt":"حتی یک آپارتمان کوچک در شمال شهر گران است.","ro":"Hattâ yek âpârtemân-e kuchek dar shomâl-e shahr gerân ast."},{"fr":"Je n'ai même pas eu le temps de visiter le deuxième appartement.","tgt":"حتی وقت نکردم آپارتمان دوم را ببینم.","ro":"Hattâ vaght nakardam âpârtemân-e dovvom râ bebinam."},{"fr":"L'agent immobilier m'a appelé même le vendredi.","tgt":"مشاور املاک حتی جمعه هم به من زنگ زد.","ro":"Moshâver-e amlâk hattâ jom'e ham be man zang zad."},{"fr":"Ici, il faut souvent verser un gros dépôt de garantie.","tgt":"اینجا معمولا باید رهن زیادی پرداخت کرد.","ro":"Injâ ma'mulan bâyad rahn-e ziyâdi pardâkht kard."},{"fr":"Je cherche un appartement près d'une station de métro.","tgt":"دنبال آپارتمانی نزدیک ایستگاه مترو هستم.","ro":"Donbâl-e âpârtemâni nazdik-e istgâh-e metro hastam."},{"fr":"Cet immeuble n'a même pas d'ascenseur.","tgt":"این ساختمان حتی آسانسور هم ندارد.","ro":"In sâkhtemân hattâ âsânsor ham nadârad."},{"fr":"Le propriétaire a l'air honnête et aimable.","tgt":"صاحبخانه آدم صادق و خوش‌برخوردی به نظر می‌رسد.","ro":"Sâhebkhâne âdam-e sâdegh va khoshbarkhordi be nazar miresad."},{"fr":"Même avec deux salaires, se loger n'est pas facile.","tgt":"حتی با دو حقوق هم پیدا کردن خانه آسان نیست.","ro":"Hattâ bâ do hoghugh ham peydâ kardan-e khâne âsân nist."},{"fr":"Finalement, j'ai trouvé un appartement ensoleillé à Shemiran.","tgt":"بالاخره یک آپارتمان آفتابگیر در شمیران پیدا کردم.","ro":"Belâkhare yek âpârtemân-e âftâbgir dar Shemirân peydâ kardam."}],"tip":{"title":"« Hattâ » : même","example":"Dans le nord de la ville, même un petit appartement coûte cher. — <b>حتی</b> یک آپارتمان کوچک در شمال شهر گران است.","body":"Le mot « hattâ » correspond à notre « même », et il se place juste devant ce qu'il met en relief : « hattâ yek âpârtemân-e kuchek », même un petit appartement. Très souvent, on le renforce avec « ham », aussi, placé juste après le mot visé : « hattâ jom'e ham », même le vendredi, mot à mot « même vendredi aussi ». Avec un verbe négatif, « hattâ » donne « ne même pas » : « hattâ vaght nakardam », je n'ai même pas eu le temps. Notez que le persan n'a pas besoin de « pas » en plus : la négation est déjà dans le verbe avec « na- ». Astuce : pensez au couple « hattâ … ham » comme à une paire de parenthèses qui encadre la surprise.","exampleRo":"Hattâ yek âpârtemân-e kuchek dar shomâl-e shahr gerân ast.","lit":"même · un · appartement · [de] petit · dans · nord · [de] ville · cher · est","say":{"Hattâ":"حتی","hattâ":"حتی","hattâ yek âpârtemân-e kuchek":"حتی یک آپارتمان کوچک","ham":"هم","hattâ jom'e ham":"حتی جمعه هم","hattâ vaght nakardam":"حتی وقت نکردم"}}},{"title":"Signer le bail","phrases":[{"fr":"Le contrat de location est signé pour un an.","tgt":"قرارداد اجاره برای یک سال امضا می‌شود.","ro":"Gharârdâd-e ejâre barâye yek sâl emzâ mishavad."},{"fr":"Nous avons rendez-vous à l'agence pour signer le bail.","tgt":"برای امضای قرارداد در دفتر املاک قرار داریم.","ro":"Barâye emzâ-ye gharârdâd dar daftar-e amlâk gharâr dârim."},{"fr":"Il faut lire chaque clause avec attention.","tgt":"باید هر بند را با دقت خواند.","ro":"Bâyad har band râ bâ deghghat khând."},{"fr":"Qui paie les charges de l'immeuble ?","tgt":"شارژ ساختمان را چه کسی می‌دهد؟","ro":"Shârzh-e sâkhtemân râ che kasi midahad?"},{"fr":"En plus du dépôt, le propriétaire veut un loyer mensuel.","tgt":"صاحبخانه علاوه بر رهن، اجاره‌ی ماهانه هم می‌خواهد.","ro":"Sâhebkhâne alâve bar rahn, ejâre-ye mâhâne ham mikhâhad."},{"fr":"Est-ce qu'on peut baisser un peu le montant ?","tgt":"می‌شود مبلغ را کمی پایین آورد؟","ro":"Mishavad mablagh râ kami pâyin âvard?"},{"fr":"Le chauffe-eau doit être réparé avant notre arrivée.","tgt":"آبگرمکن باید قبل از آمدن ما تعمیر شود.","ro":"Âbgarmkon bâyad ghabl az âmadan-e mâ ta'mir shavad."},{"fr":"Nous emménagerons au début du mois prochain.","tgt":"اول ماه آینده اسباب‌کشی می‌کنیم.","ro":"Avval-e mâh-e âyande asbâbkeshi mikonim."},{"fr":"J'ai déjà loué une camionnette pour le déménagement.","tgt":"از قبل یک وانت برای اسباب‌کشی گرفته‌ام.","ro":"Az ghabl yek vânet barâye asbâbkeshi gerefte-am."},{"fr":"Les voisins nous ont accueillis avec des pâtisseries.","tgt":"همسایه‌ها با شیرینی از ما استقبال کردند.","ro":"Hamsâyehâ bâ shirini az mâ esteghbâl kardand."}]},{"title":"Les démarches administratives","phrases":[{"fr":"Les démarches administratives prennent souvent beaucoup de temps.","tgt":"کارهای اداری اغلب خیلی وقت می‌گیرد.","ro":"Kârhâ-ye edâri aghlab kheyli vaght migirad."},{"fr":"Il faut d'abord prendre rendez-vous sur internet.","tgt":"اول باید از طریق اینترنت نوبت گرفت.","ro":"Avval bâyad az tarigh-e internet nobat gereft."},{"fr":"J'ai apporté des photocopies de tous mes documents.","tgt":"از همه‌ی مدارکم کپی آورده‌ام.","ro":"Az hame-ye madârekam kopi âvarde-am."},{"fr":"À quel guichet dois-je m'adresser ?","tgt":"به کدام باجه باید مراجعه کنم؟","ro":"Be kodâm bâje bâyad morâje'e konam?"},{"fr":"Il manque une signature sur ce formulaire.","tgt":"این فرم یک امضا کم دارد.","ro":"In form yek emzâ kam dârad."},{"fr":"Mes diplômes doivent être traduits par un traducteur officiel.","tgt":"مدرک‌هایم باید توسط مترجم رسمی ترجمه شوند.","ro":"Madrakhâyam bâyad tavassot-e motarjem-e rasmi tarjome shavand."},{"fr":"Revenez dans une semaine avec deux photos d'identité.","tgt":"یک هفته‌ی دیگر با دو قطعه عکس برگردید.","ro":"Yek hafte-ye digar bâ do ghat'e aks bargardid."},{"fr":"L'employé a été très patient avec moi.","tgt":"کارمند با من خیلی صبور بود.","ro":"Kârmand bâ man kheyli sabur bud."},{"fr":"Finalement, mon dossier a été accepté.","tgt":"بالاخره پرونده‌ام پذیرفته شد.","ro":"Belâkhare parvande-am pazirofte shod."},{"fr":"Je garde toujours une copie de chaque papier.","tgt":"همیشه از هر مدرکی یک کپی نگه می‌دارم.","ro":"Hamishe az har madraki yek kopi negah midâram."}]},{"title":"Un rendez-vous à la banque","phrases":[{"fr":"Je voudrais ouvrir un compte courant.","tgt":"می‌خواهم یک حساب جاری باز کنم.","ro":"Mikhâham yek hesâb-e jâri bâz konam."},{"fr":"Quels documents dois-je apporter ?","tgt":"چه مدارکی باید بیاورم؟","ro":"Che madâreki bâyad biyâvaram?"},{"fr":"Ma carte bancaire arrivera dans trois jours.","tgt":"کارت بانکی‌ام سه روز دیگر می‌رسد.","ro":"Kârt-e bânki-am se ruz-e digar miresad."},{"fr":"Ici, on paie presque tout par carte.","tgt":"اینجا تقریبا همه چیز را با کارت پرداخت می‌کنند.","ro":"Injâ taghriban hame chiz râ bâ kârt pardâkht mikonand."},{"fr":"Mon salaire est versé le dernier jour du mois.","tgt":"حقوقم روز آخر ماه واریز می‌شود.","ro":"Hoghugham ruz-e âkhar-e mâh vâriz mishavad."},{"fr":"Je voudrais virer un million de tomans à mon propriétaire.","tgt":"می‌خواهم یک میلیون تومان به صاحبخانه‌ام کارت به کارت کنم.","ro":"Mikhâham yek milyun tomân be sâhebkhâne-am kârt be kârt konam."},{"fr":"Ce matin, le distributeur a avalé ma carte.","tgt":"عابربانک امروز صبح کارتم را خورد.","ro":"Âberbânk emruz sobh kârtam râ khord."},{"fr":"En fin de mois, il y a énormément de monde à la banque.","tgt":"آخر ماه بانک خیلی شلوغ است.","ro":"Âkhar-e mâh bânk kheyli sholugh ast."},{"fr":"Pourriez-vous m'imprimer un relevé de compte ?","tgt":"ممکن است یک صورت‌حساب برایم چاپ کنید؟","ro":"Momken ast yek surathesâb barâyam châp konid?"},{"fr":"J'ai installé l'application de la banque sur mon téléphone.","tgt":"برنامه‌ی بانک را روی گوشی‌ام نصب کرده‌ام.","ro":"Barnâme-ye bânk râ ru-ye gushi-am nasb karde-am."}]},{"title":"Recevoir un client","phrases":[{"fr":"Soyez le bienvenu, entrez je vous prie.","tgt":"خوش آمدید، بفرمایید داخل.","ro":"Khosh âmadid, befarmâyid dâkhel."},{"fr":"Merci d'être venu jusqu'à nous.","tgt":"ممنون که تشریف آوردید.","ro":"Mamnun ke tashrif âvardid."},{"fr":"Vous prendrez du thé ou du café ?","tgt":"چای میل دارید یا قهوه؟","ro":"Chây meyl dârid yâ ghahve?"},{"fr":"Monsieur le directeur arrive dans quelques minutes.","tgt":"آقای مدیر چند دقیقه‌ی دیگر تشریف می‌آورند.","ro":"Âghâ-ye modir chand daghighe-ye digar tashrif miâvarand."},{"fr":"Je suis à votre service, je vous écoute.","tgt":"در خدمت شما هستم، بفرمایید.","ro":"Dar khedmat-e shomâ hastam, befarmâyid."},{"fr":"Comme vous le dites, il faut terminer avant la fin de l'année.","tgt":"همان‌طور که می‌فرمایید، باید تا آخر سال تمامش کنیم.","ro":"Hamântor ke mifarmâyid, bâyad tâ âkhar-e sâl tamâmash konim."},{"fr":"Pardon, qu'avez-vous dit ?","tgt":"ببخشید، چه فرمودید؟","ro":"Bebakhshid, che farmudid?"},{"fr":"Quand comptez-vous repartir ?","tgt":"کی تشریف می‌برید؟","ro":"Key tashrif mibarid?"},{"fr":"Excusez-moi de vous avoir fait attendre.","tgt":"ببخشید که منتظرتان گذاشتم.","ro":"Bebakhshid ke montazeretân gozâshtam."},{"fr":"C'était un honneur, revenez nous voir quand vous voulez.","tgt":"مایه‌ی افتخار بود، باز هم تشریف بیاورید.","ro":"Mâye-ye eftekhâr bud, bâz ham tashrif biyâvarid."}],"tip":{"title":"Le langage formel : « mifarmâyid », « tashrif âvardan »","example":"Merci d'être venu jusqu'à nous. — ممنون که <b>تشریف</b> <b>آوردید</b>.","body":"Dans un cadre professionnel, les Iraniens remplacent certains verbes ordinaires par des verbes de respect, un peu comme notre « daigner », mais en beaucoup plus courant. Pour venir, on ne dit pas « âmadid » à un visiteur, mais « tashrif âvardid », mot à mot « vous avez apporté votre présence ». Pour partir, on dit « tashrif mibarid », vous emportez votre présence. Pour dire, on remplace « goftan » par « farmudan » : « che farmudid ? », qu'avez-vous dit, et « hamântor ke mifarmâyid », comme vous le dites. Le célèbre « befarmâyid » vient du même verbe et sert à tout : entrez, servez-vous, je vous écoute. Attention, ces formes ne s'emploient jamais pour soi-même : pour vous, restez simple avec « âmadam », je suis venu.","exampleRo":"Mamnun ke tashrif âvardid.","lit":"merci · que · présence · apportâtes","say":{"mifarmâyid":"می‌فرمایید","tashrif âvardan":"تشریف آوردن","âmadid":"آمدید","tashrif âvardid":"تشریف آوردید","tashrif mibarid":"تشریف می‌برید","goftan":"گفتن","farmudan":"فرمودن","che farmudid ?":"چه فرمودید؟","hamântor ke mifarmâyid":"همان‌طور که می‌فرمایید","befarmâyid":"بفرمایید","âmadam":"آمدم"}}},{"title":"Le déjeuner au bureau","phrases":[{"fr":"À midi, nous mangeons ensemble à la cafétéria.","tgt":"ظهرها با هم در سلف غذا می‌خوریم.","ro":"Zohrhâ bâ ham dar self ghazâ mikhorim."},{"fr":"Aujourd'hui, il y a du riz au safran avec du poulet.","tgt":"امروز برنج زعفرانی با مرغ داریم.","ro":"Emruz berenj-e za'farâni bâ morgh dârim."},{"fr":"Certains collègues apportent leur repas de la maison.","tgt":"بعضی از همکارها غذایشان را از خانه می‌آورند.","ro":"Ba'zi az hamkârhâ ghazâyeshân râ az khâne miâvarand."},{"fr":"Parfois, on commande des kebabs pour toute l'équipe.","tgt":"گاهی برای همه‌ی تیم کباب سفارش می‌دهیم.","ro":"Gâhi barâye hame-ye tim kabâb sefâresh midahim."},{"fr":"Au moment de payer, chacun insiste pour inviter les autres.","tgt":"موقع حساب کردن، هر کس اصرار می‌کند که مهمان کند.","ro":"Moghe'-e hesâb kardan, har kas esrâr mikonad ke mehmân konad."},{"fr":"Après le repas, on boit toujours un thé.","tgt":"بعد از غذا همیشه یک چای می‌خوریم.","ro":"Ba'd az ghazâ hamishe yek chây mikhorim."},{"fr":"La pause déjeuner dure à peu près une heure.","tgt":"وقت ناهار تقریبا یک ساعت است.","ro":"Vaght-e nâhâr taghriban yek sâ'at ast."},{"fr":"C'est le meilleur moment pour bavarder avec les collègues.","tgt":"بهترین وقت برای گپ زدن با همکارهاست.","ro":"Behtarin vaght barâye gap zadan bâ hamkârhâst."},{"fr":"Chaque jour, je goûte un nouveau plat iranien.","tgt":"هر روز یک غذای ایرانی جدید امتحان می‌کنم.","ro":"Har ruz yek ghazâ-ye irâni-ye jadid emtehân mikonam."},{"fr":"Le ghormeh sabzi du jeudi est mon plat préféré.","tgt":"قورمه‌سبزی پنجشنبه‌ها را از همه بیشتر دوست دارم.","ro":"Ghormesabzi-ye panjshanbehâ râ az hame bishtar dust dâram."}]},{"title":"Travailler depuis la maison","phrases":[{"fr":"Je travaille de chez moi deux jours par semaine.","tgt":"هفته‌ای دو روز از خانه کار می‌کنم.","ro":"Hafte'i do ruz az khâne kâr mikonam."},{"fr":"Le télétravail m'épargne les embouteillages.","tgt":"دورکاری مرا از ترافیک نجات می‌دهد.","ro":"Durkâri marâ az terâfik nejât midahad."},{"fr":"Ma connexion internet est parfois très lente.","tgt":"اینترنتم گاهی خیلی کند است.","ro":"Internetam gâhi kheyli kond ast."},{"fr":"Nous faisons nos réunions en visioconférence.","tgt":"جلسه‌هایمان را به صورت تصویری برگزار می‌کنیم.","ro":"Jalasehâyemân râ be surat-e tasviri bargozâr mikonim."},{"fr":"Je me suis installé un petit bureau dans le salon.","tgt":"یک میز کار کوچک در پذیرایی گذاشته‌ام.","ro":"Yek miz-e kâr-e kuchek dar pazirâyi gozâshte-am."},{"fr":"Il est difficile de séparer le travail de la vie privée.","tgt":"جدا کردن کار از زندگی شخصی سخت است.","ro":"Jodâ kardan-e kâr az zendegi-ye shakhsi sakht ast."},{"fr":"Mes collègues me manquent un peu.","tgt":"دلم برای همکارهایم کمی تنگ می‌شود.","ro":"Delam barâye hamkârhâyam kami tang mishavad."},{"fr":"Je fais une pause toutes les deux heures.","tgt":"هر دو ساعت یک بار استراحت می‌کنم.","ro":"Har do sâ'at yek bâr esterâhat mikonam."},{"fr":"Mon chat adore s'asseoir sur mon clavier.","tgt":"گربه‌ام دوست دارد روی صفحه‌کلید بنشیند.","ro":"Gorbe-am dust dârad ru-ye safhekelid beneshinad."},{"fr":"À mon avis, un mélange des deux est l'idéal.","tgt":"به نظر من ترکیبی از هر دو بهترین است.","ro":"Be nazar-e man tarkibi az har do behtarin ast."}]},{"title":"Le départ d'un collègue","phrases":[{"fr":"Notre collègue Babak quitte l'entreprise à la fin du mois.","tgt":"همکارمان بابک آخر ماه از شرکت می‌رود.","ro":"Hamkâremân Bâbak âkhar-e mâh az sherkat miravad."},{"fr":"Il a trouvé un poste à Ispahan.","tgt":"او در اصفهان کار پیدا کرده است.","ro":"U dar Esfahân kâr peydâ karde ast."},{"fr":"Jeudi, nous organisons une petite fête pour lui.","tgt":"پنجشنبه برایش یک جشن کوچک می‌گیریم.","ro":"Panjshanbe barâyash yek jashn-e kuchek migirim."},{"fr":"Chacun met un peu d'argent pour acheter un cadeau.","tgt":"هر کس برای خرید هدیه پول می‌گذارد.","ro":"Har kas barâye kharid-e hediye pul migozârad."},{"fr":"Nous lui avons choisi un bel exemplaire des poèmes de Hafez.","tgt":"برایش یک نسخه‌ی زیبا از دیوان حافظ انتخاب کردیم.","ro":"Barâyash yek noskhe-ye zibâ az divân-e Hâfez entekhâb kardim."},{"fr":"Il a travaillé ici pendant presque dix ans.","tgt":"تقریبا ده سال اینجا کار کرد.","ro":"Taghriban dah sâl injâ kâr kard."},{"fr":"Tout le monde l'aimait pour sa gentillesse.","tgt":"همه به خاطر مهربانی‌اش دوستش داشتند.","ro":"Hame be khâter-e mehrabâni-ash dustash dâshtand."},{"fr":"Il a fait un petit discours très émouvant.","tgt":"یک سخنرانی کوتاه و خیلی احساسی کرد.","ro":"Yek sokhanrâni-ye kutâh va kheyli ehsâsi kard."},{"fr":"Nous nous promettons de rester en contact.","tgt":"قول می‌دهیم که در تماس بمانیم.","ro":"Ghol midahim ke dar tamâs bemânim."},{"fr":"Sans lui, son bureau va paraître bien vide.","tgt":"میزش بدون او خیلی خالی به نظر خواهد رسید.","ro":"Mizash bedun-e u kheyli khâli be nazar khâhad resid."}]},{"title":"Une visite chez le médecin","phrases":[{"fr":"J'ai pris rendez-vous chez un médecin généraliste.","tgt":"پیش یک پزشک عمومی نوبت گرفتم.","ro":"Pish-e yek pezeshk-e omumi nobat gereftam."},{"fr":"Depuis trois jours, j'ai mal à la gorge.","tgt":"سه روز است که گلویم درد می‌کند.","ro":"Se ruz ast ke guluyam dard mikonad."},{"fr":"Ce matin, la salle d'attente était pleine.","tgt":"اتاق انتظار امروز صبح پر بود.","ro":"Otâgh-e entezâr emruz sobh por bud."},{"fr":"Le médecin m'a examiné très attentivement.","tgt":"دکتر با دقت زیادی معاینه‌ام کرد.","ro":"Doktor bâ deghghat-e ziyâdi mo'âyene-am kard."},{"fr":"Il m'a prescrit des antibiotiques pour une semaine.","tgt":"برای یک هفته برایم آنتی‌بیوتیک نوشت.","ro":"Barâye yek hafte barâyam ântibiyotik nevesht."},{"fr":"La pharmacie est juste en face du dispensaire.","tgt":"داروخانه درست روبه‌روی درمانگاه است.","ro":"Dârukhâne dorost ruberu-ye darmângâh ast."},{"fr":"Je dois boire beaucoup d'infusions et me reposer.","tgt":"باید زیاد دمنوش بخورم و استراحت کنم.","ro":"Bâyad ziyâd damnush bokhoram va esterâhat konam."},{"fr":"Mon collègue m'a conseillé une infusion au gingembre.","tgt":"همکارم دمنوش زنجبیل را توصیه کرد.","ro":"Hamkâram damnush-e zanjabil râ tosiye kard."},{"fr":"J'ai envoyé le certificat médical à mon responsable.","tgt":"گواهی پزشکی را برای مدیرم فرستادم.","ro":"Govâhi-ye pezeshki râ barâye modiram ferestâdam."},{"fr":"Deux jours plus tard, j'allais déjà beaucoup mieux.","tgt":"دو روز بعد حالم خیلی بهتر شده بود.","ro":"Do ruz ba'd hâlam kheyli behtar shode bud."}]},{"title":"La voiture au garage","phrases":[{"fr":"Depuis hier, ma voiture fait un bruit bizarre.","tgt":"ماشینم از دیروز صدای عجیبی می‌دهد.","ro":"Mâshinam az diruz sedâ-ye ajibi midahad."},{"fr":"Je l'ai emmenée chez un mécanicien du quartier.","tgt":"آن را پیش یک مکانیک محل بردم.","ro":"Ân râ pish-e yek mekânik-e mahal bordam."},{"fr":"Il pense que les plaquettes de frein sont usées.","tgt":"فکر می‌کند لنت‌ها ساییده شده‌اند.","ro":"Fekr mikonad lenthâ sâyide shode-and."},{"fr":"La réparation prendra deux jours.","tgt":"تعمیرش دو روز طول می‌کشد.","ro":"Ta'mirash do ruz tul mikeshad."},{"fr":"Combien tout cela va-t-il me coûter ?","tgt":"همه‌ی این‌ها برایم چقدر خرج برمی‌دارد؟","ro":"Hame-ye inhâ barâyam cheghadr kharj barmidârad?"},{"fr":"Il m'a fait un prix honnête.","tgt":"قیمت منصفانه‌ای به من داد.","ro":"Gheymat-e monsefâne'i be man dâd."},{"fr":"En attendant, je me déplace en taxi commandé par application.","tgt":"تا آن موقع با تاکسی اینترنتی رفت‌وآمد می‌کنم.","ro":"Tâ ân moghe' bâ tâksi-ye interneti raftoâmad mikonam."},{"fr":"Je dois aussi passer le contrôle technique bientôt.","tgt":"باید به‌زودی معاینه‌ی فنی را هم انجام بدهم.","ro":"Bâyad bezudi mo'âyene-ye fanni râ ham anjâm bedaham."},{"fr":"L'essence est bon marché, mais conduire dans ces bouchons est épuisant.","tgt":"بنزین ارزان است، ولی رانندگی در این ترافیک خسته‌کننده است.","ro":"Benzin arzân ast, vali rânandegi dar in terâfik khastekonande ast."},{"fr":"Avec la voiture réparée, je pourrai partir vers la Caspienne.","tgt":"با ماشین تعمیرشده می‌توانم به سمت دریای خزر بروم.","ro":"Bâ mâshin-e ta'mirshode mitavânam be samt-e daryâ-ye Khazar beravam."}]},{"title":"La réunion des voisins","phrases":[{"fr":"Ce soir, une réunion des habitants a lieu dans le hall.","tgt":"امشب جلسه‌ی ساکنان ساختمان در لابی برگزار می‌شود.","ro":"Emshab jalase-ye sâkenân-e sâkhtemân dar lâbi bargozâr mishavad."},{"fr":"Le gardien a préparé du thé pour tout le monde.","tgt":"سرایدار برای همه چای آماده کرده است.","ro":"Serâydâr barâye hame chây âmâde karde ast."},{"fr":"Nous devons choisir un nouveau gestionnaire de l'immeuble.","tgt":"باید تصمیم بگیریم چه کسی مدیر ساختمان شود.","ro":"Bâyad tasmim begirim che kasi modir-e sâkhtemân shavad."},{"fr":"Ces temps-ci, l'ascenseur tombe souvent en panne.","tgt":"این روزها آسانسور اغلب خراب می‌شود.","ro":"In ruzhâ âsânsor aghlab kharâb mishavad."},{"fr":"Certains voisins se plaignent du bruit le soir.","tgt":"بعضی از همسایه‌ها از سروصدای شب‌ها شکایت دارند.","ro":"Ba'zi az hamsâyehâ az sarosedâ-ye shabhâ shekâyat dârand."},{"fr":"Le parking est trop petit pour toutes les voitures.","tgt":"پارکینگ برای همه‌ی ماشین‌ها خیلی کوچک است.","ro":"Pârking barâye hame-ye mâshinhâ kheyli kuchek ast."},{"fr":"La voisine du troisième propose de repeindre l'entrée.","tgt":"همسایه‌ی طبقه‌ی سوم پیشنهاد می‌کند ورودی را رنگ کنیم.","ro":"Hamsâye-ye tabaghe-ye sevvom pishnahâd mikonad vorudi râ rang konim."},{"fr":"Tout le monde n'est pas d'accord sur le budget.","tgt":"همه درباره‌ی بودجه موافق نیستند.","ro":"Hame darbâre-ye budje movâfegh nistand."},{"fr":"Après une heure de discussion, nous avons voté.","tgt":"بعد از یک ساعت بحث، رأی‌گیری کردیم.","ro":"Ba'd az yek sâ'at bahs, ra'ygiri kardim."},{"fr":"Ces réunions aident à mieux connaître ses voisins.","tgt":"این جلسه‌ها کمک می‌کنند همسایه‌ها را بهتر بشناسیم.","ro":"In jalasehâ komak mikonand hamsâyehâ râ behtar beshenâsim."}]},{"title":"Un dîner chez un collègue","phrases":[{"fr":"Mon collègue Kaveh nous a invités à dîner vendredi soir.","tgt":"همکارم کاوه ما را برای جمعه شب به شام دعوت کرده است.","ro":"Hamkâram Kâve mâ râ barâye jom'e shab be shâm da'vat karde ast."},{"fr":"Comme le veut la coutume, j'ai apporté une boîte de pâtisseries.","tgt":"طبق رسم، یک جعبه شیرینی بردم.","ro":"Tebgh-e rasm, yek ja'be shirini bordam."},{"fr":"Sa mère avait préparé un vrai festin.","tgt":"مادرش یک سفره‌ی حسابی چیده بود.","ro":"Mâdarash yek sofre-ye hesâbi chide bud."},{"fr":"Il y avait du fesenjan, du kebab et trois sortes de riz.","tgt":"فسنجان و کباب و سه جور پلو بود.","ro":"Fesenjân va kabâb va se jur polo bud."},{"fr":"Ils insistaient sans cesse pour que je me resserve.","tgt":"مدام اصرار می‌کردند که باز هم بکشم.","ro":"Modâm esrâr mikardand ke bâz ham bekesham."},{"fr":"Après le dîner, le grand-père a récité quelques vers de Hafez.","tgt":"بعد از شام، پدربزرگ چند بیت از حافظ خواند.","ro":"Ba'd az shâm, pedarbozorg chand beyt az Hâfez khând."},{"fr":"Nous avons parlé de tout, sauf du travail.","tgt":"درباره‌ی همه چیز حرف زدیم جز کار.","ro":"Darbâre-ye hame chiz harf zadim joz kâr."},{"fr":"Leur fils voulait pratiquer son français avec moi.","tgt":"پسرشان می‌خواست با من فرانسه تمرین کند.","ro":"Pesarashân mikhâst bâ man farânse tamrin konad."},{"fr":"La soirée s'est terminée bien après minuit.","tgt":"مهمانی خیلی بعد از نیمه‌شب تمام شد.","ro":"Mehmâni kheyli ba'd az nimeshab tamâm shod."},{"fr":"En partant, nous les avons invités chez nous à notre tour.","tgt":"موقع رفتن، ما هم آن‌ها را به خانه‌مان دعوت کردیم.","ro":"Moghe'-e raftan, mâ ham ânhâ râ be khânemân da'vat kardim."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module m'a appris à parler du travail en persan.","tgt":"این بخش به من یاد داد که درباره‌ی کار به فارسی حرف بزنم.","ro":"In bakhsh be man yâd dâd ke darbâre-ye kâr be fârsi harf bezanam."},{"fr":"Je sais maintenant utiliser le passif avec « shodan ».","tgt":"حالا می‌توانم از مجهول با «شدن» استفاده کنم.","ro":"Hâlâ mitavânam az majhul bâ «shodan» estefâde konam."},{"fr":"Je comprends mieux le langage formel des réunions.","tgt":"زبان رسمی جلسه‌ها را بهتر می‌فهمم.","ro":"Zabân-e rasmi-ye jalasehâ râ behtar mifahmam."},{"fr":"Je sais remercier un visiteur avec les bonnes formules.","tgt":"می‌توانم با جمله‌های درست از یک مهمان تشکر کنم.","ro":"Mitavânam bâ jomlehâ-ye dorost az yek mehmân tashakkor konam."},{"fr":"Le causatif me pose encore quelques difficultés.","tgt":"هنوز در فعل‌های سببی کمی مشکل دارم.","ro":"Hanuz dar fe'lhâ-ye sababi kami moshkel dâram."},{"fr":"J'arrive même à me plaindre des embouteillages en persan !","tgt":"حتی می‌توانم به فارسی از ترافیک گله کنم!","ro":"Hattâ mitavânam be fârsi az terâfik gele konam!"},{"fr":"Négocier un loyer ne me fait plus peur.","tgt":"چانه زدن سر اجاره دیگر مرا نمی‌ترساند.","ro":"Châne zadan sar-e ejâre digar marâ nemitarsânad."},{"fr":"Je réécoute les phrases difficiles pendant mes trajets.","tgt":"جمله‌های سخت را در راه دوباره گوش می‌دهم.","ro":"Jomlehâ-ye sakht râ dar râh dobâre gush midaham."},{"fr":"Mes collègues iraniens remarquent mes progrès.","tgt":"همکارهای ایرانی‌ام پیشرفتم را می‌بینند.","ro":"Hamkârhâ-ye irâni-am pishraftam râ mibinand."},{"fr":"Je suis prêt pour le module suivant, consacré au voyage.","tgt":"برای بخش بعدی که درباره‌ی سفر است آماده‌ام.","ro":"Barâye bakhsh-e ba'di ke darbâre-ye safar ast âmâde-am."}]}]},{"id":2,"name":"En voyage","desc":"Des aventures de voyage plus poussées et plus authentiques.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Sur la route de la Caspienne","phrases":[{"fr":"Après des heures de route, on aperçoit enfin la mer Caspienne.","tgt":"بعد از ساعت‌ها رانندگی، بالاخره دریای خزر را می‌بینیم.","ro":"Ba'd az sâ'at-hâ rânandegi, belakhare daryâ-ye Khazar râ mibinim."},{"fr":"L'air devient soudain plus humide et plus doux.","tgt":"هوا ناگهان مرطوب‌تر و ملایم‌تر می‌شود.","ro":"Havâ nâgahân martubtar o molâyemtar mishavad."},{"fr":"Ici, les montagnes descendent presque jusqu'au bord de l'eau.","tgt":"اینجا کوه‌ها تقریبا تا لب دریا پایین می‌آیند.","ro":"Injâ kuh-hâ taghriban tâ lab-e daryâ pâyin miâyand."},{"fr":"Tout est vert, même en plein cœur de l'été.","tgt":"همه‌جا سبز است، حتی وسط تابستان.","ro":"Hamejâ sabz ast, hattâ vasat-e tâbestân."},{"fr":"Les gens du nord sont réputés pour leur hospitalité.","tgt":"مردم شمال به مهمان‌نوازی معروف‌اند.","ro":"Mardom-e shomâl be mehmân-navâzi ma'rufand."},{"fr":"Nous avons loué une petite voiture pour longer toute la côte.","tgt":"یک ماشین کوچک کرایه کرده‌ایم تا در طول ساحل سفر کنیم.","ro":"Yek mâshin-e kuchek kerâye karde'im tâ dar tul-e sâhel safar konim."},{"fr":"La route côtière traverse des dizaines de petites villes.","tgt":"جاده‌ی ساحلی از ده‌ها شهر کوچک می‌گذرد.","ro":"Jâdde-ye sâheli az dah-hâ shahr-e kuchek migozarad."},{"fr":"Chaque ville a son propre marché et ses plats typiques.","tgt":"هر شهری بازار و غذاهای مخصوص خودش را دارد.","ro":"Har shahri bâzâr o ghazâ-hâ-ye makhsus-e khodash râ dârad."},{"fr":"Les Téhéranais viennent souvent ici le week-end.","tgt":"تهرانی‌ها آخر هفته‌ها زیاد به اینجا می‌آیند.","ro":"Tehrâni-hâ âkhar-e hafte-hâ ziyâd be injâ miâyand."},{"fr":"On comprend vite pourquoi tout le monde aime cette région.","tgt":"زود می‌فهمیم چرا همه این منطقه را دوست دارند.","ro":"Zud mifahmim cherâ hame in mantaghe râ dust dârand."}]},{"title":"Un hôtel au bord de la mer","phrases":[{"fr":"Nous cherchons un hôtel qui soit tout près de la plage.","tgt":"دنبال هتلی هستیم که نزدیک ساحل باشد.","ro":"Donbâl-e hoteli hastim ke nazdik-e sâhel bâshad."},{"fr":"L'hôtel que vous nous avez recommandé est complet.","tgt":"هتلی که به ما پیشنهاد کردید پر است.","ro":"Hoteli ke be mâ pishnahâd kardid por ast."},{"fr":"Avez-vous une chambre qui donne sur la mer ?","tgt":"اتاقی دارید که رو به دریا باشد؟","ro":"Otâghi dârid ke ru be daryâ bâshad?"},{"fr":"La dame qui travaille à la réception est très gentille.","tgt":"خانمی که در پذیرش کار می‌کند خیلی مهربان است.","ro":"Khânomi ke dar paziresh kâr mikonad kheyli mehrabân ast."},{"fr":"C'est bien la chambre que nous avons réservée ?","tgt":"این همان اتاقی است که رزرو کردیم؟","ro":"In hamân otâghi ast ke rezerv kardim?"},{"fr":"Le restaurant qui est au rez-de-chaussée a du poisson frais.","tgt":"رستورانی که طبقه‌ی پایین است ماهی تازه دارد.","ro":"Restorâni ke tabaghe-ye pâyin ast mâhi-ye tâze dârad."},{"fr":"Je ne retrouve pas la clé que vous m'avez donnée.","tgt":"کلیدی را که به من دادید پیدا نمی‌کنم.","ro":"Kelidi râ ke be man dâdid peydâ nemikonam."},{"fr":"Les gens qui viennent ici reviennent souvent chaque année.","tgt":"کسانی که به اینجا می‌آیند، اغلب هر سال برمی‌گردند.","ro":"Kasâni ke be injâ miâyand, aghlab har sâl barmigardand."},{"fr":"Il y a un sentier qui descend directement à la plage.","tgt":"راهی هست که مستقیم به ساحل می‌رود.","ro":"Râhi hast ke mostaghim be sâhel miravad."},{"fr":"C'est exactement l'endroit dont nous rêvions.","tgt":"این دقیقا همان جایی است که آرزویش را داشتیم.","ro":"In daghighan hamân jâyi ast ke ârezuyash râ dâshtim."}],"tip":{"title":"Les relatives avec « ke » et le « -i » : « hotel-i ke »","example":"L'hôtel que vous nous avez recommandé est complet. — <b>هتلی که</b> به ما پیشنهاد کردید پر است.","body":"Pour dire « l'hôtel que » ou « une chambre qui », le persan ajoute un petit « -i » à la fin du nom, puis le mot « ke », qui veut dire à la fois qui, que et où. Décomposons « hoteli ke be mâ pishnahâd kardid por ast » : « hoteli », cet hôtel-là, « ke », que, « be mâ pishnahâd kardid », vous nous avez proposé, et enfin « por ast », est plein. Ce « -i » prévient l'oreille qu'une précision arrive, comme une porte qu'on entrouvre. Vous l'entendrez partout : « otâghi ke ru be daryâ bâshad », une chambre qui donne sur la mer, ou « râhi ke be sâhel miravad », un chemin qui va à la plage. Quand le nom est l'objet, le « râ » se glisse juste après le « -i » : « kelidi râ ke dâdid », la clé que vous avez donnée. Astuce : dites « -i ke » d'un seul souffle, comme un seul mot, et vos phrases couleront toutes seules.","exampleRo":"Hoteli ke be mâ pishnahâd kardid por ast.","lit":"hôtel-[i] · que · [à] · nous · proposition · avez faite · plein · est","say":{"ke":"که","hotel-i ke":"هتلی که","hoteli ke be mâ pishnahâd kardid por ast":"هتلی که به ما پیشنهاد کردید پر است","hoteli":"هتلی","be mâ pishnahâd kardid":"به ما پیشنهاد کردید","por ast":"پر است","otâghi ke ru be daryâ bâshad":"اتاقی که رو به دریا باشد","râhi ke be sâhel miravad":"راهی که به ساحل می‌رود","râ":"را","kelidi râ ke dâdid":"کلیدی را که دادید"}}},{"title":"Les rizières du Guilan","phrases":[{"fr":"Au printemps, les rizières ressemblent à de grands miroirs.","tgt":"در بهار، شالیزارها مثل آینه‌های بزرگ‌اند.","ro":"Dar bahâr, shâlizâr-hâ mesl-e âyene-hâ-ye bozorgand."},{"fr":"Les femmes repiquent le riz à la main, dans l'eau.","tgt":"زن‌ها برنج را با دست و در آب نشا می‌کنند.","ro":"Zan-hâ berenj râ bâ dast va dar âb neshâ mikonand."},{"fr":"Ce travail est épuisant, mais il se fait en chantant.","tgt":"این کار خسته‌کننده است، اما با آواز انجام می‌شود.","ro":"In kâr khaste-konande ast, ammâ bâ âvâz anjâm mishavad."},{"fr":"Le riz du nord est considéré comme le meilleur du pays.","tgt":"برنج شمال بهترین برنج کشور به شمار می‌رود.","ro":"Berenj-e shomâl behtarin berenj-e keshvar be shomâr miravad."},{"fr":"La récolte se fait à la fin de l'été.","tgt":"برداشت در آخر تابستان انجام می‌شود.","ro":"Bardâsht dar âkhar-e tâbestân anjâm mishavad."},{"fr":"Un paysan nous a expliqué comment on fait sécher le riz.","tgt":"یک کشاورز برایمان توضیح داد که برنج را چطور خشک می‌کنند.","ro":"Yek keshâvarz barâyemân tozih dâd ke berenj râ chetor khoshk mikonand."},{"fr":"Chaque famille garde une partie de la récolte pour elle-même.","tgt":"هر خانواده بخشی از محصول را برای خودش نگه می‌دارد.","ro":"Har khânevâde bakhshi az mahsul râ barâye khodash negah midârad."},{"fr":"Au milieu des champs, on aperçoit des maisons en bois.","tgt":"وسط مزرعه‌ها خانه‌های چوبی دیده می‌شود.","ro":"Vasat-e mazra'e-hâ khâne-hâ-ye chubi dide mishavad."},{"fr":"Le soir, le chant des grenouilles ne s'arrête jamais.","tgt":"شب‌ها صدای قورباغه‌ها هیچ‌وقت قطع نمی‌شود.","ro":"Shab-hâ sedâ-ye ghurbâghe-hâ hichvaght ghat' nemishavad."},{"fr":"Après ce séjour, je ne regarderai plus une assiette de riz de la même façon.","tgt":"بعد از این سفر، دیگر به یک بشقاب برنج همان‌طور نگاه نمی‌کنم.","ro":"Ba'd az in safar, digar be yek boshghâb berenj hamântor negâh nemikonam."}]},{"title":"Le marché aux poissons d'Anzali","phrases":[{"fr":"On s'est levés tôt pour voir arriver les bateaux de pêche.","tgt":"صبح زود بیدار شدیم برای اینکه آمدن قایق‌های ماهیگیری را ببینیم.","ro":"Sobh-e zud bidâr shodim barâye inke âmadan-e ghâyegh-hâ-ye mâhigiri râ bebinim."},{"fr":"Les pêcheurs partent la nuit pour que le poisson soit frais le matin.","tgt":"ماهیگیرها شب می‌روند برای اینکه ماهی صبح تازه باشد.","ro":"Mâhigir-hâ shab miravand barâye inke mâhi sobh tâze bâshad."},{"fr":"Il faut arriver avant sept heures pour trouver les plus beaux poissons.","tgt":"باید قبل از ساعت هفت برسید برای اینکه بهترین ماهی‌ها را پیدا کنید.","ro":"Bâyad ghabl az sâ'at-e haft beresid barâye inke behtarin mâhi-hâ râ peydâ konid."},{"fr":"Le vendeur nettoie le poisson sur place pour vous éviter la corvée.","tgt":"فروشنده ماهی را همان‌جا تمیز می‌کند برای اینکه شما زحمتی نداشته باشید.","ro":"Forushande mâhi râ hamânjâ tamiz mikonad barâye inke shomâ zahmati nadâshte bâshid."},{"fr":"On fume aussi le poisson pour pouvoir le garder tout l'hiver.","tgt":"ماهی را دودی هم می‌کنند برای اینکه بتوانند تمام زمستان نگهش دارند.","ro":"Mâhi râ dudi ham mikonand barâye inke betavânand tamâm-e zemestân negahash dârand."},{"fr":"J'ai demandé le prix deux fois pour être sûr d'avoir bien compris.","tgt":"قیمت را دو بار پرسیدم برای اینکه مطمئن شوم درست فهمیده‌ام.","ro":"Gheymat râ do bâr porsidam barâye inke motma'en shavam dorost fahmide'am."},{"fr":"Ce poisson coûte cent cinquante mille tomans le kilo.","tgt":"این ماهی کیلویی صد و پنجاه هزار تومان است.","ro":"In mâhi kiluyi sad o panjâh hezâr tomân ast."},{"fr":"Le marchand a ajouté un petit poisson pour me faire plaisir.","tgt":"فروشنده یک ماهی کوچک اضافه داد برای اینکه خوشحالم کند.","ro":"Forushande yek mâhi-ye kuchek ezâfe dâd barâye inke khoshhâlam konad."},{"fr":"Les mouettes tournent au-dessus du port pour attraper les restes.","tgt":"مرغ‌های دریایی بالای بندر می‌چرخند برای اینکه تکه‌های باقی‌مانده را بگیرند.","ro":"Morgh-hâ-ye daryâyi bâlâ-ye bandar micharkhand barâye inke tekke-hâ-ye bâghimânde râ begirand."},{"fr":"On a pris des photos pour les montrer à nos amis en France.","tgt":"عکس گرفتیم برای اینکه به دوستانمان در فرانسه نشان بدهیم.","ro":"Aks gereftim barâye inke be dustânemân dar Farânse neshân bedahim."}],"tip":{"title":"« Barâye inke » : pour, afin de","example":"Les pêcheurs partent la nuit pour que le poisson soit frais le matin. — ماهیگیرها شب می‌روند <b>برای اینکه</b> ماهی صبح تازه باشد.","body":"« Barâye inke » se construit exactement comme notre « pour que » : « barâye » veut dire pour, et « inke » veut dire que. Juste après, le verbe se met au subjonctif, la forme en « be- » que vous connaissez déjà : « barâye inke bebinim », pour que nous voyions, autrement dit pour voir. Le persan n'utilise pas d'infinitif ici, il redit toujours la personne : « barâye inke peydâ konid », pour que vous trouviez. Dans « mâhigir-hâ shab miravand barâye inke mâhi sobh tâze bâshad », on entend mot à mot : les pêcheurs, la nuit, partent, pour que, le poisson, le matin, frais, soit. Attention, suivi d'un verbe ordinaire et non du subjonctif, « barâye inke » signifie plutôt parce que. Astuce : pour une phrase plus courte, on peut aussi dire simplement « tâ », comme dans « tâ bebinid », pour voir.","exampleRo":"Mâhigir-hâ shab miravand barâye inke mâhi sobh tâze bâshad.","lit":"pêcheurs · nuit · partent · pour · que · poisson · matin · frais · soit","say":{"Barâye inke":"برای اینکه","barâye":"برای","inke":"اینکه","barâye inke bebinim":"برای اینکه ببینیم","barâye inke peydâ konid":"برای اینکه پیدا کنید","mâhigir-hâ shab miravand barâye inke mâhi sobh tâze bâshad":"ماهیگیرها شب می‌روند برای اینکه ماهی صبح تازه باشد","barâye inke":"برای اینکه","tâ":"تا","tâ bebinid":"تا ببینید"}}},{"title":"Une nuit chez l'habitant","phrases":[{"fr":"Une famille du village nous a proposé de passer la nuit chez elle.","tgt":"یک خانواده‌ی روستایی به ما پیشنهاد داد که شب را پیش آن‌ها بمانیم.","ro":"Yek khânevâde-ye rustâyi be mâ pishnahâd dâd ke shab râ pish-e ânhâ bemânim."},{"fr":"La maison est faite en bois et posée sur de hauts piliers.","tgt":"خانه از چوب ساخته شده و روی پایه‌های بلند است.","ro":"Khâne az chub sâkhte shode va ru-ye pâye-hâ-ye boland ast."},{"fr":"La grand-mère a préparé du riz avec du poisson grillé.","tgt":"مادربزرگ برنج و ماهی کبابی درست کرد.","ro":"Mâdarbozorg berenj o mâhi-ye kabâbi dorost kard."},{"fr":"On mange assis par terre, autour d'une grande nappe.","tgt":"روی زمین، دور یک سفره‌ی بزرگ نشسته غذا می‌خوریم.","ro":"Ru-ye zamin, dor-e yek sofre-ye bozorg neshaste ghazâ mikhorim."},{"fr":"Ils ont insisté pour qu'on se resserve de tout.","tgt":"اصرار کردند که از همه چیز دوباره بکشیم.","ro":"Esrâr kardand ke az hame chiz dobâre bekeshim."},{"fr":"Selon eux, on fait moins de ta'ârof ici qu'à Téhéran.","tgt":"به گفته‌ی آن‌ها، اینجا تعارف کمتر از تهران است.","ro":"Be gofte-ye ânhâ, injâ ta'ârof kamtar az Tehrân ast."},{"fr":"Le grand-père nous a raconté des histoires de son enfance.","tgt":"پدربزرگ از بچگی‌اش برایمان قصه تعریف کرد.","ro":"Pedarbozorg az bachegi'ash barâyemân ghesse ta'rif kard."},{"fr":"Entre eux, ils parlent guilaki, mais avec nous, ils parlent persan.","tgt":"بین خودشان گیلکی حرف می‌زنند، اما با ما فارسی.","ro":"Beyn-e khodeshân gilaki harf mizanand, ammâ bâ mâ fârsi."},{"fr":"Le matin, on s'est réveillés au chant du coq.","tgt":"صبح با صدای خروس بیدار شدیم.","ro":"Sobh bâ sedâ-ye khorus bidâr shodim."},{"fr":"Au moment du départ, ils nous ont offert un sac de riz.","tgt":"وقت رفتن، یک کیسه برنج به ما دادند.","ro":"Vaght-e raftan, yek kise berenj be mâ dâdand."}]},{"title":"La forêt sous la pluie","phrases":[{"fr":"Les forêts du nord comptent parmi les plus anciennes du monde.","tgt":"جنگل‌های شمال از قدیمی‌ترین جنگل‌های دنیا هستند.","ro":"Jangal-hâ-ye shomâl az ghadimitarin jangal-hâ-ye donyâ hastand."},{"fr":"Il a plu toute la nuit, et la brume couvre encore les arbres.","tgt":"تمام شب باران آمد و هنوز مه روی درخت‌ها را پوشانده است.","ro":"Tamâm-e shab bârân âmad va hanuz meh ru-ye derakht-hâ râ pushânde ast."},{"fr":"Le sentier est glissant, faites attention où vous mettez les pieds.","tgt":"راه لیز است، مواظب جای پایتان باشید.","ro":"Râh liz ast, movâzeb-e jâ-ye pâyetân bâshid."},{"fr":"On entend le bruit de l'eau de tous les côtés.","tgt":"صدای آب از هر طرف شنیده می‌شود.","ro":"Sedâ-ye âb az har taraf shenide mishavad."},{"fr":"Certains arbres ici ont plus de cinq cents ans.","tgt":"بعضی از درخت‌های اینجا بیشتر از پانصد سال عمر دارند.","ro":"Ba'zi az derakht-hâ-ye injâ bishtar az pânsad sâl omr dârand."},{"fr":"Le guide nous montre les champignons auxquels il ne faut pas toucher.","tgt":"راهنما قارچ‌هایی را نشانمان می‌دهد که نباید به آن‌ها دست زد.","ro":"Râhnamâ ghârch-hâyi râ neshânemân midahad ke nabâyad be ânhâ dast zad."},{"fr":"Même sous la pluie, cette promenade est merveilleuse.","tgt":"حتی زیر باران، این پیاده‌روی فوق‌العاده است.","ro":"Hattâ zir-e bârân, in piyâderavi fogholâde ast."},{"fr":"Au bout d'une heure, nos chaussures étaient trempées.","tgt":"بعد از یک ساعت کفش‌هایمان خیس خیس بود.","ro":"Ba'd az yek sâ'at kafsh-hâyemân khis-e khis bud."},{"fr":"Un vieux berger nous a offert du thé dans sa cabane.","tgt":"یک چوپان پیر در کلبه‌اش به ما چای تعارف کرد.","ro":"Yek chupân-e pir dar kolbe'ash be mâ chây ta'ârof kard."},{"fr":"Rien ne vaut l'odeur de la forêt après la pluie.","tgt":"هیچ چیز به پای بوی جنگل بعد از باران نمی‌رسد.","ro":"Hich chiz be pâ-ye bu-ye jangal ba'd az bârân nemiresad."}]},{"title":"Masuleh, le village en escalier","phrases":[{"fr":"On nous avait dit que les toits servaient de ruelles.","tgt":"به ما گفته بودند که پشت‌بام‌ها کار کوچه را می‌کنند.","ro":"Be mâ gofte budand ke poshtbâm-hâ kâr-e kuche râ mikonand."},{"fr":"Jusque-là, je n'avais jamais vu un village pareil.","tgt":"تا آن موقع چنین روستایی ندیده بودم.","ro":"Tâ ân moghe' chenin rustâyi nadide budam."},{"fr":"Quand nous sommes arrivés, le brouillard avait tout recouvert.","tgt":"وقتی رسیدیم، مه همه‌جا را گرفته بود.","ro":"Vaghti residim, meh hamejâ râ gerefte bud."},{"fr":"Mes amis étaient déjà venus ici il y a dix ans.","tgt":"دوستانم ده سال پیش یک بار اینجا آمده بودند.","ro":"Dustânam dah sâl pish yek bâr injâ âmade budand."},{"fr":"Ils nous avaient conseillé de dormir sur place.","tgt":"به ما توصیه کرده بودند که شب همین‌جا بمانیم.","ro":"Be mâ tosiye karde budand ke shab haminjâ bemânim."},{"fr":"Heureusement, j'avais réservé une chambre à l'avance.","tgt":"خوشبختانه از قبل یک اتاق رزرو کرده بودم.","ro":"Khoshbakhtâne az ghabl yek otâgh rezerv karde budam."},{"fr":"Le vieux marchand avait passé toute sa vie dans ce village.","tgt":"پیرمرد فروشنده تمام عمرش را در این روستا گذرانده بود.","ro":"Piremard-e forushande tamâm-e omrash râ dar in rustâ gozarânde bud."},{"fr":"Nous étions partis sans parapluie, quelle erreur !","tgt":"بدون چتر راه افتاده بودیم، چه اشتباهی!","ro":"Bedun-e chatr râh oftâde budim, che eshtebâhi!"},{"fr":"Les biscuits du village étaient meilleurs que ce que nous avions imaginé.","tgt":"شیرینی‌های محلی از آنچه فکر کرده بودیم خوشمزه‌تر بودند.","ro":"Shirini-hâ-ye mahalli az ânche fekr karde budim khoshmazetar budand."},{"fr":"Avant ce voyage, je n'étais jamais monté aussi haut.","tgt":"قبل از این سفر، هیچ‌وقت تا این ارتفاع بالا نرفته بودم.","ro":"Ghabl az in safar, hichvaght tâ in ertefâ' bâlâ narafte budam."}],"tip":{"title":"Le plus-que-parfait : « rafte budam »","example":"Avant ce voyage, je n'étais jamais monté aussi haut. — قبل از این سفر، هیچ‌وقت تا این ارتفاع بالا <b>نرفته بودم</b>.","body":"Le plus-que-parfait persan ressemble beaucoup au nôtre : un participe, puis le verbe être au passé. On prend le participe en « -e », comme « rafte », allé, « dide », vu, ou « gofte », dit, et on ajoute « budam », « budi », « bud », « budim », « budid » ou « budand ». « Rafte budam » se dit donc mot à mot « allé j'étais », c'est-à-dire j'étais allé. Pour la négation, le « na- » se colle au participe : « narafte budam », je n'étais pas allé, « nadide budam », je n'avais pas vu. Comme en français, il sert à placer un fait avant un autre moment du passé : « vaghti residim, meh hamejâ râ gerefte bud », quand nous sommes arrivés, le brouillard avait tout recouvert. Astuce : ici, pas de choix entre avoir et être comme en français, c'est toujours « bud », et ça simplifie bien la vie.","exampleRo":"Ghabl az in safar, hichvaght tâ in ertefâ' bâlâ narafte budam.","lit":"avant · de · ce · voyage · jamais · jusqu'à · cette · hauteur · en haut · [ne… pas]-allé · j'étais","say":{"rafte budam":"رفته بودم","rafte":"رفته","dide":"دیده","gofte":"گفته","budam":"بودم","budi":"بودی","bud":"بود","budim":"بودیم","budid":"بودید","budand":"بودند","Rafte budam":"رفته بودم","narafte budam":"نرفته بودم","nadide budam":"ندیده بودم","vaghti residim, meh hamejâ râ gerefte bud":"وقتی رسیدیم، مه همه‌جا را گرفته بود"}}},{"title":"Le train à travers les montagnes","phrases":[{"fr":"Le train de Téhéran à Sari traverse la chaîne de l'Alborz.","tgt":"قطار تهران به ساری از رشته‌کوه البرز می‌گذرد.","ro":"Ghatâr-e Tehrân be Sâri az reshtekuh-e Alborz migozarad."},{"fr":"Cette ligne a été construite il y a presque un siècle.","tgt":"این خط تقریبا صد سال پیش ساخته شده است.","ro":"In khat taghriban sad sâl pish sâkhte shode ast."},{"fr":"Le train passe par des dizaines de tunnels.","tgt":"قطار از ده‌ها تونل عبور می‌کند.","ro":"Ghatâr az dah-hâ tunel obur mikonad."},{"fr":"Le pont de Veresk est l'un des plus célèbres du pays.","tgt":"پل ورسک یکی از معروف‌ترین پل‌های کشور است.","ro":"Pol-e Veresk yeki az ma'ruftarin pol-hâ-ye keshvar ast."},{"fr":"Asseyez-vous du côté gauche pour avoir la plus belle vue.","tgt":"سمت چپ بنشینید تا بهترین منظره را ببینید.","ro":"Samt-e chap beneshinid tâ behtarin manzare râ bebinid."},{"fr":"En quelques heures, le paysage passe du désert à la forêt.","tgt":"منظره در چند ساعت از بیابان به جنگل تغییر می‌کند.","ro":"Manzare dar chand sâ'at az biyâbân be jangal taghyir mikonad."},{"fr":"Derrière chaque virage, une nouvelle vallée apparaît.","tgt":"پشت هر پیچ، دره‌ی تازه‌ای پیدا می‌شود.","ro":"Posht-e har pich, darre-ye tâze'i peydâ mishavad."},{"fr":"Le train avance lentement, et c'est tant mieux.","tgt":"قطار آهسته حرکت می‌کند و چه بهتر.","ro":"Ghatâr âheste harekat mikonad va che behtar."},{"fr":"Un vendeur passe dans les wagons avec du thé et des gâteaux.","tgt":"یک فروشنده با چای و کیک توی واگن‌ها می‌گردد.","ro":"Yek forushande bâ chây o keyk tu-ye vâgon-hâ migardad."},{"fr":"Ce trajet vaut à lui seul tout le voyage.","tgt":"همین مسیر به‌تنهایی ارزش سفر را دارد.","ro":"Hamin masir betanhâyi arzesh-e safar râ dârad."}]},{"title":"Une rencontre dans le compartiment","phrases":[{"fr":"Une famille de Sari partage notre compartiment.","tgt":"یک خانواده از ساری در کوپه‌ی ما هستند.","ro":"Yek khânevâde az Sâri dar kupe-ye mâ hastand."},{"fr":"Dès le début, ils ont sorti des fruits et des graines.","tgt":"همان اول میوه و تخمه درآوردند.","ro":"Hamân avval mive o tokhme darâvardand."},{"fr":"Impossible de refuser sans les vexer.","tgt":"نمی‌شود رد کرد بدون اینکه دلخور شوند.","ro":"Nemishavad rad kard bedun-e inke delkhor shavand."},{"fr":"Le père m'a demandé d'où je venais et ce que je faisais.","tgt":"پدر خانواده پرسید اهل کجا هستم و چه کار می‌کنم.","ro":"Pedar-e khânevâde porsid ahl-e kojâ hastam va che kâr mikonam."},{"fr":"Il était surpris qu'un Français parle persan.","tgt":"تعجب کرد که یک فرانسوی فارسی حرف می‌زند.","ro":"Ta'ajjob kard ke yek farânsavi fârsi harf mizanad."},{"fr":"Leur fille étudie le français à l'université.","tgt":"دخترشان در دانشگاه زبان فرانسه می‌خواند.","ro":"Dokhtareshân dar dâneshgâh zabân-e farânse mikhânad."},{"fr":"Avant d'arriver, nous avons échangé nos numéros.","tgt":"قبل از رسیدن، شماره‌هایمان را به هم دادیم.","ro":"Ghabl az residan, shomâre-hâyemân râ be ham dâdim."},{"fr":"Ils nous ont invités à déjeuner chez eux le lendemain.","tgt":"ما را برای فردای آن روز به ناهار دعوت کردند.","ro":"Mâ râ barâye fardâ-ye ân ruz be nâhâr da'vat kardand."},{"fr":"En Iran, un voyage en train se termine rarement sans une nouvelle amitié.","tgt":"در ایران، سفر با قطار کمتر بدون یک دوستی تازه تمام می‌شود.","ro":"Dar Irân, safar bâ ghatâr kamtar bedun-e yek dusti-ye tâze tamâm mishavad."},{"fr":"Ces quelques heures sont passées comme quelques minutes.","tgt":"این چند ساعت مثل چند دقیقه گذشت.","ro":"In chand sâ'at mesl-e chand daghighe gozasht."}]},{"title":"Les plantations de thé de Lahijan","phrases":[{"fr":"Lahijan est la capitale du thé iranien.","tgt":"لاهیجان پایتخت چای ایران است.","ro":"Lâhijân pâytakht-e chây-e Irân ast."},{"fr":"Les collines sont couvertes de théiers à perte de vue.","tgt":"تپه‌ها تا چشم کار می‌کند پوشیده از بوته‌های چای‌اند.","ro":"Tappe-hâ tâ cheshm kâr mikonad pushide az bute-hâ-ye châyand."},{"fr":"Au printemps, les feuilles sont cueillies à la main.","tgt":"برگ‌ها در بهار با دست چیده می‌شوند.","ro":"Barg-hâ dar bahâr bâ dast chide mishavand."},{"fr":"Nous visitons une petite usine où l'on fait sécher le thé.","tgt":"از یک کارخانه‌ی کوچک دیدن می‌کنیم که در آن چای خشک می‌شود.","ro":"Az yek kârkhâne-ye kuchek didan mikonim ke dar ân chây khoshk mishavad."},{"fr":"Le thé du nord est plus léger que celui qu'on boit d'habitude.","tgt":"چای شمال از چایی که معمولا می‌خوریم سبک‌تر است.","ro":"Chây-e shomâl az châyi ke ma'mulan mikhorim saboktar ast."},{"fr":"Le propriétaire nous a préparé trois sortes de thé.","tgt":"صاحب باغ سه نوع چای برایمان دم کرد.","ro":"Sâheb-e bâgh se no' chây barâyemân dam kard."},{"fr":"En Iran, on boit le thé avec un morceau de sucre dans la bouche.","tgt":"در ایران، چای را با یک حبه قند در دهان می‌خورند.","ro":"Dar Irân, chây râ bâ yek habbe ghand dar dahân mikhorand."},{"fr":"Du haut de la colline, on voit la ville et la mer.","tgt":"از بالای تپه، شهر و دریا دیده می‌شوند.","ro":"Az bâlâ-ye tappe, shahr o daryâ dide mishavand."},{"fr":"J'ai acheté un kilo de thé pour ma famille.","tgt":"برای خانواده‌ام یک کیلو چای خریدم.","ro":"Barâye khânevâde'am yek kilu chây kharidam."},{"fr":"Chaque verre de thé me fera penser à ces collines.","tgt":"با هر استکان چای به یاد این تپه‌ها می‌افتم.","ro":"Bâ har estekân chây be yâd-e in tappe-hâ mioftam."}]},{"title":"Un jour de pluie à Rasht","phrases":[{"fr":"À Rasht, il pleut presque un jour sur deux.","tgt":"در رشت تقریبا یک روز در میان باران می‌بارد.","ro":"Dar Rasht taghriban yek ruz dar miyân bârân mibârad."},{"fr":"Les gens d'ici ne sortent jamais sans parapluie.","tgt":"مردم اینجا هیچ‌وقت بدون چتر بیرون نمی‌روند.","ro":"Mardom-e injâ hichvaght bedun-e chatr birun nemiravand."},{"fr":"Nous nous sommes réfugiés dans un petit café près de la place.","tgt":"به یک کافه‌ی کوچک نزدیک میدان پناه بردیم.","ro":"Be yek kâfe-ye kuchek nazdik-e meydân panâh bordim."},{"fr":"La pluie rend les couleurs de la ville encore plus vives.","tgt":"باران رنگ‌های شهر را زنده‌تر می‌کند.","ro":"Bârân rang-hâ-ye shahr râ zendetar mikonad."},{"fr":"Rasht est célèbre pour sa cuisine, la meilleure du nord selon beaucoup.","tgt":"رشت به غذاهایش معروف است، به نظر خیلی‌ها بهترین غذاهای شمال.","ro":"Rasht be ghazâ-hâyash ma'ruf ast, be nazar-e kheyli-hâ behtarin ghazâ-hâ-ye shomâl."},{"fr":"Dans le bazar couvert, on peut se promener même pendant l'averse.","tgt":"در بازار سرپوشیده، حتی وقتی رگبار می‌بارد، می‌شود قدم زد.","ro":"Dar bâzâr-e sarpushide, hattâ vaghti ragbâr mibârad, mishavad ghadam zad."},{"fr":"Un vieil homme nous a dit : « Ici, la pluie est notre amie. »","tgt":"پیرمردی به ما گفت: «اینجا باران دوست ماست.»","ro":"Piremardi be mâ goft: «Injâ bârân dust-e mâst.»"},{"fr":"Les toits sont en pente pour que l'eau s'écoule facilement.","tgt":"سقف خانه‌ها شیب دارد تا آب راحت پایین برود.","ro":"Saghf-e khâne-hâ shib dârad tâ âb râhat pâyin beravad."},{"fr":"Le soir, la pluie s'est arrêtée d'un seul coup.","tgt":"شب، باران یک‌دفعه بند آمد.","ro":"Shab, bârân yekdafe band âmad."},{"fr":"Tout sentait la terre mouillée et le pain chaud.","tgt":"همه‌جا بوی خاک خیس و نان گرم می‌داد.","ro":"Hamejâ bu-ye khâk-e khis o nân-e garm midâd."}]},{"title":"Un train manqué","phrases":[{"fr":"Si nous étions partis plus tôt, nous n'aurions pas raté le train.","tgt":"اگر زودتر راه می‌افتادیم، قطار را از دست نمی‌دادیم.","ro":"Agar zudtar râh mioftâdim, ghatâr râ az dast nemidâdim."},{"fr":"Si tu étais venu avec nous, tu aurais vu le lever du soleil sur la mer.","tgt":"اگر با ما می‌آمدی، طلوع آفتاب روی دریا را می‌دیدی.","ro":"Agar bâ mâ miâmadi, tolu'-e âftâb ru-ye daryâ râ mididi."},{"fr":"Si le taxi était arrivé à l'heure, tout se serait bien passé.","tgt":"اگر تاکسی سر وقت می‌رسید، همه چیز خوب پیش می‌رفت.","ro":"Agar tâksi sar-e vaght miresid, hame chiz khub pish miraft."},{"fr":"Si j'avais su, j'aurais acheté les billets la veille.","tgt":"اگر می‌دانستم، بلیت‌ها را روز قبل می‌خریدم.","ro":"Agar midânestam, belit-hâ râ ruz-e ghabl mikharidam."},{"fr":"Si vous l'aviez dit, l'hôtel vous aurait réveillés.","tgt":"اگر می‌گفتید، هتل بیدارتان می‌کرد.","ro":"Agar migoftid, hotel bidâretân mikard."},{"fr":"Si la voiture n'était pas tombée en panne, nous serions arrivés à Sari avant midi.","tgt":"اگر ماشین خراب نمی‌شد، قبل از ظهر به ساری می‌رسیدیم.","ro":"Agar mâshin kharâb nemishod, ghabl az zohr be Sâri miresidim."},{"fr":"En fait, sans ce train manqué, nous n'aurions jamais rencontré Reza.","tgt":"در واقع اگر آن قطار را از دست نمی‌دادیم، با رضا آشنا نمی‌شدیم.","ro":"Dar vâghe' agar ân ghatâr râ az dast nemidâdim, bâ Rezâ âshnâ nemishodim."},{"fr":"Reza nous a conduits en voiture jusqu'à la gare suivante.","tgt":"رضا ما را با ماشین تا ایستگاه بعدی رساند.","ro":"Rezâ mâ râ bâ mâshin tâ istgâh-e ba'di resând."},{"fr":"Si nous avions pris le train, nous n'aurions pas vu cette belle route.","tgt":"اگر با قطار می‌رفتیم، این جاده‌ی زیبا را نمی‌دیدیم.","ro":"Agar bâ ghatâr miraftim, in jâdde-ye zibâ râ nemididim."},{"fr":"Finalement, ce retard nous a porté chance.","tgt":"در آخر، این تاخیر برایمان خوش‌شانسی آورد.","ro":"Dar âkhar, in ta'khir barâyemân khoshshânsi âvard."}],"tip":{"title":"Le conditionnel passé : « agar mirafti, mididi »","example":"Si tu étais venu avec nous, tu aurais vu le lever du soleil sur la mer. — اگر با ما <b>می‌آمدی</b>، طلوع آفتاب روی دریا را <b>می‌دیدی</b>.","body":"Pour parler de ce qui aurait pu arriver, le persan a une solution étonnamment simple : il emploie deux fois l'imparfait, ce passé qui commence par « mi- ». « Agar mirafti, mididi » veut dire mot à mot « si tu allais, tu voyais », mais tout le monde comprend « si tu étais allé, tu aurais vu ». C'est le contexte qui indique qu'on parle d'une occasion manquée. Ainsi, « agar zudtar râh mioftâdim, ghatâr râ az dast nemidâdim » signifie : si nous étions partis plus tôt, nous n'aurions pas raté le train. La négation reste toute simple, avec « nemi- » : « nemidâdim », « nemididim ». Vous entendrez parfois une forme plus soutenue, « agar rafte budi », mais à l'oral la forme en « mi- » est de loin la plus courante. Astuce : pensez « si mi-, alors mi- » et faites simplement rimer les deux verbes.","exampleRo":"Agar bâ mâ miâmadi, tolu'-e âftâb ru-ye daryâ râ mididi.","lit":"si · avec · nous · tu venais · lever · [de] · soleil · sur · mer · [objet] · tu voyais","say":{"agar mirafti, mididi":"اگر می‌رفتی، می‌دیدی","Agar mirafti, mididi":"اگر می‌رفتی، می‌دیدی","agar zudtar râh mioftâdim, ghatâr râ az dast nemidâdim":"اگر زودتر راه می‌افتادیم، قطار را از دست نمی‌دادیم","nemidâdim":"نمی‌دادیم","nemididim":"نمی‌دیدیم","agar rafte budi":"اگر رفته بودی","nemi-":"نمی"}}},{"title":"La cuisine du nord","phrases":[{"fr":"Ici, on mange du riz à presque tous les repas.","tgt":"اینجا تقریبا در همه‌ی وعده‌ها برنج می‌خورند.","ro":"Injâ taghriban dar hame-ye va'de-hâ berenj mikhorand."},{"fr":"Le mirza ghassemi se fait avec des aubergines grillées et des œufs.","tgt":"میرزاقاسمی با بادمجان کبابی و تخم‌مرغ درست می‌شود.","ro":"Mirzâghâsemi bâ bâdemjân-e kabâbi o tokhm-e morgh dorost mishavad."},{"fr":"Les plats du nord sont souvent acidulés, avec de la grenade ou des prunes.","tgt":"غذاهای شمالی اغلب ترش‌اند، با انار یا آلوچه.","ro":"Ghazâ-hâ-ye shomâli aghlab torshand, bâ anâr yâ âluche."},{"fr":"On met beaucoup d'herbes fraîches et d'ail dans tous les plats.","tgt":"توی همه‌ی غذاها سبزی تازه و سیر زیاد می‌ریزند.","ro":"Tu-ye hame-ye ghazâ-hâ sabzi-ye tâze va sir ziyâd mirizand."},{"fr":"Le poisson fumé se mange avec du riz et des herbes.","tgt":"ماهی دودی را با برنج و سبزی می‌خورند.","ro":"Mâhi-ye dudi râ bâ berenj o sabzi mikhorand."},{"fr":"Goûtez ce plat, c'est la spécialité de la maison.","tgt":"این غذا را بچشید، غذای مخصوص اینجاست.","ro":"In ghazâ râ bechashid, ghazâ-ye makhsus-e injâst."},{"fr":"C'est un peu trop acide pour moi, mais c'est délicieux.","tgt":"برای من کمی زیادی ترش است، ولی خوشمزه است.","ro":"Barâye man kami ziyâdi torsh ast, vali khoshmaze ast."},{"fr":"Le cuisinier a refusé de nous donner sa recette secrète.","tgt":"آشپز حاضر نشد دستور پخت مخفی‌اش را به ما بگوید.","ro":"Âshpaz hâzer nashod dastur-e pokht-e makhfi'ash râ be mâ beguyad."},{"fr":"Les olives de Roudbar sont marinées avec des herbes et de la grenade.","tgt":"زیتون رودبار را با سبزی و انار پرورده می‌کنند.","ro":"Zeytun-e Rudbâr râ bâ sabzi va anâr parvarde mikonand."},{"fr":"J'ai trop mangé, je ne peux plus bouger.","tgt":"زیادی خوردم، دیگر نمی‌توانم تکان بخورم.","ro":"Ziyâdi khordam, digar nemitavânam tekân bekhoram."}]},{"title":"Une randonnée vers la cascade","phrases":[{"fr":"Le chemin de la cascade monte à travers la forêt.","tgt":"راه آبشار از وسط جنگل بالا می‌رود.","ro":"Râh-e âbshâr az vasat-e jangal bâlâ miravad."},{"fr":"Il faut compter environ trois heures de marche.","tgt":"حدود سه ساعت پیاده‌روی لازم است.","ro":"Hodud-e se sâ'at piyâderavi lâzem ast."},{"fr":"Nous avons traversé la rivière sur un vieux pont en bois.","tgt":"از روی یک پل چوبی قدیمی از رودخانه رد شدیم.","ro":"Az ru-ye yek pol-e chubi-ye ghadimi az rudkhâne rad shodim."},{"fr":"On a fait une pause près d'une source d'eau fraîche.","tgt":"کنار یک چشمه‌ی آب خنک استراحت کردیم.","ro":"Kenâr-e yek cheshme-ye âb-e khonak esterâhat kardim."},{"fr":"On entend la cascade bien avant de la voir.","tgt":"صدای آبشار خیلی قبل از دیدنش شنیده می‌شود.","ro":"Sedâ-ye âbshâr kheyli ghabl az didanash shenide mishavad."},{"fr":"L'eau tombe de plus de trente mètres de haut.","tgt":"آب از ارتفاع بیش از سی متر پایین می‌ریزد.","ro":"Âb az ertefâ'-e bish az si metr pâyin mirizad."},{"fr":"Les plus courageux se sont baignés dans l'eau glacée.","tgt":"شجاع‌ترها در آب یخ شنا کردند.","ro":"Shojâ'tar-hâ dar âb-e yakh shenâ kardand."},{"fr":"Moi, je me suis contenté d'y tremper les pieds.","tgt":"من فقط پاهایم را در آب گذاشتم.","ro":"Man faghat pâhâyam râ dar âb gozâshtam."},{"fr":"Au retour, la descente a été plus dure que la montée.","tgt":"در برگشت، سرازیری از سربالایی سخت‌تر بود.","ro":"Dar bargasht, sarâziri az sarbâlâyi sakhttar bud."},{"fr":"Nous sommes rentrés fatigués, mais le cœur léger.","tgt":"خسته اما سبک‌بال برگشتیم.","ro":"Khaste ammâ sabokbâl bargashtim."}]},{"title":"Le marché de la semaine","phrases":[{"fr":"Chaque semaine, les villageois viennent en ville pour le marché.","tgt":"هر هفته، روستایی‌ها برای بازار به شهر می‌آیند.","ro":"Har hafte, rustâyi-hâ barâye bâzâr be shahr miâyand."},{"fr":"Les femmes vendent des produits qu'elles ont faits elles-mêmes.","tgt":"زن‌ها محصولاتی را می‌فروشند که خودشان درست کرده‌اند.","ro":"Zan-hâ mahsulâti râ miforushand ke khodeshân dorost karde'and."},{"fr":"On y trouve du fromage, du miel et des herbes séchées.","tgt":"پنیر و عسل و سبزی خشک پیدا می‌شود.","ro":"Panir o asal o sabzi-ye khoshk peydâ mishavad."},{"fr":"Ce miel vient des montagnes qui dominent le village.","tgt":"این عسل از کوه‌های بالای روستا آمده است.","ro":"In asal az kuh-hâ-ye bâlâ-ye rustâ âmade ast."},{"fr":"Combien coûte ce pot de miel ?","tgt":"این شیشه‌ی عسل چند است؟","ro":"In shishe-ye asal chand ast?"},{"fr":"C'est un peu cher, vous ne pourriez pas me faire une petite remise ?","tgt":"کمی گران است، نمی‌توانید تخفیف بدهید؟","ro":"Kami gerân ast, nemitavânid takhfif bedahid?"},{"fr":"La vendeuse a ri et m'a baissé un peu le prix.","tgt":"فروشنده خندید و کمی تخفیف داد.","ro":"Forushande khandid va kami takhfif dâd."},{"fr":"Les canards et les poules sont vendus vivants.","tgt":"اردک‌ها و مرغ‌ها زنده فروخته می‌شوند.","ro":"Ordak-hâ va morgh-hâ zende forukhte mishavand."},{"fr":"Autour de nous, tout le monde parle guilaki.","tgt":"اطراف ما همه گیلکی حرف می‌زنند.","ro":"Atrâf-e mâ hame gilaki harf mizanand."},{"fr":"Ce marché est le cœur battant de la région.","tgt":"این بازار قلب تپنده‌ی منطقه است.","ro":"In bâzâr ghalb-e tapande-ye mantaghe ast."}]},{"title":"La plage en hiver","phrases":[{"fr":"En hiver, la plage est presque déserte.","tgt":"در زمستان، ساحل تقریبا خالی است.","ro":"Dar zemestân, sâhel taghriban khâli ast."},{"fr":"Seuls quelques pêcheurs réparent leurs filets.","tgt":"فقط چند ماهیگیر تورهایشان را تعمیر می‌کنند.","ro":"Faghat chand mâhigir tur-hâyeshân râ ta'mir mikonand."},{"fr":"La mer est grise et le vent souffle fort.","tgt":"دریا خاکستری است و باد تند می‌وزد.","ro":"Daryâ khâkestari ast va bâd tond mivazad."},{"fr":"Un pêcheur nous a raconté que la mer avait beaucoup changé.","tgt":"یک ماهیگیر برایمان تعریف کرد که دریا خیلی عوض شده است.","ro":"Yek mâhigir barâyemân ta'rif kard ke daryâ kheyli avaz shode ast."},{"fr":"Autrefois, on pêchait beaucoup plus de poissons ici.","tgt":"قدیم‌ها اینجا خیلی بیشتر ماهی صید می‌شد.","ro":"Ghadim-hâ injâ kheyli bishtar mâhi seyd mishod."},{"fr":"Il part en mer avant l'aube, même quand il fait froid.","tgt":"او قبل از سپیده‌دم به دریا می‌رود، حتی وقتی هوا سرد است.","ro":"U ghabl az sepidedam be daryâ miravad, hattâ vaghti havâ sard ast."},{"fr":"Son fils l'aide depuis l'âge de quinze ans.","tgt":"پسرش از پانزده‌سالگی کمکش می‌کند.","ro":"Pesarash az pânzdahsâlegi komakash mikonad."},{"fr":"Ils nous ont invités à boire un thé dans leur cabane.","tgt":"ما را برای یک چای به کلبه‌ی خودشان دعوت کردند.","ro":"Mâ râ barâye yek chây be kolbe-ye khodeshân da'vat kardand."},{"fr":"Le bruit des vagues couvrait presque nos voix.","tgt":"صدای موج‌ها تقریبا صدایمان را می‌پوشاند.","ro":"Sedâ-ye moj-hâ taghriban sedâyemân râ mipushând."},{"fr":"Cette plage vide a un charme que l'été ne connaît pas.","tgt":"این ساحل خالی جذابیتی دارد که تابستان ندارد.","ro":"In sâhel-e khâli jazzâbiyati dârad ke tâbestân nadârad."}]},{"title":"La route de Chalus","phrases":[{"fr":"La route de Chalus relie Téhéran à la mer à travers les montagnes.","tgt":"جاده‌ی چالوس تهران را از میان کوه‌ها به دریا وصل می‌کند.","ro":"Jâdde-ye Châlus Tehrân râ az miyân-e kuh-hâ be daryâ vasl mikonad."},{"fr":"On dit que c'est l'une des plus belles routes d'Iran.","tgt":"می‌گویند یکی از زیباترین جاده‌های ایران است.","ro":"Miguyand yeki az zibâtarin jâdde-hâ-ye Irân ast."},{"fr":"Le week-end, la circulation y est souvent très dense.","tgt":"آخر هفته‌ها اغلب ترافیک سنگین است.","ro":"Âkhar-e hafte-hâ aghlab terâfik sangin ast."},{"fr":"La route longe une rivière au fond d'une vallée étroite.","tgt":"جاده از کنار رودخانه‌ای در ته یک دره‌ی تنگ می‌گذرد.","ro":"Jâdde az kenâr-e rudkhâne'i dar tah-e yek darre-ye tang migozarad."},{"fr":"On s'arrête au bord de la route pour acheter du maïs grillé.","tgt":"کنار جاده می‌ایستیم تا بلال کبابی بخریم.","ro":"Kenâr-e jâdde mi'istim tâ balâl-e kabâbi bekharim."},{"fr":"Les virages sont dangereux, mieux vaut ne pas conduire la nuit.","tgt":"پیچ‌ها خطرناک‌اند، بهتر است شب رانندگی نکنید.","ro":"Pich-hâ khatarnâkand, behtar ast shab rânandegi nakonid."},{"fr":"Plus haut, on passe dans un long tunnel creusé dans la roche.","tgt":"بالاتر، از یک تونل طولانی که در دل سنگ کنده شده رد می‌شویم.","ro":"Bâlâtar, az yek tunel-e tulâni ke dar del-e sang kande shode rad mishavim."},{"fr":"De l'autre côté, le ciel change complètement.","tgt":"آن طرف، آسمان کاملا عوض می‌شود.","ro":"Ân taraf, âsemân kâmelan avaz mishavad."},{"fr":"Les nuages s'accrochent aux sommets comme du coton.","tgt":"ابرها مثل پنبه به قله‌ها چسبیده‌اند.","ro":"Abr-hâ mesl-e panbe be gholle-hâ chasbide'and."},{"fr":"On a mis huit heures au lieu de quatre, mais personne ne s'est plaint.","tgt":"به جای چهار ساعت، هشت ساعت طول کشید، اما کسی شکایت نکرد.","ro":"Be jâ-ye chahâr sâ'at, hasht sâ'at tul keshid, ammâ kasi shekâyat nakard."}]},{"title":"Plus on voyage, plus on aime","phrases":[{"fr":"Plus on reste ici, plus on a envie de rester.","tgt":"هر چه بیشتر اینجا می‌مانیم، بیشتر دلمان می‌خواهد بمانیم.","ro":"Har che bishtar injâ mimânim, bishtar delemân mikhâhad bemânim."},{"fr":"Plus je parle avec les gens, plus mon persan s'améliore.","tgt":"هر چه بیشتر با مردم حرف می‌زنم، فارسی‌ام بهتر می‌شود.","ro":"Har che bishtar bâ mardom harf mizanam, fârsi'am behtar mishavad."},{"fr":"Plus on s'approche de la mer, plus l'air devient humide.","tgt":"هر چه به دریا نزدیک‌تر می‌شویم، هوا مرطوب‌تر می‌شود.","ro":"Har che be daryâ nazdiktar mishavim, havâ martubtar mishavad."},{"fr":"Plus on goûte la cuisine du nord, plus on l'aime.","tgt":"هر چه بیشتر غذای شمالی می‌خوریم، بیشتر دوستش داریم.","ro":"Har che bishtar ghazâ-ye shomâli mikhorim, bishtar dustash dârim."},{"fr":"Les jours passent de plus en plus vite.","tgt":"روزها روز به روز تندتر می‌گذرند.","ro":"Ruz-hâ ruz be ruz tondtar migozarand."},{"fr":"Je comprends de plus en plus de mots en guilaki.","tgt":"روز به روز کلمه‌های گیلکی بیشتری می‌فهمم.","ro":"Ruz be ruz kalame-hâ-ye gilaki-ye bishtari mifahmam."},{"fr":"Plus le voyage avance, plus nos sacs deviennent lourds.","tgt":"هر چه سفر جلوتر می‌رود، کوله‌هایمان سنگین‌تر می‌شوند.","ro":"Har che safar jelotar miravad, kule-hâyemân sangintar mishavand."},{"fr":"Venez le plus vite possible, avant la pluie.","tgt":"هر چه زودتر بیایید، قبل از باران.","ro":"Har che zudtar biyâyid, ghabl az bârân."},{"fr":"Plus on voyage, plus on rencontre de gens généreux.","tgt":"هر چه بیشتر سفر می‌کنیم، آدم‌های دست‌ودل‌باز بیشتری می‌بینیم.","ro":"Har che bishtar safar mikonim, âdam-hâ-ye dast-o-delbâz-e bishtari mibinim."},{"fr":"Plus le départ approche, plus il est difficile de dire au revoir.","tgt":"هر چه به رفتن نزدیک‌تر می‌شویم، خداحافظی سخت‌تر می‌شود.","ro":"Har che be raftan nazdiktar mishavim, khodâhâfezi sakhttar mishavad."}],"tip":{"title":"« Har che bishtar » : de plus en plus","example":"Plus on reste ici, plus on a envie de rester. — <b>هر چه بیشتر</b> اینجا می‌مانیم، بیشتر دلمان می‌خواهد بمانیم.","body":"« Har che » signifie mot à mot tout ce que, et « bishtar » veut dire plus. Ensemble, « har che bishtar » correspond à notre « plus… plus… » : « har che bishtar injâ mimânim, bishtar delemân mikhâhad bemânim », plus nous restons ici, plus notre cœur veut rester. On peut remplacer « bishtar » par n'importe quel comparatif en « -tar » : « har che nazdiktar », plus on est près, ou « har che sakhttar », plus c'est dur. Seul, « har che zudtar » veut dire le plus tôt possible, une formule très utile en voyage. Pour dire simplement de plus en plus, sans deuxième partie, le persan préfère « ruz be ruz », jour après jour : « ruz be ruz tondtar migozarand », ils passent de plus en plus vite. Astuce : retenez le rythme « har che… -tar, … -tar », comme une balançoire qui monte des deux côtés.","exampleRo":"Har che bishtar injâ mimânim, bishtar delemân mikhâhad bemânim.","lit":"tout · ce que · plus · ici · nous restons · plus · notre cœur · veut · que nous restions","say":{"Har che bishtar":"هر چه بیشتر","Har che":"هر چه","bishtar":"بیشتر","har che bishtar":"هر چه بیشتر","har che bishtar injâ mimânim, bishtar delemân mikhâhad bemânim":"هر چه بیشتر اینجا می‌مانیم، بیشتر دلمان می‌خواهد بمانیم","har che nazdiktar":"هر چه نزدیک‌تر","har che sakhttar":"هر چه سخت‌تر","har che zudtar":"هر چه زودتر","ruz be ruz":"روز به روز","ruz be ruz tondtar migozarand":"روز به روز تندتر می‌گذرند"}}},{"title":"Dernier jour au bord de la mer","phrases":[{"fr":"C'est notre dernier matin au bord de la Caspienne.","tgt":"امروز آخرین صبح ما کنار دریاست.","ro":"Emruz âkharin sobh-e mâ kenâr-e daryâst."},{"fr":"Nous sommes allés voir le lever du soleil une dernière fois.","tgt":"برای آخرین بار به تماشای طلوع آفتاب رفتیم.","ro":"Barâye âkharin bâr be tamâshâ-ye tolu'-e âftâb raftim."},{"fr":"Nos hôtes nous ont préparé un petit-déjeuner du nord.","tgt":"میزبان‌هایمان برایمان صبحانه‌ی شمالی درست کردند.","ro":"Mizbân-hâyemân barâyemân sobhâne-ye shomâli dorost kardand."},{"fr":"Il y avait du pain chaud, une omelette aux herbes et du miel.","tgt":"نان گرم و کوکوی سبزی و عسل بود.","ro":"Nân-e garm o kuku-ye sabzi o asal bud."},{"fr":"Ils nous ont fait promettre de revenir au printemps.","tgt":"از ما قول گرفتند که بهار برگردیم.","ro":"Az mâ ghol gereftand ke bahâr bargardim."},{"fr":"On a échangé des cadeaux et quelques larmes.","tgt":"هدیه رد و بدل کردیم و چند قطره اشک هم ریخت.","ro":"Hediye rad o badal kardim va chand ghatre ashk ham rikht."},{"fr":"Selon la coutume, la grand-mère a versé de l'eau derrière nous.","tgt":"مادربزرگ طبق رسم، پشت سرمان آب ریخت.","ro":"Mâdarbozorg tebgh-e rasm, posht-e saremân âb rikht."},{"fr":"Ça veut dire que nous reviendrons sains et saufs.","tgt":"یعنی به سلامت برمی‌گردیم.","ro":"Ya'ni be salâmat barmigardim."},{"fr":"Dans le train du retour, personne n'avait envie de parler.","tgt":"در قطار برگشت، کسی حوصله‌ی حرف زدن نداشت.","ro":"Dar ghatâr-e bargasht, kasi hosele-ye harf zadan nadâsht."},{"fr":"Une partie de nous est restée là-bas, entre la mer et la forêt.","tgt":"تکه‌ای از وجودمان آنجا ماند، بین دریا و جنگل.","ro":"Tekke'i az vojudemân ânjâ mând, beyn-e daryâ va jangal."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a emmenés tout le long de la mer Caspienne.","tgt":"این بخش ما را در تمام طول ساحل دریای خزر همراهی کرد.","ro":"In bakhsh mâ râ dar tamâm-e tul-e sâhel-e daryâ-ye Khazar hamrâhi kard."},{"fr":"Rizières, forêts, villages : nous avons découvert un autre visage de l'Iran.","tgt":"شالیزارها، جنگل‌ها، روستاها: چهره‌ی دیگری از ایران را شناختیم.","ro":"Shâlizâr-hâ, jangal-hâ, rustâ-hâ: chehre-ye digari az Irân râ shenâkhtim."},{"fr":"Nous savons maintenant décrire un lieu avec « ke ».","tgt":"حالا می‌توانیم با «که» جایی را توصیف کنیم.","ro":"Hâlâ mitavânim bâ «ke» jâyi râ tosif konim."},{"fr":"Nous pouvons aussi parler de ce que nous aurions pu faire.","tgt":"می‌توانیم از کارهایی هم حرف بزنیم که می‌توانستیم بکنیم.","ro":"Mitavânim az kâr-hâyi ham harf bezanim ke mitavânestim bekonim."},{"fr":"Le plus-que-parfait nous aide à raconter nos souvenirs.","tgt":"ماضی بعید کمکمان می‌کند خاطراتمان را تعریف کنیم.","ro":"Mâzi-ye ba'id komakemân mikonad khâterâtemân râ ta'rif konim."},{"fr":"Plus nous pratiquons le persan, plus il nous semble naturel.","tgt":"هر چه بیشتر فارسی تمرین می‌کنیم، به نظرمان طبیعی‌تر می‌آید.","ro":"Har che bishtar fârsi tamrin mikonim, be nazaremân tabi'itar miâyad."},{"fr":"Nous osons maintenant parler aux inconnus rencontrés en chemin.","tgt":"حالا جرئت می‌کنیم در راه با غریبه‌ها حرف بزنیم.","ro":"Hâlâ jor'at mikonim dar râh bâ gharibe-hâ harf bezanim."},{"fr":"Bravo pour tout le chemin que vous avez fait !","tgt":"به خاطر این همه راهی که آمده‌اید، آفرین!","ro":"Be khâter-e in hame râhi ke âmade'id, âfarin!"},{"fr":"Reposez-vous un peu avant le module suivant.","tgt":"قبل از بخش بعدی کمی استراحت کنید.","ro":"Ghabl az bakhsh-e ba'di kami esterâhat konid."},{"fr":"À bientôt pour de nouvelles conversations en persan.","tgt":"به امید دیدار، برای گفت‌وگوهای تازه به فارسی.","ro":"Be omid-e didâr, barâye goftogu-hâ-ye tâze be fârsi."}]}]},{"id":3,"name":"Conversation sociale","desc":"Des conversations profondes : opinions, débats, émotions.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Une soirée de poésie à Chiraz","phrases":[{"fr":"Ce soir, nos amis de Chiraz nous ont invités à une soirée de poésie.","tgt":"امشب دوستان شیرازی‌مان ما را به یک شب شعر دعوت کرده‌اند.","ro":"Emshab dustân-e shirâzi-mân mâ râ be yek shab-e she'r da'vat karde-and."},{"fr":"Dans cette ville, presque tout le monde sait réciter quelques vers de Hafez par cœur.","tgt":"در این شهر تقریبا همه می‌توانند چند بیت از حافظ را از حفظ بخوانند.","ro":"Dar in shahr taghriban hame mitavânand chand beyt az Hâfez râ az hefz bekhânand."},{"fr":"La langue de Hafez est ancienne, mais les Iraniens la comprennent encore aujourd'hui.","tgt":"زبان حافظ کهن است، اما ایرانی‌ها هنوز هم آن را می‌فهمند.","ro":"Zabân-e Hâfez kohan ast, ammâ irâni-hâ hanuz ham ân râ mifahmand."},{"fr":"Dans ces poèmes, il est toujours question du cœur et de l'amour.","tgt":"در این شعرها همیشه سخن از دل و عشق است.","ro":"Dar in she'r-hâ hamishe sokhan az del va eshgh ast."},{"fr":"Le persan littéraire est plus lent et plus musical que la langue de tous les jours.","tgt":"فارسی ادبی آرام‌تر و آهنگین‌تر از زبان کوچه و بازار است.","ro":"Fârsi-ye adabi ârâmtar va âhangintar az zabân-e kuche va bâzâr ast."},{"fr":"Lorsque le poème s'est achevé, un long silence s'est installé.","tgt":"چون شعر به پایان رسید، سکوتی طولانی برقرار شد.","ro":"Chon she'r be pâyân resid, sokuti tulâni bargharâr shod."},{"fr":"Je trouve ces vers très beaux, même si je ne comprends pas chaque mot.","tgt":"این بیت‌ها به نظرم بسیار زیبا هستند، حتی اگر همه‌ی واژه‌ها را نفهمم.","ro":"In beyt-hâ be nazaram besyâr zibâ hastand, hattâ agar hame-ye vâzhe-hâ râ nafahmam."},{"fr":"Notre hôte nous a expliqué le sens caché de chaque vers.","tgt":"میزبان‌مان معنای پنهان هر بیت را برایمان توضیح داد.","ro":"Mizbânemân ma'nâ-ye penhân-e har beyt râ barâyemân towzih dâd."},{"fr":"On dit que la poésie de Hafez parle à chacun d'une manière différente.","tgt":"می‌گویند شعر حافظ با هر کسی به زبانی دیگر سخن می‌گوید.","ro":"Miguyand she'r-e Hâfez bâ har kasi be zabâni digar sokhan miguyad."},{"fr":"Je voudrais un jour lire Hafez sans l'aide de personne.","tgt":"دوست دارم روزی حافظ را بدون کمک کسی بخوانم.","ro":"Dust dâram ruzi Hâfez râ bedun-e komak-e kasi bekhânam."}],"tip":{"title":"La langue de Hafez : le persan littéraire","example":"Dans ces poèmes, il est toujours question du cœur et de l'amour. — در این شعرها همیشه <b>سخن</b> از دل و عشق است.","body":"Le persan a une chance rare : la langue de Hafez, vieille de plus de six siècles, reste compréhensible pour un Iranien d'aujourd'hui. Mais on ne parle pas comme on récite un poème : le registre littéraire préfère « sokhan », la parole, là où la conversation dit « harf », et « besyâr », très, là où l'on dit d'habitude « kheyli ». Même chose pour le verbe être : on prononce « khub ast » en lisant, mais « khube » entre amis. Dans « dar in she'r-hâ hamishe sokhan az del va eshgh ast », mot à mot « dans ces poèmes toujours parole de cœur et amour est », chaque mot sonne un peu solennel, comme « jadis » ou « fort beau » en français. L'astuce est simple : reconnaissez ces mots quand vous les entendez dans un poème ou un discours, mais gardez « kheyli » et « harf » pour bavarder.","exampleRo":"Dar in she'r-hâ hamishe sokhan az del va eshgh ast.","lit":"dans · ces · poèmes · toujours · parole · de · cœur · et · amour · est","say":{"sokhan":"سخن","harf":"حرف","besyâr":"بسیار","kheyli":"خیلی","khub ast":"خوب است","khube":"خوبه","dar in she'r-hâ hamishe sokhan az del va eshgh ast":"در این شعرها همیشه سخن از دل و عشق است"}}},{"title":"Au tombeau de Hafez","phrases":[{"fr":"Le tombeau de Hafez se trouve dans un jardin paisible de Chiraz.","tgt":"آرامگاه حافظ در باغی آرام در شیراز قرار دارد.","ro":"Ârâmgâh-e Hâfez dar bâghi ârâm dar Shirâz gharâr dârad."},{"fr":"En fin d'après-midi, les familles viennent ici se promener et lire des poèmes.","tgt":"عصرها خانواده‌ها برای قدم زدن و شعر خواندن به اینجا می‌آیند.","ro":"Asr-hâ khânevâde-hâ barâye ghadam zadan va she'r khândan be injâ miâyand."},{"fr":"Ce monument a été rénové plusieurs fois au cours des siècles.","tgt":"این بنا در طول قرن‌ها چند بار بازسازی شده است.","ro":"In banâ dar tul-e gharn-hâ chand bâr bâzsâzi shode ast."},{"fr":"Les visiteurs lisent à voix basse les vers gravés dans la pierre.","tgt":"بازدیدکنندگان بیت‌هایی را که روی سنگ حک شده‌اند آهسته می‌خوانند.","ro":"Bâzdidkonandegân beyt-hâyi râ ke ru-ye sang hak shode-and âheste mikhânand."},{"fr":"Un vieil homme récitait des poèmes pour quelques jeunes.","tgt":"پیرمردی برای چند جوان شعر می‌خواند.","ro":"Pirmardi barâye chand javân she'r mikhând."},{"fr":"Voir l'émotion des gens autour de moi m'a beaucoup touché.","tgt":"دیدن احساسات مردم اطرافم خیلی مرا تحت تأثیر قرار داد.","ro":"Didan-e ehsâsât-e mardom-e atrâfam kheyli marâ taht-e ta'sir gharâr dâd."},{"fr":"Ici, on sent que la poésie fait vraiment partie de la vie quotidienne.","tgt":"اینجا آدم حس می‌کند که شعر واقعا بخشی از زندگی روزمره است.","ro":"Injâ âdam hes mikonad ke she'r vâghe'an bakhshi az zendegi-ye ruzmarre ast."},{"fr":"Les jardins de Chiraz sont célèbres pour leurs orangers et leurs roses.","tgt":"باغ‌های شیراز به خاطر درختان نارنج و گل‌های سرخشان معروف‌اند.","ro":"Bâgh-hâ-ye Shirâz be khâter-e derakhtân-e nârenj va gol-hâ-ye sorkheshân ma'ruf-and."},{"fr":"Nous sommes restés assis là jusqu'à la tombée de la nuit.","tgt":"آنجا نشستیم تا شب شد.","ro":"Ânjâ neshastim tâ shab shod."},{"fr":"Je n'oublierai jamais cette soirée passée près du poète.","tgt":"آن شبی را که کنار شاعر گذراندیم، هرگز فراموش نمی‌کنم.","ro":"Ân shabi râ ke kenâr-e shâ'er gozarândim, hargez farâmush nemikonam."}]},{"title":"Remercier et encourager","phrases":[{"fr":"Merci pour vos efforts, vous avez travaillé toute la journée !","tgt":"خسته نباشید، تمام روز کار کردید!","ro":"Khaste nabâshid, tamâm-e ruz kâr kardid!"},{"fr":"Merci infiniment pour ce repas, c'était délicieux !","tgt":"دستتون درد نکنه، غذا خیلی خوشمزه بود!","ro":"Dastetun dard nakone, ghazâ kheyli khoshmaze bud!"},{"fr":"L'hôtesse a répondu : « Merci à vous, ce n'était rien. »","tgt":"میزبان جواب داد: «سرتون درد نکنه، قابلی نداشت.»","ro":"Mizbân javâb dâd: «Saretun dard nakone, ghâbeli nadâsht.»"},{"fr":"Au commerçant qui travaille depuis le matin, on souhaite bon courage.","tgt":"به مغازه‌داری که از صبح کار می‌کند، «خسته نباشید» می‌گوییم.","ro":"Be maghâzedâri ke az sobh kâr mikonad, «khaste nabâshid» miguyim."},{"fr":"Le chauffeur de taxi m'a répondu : « Merci, portez-vous bien. »","tgt":"راننده‌ی تاکسی جواب داد: «سلامت باشید، ممنون.»","ro":"Rânande-ye tâksi javâb dâd: «Salâmat bâshid, mamnun.»"},{"fr":"Merci, tu m'as beaucoup aidé à porter les cartons !","tgt":"دستت درد نکنه، برای بردن کارتن‌ها خیلی کمکم کردی!","ro":"Dastet dard nakone, barâye bordan-e kârton-hâ kheyli komakam kardi!"},{"fr":"Je vous en prie, entrez, vous êtes ici chez vous.","tgt":"بفرمایید داخل، اینجا خانه‌ی خودتان است.","ro":"Befarmâyid dâkhel, injâ khâne-ye khodetân ast."},{"fr":"Ces formules montrent qu'on remarque les efforts des autres.","tgt":"این عبارت‌ها نشان می‌دهند که ما زحمت دیگران را می‌بینیم.","ro":"In ebârat-hâ neshân midahand ke mâ zahmat-e digarân râ mibinim."},{"fr":"Désolés de vous avoir dérangés, vous vous êtes donné beaucoup de mal.","tgt":"ببخشید که زحمت دادیم، خیلی به زحمت افتادید.","ro":"Bebakhshid ke zahmat dâdim, kheyli be zahmat oftâdid."},{"fr":"En partant, nous avons encore remercié au moins trois fois.","tgt":"موقع رفتن، دست‌کم سه بار دیگر تشکر کردیم.","ro":"Mowghe'-e raftan, dast-e kam se bâr-e digar tashakkor kardim."}],"tip":{"title":"Les expressions du quotidien : « khaste nabâshid », « dastet dard nakone »","example":"Merci infiniment pour ce repas, c'était délicieux ! — <b>دستتون درد نکنه</b>، غذا خیلی خوشمزه بود!","body":"Ces deux formules sont partout en Iran, et les dire au bon moment vous rendra tout de suite sympathique. « Khaste nabâshid » veut dire mot à mot « ne soyez pas fatigués » : on le dit à quelqu'un qui travaille, à un commerçant ou à un collègue en fin de journée, un peu comme notre « bon courage ». « Dastet dard nakone », littéralement « que ta main ne souffre pas », remercie quelqu'un qui a fait quelque chose pour vous, un repas ou un service ; pour vouvoyer, on dit « dastetun dard nakone ». On y répond par « saretun dard nakone », « que votre tête ne souffre pas », ou simplement par « salâmat bâshid », « portez-vous bien ». Retenez l'image : la fatigue pour l'effort, la main pour le cadeau.","exampleRo":"Dastetun dard nakone, ghazâ kheyli khoshmaze bud!","lit":"main-votre · douleur · [ne… pas] fasse · repas · très · délicieux · était","say":{"khaste nabâshid":"خسته نباشید","dastet dard nakone":"دستت درد نکنه","Khaste nabâshid":"خسته نباشید","Dastet dard nakone":"دستت درد نکنه","dastetun dard nakone":"دستتون درد نکنه","saretun dard nakone":"سرتون درد نکنه","salâmat bâshid":"سلامت باشید"}}},{"title":"Un dîner de famille à Ispahan","phrases":[{"fr":"Toute la famille s'était réunie chez la grand-mère pour le dîner du vendredi.","tgt":"همه‌ی خانواده برای شام جمعه در خانه‌ی مادربزرگ جمع شده بودند.","ro":"Hame-ye khânevâde barâye shâm-e jom'e dar khâne-ye mâdarbozorg jam' shode budand."},{"fr":"La nappe était étendue par terre, couverte de plats cuisinés depuis le matin.","tgt":"سفره روی زمین پهن شده بود و پر از غذاهایی بود که از صبح پخته شده بودند.","ro":"Sofre ru-ye zamin pahn shode bud va por az ghazâhâyi bud ke az sobh pokhte shode budand."},{"fr":"Ma tante insistait pour que je me resserve du riz au safran.","tgt":"خاله‌ام اصرار داشت که باز هم برنج زعفرانی بکشم.","ro":"Khâle-am esrâr dâsht ke bâz ham berenj-e za'farâni bekesham."},{"fr":"Les enfants couraient dans la cour pendant que les adultes buvaient du thé.","tgt":"بچه‌ها در حیاط می‌دویدند و بزرگ‌ترها چای می‌نوشیدند.","ro":"Bachche-hâ dar hayât midavidand va bozorgtar-hâ chây minushidand."},{"fr":"Mon grand-père racontait encore la même histoire de sa jeunesse.","tgt":"پدربزرگم باز همان داستان جوانی‌اش را تعریف می‌کرد.","ro":"Pedarbozorgam bâz hamân dâstân-e javâni-ash râ ta'rif mikard."},{"fr":"Chez nous, on ne laisse jamais un invité repartir le ventre vide.","tgt":"در خانه‌ی ما هیچ‌وقت نمی‌گذاریم مهمان گرسنه برود.","ro":"Dar khâne-ye mâ hichvaght nemigozârim mehmân gorosne beravad."},{"fr":"Après le dîner, on a apporté des fruits et des pâtisseries d'Ispahan.","tgt":"بعد از شام، میوه و شیرینی اصفهانی آوردند.","ro":"Ba'd az shâm, mive va shirini-ye esfahâni âvardand."},{"fr":"Tout le monde parlait en même temps, et personne ne s'en plaignait.","tgt":"همه با هم حرف می‌زدند و کسی هم گله‌ای نداشت.","ro":"Hame bâ ham harf mizadand va kasi ham gele-i nadâsht."},{"fr":"Ma cousine m'a demandé ce que je pensais de la vie en Iran.","tgt":"دخترخاله‌ام از من پرسید نظرم درباره‌ی زندگی در ایران چیست.","ro":"Dokhtarkhâle-am az man porsid nazaram darbâre-ye zendegi dar Irân chist."},{"fr":"Il était minuit passé quand nous avons enfin pris congé.","tgt":"از نیمه‌شب گذشته بود که بالاخره خداحافظی کردیم.","ro":"Az nimeshab gozashte bud ke bâlâkhare khodâhâfezi kardim."}]},{"title":"Partager ses impressions","phrases":[{"fr":"On dirait qu'il va pleuvoir, prenons le thé à l'intérieur.","tgt":"مثل اینکه باران می‌آید، بیایید چای را داخل بخوریم.","ro":"Mesl-e inke bârân miâyad, biâyid chây râ dâkhel bekhorim."},{"fr":"On dirait que vous avez passé une journée difficile, tout va bien ?","tgt":"مثل اینکه روز سختی داشتید، همه چیز خوب است؟","ro":"Mesl-e inke ruz-e sakhti dâshtid, hame chiz khub ast?"},{"fr":"Apparemment, le restaurant est fermé le vendredi.","tgt":"مثل اینکه رستوران جمعه‌ها تعطیل است.","ro":"Mesl-e inke restorân jom'e-hâ ta'til ast."},{"fr":"On dirait que ces deux-là se connaissent depuis des années.","tgt":"مثل اینکه این دو نفر سال‌هاست همدیگر را می‌شناسند.","ro":"Mesl-e inke in do nafar sâl-hâst hamdigar râ mishenâsand."},{"fr":"Le soir, le pont Si-o-se Pol ressemble à un tableau.","tgt":"شب‌ها سی‌وسه‌پل مثل یک تابلوی نقاشی است.","ro":"Shab-hâ Si-o-se Pol mesl-e yek tâblo-ye naghghâshi ast."},{"fr":"Apparemment, nos amis sont déjà partis sans nous.","tgt":"مثل اینکه دوستان‌مان بدون ما رفته‌اند.","ro":"Mesl-e inke dustânemân bedun-e mâ rafte-and."},{"fr":"On dirait que vous avez toujours vécu ici, vous connaissez toutes les ruelles !","tgt":"مثل اینکه همیشه اینجا زندگی کرده‌اید، همه‌ی کوچه‌ها را می‌شناسید!","ro":"Mesl-e inke hamishe injâ zendegi karde-id, hame-ye kuche-hâ râ mishenâsid!"},{"fr":"Il parle comme s'il était le seul à avoir raison.","tgt":"طوری حرف می‌زند که انگار فقط خودش حق دارد.","ro":"Towri harf mizanad ke engâr faghat khodash hagh dârad."},{"fr":"Apparemment, il faut réserver une table pour ce soir.","tgt":"مثل اینکه برای امشب باید میز رزرو کنیم.","ro":"Mesl-e inke barâye emshab bâyad miz rezerv konim."},{"fr":"Le temps passe si vite ici qu'on dirait que nous venons d'arriver.","tgt":"اینجا زمان آن‌قدر زود می‌گذرد که انگار تازه رسیده‌ایم.","ro":"Injâ zamân ânghadr zud migozarad ke engâr tâze reside-im."}],"tip":{"title":"« Mesl-e inke » : on dirait que","example":"Apparemment, le restaurant est fermé le vendredi. — <b>مثل اینکه</b> رستوران جمعه‌ها تعطیل است.","body":"« Mesl-e inke » se compose de « mesl », comme, de l'ezâfe « -e », et de « inke », que : mot à mot « comme que », c'est-à-dire « on dirait que » ou « apparemment ». On le place tout au début, puis la phrase continue normalement, sans rien changer au verbe : « mesl-e inke bârân miâyad », on dirait qu'il pleut. Il sert à donner une impression, ou une information qu'on n'a pas vérifiée soi-même, ce qui adoucit beaucoup la phrase, à l'iranienne. Son cousin « engâr » s'emploie de la même façon : « engâr tâze reside-im », comme si nous venions d'arriver. Pour le retenir, pensez à notre « on dirait » : deux petits mots qui ouvrent la phrase et laissent planer un doute poli.","exampleRo":"Mesl-e inke restorân jom'e-hâ ta'til ast.","lit":"comme · que · restaurant · vendredis · fermé · est","say":{"Mesl-e inke":"مثل اینکه","mesl":"مثل","inke":"اینکه","mesl-e inke bârân miâyad":"مثل اینکه باران می‌آید","engâr":"انگار","engâr tâze reside-im":"انگار تازه رسیده‌ایم"}}},{"title":"Le thé sur la place Naghsh-e Jahan","phrases":[{"fr":"Nous avons pris le thé dans une maison de thé qui donne sur la place.","tgt":"در چایخانه‌ای رو به میدان چای خوردیم.","ro":"Dar châykhâne-i ru be meydân chây khordim."},{"fr":"La place Naghsh-e Jahan est l'une des plus grandes places du monde.","tgt":"میدان نقش جهان یکی از بزرگ‌ترین میدان‌های جهان است.","ro":"Meydân-e Naghsh-e Jahân yeki az bozorgtarin meydân-hâ-ye jahân ast."},{"fr":"D'ici, on voit les arcades éclairées et les calèches qui passent.","tgt":"از اینجا طاق‌های روشن و درشکه‌هایی را که رد می‌شوند می‌بینیم.","ro":"Az injâ tâgh-hâ-ye rowshan va doroshke-hâyi râ ke rad mishavand mibinim."},{"fr":"Le serveur nous a apporté du thé avec du sucre candi au safran.","tgt":"گارسون برایمان چای با نبات زعفرانی آورد.","ro":"Gârson barâyemân chây bâ nabât-e za'farâni âvard."},{"fr":"En Iran, on boit souvent le thé avec un morceau de sucre dans la bouche.","tgt":"در ایران معمولا چای را با یک حبه قند در دهان می‌نوشند.","ro":"Dar Irân ma'mulan chây râ bâ yek habbe ghand dar dahân minushand."},{"fr":"Mon ami est convaincu que le thé d'ici a un goût différent.","tgt":"دوستم معتقد است چای اینجا طعم دیگری دارد.","ro":"Dustam mo'taghed ast chây-e injâ ta'm-e digari dârad."},{"fr":"Assis sur les tapis, nous avons parlé pendant des heures.","tgt":"روی فرش‌ها نشستیم و ساعت‌ها حرف زدیم.","ro":"Ru-ye farsh-hâ neshastim va sâ'at-hâ harf zadim."},{"fr":"Les artisans du bazar fermaient leurs boutiques une à une.","tgt":"صنعتگران بازار یکی‌یکی مغازه‌هایشان را می‌بستند.","ro":"San'atgarân-e bâzâr yeki-yeki maghâze-hâyeshân râ mibastand."},{"fr":"La lumière du couchant rendait les murs de la place presque dorés.","tgt":"نور غروب دیوارهای میدان را تقریبا طلایی کرده بود.","ro":"Nur-e ghorub divâr-hâ-ye meydân râ taghriban talâyi karde bud."},{"fr":"C'est là que j'ai compris pourquoi on appelle Ispahan « la moitié du monde ».","tgt":"همان موقع فهمیدم چرا به اصفهان «نصف جهان» می‌گویند.","ro":"Hamân mowghe' fahmidam cherâ be Esfahân «nesf-e jahân» miguyand."}]},{"title":"Un débat amical sur le bonheur","phrases":[{"fr":"Pour vous, le bonheur, c'est plutôt l'argent ou la tranquillité ?","tgt":"به نظر شما خوشبختی پول است یا آرامش؟","ro":"Be nazar-e shomâ khoshbakhti pul ast yâ ârâmesh?"},{"fr":"Je pense que l'argent aide, mais qu'il ne suffit pas.","tgt":"فکر می‌کنم پول کمک می‌کند، ولی کافی نیست.","ro":"Fekr mikonam pul komak mikonad, vali kâfi nist."},{"fr":"Mon ami n'était pas d'accord et a défendu son point de vue avec passion.","tgt":"دوستم موافق نبود و با شور از نظرش دفاع کرد.","ro":"Dustam movâfegh nabud va bâ shur az nazarash defâ' kard."},{"fr":"Selon lui, sans un minimum de confort, on ne peut pas être serein.","tgt":"به عقیده‌ی او، بدون کمی رفاه نمی‌شود آرام بود.","ro":"Be aghide-ye u, bedun-e kami refâh nemishavad ârâm bud."},{"fr":"Je comprends votre point de vue, mais je vois les choses autrement.","tgt":"نظرتان را می‌فهمم، اما من جور دیگری به قضیه نگاه می‌کنم.","ro":"Nazaretân râ mifahmam, ammâ man jur-e digari be ghazie negâh mikonam."},{"fr":"À mon avis, ce qui compte le plus, ce sont les gens qu'on aime.","tgt":"به نظر من، مهم‌ترین چیز آدم‌هایی هستند که دوستشان داریم.","ro":"Be nazar-e man, mohemtarin chiz âdam-hâyi hastand ke dustashân dârim."},{"fr":"Le débat s'est animé, mais personne ne s'est fâché.","tgt":"بحث داغ شد، ولی کسی ناراحت نشد.","ro":"Bahs dâgh shod, vali kasi nârâhat nashod."},{"fr":"Les Iraniens adorent discuter de la vie autour d'un verre de thé.","tgt":"ایرانی‌ها عاشق این‌اند که دور یک استکان چای درباره‌ی زندگی بحث کنند.","ro":"Irâni-hâ âshegh-e in-and ke dowr-e yek estekân chây darbâre-ye zendegi bahs konand."},{"fr":"Finalement, nous sommes tombés d'accord sur un point : la santé avant tout.","tgt":"آخرش سر یک چیز به توافق رسیدیم: سلامتی از همه مهم‌تر است.","ro":"Âkharash sar-e yek chiz be tavâfogh residim: salâmati az hame mohemtar ast."},{"fr":"Ce genre de conversation me fait progresser plus que n'importe quel livre.","tgt":"این جور گفت‌وگوها بیشتر از هر کتابی به پیشرفتم کمک می‌کنند.","ro":"In jur goft-o-gu-hâ bishtar az har ketâbi be pishraftam komak mikonand."}]},{"title":"Les contraintes de la vie","phrases":[{"fr":"Désolé, je suis obligé de partir tôt ce soir.","tgt":"ببخشید، امشب مجبورم زود بروم.","ro":"Bebakhshid, emshab majburam zud beravam."},{"fr":"Demain, je suis obligé de me lever à cinq heures pour attraper le bus.","tgt":"فردا مجبورم ساعت پنج بیدار شوم تا به اتوبوس برسم.","ro":"Fardâ majburam sâ'at-e panj bidâr shavam tâ be otobus beresam."},{"fr":"L'année dernière, mon frère a été obligé de changer de travail.","tgt":"پارسال برادرم مجبور شد کارش را عوض کند.","ro":"Pârsâl barâdaram majbur shod kârash râ avaz konad."},{"fr":"Vous n'êtes pas obligé de finir votre assiette, vous savez.","tgt":"مجبور نیستید غذایتان را تمام کنید، می‌دانید که.","ro":"Majbur nistid ghazâyetân râ tamâm konid, midânid ke."},{"fr":"Nous étions obligés de parler persan, car personne ne parlait français.","tgt":"مجبور بودیم فارسی حرف بزنیم، چون هیچ‌کس فرانسوی بلد نبود.","ro":"Majbur budim fârsi harf bezanim, chon hichkas farânsavi balad nabud."},{"fr":"Parfois, on est obligé de dire non, même à ceux qu'on aime.","tgt":"گاهی آدم مجبور است حتی به عزیزانش نه بگوید.","ro":"Gâhi âdam majbur ast hattâ be azizânash na beguyad."},{"fr":"Personne ne vous oblige à accepter, prenez le temps de réfléchir.","tgt":"کسی شما را مجبور نمی‌کند قبول کنید، با خیال راحت فکر کنید.","ro":"Kasi shomâ râ majbur nemikonad ghabul konid, bâ khiyâl-e râhat fekr konid."},{"fr":"À cause de la neige, nous avons dû rester une nuit de plus à Ispahan.","tgt":"به خاطر برف، مجبور شدیم یک شب دیگر در اصفهان بمانیم.","ro":"Be khâter-e barf, majbur shodim yek shab-e digar dar Esfahân bemânim."},{"fr":"Je déteste être obligé de me dépêcher pendant les vacances.","tgt":"از اینکه در تعطیلات مجبور باشم عجله کنم، بدم می‌آید.","ro":"Az inke dar ta'tilât majbur bâsham ajale konam, badam miâyad."},{"fr":"Dans la vie, on fait souvent ce qu'on doit avant ce qu'on veut.","tgt":"در زندگی، آدم اغلب اول کاری را می‌کند که باید، بعد کاری را که می‌خواهد.","ro":"Dar zendegi, âdam aghlab avval kâri râ mikonad ke bâyad, ba'd kâri râ ke mikhâhad."}],"tip":{"title":"« Majbur budan » : être obligé de","example":"Désolé, je suis obligé de partir tôt ce soir. — ببخشید، امشب <b>مجبورم</b> زود بروم.","body":"« Majbur » veut dire « obligé », et on le conjugue tout simplement avec le verbe être : « majburam », je suis obligé, « majburid », vous êtes obligé. Ensuite vient le verbe au subjonctif, avec le petit préfixe « be- » : « majburam beravam », mot à mot « obligé-je-suis que-j'aille ». Au passé, on dit « majbur budam » pour une obligation qui durait, et « majbur shodam », je me suis retrouvé obligé, pour une contrainte soudaine, comme dans « majbur shodim bemânim », nous avons dû rester. La négation est très utile pour rassurer quelqu'un : « majbur nistid », vous n'êtes pas obligé. Et quand quelqu'un vous force la main, c'est « majbur kardan », obliger. Pour le retenir, pensez à la « force majeure », celle qui vous oblige toujours.","exampleRo":"Bebakhshid, emshab majburam zud beravam.","lit":"pardonnez · ce soir · obligé-je-suis · tôt · [que] j'aille","say":{"Majbur budan":"مجبور بودن","Majbur":"مجبور","majburam":"مجبورم","majburid":"مجبورید","majburam beravam":"مجبورم بروم","majbur budam":"مجبور بودم","majbur shodam":"مجبور شدم","majbur shodim bemânim":"مجبور شدیم بمانیم","majbur nistid":"مجبور نیستید","majbur kardan":"مجبور کردن"}}},{"title":"Souvenirs d'enfance","phrases":[{"fr":"Quand j'étais petit, je passais tous mes étés chez mes grands-parents.","tgt":"بچه که بودم، همه‌ی تابستان‌ها را در خانه‌ی پدربزرگ و مادربزرگم می‌گذراندم.","ro":"Bachche ke budam, hame-ye tâbestân-hâ râ dar khâne-ye pedarbozorg va mâdarbozorgam migozarândam."},{"fr":"Leur maison avait une cour avec un petit bassin et un grenadier.","tgt":"خانه‌شان حیاطی داشت با یک حوض کوچک و یک درخت انار.","ro":"Khâne-shân hayâti dâsht bâ yek howz-e kuchak va yek derakht-e anâr."},{"fr":"Je me souviens encore de l'odeur du pain frais le matin.","tgt":"هنوز بوی نان تازه‌ی صبح‌ها یادم هست.","ro":"Hanuz bu-ye nân-e tâze-ye sobh-hâ yâdam hast."},{"fr":"Pendant les nuits les plus chaudes, nous dormions sur le toit.","tgt":"در شب‌های خیلی گرم، روی پشت‌بام می‌خوابیدیم.","ro":"Dar shab-hâ-ye kheyli garm, ru-ye poshtbâm mikhâbidim."},{"fr":"Ma mère me racontait des contes avant de dormir.","tgt":"مادرم قبل از خواب برایم قصه تعریف می‌کرد.","ro":"Mâdaram ghabl az khâb barâyam ghesse ta'rif mikard."},{"fr":"À l'époque, la vie semblait plus simple et plus lente.","tgt":"آن زمان، زندگی ساده‌تر و آرام‌تر به نظر می‌رسید.","ro":"Ân zamân, zendegi sâdetar va ârâmtar be nazar miresid."},{"fr":"Ce souvenir m'est revenu en entendant cette vieille chanson.","tgt":"با شنیدن این آهنگ قدیمی، آن خاطره یادم آمد.","ro":"Bâ shenidan-e in âhang-e ghadimi, ân khâtere yâdam âmad."},{"fr":"Êtes-vous encore en contact avec vos amis d'enfance ?","tgt":"آیا هنوز با دوستان دوران کودکی‌تان در ارتباط هستید؟","ro":"Âyâ hanuz bâ dustân-e dowrân-e kudaki-tân dar ertebât hastid?"},{"fr":"Chaque fois que je retourne dans ce quartier, j'ai le cœur serré.","tgt":"هر بار که به آن محله برمی‌گردم، دلم می‌گیرد.","ro":"Har bâr ke be ân mahalle barmigardam, delam migirad."},{"fr":"Les souvenirs sont la seule chose que personne ne peut nous prendre.","tgt":"خاطره‌ها تنها چیزی هستند که هیچ‌کس نمی‌تواند از ما بگیرد.","ro":"Khâtere-hâ tanhâ chizi hastand ke hichkas nemitavânad az mâ begirad."}]},{"title":"Une fête de mariage","phrases":[{"fr":"Nous avons été invités au mariage de la fille de nos voisins.","tgt":"ما به عروسی دختر همسایه‌مان دعوت شده‌ایم.","ro":"Mâ be arusi-ye dokhtar-e hamsâye-mân da'vat shode-im."},{"fr":"La fête a eu lieu dans un grand jardin décoré de lumières.","tgt":"جشن در باغ بزرگی برگزار شد که با چراغ‌ها تزیین شده بود.","ro":"Jashn dar bâgh-e bozorgi bargozâr shod ke bâ cherâgh-hâ tazyin shode bud."},{"fr":"Plus de trois cents invités étaient venus.","tgt":"بیش از سیصد مهمان آمده بودند.","ro":"Bish az sisad mehmân âmade budand."},{"fr":"La mariée portait une magnifique robe blanche.","tgt":"عروس لباس سفید بسیار زیبایی پوشیده بود.","ro":"Arus lebâs-e sefid-e besyâr zibâyi pushide bud."},{"fr":"Tout le monde a dansé jusqu'à deux heures du matin.","tgt":"همه تا ساعت دوی صبح رقصیدند.","ro":"Hame tâ sâ'at-e do-ye sobh raghsidand."},{"fr":"Le dîner était servi en buffet : kebabs, riz aux griottes et salades.","tgt":"شام به صورت سلف‌سرویس سرو شد: کباب، آلبالوپلو و سالاد.","ro":"Shâm be surat-e self-servis serv shod: kabâb, âlbâlupolo va sâlâd."},{"fr":"J'ai offert aux mariés une petite boîte en marqueterie d'Ispahan.","tgt":"به عروس و داماد یک جعبه‌ی کوچک خاتم‌کاری هدیه دادم.","ro":"Be arus va dâmâd yek ja'be-ye kuchak-e khâtamkâri hedye dâdam."},{"fr":"Je vous souhaite toute une vie de bonheur.","tgt":"برایتان یک عمر خوشبختی آرزو می‌کنم.","ro":"Barâyetân yek omr khoshbakhti ârezu mikonam."},{"fr":"Les mariages iraniens sont réputés pour leur ambiance animée et leur générosité.","tgt":"عروسی‌های ایرانی به شلوغی و سخاوت معروف‌اند.","ro":"Arusi-hâ-ye irâni be sholughi va sekhâvat ma'ruf-and."},{"fr":"J'ai rarement vu une fête aussi joyeuse.","tgt":"کمتر جشنی به این شادی دیده‌ام.","ro":"Kamtar jashni be in shâdi dide-am."}]},{"title":"Donner du sens à sa vie","phrases":[{"fr":"Est-ce que le travail que vous faites vous plaît vraiment ?","tgt":"آیا کاری را که انجام می‌دهید واقعا دوست دارید؟","ro":"Âyâ kâri râ ke anjâm midahid vâghe'an dust dârid?"},{"fr":"Mon ami a quitté un bon poste pour ouvrir un petit café à Chiraz.","tgt":"دوستم یک شغل خوب را رها کرد تا در شیراز یک کافه‌ی کوچک باز کند.","ro":"Dustam yek shoghl-e khub râ rahâ kard tâ dar Shirâz yek kâfe-ye kuchak bâz konad."},{"fr":"Il gagne moins, mais il dit qu'il n'a jamais été aussi heureux.","tgt":"درآمدش کمتر است، اما می‌گوید هیچ‌وقت این‌قدر خوشحال نبوده است.","ro":"Darâmadash kamtar ast, ammâ miguyad hichvaght inghadr khoshhâl nabude ast."},{"fr":"À votre avis, faut-il suivre son cœur ou sa raison ?","tgt":"به نظر شما باید دنبال دل رفت یا عقل؟","ro":"Be nazar-e shomâ bâyad donbâl-e del raft yâ aghl?"},{"fr":"Pour moi, un travail utile aux autres donne du sens à la vie.","tgt":"برای من، کاری که به درد دیگران بخورد به زندگی معنا می‌دهد.","ro":"Barâye man, kâri ke be dard-e digarân bekhorad be zendegi ma'nâ midahad."},{"fr":"J'ai longtemps cru que la réussite se mesurait au salaire.","tgt":"مدت‌ها فکر می‌کردم موفقیت با حقوق سنجیده می‌شود.","ro":"Moddat-hâ fekr mikardam movaffaghiyat bâ hoghugh sanjide mishavad."},{"fr":"Aujourd'hui, je préfère avoir du temps pour ma famille.","tgt":"امروز ترجیح می‌دهم برای خانواده‌ام وقت داشته باشم.","ro":"Emruz tarjih midaham barâye khânevâde-am vaght dâshte bâsham."},{"fr":"Beaucoup de jeunes rêvent de lancer leur propre affaire.","tgt":"خیلی از جوان‌ها آرزو دارند کسب‌وکار خودشان را راه بیندازند.","ro":"Kheyli az javân-hâ ârezu dârand kasb-o-kâr-e khodeshân râ râh beyandâzand."},{"fr":"On peut changer de chemin à tout âge.","tgt":"در هر سنی می‌شود مسیر را عوض کرد.","ro":"Dar har senni mishavad masir râ avaz kard."},{"fr":"Ce soir-là, notre discussion m'a beaucoup fait réfléchir.","tgt":"آن شب، گفت‌وگویمان مرا خیلی به فکر فرو برد.","ro":"Ân shab, goft-o-guyemân marâ kheyli be fekr foru bord."}]},{"title":"La sagesse des proverbes","phrases":[{"fr":"Les Iraniens aiment glisser un proverbe au milieu de la conversation.","tgt":"ایرانی‌ها دوست دارند وسط حرف‌هایشان یک ضرب‌المثل بیاورند.","ro":"Irâni-hâ dust dârand vasat-e harf-hâyeshân yek zarbolmasal biâvarand."},{"fr":"Comme on dit : les petites gouttes finissent par faire une mer.","tgt":"به قول معروف: «قطره قطره جمع گردد، وانگهی دریا شود.»","ro":"Be ghowl-e ma'ruf: «Ghatre ghatre jam' gardad, vângahi daryâ shavad.»"},{"fr":"Mon professeur me répétait : « C'est en forgeant qu'on devient forgeron. »","tgt":"معلمم همیشه می‌گفت: «کار نیکو کردن از پر کردن است.»","ro":"Mo'allemam hamishe migoft: «Kâr-e niku kardan az por kardan ast.»"},{"fr":"Vous voulez y aller ? Alors partons tout de suite : il faut battre le fer tant qu'il est chaud.","tgt":"می‌خواهید بروید؟ پس همین حالا برویم؛ تا تنور گرم است باید نان را چسباند.","ro":"Mikhâhid beravid? Pas hamin hâlâ beravim; tâ tanur garm ast bâyad nân râ chasbând."},{"fr":"Ne vous inquiétez pas : il n'est jamais trop tard pour bien faire.","tgt":"نگران نباشید؛ ماهی را هر وقت از آب بگیری تازه است.","ro":"Negarân nabâshid; mâhi râ har vaght az âb begiri tâze ast."},{"fr":"Comme dit le proverbe, plus on a de responsabilités, plus on a de soucis.","tgt":"به قول ضرب‌المثل، هر که بامش بیش، برفش بیشتر.","ro":"Be ghowl-e zarbolmasal, har ke bâmash bish, barfash bishtar."},{"fr":"Il faut venir voir Ispahan : rien ne vaut ce qu'on voit de ses propres yeux.","tgt":"باید بیایید اصفهان را ببینید؛ شنیدن کی بود مانند دیدن.","ro":"Bâyad biâyid Esfahân râ bebinid; shenidan key bovad mânand-e didan."},{"fr":"Aidez-moi un peu, on ne peut pas applaudir d'une seule main.","tgt":"کمی کمکم کنید، یک دست صدا ندارد.","ro":"Kami komakam konid, yek dast sedâ nadârad."},{"fr":"Ces proverbes sont souvent tirés de la poésie classique.","tgt":"این ضرب‌المثل‌ها اغلب از شعر کهن گرفته شده‌اند.","ro":"In zarbolmasal-hâ aghlab az she'r-e kohan gerefte shode-and."},{"fr":"Connaître quelques proverbes fait toujours sourire les Iraniens.","tgt":"دانستن چند ضرب‌المثل همیشه لبخند به لب ایرانی‌ها می‌آورد.","ro":"Dânestan-e chand zarbolmasal hamishe labkhand be lab-e irâni-hâ miâvarad."}],"tip":{"title":"Les proverbes persans","example":"Aidez-moi un peu, on ne peut pas applaudir d'une seule main. — کمی کمکم کنید، <b>یک دست صدا ندارد</b>.","body":"Les Iraniens adorent les proverbes, souvent tirés de la poésie classique, et ils les glissent volontiers au milieu d'une conversation. Pour en annoncer un, on dit « be ghowl-e ma'ruf », comme on dit, puis on récite la formule telle quelle, sans rien y changer. Prenez « yek dast sedâ nadârad », mot à mot « une main n'a pas de son » : il faut deux mains pour applaudir, donc il faut s'entraider. « Tâ tanur garm ast, bâyad nân râ chasbând », tant que le four est chaud il faut y coller le pain, correspond à notre « battre le fer tant qu'il est chaud ». Et « shenidan key bovad mânand-e didan », entendre ne vaut pas voir, rappelle qu'il faut aller voir les choses soi-même. Apprenez-en deux ou trois par cœur : placés au bon moment, ils feront sourire vos amis iraniens à coup sûr.","exampleRo":"Kami komakam konid, yek dast sedâ nadârad.","lit":"un peu · aidez-moi · une · main · son · n'a pas","say":{"be ghowl-e ma'ruf":"به قول معروف","yek dast sedâ nadârad":"یک دست صدا ندارد","Tâ tanur garm ast, bâyad nân râ chasbând":"تا تنور گرم است، باید نان را چسباند","shenidan key bovad mânand-e didan":"شنیدن کی بود مانند دیدن"}}},{"title":"Ce que veut dire l'amitié","phrases":[{"fr":"Pour vous, qu'est-ce qu'un véritable ami ?","tgt":"به نظر شما دوست واقعی کیست؟","ro":"Be nazar-e shomâ dust-e vâghe'i kist?"},{"fr":"Un vrai ami, c'est celui qui reste à tes côtés quand tout va mal.","tgt":"دوست واقعی کسی است که وقتی همه چیز بد پیش می‌رود، کنارت می‌ماند.","ro":"Dust-e vâghe'i kasi ast ke vaghti hame chiz bad pish miravad, kenârat mimânad."},{"fr":"Nous nous sommes rencontrés à l'université de Chiraz il y a vingt ans.","tgt":"بیست سال پیش در دانشگاه شیراز با هم آشنا شدیم.","ro":"Bist sâl pish dar dâneshgâh-e Shirâz bâ ham âshnâ shodim."},{"fr":"Même si nous vivons loin l'un de l'autre, nous nous appelons chaque semaine.","tgt":"با اینکه از هم دوریم، هر هفته به هم زنگ می‌زنیم.","ro":"Bâ inke az ham dur-im, har hafte be ham zang mizanim."},{"fr":"En Iran, l'amitié se construit souvent autour d'un repas partagé.","tgt":"در ایران، دوستی اغلب سر یک سفره‌ی مشترک شکل می‌گیرد.","ro":"Dar Irân, dusti aghlab sar-e yek sofre-ye moshtarak shekl migirad."},{"fr":"Il m'a soutenu au moment le plus difficile de ma vie.","tgt":"او در سخت‌ترین لحظه‌ی زندگی‌ام پشتم ایستاد.","ro":"U dar sakhttarin lahze-ye zendegi-am poshtam istâd."},{"fr":"On ne se voit pas souvent, mais rien n'a changé entre nous.","tgt":"زیاد همدیگر را نمی‌بینیم، ولی چیزی بین ما عوض نشده است.","ro":"Ziyâd hamdigar râ nemibinim, vali chizi beyn-e mâ avaz nashode ast."},{"fr":"Une vieille amitié vaut plus que mille nouvelles connaissances.","tgt":"یک دوستی قدیمی از هزار آشنای تازه بیشتر می‌ارزد.","ro":"Yek dusti-ye ghadimi az hezâr âshnâ-ye tâze bishtar miarzad."},{"fr":"Je suis heureux que la vie nous ait mis sur le même chemin.","tgt":"خوشحالم که زندگی ما را سر راه هم قرار داد.","ro":"Khoshhâlam ke zendegi mâ râ sar-e râh-e ham gharâr dâd."},{"fr":"À notre amitié, et à toutes les années qui viennent !","tgt":"به سلامتی دوستی‌مان و همه‌ی سال‌هایی که در پیش است!","ro":"Be salâmati-ye dusti-mân va hame-ye sâl-hâyi ke dar pish ast!"}]},{"title":"Norouz en famille","phrases":[{"fr":"Pour Norouz, toute la maison est nettoyée de fond en comble.","tgt":"برای نوروز، کل خانه از بالا تا پایین تمیز می‌شود.","ro":"Barâye Nowruz, kol-e khâne az bâlâ tâ pâyin tamiz mishavad."},{"fr":"Ma tante dresse la nappe du Haft-sin avec beaucoup de soin.","tgt":"خاله‌ام سفره‌ی هفت‌سین را با دقت زیادی می‌چیند.","ro":"Khâle-am sofre-ye haftsin râ bâ deghghat-e ziyâdi michinad."},{"fr":"On y pose des pommes, de l'ail, des pièces et des pousses vertes.","tgt":"روی آن سیب، سیر، سکه و سبزه می‌گذارند.","ro":"Ru-ye ân sib, sir, sekke va sabze migozârand."},{"fr":"Au moment du passage à la nouvelle année, toute la famille est réunie.","tgt":"لحظه‌ی تحویل سال، همه‌ی خانواده دور هم جمع‌اند.","ro":"Lahze-ye tahvil-e sâl, hame-ye khânevâde dowr-e ham jam'-and."},{"fr":"Les grands-parents offrent aux enfants des billets tout neufs.","tgt":"پدربزرگ و مادربزرگ به بچه‌ها اسکناس‌های نو عیدی می‌دهند.","ro":"Pedarbozorg va mâdarbozorg be bachche-hâ eskenâs-hâ-ye now eydi midahand."},{"fr":"Pendant deux semaines, on rend visite à toute la famille.","tgt":"در این دو هفته به دید و بازدید همه‌ی فامیل می‌رویم.","ro":"Dar in do hafte be did-o-bâzdid-e hame-ye fâmil miravim."},{"fr":"Chez chacun, on nous sert du thé, des fruits et des pâtisseries.","tgt":"خانه‌ی هر کس که می‌رویم، چای و میوه و شیرینی جلویمان می‌گذارند.","ro":"Khâne-ye har kas ke miravim, chây va mive va shirini jeloyemân migozârand."},{"fr":"Le treizième jour, tout le monde part pique-niquer dans la nature.","tgt":"روز سیزدهم، همه برای پیک‌نیک به دل طبیعت می‌روند.","ro":"Ruz-e sizdahom, hame barâye piknik be del-e tabi'at miravand."},{"fr":"Ce jour-là, on jette les pousses vertes dans l'eau d'une rivière.","tgt":"آن روز سبزه را در آب روان می‌اندازند.","ro":"Ân ruz sabze râ dar âb-e ravân miandâzand."},{"fr":"Bonne année, j'espère que cette année vous sera douce !","tgt":"سال نو مبارک، امیدوارم سال خوبی داشته باشید!","ro":"Sâl-e now mobârak, omidvâram sâl-e khubi dâshte bâshid!"}]},{"title":"La nuit de Yalda","phrases":[{"fr":"Yalda est la nuit la plus longue de l'année.","tgt":"شب یلدا طولانی‌ترین شب سال است.","ro":"Shab-e Yaldâ tulânitarin shab-e sâl ast."},{"fr":"Ce soir-là, on veille tard chez les grands-parents.","tgt":"آن شب تا دیروقت در خانه‌ی پدربزرگ و مادربزرگ بیدار می‌مانیم.","ro":"Ân shab tâ dirvaght dar khâne-ye pedarbozorg va mâdarbozorg bidâr mimânim."},{"fr":"On mange des grenades, de la pastèque et des fruits secs.","tgt":"انار و هندوانه و آجیل می‌خوریم.","ro":"Anâr va hendevâne va âjil mikhorim."},{"fr":"La couleur rouge des fruits rappelle la lumière de l'aube.","tgt":"رنگ سرخ میوه‌ها یادآور نور سپیده‌دم است.","ro":"Rang-e sorkh-e mive-hâ yâdâvar-e nur-e sepidedam ast."},{"fr":"Ensuite, quelqu'un ouvre le recueil de Hafez et lit un poème à voix haute.","tgt":"بعد یک نفر دیوان حافظ را باز می‌کند و شعری را بلند می‌خواند.","ro":"Ba'd yek nafar divân-e Hâfez râ bâz mikonad va she'ri râ boland mikhânad."},{"fr":"Chacun essaie d'y trouver un message pour l'année à venir.","tgt":"هر کس سعی می‌کند در آن پیامی برای سال پیش رو پیدا کند.","ro":"Har kas sa'y mikonad dar ân payâmi barâye sâl-e pish-e ru peydâ konad."},{"fr":"Ma grand-mère connaît des histoires dont personne d'autre ne se souvient.","tgt":"مادربزرگم قصه‌هایی بلد است که هیچ‌کس دیگر یادش نیست.","ro":"Mâdarbozorgam ghesse-hâyi balad ast ke hichkas-e digar yâdash nist."},{"fr":"Cette fête existe depuis des milliers d'années.","tgt":"این جشن هزاران سال قدمت دارد.","ro":"In jashn hezârân sâl ghedmat dârad."},{"fr":"Même ceux qui vivent loin essaient de rentrer pour cette nuit.","tgt":"حتی کسانی که دور زندگی می‌کنند، سعی می‌کنند برای این شب برگردند.","ro":"Hattâ kasâni ke dur zendegi mikonand, sa'y mikonand barâye in shab bargardand."},{"fr":"Passer Yalda avec une famille iranienne a été un vrai cadeau.","tgt":"گذراندن یلدا با یک خانواده‌ی ایرانی برایم هدیه‌ای واقعی بود.","ro":"Gozarândan-e Yaldâ bâ yek khânevâde-ye irâni barâyam hedye-i vâghe'i bud."}]},{"title":"Entre les générations","phrases":[{"fr":"Mes grands-parents se sont mariés sans presque se connaître.","tgt":"پدربزرگ و مادربزرگم تقریبا بدون شناخت از هم ازدواج کردند.","ro":"Pedarbozorg va mâdarbozorgam taghriban bedun-e shenâkht az ham ezdevâj kardand."},{"fr":"Aujourd'hui, les jeunes choisissent eux-mêmes leur conjoint.","tgt":"امروز جوان‌ها خودشان همسرشان را انتخاب می‌کنند.","ro":"Emruz javân-hâ khodeshân hamsarashân râ entekhâb mikonand."},{"fr":"Mon père ne comprend pas pourquoi je passe autant de temps sur mon téléphone.","tgt":"پدرم نمی‌فهمد چرا این‌قدر وقتم را با گوشی‌ام می‌گذرانم.","ro":"Pedaram nemifahmad cherâ inghadr vaghtam râ bâ gushi-am migozarânam."},{"fr":"Les anciens ont souvent plus de patience que nous.","tgt":"قدیمی‌ها اغلب از ما صبورتر هستند.","ro":"Ghadimi-hâ aghlab az mâ saburtar hastand."},{"fr":"Ma mère dit qu'autrefois, les voisins étaient comme une famille.","tgt":"مادرم می‌گوید قدیم همسایه‌ها مثل خانواده بودند.","ro":"Mâdaram miguyad ghadim hamsâye-hâ mesl-e khânevâde budand."},{"fr":"Chaque génération pense que la précédente avait la vie plus facile.","tgt":"هر نسلی فکر می‌کند زندگی نسل قبل آسان‌تر بوده است.","ro":"Har nasli fekr mikonad zendegi-ye nasl-e ghabl âsântar bude ast."},{"fr":"Mon grand-père m'a appris à jouer au backgammon.","tgt":"پدربزرگم تخته‌نرد بازی کردن را به من یاد داد.","ro":"Pedarbozorgam takhte-nard bâzi kardan râ be man yâd dâd."},{"fr":"En échange, je lui ai montré comment envoyer des photos à ses petits-enfants.","tgt":"در عوض، من به او یاد دادم چطور برای نوه‌هایش عکس بفرستد.","ro":"Dar avaz, man be u yâd dâdam chetowr barâye nave-hâyash aks befrestad."},{"fr":"Les anciens et les jeunes peuvent apprendre beaucoup les uns des autres.","tgt":"پیرها و جوان‌ها خیلی چیزها می‌توانند از هم یاد بگیرند.","ro":"Pir-hâ va javân-hâ kheyli chiz-hâ mitavânand az ham yâd begirand."},{"fr":"Ce qui ne change pas, c'est l'amour qu'on porte à sa famille.","tgt":"چیزی که عوض نمی‌شود، عشق به خانواده است.","ro":"Chizi ke avaz nemishavad, eshgh be khânevâde ast."}]},{"title":"Un au revoir difficile","phrases":[{"fr":"Demain, je quitte Chiraz, et j'ai le cœur lourd.","tgt":"فردا از شیراز می‌روم و دلم گرفته است.","ro":"Fardâ az Shirâz miravam va delam gerefte ast."},{"fr":"Mes amis ont organisé un dernier dîner pour mon départ.","tgt":"دوستانم برایم یک شام خداحافظی ترتیب دادند.","ro":"Dustânam barâyam yek shâm-e khodâhâfezi tartib dâdand."},{"fr":"Je n'arrive pas à croire que ces trois mois soient passés si vite.","tgt":"باورم نمی‌شود که این سه ماه این‌قدر زود گذشت.","ro":"Bâvaram nemishavad ke in se mâh inghadr zud gozasht."},{"fr":"Vous m'avez accueilli comme un membre de votre famille.","tgt":"شما مرا مثل یکی از اعضای خانواده‌تان پذیرفتید.","ro":"Shomâ marâ mesl-e yeki az a'zâ-ye khânevâde-tân paziroftid."},{"fr":"Promettez-moi de venir me voir en France un jour.","tgt":"قول بدهید یک روز به دیدنم به فرانسه بیایید.","ro":"Ghowl bedahid yek ruz be didanam be Farânse biâyid."},{"fr":"Mon amie m'a offert un petit recueil de Hafez en souvenir.","tgt":"دوستم یک دیوان کوچک حافظ به یادگار به من هدیه داد.","ro":"Dustam yek divân-e kuchak-e Hâfez be yâdegâr be man hedye dâd."},{"fr":"Selon la coutume, on a versé un peu d'eau derrière moi pour que je revienne.","tgt":"طبق رسم، پشت سرم آب ریختند تا دوباره برگردم.","ro":"Tebgh-e rasm, posht-e saram âb rikhtand tâ dobâre bargardam."},{"fr":"Ne pleurez pas, ce n'est qu'un au revoir.","tgt":"گریه نکنید، این فقط یک خداحافظی موقت است.","ro":"Gerye nakonid, in faghat yek khodâhâfezi-ye movaghghat ast."},{"fr":"Je garderai ces moments au fond de mon cœur.","tgt":"این لحظه‌ها را در ته دلم نگه می‌دارم.","ro":"In lahze-hâ râ dar tah-e delam negah midâram."},{"fr":"À bientôt, mes amis, vous allez me manquer.","tgt":"به امید دیدار، دوستان من؛ دلم برایتان تنگ می‌شود.","ro":"Be omid-e didâr, dustân-e man; delam barâyetân tang mishavad."}]},{"title":"Regarder vers l'avenir","phrases":[{"fr":"Comment imaginez-vous votre vie dans dix ans ?","tgt":"زندگی‌تان را ده سال دیگر چطور تصور می‌کنید؟","ro":"Zendegi-tân râ dah sâl-e digar chetowr tasavvor mikonid?"},{"fr":"J'espère avoir une maison avec un jardin plein d'arbres fruitiers.","tgt":"امیدوارم خانه‌ای داشته باشم با باغی پر از درخت میوه.","ro":"Omidvâram khâne-i dâshte bâsham bâ bâghi por az derakht-e mive."},{"fr":"Personne ne sait ce que l'avenir nous réserve.","tgt":"هیچ‌کس نمی‌داند آینده چه در چنته دارد.","ro":"Hichkas nemidânad âyande che dar chante dârad."},{"fr":"Mon grand-père disait toujours qu'il faut savourer chaque instant.","tgt":"پدربزرگم همیشه می‌گفت باید قدر لحظه را دانست.","ro":"Pedarbozorgam hamishe migoft bâyad ghadr-e lahze râ dânest."},{"fr":"Les poètes persans ont beaucoup parlé du temps qui passe.","tgt":"شاعران فارسی‌زبان زیاد از گذر زمان سخن گفته‌اند.","ro":"Shâ'erân-e fârsizabân ziyâd az gozar-e zamân sokhan gofte-and."},{"fr":"Malgré les difficultés, je reste plutôt optimiste.","tgt":"با وجود سختی‌ها، من نسبتا خوش‌بین هستم.","ro":"Bâ vojud-e sakhti-hâ, man nesbatan khoshbin hastam."},{"fr":"Garder espoir, c'est déjà avancer un peu.","tgt":"امید داشتن یعنی کمی جلو رفتن.","ro":"Omid dâshtan ya'ni kami jelo raftan."},{"fr":"Je voudrais revenir en Iran chaque année, au printemps.","tgt":"دوست دارم هر سال، در بهار، به ایران برگردم.","ro":"Dust dâram har sâl, dar bahâr, be Irân bargardam."},{"fr":"Mes projets ont beaucoup changé depuis que je suis arrivé ici.","tgt":"از وقتی اینجا آمده‌ام، برنامه‌هایم خیلی عوض شده‌اند.","ro":"Az vaghti injâ âmade-am, barnâme-hâyam kheyli avaz shode-and."},{"fr":"Le plus important, c'est de garder l'envie de découvrir.","tgt":"مهم‌ترین چیز این است که شوق کشف کردن را حفظ کنیم.","ro":"Mohemtarin chiz in ast ke showgh-e kashf kardan râ hefz konim."}]},{"title":"Regard en arrière sur le parcours en persan","phrases":[{"fr":"Quand j'ai commencé le persan, je ne savais même pas dire bonjour.","tgt":"وقتی فارسی را شروع کردم، حتی بلد نبودم سلام کنم.","ro":"Vaghti fârsi râ shoru' kardam, hattâ balad nabudam salâm konam."},{"fr":"Les premiers mots que j'ai appris étaient « merci » et « thé ».","tgt":"اولین کلمه‌هایی که یاد گرفتم «مرسی» و «چای» بودند.","ro":"Avvalin kalame-hâyi ke yâd gereftam «mersi» va «chây» budand."},{"fr":"Au début, l'ordre des mots dans la phrase me paraissait très étrange.","tgt":"اوایل، ترتیب کلمه‌ها در جمله به نظرم خیلی عجیب بود.","ro":"Avâyel, tartib-e kalame-hâ dar jomle be nazaram kheyli ajib bud."},{"fr":"Peu à peu, j'ai pris l'habitude de mettre le verbe à la fin.","tgt":"کم‌کم عادت کردم فعل را آخر جمله بگذارم.","ro":"Kamkam âdat kardam fe'l râ âkhar-e jomle begozâram."},{"fr":"Aujourd'hui, je peux tenir une vraie conversation avec mes amis iraniens.","tgt":"امروز می‌توانم با دوستان ایرانی‌ام یک گفت‌وگوی واقعی داشته باشم.","ro":"Emruz mitavânam bâ dustân-e irâni-am yek goft-o-gu-ye vâghe'i dâshte bâsham."},{"fr":"Mes trajets quotidiens sont devenus mes moments préférés pour pratiquer.","tgt":"رفت‌وآمدهای روزانه‌ام بهترین وقت برای تمرین شده‌اند.","ro":"Raft-o-âmad-hâ-ye ruzâne-am behtarin vaght barâye tamrin shode-and."},{"fr":"J'ai fait beaucoup d'erreurs, mais on m'a toujours encouragé.","tgt":"خیلی اشتباه کردم، اما همیشه تشویقم کردند.","ro":"Kheyli eshtebâh kardam, ammâ hamishe tashvigham kardand."},{"fr":"Le plus beau compliment, c'est quand on m'a demandé si j'avais vécu en Iran.","tgt":"قشنگ‌ترین تعریف این بود که از من پرسیدند آیا در ایران زندگی کرده‌ام.","ro":"Ghashangtarin ta'rif in bud ke az man porsidand âyâ dar Irân zendegi karde-am."},{"fr":"Apprendre cette langue m'a ouvert les portes de toute une culture.","tgt":"یاد گرفتن این زبان درهای یک فرهنگ کامل را به رویم باز کرد.","ro":"Yâd gereftan-e in zabân dar-hâ-ye yek farhang-e kâmel râ be ruyam bâz kard."},{"fr":"Je suis fier du chemin parcouru depuis le premier jour.","tgt":"به راهی که از روز اول آمده‌ام افتخار می‌کنم.","ro":"Be râhi ke az ruz-e avval âmade-am eftekhâr mikonam."}]},{"title":"Fin du parcours : un dernier bilan","phrases":[{"fr":"Je comprends maintenant les poèmes, les proverbes et les plaisanteries.","tgt":"حالا شعرها، ضرب‌المثل‌ها و شوخی‌ها را می‌فهمم.","ro":"Hâlâ she'r-hâ, zarbolmasal-hâ va shukhi-hâ râ mifahmam."},{"fr":"Je sais remercier, consoler et débattre en persan.","tgt":"بلدم به فارسی تشکر کنم، دلداری بدهم و بحث کنم.","ro":"Baladam be fârsi tashakkor konam, deldâri bedaham va bahs konam."},{"fr":"Je passe sans difficulté du persan familier au persan soutenu.","tgt":"بدون زحمت از فارسی محاوره‌ای به فارسی رسمی می‌روم.","ro":"Bedun-e zahmat az fârsi-ye mohâvere-i be fârsi-ye rasmi miravam."},{"fr":"Ma prononciation n'est pas parfaite, mais on me comprend bien.","tgt":"تلفظم کامل نیست، ولی حرفم را خوب می‌فهمند.","ro":"Talaffozam kâmel nist, vali harfam râ khub mifahmand."},{"fr":"Ce qui m'a le plus marqué, c'est la chaleur des gens.","tgt":"چیزی که بیشتر از همه مرا تحت تأثیر قرار داد، گرمی مردم بود.","ro":"Chizi ke bishtar az hame marâ taht-e ta'sir gharâr dâd, garmi-ye mardom bud."},{"fr":"Il me reste encore beaucoup de choses à apprendre.","tgt":"هنوز چیزهای زیادی مانده که باید یاد بگیرم.","ro":"Hanuz chiz-hâ-ye ziyâdi mânde ke bâyad yâd begiram."},{"fr":"Désormais, je lirai encore un peu de Hafez chaque soir.","tgt":"از این به بعد هم هر شب کمی حافظ خواهم خواند.","ro":"Az in be ba'd ham har shab kami Hâfez khâham khând."},{"fr":"Merci à tous ceux qui m'ont aidé tout au long de ce chemin.","tgt":"از همه‌ی کسانی که در این راه کمکم کردند، ممنونم.","ro":"Az hame-ye kasâni ke dar in râh komakam kardand, mamnunam."},{"fr":"Le persan ne sera plus jamais une langue étrangère pour moi.","tgt":"فارسی دیگر هیچ‌وقت برایم زبانی بیگانه نخواهد بود.","ro":"Fârsi digar hichvaght barâyam zabâni bigâne nakhâhad bud."},{"fr":"Comme disent mes amis iraniens : si la vie le permet, nous nous reverrons.","tgt":"به قول دوستان ایرانی‌ام، اگر عمری باقی بود، دوباره همدیگر را می‌بینیم.","ro":"Be ghowl-e dustân-e irâni-am, agar omri bâghi bud, dobâre hamdigar râ mibinim."}]}]}]}];
